// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":16,"question":"يكثر الاختلاطُ بين الأقارب، مثل: أولاد العم، والأرحام، وغيرهم، وحيث إنني قمتُ بنصح أقاربي في ذلك، ولكن لم يُصغوا لذلك، حيث يقولون: عشنا على ذلك، وتربّينا عليه مع بعضنا البعض، ونحن أقرباء، ونحن واثقون في بعضنا البعض! وحيث إن نيتنا طيبة مع بعضنا، وحيث إنهم حينما يقومون بذلك الاختلاط يحزّ في قلبي، حتى أحيانًا أُفكر في عدم زيارتهم، حيث إنني ولله الحمد أهلي لا يكشفون على أحدٍ منهم في وقتنا هذا، وقد قمتُ بنصحهم حتى أبي، ولم يُبالوا بذلك، فبماذا تنصحونني؟ جزاكم الله خيرًا","title":"ما النصيحة تجاه الاختلاط بين الأقارب؟","answer":"الجواب: الواجب مثلما فعلت: النصيحة والتوجيه؛ لأنَّ العادات السَّيئة ما هي بعذرٍ، العادات السيئة يجب أن تُزال، كان المشركون على عادات عبادة الأصنام والأوثان وقتل البنات وغير هذا من حاجاتهم الخبيثة، فجاء الشرعُ بالنَّهي عنها وإزالتها، فعلى كل إنسانٍ أن يتحرَّى ما جاء به الشرعُ، حتى يُزيل العادة المُنكرة، وليس له بعذرٍ أن يكون أسلافه مشوا عليها، أو أبوه، أو أمه، أو جيرانه، لا، هذا ليس بعذرٍ، هذا عذر الكفَّار: إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِمْ مُقْتَدُونَ [الزخرف:23]، هذا عذر الكفرة -والعياذ بالله.\nفالواجب إزالة العادات السيئة، فعليك أن تستمر في النَّصيحة والتَّوجيه إلى الخير، وإخوانك الذين معك كذلك: من جيرانكم وأصحابكم الطيبين، حتى تكون الجهودُ مكثفةً، تستعين بالله ثم بإخوانك الطيبين من أقارب أو جيران أو أناس معروفين، حتى ينصحوا معك، حتى يُساعدوك، وبهذا تزول العادات السيئة إن شاء الله. أما مُقاطعتهم فلا، لا تُقاطعهم، ولكن عليك بالنَّصيحة والجدّ وغضّ البصر حتى يزول الشرُّ ويحصل الخير إن شاء الله.","link":"https://binbaz.org.sa/fatwas/2795/ما-النصيحة-تجاه-الاختلاط-بين-الاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0268.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":141,"question":"ما حكم الشرع بالنسبة للسَّائقين الأجانب الذين يختلون بالنِّساء خارج منازلهم، والذهاب بهنَّ إلى الأسواق والمُنتزهات، وفي بعض الأوقات خارج المدينة بحجَّة أنه سائقٌ لديهم؟","title":"ما حكم خلوة المرأة مع السائق الأجنبي؟","answer":"الجواب: السائق إذا كان ليس محرمًا للمرأة لا يجوز أن يخلو بها، بل يجب أن يكون معهما غيرُهما ثالث، فإذا أراد السوق أو المدرسة يكون معهما ثالث، لا يذهب بالبنت إلى المدرسة وحده، ولا بالمرأة إلى السوق وحده، وليكن معهما آخر: من أخيه، أو أمه، أو زوجته، أو رجل ثالث، أو امرأة أخرى يحصل بها عدم الخلوة؛ لقول النبي ﷺ: لا يخلونَّ رجلٌ بامرأةٍ، فإنَّ الشيطان ثالثهما، فلا يجوز أن يخلو بها، لا بذهابه بها إلى المدرسة، ولا في غير ذلك، بل يكون معهما مَن تزول معه الخلوة وما يحصل معه الطُّمأنينة وتزول الريبة.","link":"https://binbaz.org.sa/fatwas/3678/ما-حكم-خلوة-المراة-مع-الساىق-الاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0134.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":175,"question":"هل يجوز للمرأة أن تُصافح أخا زوجها، والركوب معه وحدها في السيارة؟","title":"حكم مصافحة أقارب الزوج والركوب معهم","answer":"الجواب: ليس للمرأة أن تُصافح أخا زوجها، ولا عمه، ولا خاله؛ لأنه ليس محرمًا، ليس لها أن تُصافح، ولا أن تخلو به في السيارة، ولا في غيرها؛ لأنَّه ليس بمحرمٍ، محرمها أبوه، وجده، وأبو جده، ونحو ذلك، وأولاده، أما إخوانه وأعمامه وأخواله فليسوا محارم، وليس لها مصافحة مَن ليس محرمًا لها، وليس لها الخلوة بأحدٍ، لا بالسائق، ولا بغيره.","link":"https://binbaz.org.sa/fatwas/3723/حكم-مصافحة-اقارب-الزوج-والركوب-معهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0175.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":237,"question":"أعيش في منزلٍ مع والدي ووالدتي، في مجتمعٍ تعوَّد الناسُ فيه على الدخول بعضهم على بعضٍ دون الشعور بأي حرجٍ في ذلك، نساء ورجالًا، وخاصةً الأقارب منهم، وأنا في منزلي هذا يُشاركنا إخوة لي في مأكلنا مع زوجاتهم، دون أن يلتزمن بالحجاب، وخاصةً في إفطار رمضان، وهم يعلمون أنَّ ذلك لا يجوز، ولكن يحتجُّون بأنَّ هذه عادتهم منذ وقتٍ طويلٍ، فهل من نصيحةٍ؟ علمًا بأنني سآخذ ما سجّل من هذه المُحاضرة وأُسمعهم إيَّاها.","title":"حكم من يتساهل في الاختلاط مع الأقارب","answer":"الجواب: نعم، هذا واقعٌ، قد وقع من بعض الناس التَّساهل بأكل بعضهم مع بعضٍ، نساء ورجالًا، وجلوس بعضهم مع بعضٍ والنساء كاشفات عن وجوههن، وقد يكون ما هو أعظم من ذلك: من الكشف عن الرؤوس أيضًا، والأذرع، وغير ذلك، وهذا لا شكَّ منكرٌ عظيمٌ لا يجوز، والواجب على المسلم أن يتَّقي الله، وأن ينصح أهل بيته عن مثل هذا، فطالب العلم له أهمية وله منزلة، فالعلماء هم خلفاء الرسل، فعلى طالب العلم أن ينصح آباءه وأمهاته وأخواته وأهل بيته جميعًا. فلا يجوز هذا العمل، لا يجوز أن يجلس الرجالُ والنساء والرجال ليسوا محارم للنساء، وهنَّ كاشفات، لا، يكون للنساء محلٌّ يُفطرن فيه ويأكلن فيه فيما بينهنَّ، والرجال في محلٍّ آخر؛ حتى لا يتأثر أحدٌ بأحدٍ، وحتى لا يشقَّ بعضُهم على بعضٍ، أما أن يجلسوا جميعًا بدون حجابٍ ولا تستُّرٍ من أخي زوجها ومن عمِّ زوجها؛ فهذا منكرٌ لا يجوز، والله يقول جلَّ وعلا: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، ويقول سبحانه: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ الآية [النور:31]، ويقول جلَّ وعلا: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلَابِيبِهِنَّ الآية [الأحزاب:59].\nفالواجب على طالب العلم وعلى ربِّ الأسرة وعلى رأس الأسرة أن يُعنى بهذا الأمر، وأن يُوجّه أبناءه وإخوانه إلى ما أوجب الله، وأن يتأدَّب المؤمنُ بآداب الله، فالنساء يكُنَّ على حدةٍ حتى لا يتكلفن، والرجال على حدةٍ، ولا يجوز أن يكن مع الرجال سافرات عن وجوههن، أو عن رؤوسهن، أو عن بقية أجسامهن، بل يكن مستورات متحجبات عند الخُلطة، ولا يخلو الرجلُ بامرأة أخيه، ولا بزوجة عمِّه أو خاله ليس معهما ثالثٌ، لا يجوز، فالخلوة لا تجوز، والإسفار والتَّكشف لا يجوز، بل يجب البُعد عن هذا كما شرع الله ذلك وأمر به.","link":"https://binbaz.org.sa/fatwas/4115/حكم-من-يتساهل-في-الاختلاط-مع-الاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0247.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":319,"question":"هل يجوز للمرأة أن تركب مع السائق وحدها، أو مع طفلٍ صغيرٍ؟ وكذلك هل يجوز للمرأة أن تُسافر وحدها من غير محرمٍ بالطائرة؟","title":"حكم سفر المرأة وحدها وركوبها مع السائق","answer":"الجواب: هذا قد بُيِّن في \"نور على الدرب\" مرات كثيرة، وفي مجلة \"الدعوة\" مرات كثيرة، فلا يجوز.\nوبالمناسبة مجلة \"الدعوة\" أيضًا فيها مقالات مفيدة، وأجوبة مفيدة، ينبغي أن يُراجعها طالبُ الفائدة.\nفالحاصل أنَّ المرأة ليس لها أن تركب مع السائق وحدها إذا كان أجنبيًّا، ما هو محرمٌ لها، بل عليها أن يكون معها ثالثٌ: كأخيها، كأمِّها، كخالتها، ونحو ذلك، حتى تزول الخلوة، يقول النبيُّ ﷺ: لا يخلونَّ الرجلُ بامرأةٍ، فإنَّ الشيطان ثالثهما.","link":"https://binbaz.org.sa/fatwas/4352/حكم-سفر-المراة-وحدها-وركوبها-مع-الساىق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0370.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":369,"question":"هل يصح أن أُسَلِّم على امرأة عمي –أنا أعرف والله أعلم أن السلام هنا القبلة- أو امرأة خالي في وجهها؟","title":"حكم تقبيل ومصافحة زوجة العم أو الخال","answer":"الجواب: امرأة عمِّك وامرأة خالك لا، ليسا بمحرم لك، فزوجة عمك وزوجة خالك وزوجة أخيك كلهم ما هم محارم، ليس لك أن تُسلم عليها في وجهها، وليس لك أن تُصافحها، ولكن السلام من بعيدٍ بالكلام، تُسلم عليها بالكلام: السلام عليكم، وعليكم السلام، كيف حالك يا فلانة؟","link":"https://binbaz.org.sa/fatwas/4623/حكم-تقبيل-ومصافحة-زوجة-العم-او-الخال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0424.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":373,"question":"يقول: فضيلة الشيخ، السلام عليكم ورحمة الله وبركاته، أنا أعمل في الوظيفة مع نساء، فما الحكم؟","title":"حكم العمل المختلط بين الرجال والنساء","answer":"الجواب: هذا خطير، العمل مع النساء فيه خطرٌ عظيمٌ؛ لأنَّ قربه منهن ونظره إليهن واختلاطه بهن وسيلةٌ إلى شرٍّ كثيرٍ، فنصيحتي له أن يبتعد عن هذا العمل، وأن يعمل في مجال الرجال، لا في مجال النساء، ولو كان هناك معاشٌ كثيرٌ؛ لأنَّ ما عند الله خيرٌ وأبقى، فلينتقل من العمل مع النساء إلى عمل الرجال بدلًا من أمر النساء، النساء يكون لهن مَن يتولاهن من النساء: كالطبيبة مع الطبيبات، والممرضة مع الممرضات، وهكذا، والرجل مع الممرضين إن كان ممرضًا، وإن كان طبيبًا مع الأطباء، إذا حرص في ذلك واتَّقى الله في ذلك يسَّر الله أمره، أما إذا تساهل وآثر المعاش والدنيا فهذا هو الخطر العظيم الذي يُخشى على دينه منه، ويُخشى على أخلاقه من الانحراف بأسباب هذا التَّساهل.","link":"https://binbaz.org.sa/fatwas/4630/حكم-العمل-المختلط-بين-الرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0428.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":415,"question":"هل يجوز لمَن تملّك فتاةً أن يخلو بها ويرى وجهها، وذلك قبل مراسيم الزواج؟","title":"ما حكم الخلوة بالزوجة بعد العقد قبل الزفاف؟","answer":"الجواب: نعم، يُباح أن يرى وجهها ويخلو بها، لكن إذا كان يخشى من ذلك وقوع ما لا يُرتضى وأهلها لا يرضون فلا؛ لأنه قد يقع بينهما الاتصال فتحمل، فقد يُنكر أو تُتهم بالزنا، فيقع شرٌّ عظيمٌ، فلا ينبغي في هذا إلا برضاهم وعلمهم، فإذا كانوا لا يرضون ولا يعلمون فليكن الاتِّصال عند الحاجة بالهاتف، أو المكاتبة، أو إرسال مَن يثق بها من النساء، أو من محارمها، إذا كان له حاجة في الاتصال بها.\nأما الخلوة بها وأهلها لا يدرون ولا يعلمون فهذا قد يُفضي إلى شرٍّ: قد يُجامعها، وقد تحمل؛ فتقع فتنة، ويقول الناس: إنه من غير زوجها، أو يدَّعي هو أنَّ هذا ليس منه، فتكون مصيبة كبيرة على الجميع.\nفالأولى بالمؤمن والاحتياط له أن يبتعد عن هذه الأشياء، وليس له فعل ذلك إلا برضا أهلها؛ حتى يعلموا، حتى يكونوا على بصيرةٍ، وحتى لا تقع الفتنة، وحتى لا تُتهم البنت بما لا ينبغي.\nوهذا كله إذا كان قد عقد عليها، أما إذا كان ما عقد عليها فليس له الخلوة بها بالكلية، ولا يجوز له، بل إنما ينظر إليها بحضرة أبيها أو أمِّها ونحو ذلك؛ ليرى ما يدعوه إلى خطبتها والزواج بها، كما أذن به النبي عليه الصلاة والسلام للخاطب أن ينظر، لكن من دون خلوة.","link":"https://binbaz.org.sa/fatwas/4833/ما-حكم-الخلوة-بالزوجة-بعد-العقد-قبل-الزفاف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0473.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":425,"question":"ما حكم استعمال حبوب تأخير العادة الشهرية في شهر رمضان؟","title":"حكم استعمال الحبوب لتأخير العادة الشهرية في رمضان","answer":"الجواب: لا حرج، إذا تعاطت بعض الحبوب؛ حتى لا تأتيها العادةُ في رمضان حتى تُصلي مع الناس وتصوم مع الناس؛ لا بأس. وهكذا في أيام الحج؛ حتى تطوف مع الناس وحتى تؤدي مناسك الحج مع الناس؛ لا حرج في ذلك؛ لأنها لا يضرُّها ذلك إن شاء الله، إذا كانت ممن لا تضرّها الحبوب. وإذا كانت ذات زوجٍ فالأحوط مشاورة الزوج في ذلك حتى لا يلحقها حرج.","link":"https://binbaz.org.sa/fatwas/4849/حكم-استعمال-الحبوب-لتاخير-العادة-الشهرية-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0483.mp3","categories":["قضايا المرأة","ما لا يفسد الصيام","النظر والخلوة والاختلاط"]},{"id":526,"question":"الشارح يقول: وأنه ﷺ كان لا يحرم عليه النظر إلى المؤمنات الأجنبيات بخلاف غيره؟","title":"هل النظر للأجنبيات كان جائزًا للنبي ﷺ؟","answer":"الجواب: لا، هذا ما عليه دليل، يقال: أن هذا قبل الحجاب، أحسن ما حُمِل عليه.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6357/هل-النظر-للاجنبيات-كان-جاىزا-للنبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/maram092 - 04 - .mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":619,"question":"ما الدليل على أن وجود امرأة ثالثة يسقط الخلوة؟","title":"ما دليل زوال الخلوة بوجود ثالث مع الاثنين؟","answer":"الجواب: فإن الشيطان ثالثهما فإذا صار معهما امرأة صار رابعًا ما صار ثالثًا؛ لأن الغالب أنها تزول الشبهة، لكن الواحدة قد يُسِرّ إليها ويطلب منها، فإذا كانوا ثلاثة زالت التهمة.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6459/ما-دليل-زوال-الخلوة-بوجود-ثالث-مع-الاثنين","audio":"https://files.zadapps.info/binbaz.org.sa/maram187 - 03 - .mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":723,"question":"ما حكم الاختلاط والاختلاء بالخادمات العاملات في كثيرٍ من بيوت المسلمين اليوم؟ وهل يجوز استقدام خادمة كافرة؟","title":"حكم استقدام خادمة كافرة والاختلاط بها","answer":"الجواب: الخادمات خطرهنَّ عظيم، والبليَّة بهن كبيرة، فلا تجوز الخلوة بالأجنبية، لا خادمة، ولا غيرها، لا يجوز أن يخلو بالخادمة، ولا يخلو بزوجة أخيه، ولا يخلو بزوجة عمِّه، ولا يخلو بزوجة خاله، ولا يخلو بامرأةٍ من جيرانه، ولا غيرهنَّ من الأجنبيات.\nيقول النبيُّ ﷺ: لا يخلونَّ رجلٌ بامرأةٍ، فإنَّ الشيطان ثالثهما، فليس له أن يخلو بامرأةٍ ليست محرمًا له، لا خادمة، ولا غيرها، وليس له أن يستقدم خدمًا كفَّارًا، ولا خادمات في هذه الجزيرة، هذه الجزيرة لا يجوز أن يُستقدم لها إلا المسلمون من الرجال والنساء؛ لأنَّ الرسول ﷺ أمر بإخراج الكفَّار منها، وأوصى عند موته بذلك، وألا يبقى فيها إلا الإسلام فقط، فهي معقل الإسلام، وهي منبع الإسلام، فلا يجوز أن يستقدم لها الكفار، الجزيرة العربية على طولها وعرضها.\nولا ينبغي لعاقلٍ أن يغترَّ بالناس اليوم وما فعلوه من استقدام الكفرة، لا ينبغي له أن يغترَّ بذلك، نعم اللهم ولي الأمر إذا دعت الضَّرورة إلى ذلك؛ لحاجة المسلمين إلى طبيبٍ اضطُرَّ إليه، أو عاملٍ اضطرَّ إليه، يراه وليُّ الأمر من مصلحة المسلمين، كما استخدم النبيُّ ﷺ اليهودَ في خيبر للضَّرورة إليهم، ثم أجلاهم عمر ، كذلك إذا استُقدموا لمصلحةٍ للمسلمين من غير إقامةٍ: كالمستقدمين لبيع البضائع، يبيعون بضائع ثم يرجعون بمدةٍ معلومةٍ وأيامٍ محدودةٍ، بيَّن هذا أهلُ العلم.","link":"https://binbaz.org.sa/fatwas/20557/حكم-استقدام-خادمة-كافرة-والاختلاط-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0515فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":727,"question":"هل زوجة أخي مَحْرَمٌ لي؟ علمًا بأنها لا تتحجب عني، وهل عليَّ ذنبٌ؟","title":"حكم النظر إلى زوجة الأخ والخلوة بها","answer":"الجواب: تقدَّم هذا، زوجة أخيك ليست بمحرمٍ لك، ولا زوجة عمك، ولا زوجة خالك، ولا زوجة ابن عمك، ليسوا محارم، وعليهم التَّحجب عنك، ولا تخلو بواحدةٍ منهن؛ لأنهن أجنبيات منك، لَسْنَ محارم.\nأما زوجة أبيك فمَحْرَمٌ لك، وزوجة جدِّك محرمٌ لك، وزوجة ابنك وابن ابنك وابن بنتك محرمٌ لك.\nأما زوجة أخيك وزوجة عمك وزوجة خالك وزوجة ابن عمك فلا، ليسوا محارم، لا يحل لك النظر إليها، ولا الخلوة بها، والواجب عليها الحجاب وعدم التَّكشف لأخي زوجها، ولا زوج أختها، ولا خال زوجها، ولا عمه، ولا ابن عمه.\nكثيرٌ من النساء يُفرطن في هذا كثيرًا، في بلدان كثيرة، وفي مواضع كثيرة، وهو غلطٌ عظيمٌ، نسأل الله أن يهديهنَّ، وأن يرزقهنَّ الاستقامةَ والحجاب الصَّالح.","link":"https://binbaz.org.sa/fatwas/20586/حكم-النظر-الى-زوجة-الاخ-والخلوة-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0539فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":773,"question":"سائلة تسأل تقول: نحن عائلة كبيرة، ولدنيا سائقٌ يقوم بإيصالنا إلى المدارس والأسواق والأقارب، فما حكم ركوبنا معه داخل المدينة وخارجها؟ علمًا بأنه لا يوجد معنا رجلٌ في السيارة؟","title":"حكم ركوب النساء مع السائق الأجنبي","answer":"الجواب: لا حرج في ذلك، تكون مع السائق إذا كان الموجودون ثنتين فأكثر، وليس هناك ريبة، فلا بأس أن يخرجا معه للمدرسة، للحاجة، ويرجعا معه، ثنتان فأكثر، لا تكون واحدةً، لا يخلو بواحدةٍ، بل لا بدّ أن تكون الراكبات معه ثنتين فأكثر على وجهٍ لا ريبةَ فيه، وإذا تيسر أن يكون معهن رجلٌ فهذا خير وأصلح، ولكن الحمد لله يكفي؛ لأنَّ هذا لا يتيسر لكل أحدٍ، ففي البلد وما حولها يكفي خروج ثنتين فأكثر. أما إذا كان الطريقُ سفرًا فلا يجوز إلا بمحرمٍ، إذا كان يُعدّ سفرًا لا بدّ أن يكون مَحْرَمًا، أما ما دام في البلد وأطراف البلد فلا بأس أن يكون مع السائق غيره، رجل ثانٍ، أو امرأة ثانية، حتى لا تحصل الخلوة، ولا بدّ أن تكون المرأةُ التي معه الثانية ما هي محل ريبةٍ، أما الثنتان محل الريبة فما ينفع، لا بدّ أن يكن بعيدات عن الريبة.\n س: هل يُشترط أن يكون كبير السن؟\nالشيخ: ما يُشترط، لكن إذا كان كبير السن فطيب، وإذا كان مع زوجته أو أمّه فطيب، لكن قد لا يتيسر هذا، ثم يلاحظ أنه لابد ّمع الحجاب والبُعد عن أسباب الفتنة، ومعه مستورة مُتحجبة بعيدة عن أسباب الفتنة، حتى لا يقع شرٌّ بينهم وبينه.","link":"https://binbaz.org.sa/fatwas/20693/حكم-ركوب-النساء-مع-الساىق-الاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0590حكم ركوب النساء مع السائق داخل المدينة وخارجها؟ ابن باز فتاوى المحاضرات.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":788,"question":"ما حكم مشاهدة المسلسلات التلفزيونية وفيها نساء متبرجات؟","title":"حكم مشاهدة المسلسلات التي بها نساء متبرجة","answer":"الجواب: لا يجوز ذلك، المسلسلات التي فيها منكرٌ وتبرجٌ بالنساء، أو تقبيل الرجل للمرأة، أو أغانٍ، أو ما أشبه ذلك مما يكون مُحَرَّمًا؛ ليس للرجل والمرأة مشاهدة ذلك.","link":"https://binbaz.org.sa/fatwas/20788/حكم-مشاهدة-المسلسلات-التي-بها-نساء-متبرجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0618ما حكم مشاهدة المسلسلات التلفزيونية وفيها نساء متبرجات؟ابن باز فتاوى المحاضرات.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":923,"question":"ما حكم حفلات التَّوديع المُختلطة من الجنسين؟ وما حكم العلاج بالمُوسيقى؟","title":"حكم الحفلات المُختلطة والعلاج بالمُوسيقى","answer":"الجواب: الحفلات لا يكون فيها الاختلاط، إذا كانت حفلات تكون للرجال وحدهم، وللنساء وحدهن، حفلة لهؤلاء عند الوداع، وحفلة لهؤلاء عند الوداع، النساء للنساء، والرجال للرجال، أما الاختلاط فهذا منكرٌ، هذا من عمل الجاهلية -نعوذ بالله- من عمل الجاهلية، بل تكون الحفلة للرجال وحدهم، وللنساء وحدهن، هذا هو الواجب على المسؤولين.\nوأما العلاج بالموسيقى فلا أصلَ له، هذا من عمل السُّفهاء، الموسيقى ما هي بعلاجٍ، الموسيقى وآلات الملاهي مرضٌ للقلوب، ما هي بعلاجٍ، مَن أراد أن يُعالج بالموسيقى معناه: يمرضهم ويضرُّهم، حتى يُعوّدهم الباطل، ويثقل عليهم سماع القرآن والسنة، لا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/20961/حكم-الحفلات-المختلطة-والعلاج-بالموسيقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0757ما حكم حفلات التوديع المختلطة من الجنسين؟ابن باز فتاوى المحاضرات.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":946,"question":"هل للحاكم القاضي مثلًا أن يختلي بالمرأة؟","title":"هل يجوز للقاضي أن يختلي بالمرأة؟","answer":"الجواب: ليس للقاضي أن يختلي بالمرأة، لا القاضي ولا غيره، ليس له الخلوة بالمرأة، لا القاضي، ولا العالم، ولا غيرهما، المرأة فتنة، لا تجوز الخلوة بها، يقول النبيُّ ﷺ: لا يخلونَّ رجلٌ بامرأةٍ، فإنَّ الشيطان ثالثهما، ولا الذي يقرأ على النساء، الذي يقرأ على المرأة -الطبيب القارئ- يقرأ، ما يخلو بالمرأة التي يقرأ عليها، لابدّ أن يكون معه أمُّها أو خالتها أو زوجها، لا يجوز أن يخلو بها ويقرأ عليها، ولا الطبيب يخلو بالمرأة، ولا المُوَلِّد -لو اضطُرَّ إلى مُوَلِّدٍ عند عدم وجود مولدةٍ- لا يخلو بها.\nالمقصود: ما يجوز خلوة الرجل بالمرأة أبدًا: لا طبيب، ولا معلم، ولا قاضٍ، ولا غير ذلك، يجب أن يكون معهما ثالثٌ فأكثر.","link":"https://binbaz.org.sa/fatwas/20992/هل-يجوز-للقاضي-ان-يختلي-بالمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0789هل للقاضي أن يخلو بالمرأة ؟ابن باز فتاوى المحاضرات.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":968,"question":"أرجو منك يا سماحة الشيخ السماح؛ لأنني قد أخطأتُ عليك وأنا جاهلة، وتقول في سؤالها بأنها فتاة متزوجة، وزوجها يأمرها بكشف وجهها لإخوته وأعمامه، والجلوس معهم، علمًا بأنها عادة جاهلية، وترجوكم نصحه حتى يسمع نصيحتكم، جزاكم الله خيرًا.","title":"حكم طاعة الزوج في الكشف لغير المحارم","answer":"الجواب: أما ما يتعلق بالسماح عمَّا قد وقع منك من غيبةٍ فأنت وغيرك مسامحون، كل مَن تكلم في عرضي فهو مسامح، نسأل الله أن يُسامح الجميع، وأن يهدي الجميع إلى صراطه المستقيم.\nأما ما يتعلق بالكشف: فهذا يجب على الزوج -هداه الله- أن يتَّقي الله، وألا يُعينك على الباطل، بل يجب أن يُعينك على الخير والحجاب خيرٌ له ولك، ولكن لضعف غيرته وضعف بصيرته يأمرك بعدم الحجاب، هذا من أجل ضعف الغيرة وقلة البصيرة، فالواجب عليه أن يأمرك بالحجاب، وأن يُعينك عليه مع إخوته وأعمامه وغيرهم، والله يقول سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53].\nفالواجب عليك الحجاب وتقوى الله في ذلك، وليس لكِ أن تُطيعيه في الكشف لإخوته وأعمامه ونحوهم، ولو كانت عادةً لهم، العادة المخالفة للشرع يجب أن تُترك، الشرع يحكم على الناس، ليست العادةُ تحكم على الناس، الشرع الشريف هو الذي يحكم على الناس، ويُغير العادات، وكان أهلُ الجاهلية يعبدون الأوثان والأصنام، فجاء الشرع فأبطل ذلك، وهكذا كانوا يعملون القمار ويزنون ويشربون الخمر، فجاء الشرع فأبطل ذلك، فالعادات المخالفة للشرع يجب تركها.\nولا يجوز للزوج ولا لغيره أن يُعين زوجته على الباطل، أو يسمح لها في الباطل، وليس للزوجة أن تُطيعه في الباطل، يقول النبيُّ ﷺ: إنما الطاعة في المعروف، لا طاعةَ لمخلوقٍ في معصية الخالق.\nفالواجب على الأزواج أن يتَّقوا الله، وأن يحذروا غضبَ الله، وأن يُعينوا زوجاتهم على الخير، لا على الشر، وعلى الزوجات أيضًا أن يُطعن الله في ذلك، وأن يتَّقين الله في ذلك، وأن يُعِنَّ أزواجهن على الخير، عليهنَّ أن يُعِنَّ أزواجهن على المحافظة على الصَّلوات، على إيقاظهم للصلاة، على نصيحتهم في الخير، فالزوجة تُعين زوجها، وهو يُعينها أيضًا على الخير، كما قال الله سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، وهكذا الأخ مع أخته، والأب مع بنته، والعم مع بنت أخيه، يتعاونون على الخير والهدى والصلاح.","link":"https://binbaz.org.sa/fatwas/21014/حكم-طاعة-الزوج-في-الكشف-لغير-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0811هل يجوز أن تطيع الزوجة زوجها بكشف وجهها لأخوته وأعمامه والجلوس معهم؟ ابن باز.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":1090,"question":"يرى بعضُ الناس جواز عمل المرأة مع الرجل، كما يحدث في المُستشفيات مثلًا، ويستدلّون على ذلك بأن من الصَّحابيات مَن شارك في تضميد الجرحى في الغزوات، فما رأي الشرع في ذلك؟","title":"حكم اختلاط المرأة بالرجال في بعض الأعمال","answer":"الجواب:\nالشرع في هذا معلومٌ، وأن الواجب أن يكون عملُ النساء في ميدان النساء، وأن يكون عمل الرجال في ميدان الرجال، وأن يحذر المؤمنون والمؤمنات من الاختلاط الذي يُسبب الفساد، وانتشار الفواحش، وحصول أنواع المنكرات؛ لأنَّ الله جلَّ وعلا أوجب على المؤمن البُعد عن أسباب الشرِّ، وعلى المؤمنة البُعد عن أسباب الشرِّ، ولا ريب أن الاختلاط من أسباب الشرِّ، ولا ريب أن عمل هذا في ميدانه وهذا في ميدانه من أسباب السلامة، ولهذا قال سبحانه: وَقَرْنَ فِي بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَى [الأحزاب:33]، فنهى عن التَّبرج، وهو إبداء المحاسن؛ لما فيه من الفساد والخطر، وأمر بلزوم البيوت إلا من حاجةٍ؛ لما فيه من أسباب السلامة والبُعد عن الخطر.\nوقال جلَّ وعلا: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ  ۝  وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ [النور:30- 31]، وقال سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، وإذا اجتمع الصِّنفان عَسُر الحجاب، وعَسُر غضّ البصر، وجاء التَّبرج، وزال لزوم البيت، فكلٌّ له ميدان، فالواجب على كل صنفٍ أن يلزم ميدانه، وأن يكون في ميدانه؛ ليتم نفعه، ويتم جهاده.\nوأما عمل النِّساء في عهده ﷺ في بعض الغزوات: فهذا لدعاء الحاجة إلى ذلك؛ لقلة المسلمين، وكثرة الحاجة إلى مَن يُساعد على علاج المرضى، وإيصال الحاجات إليهم: من طعامٍ ودواءٍ وغير ذلك، فإذا دعت الحاجةُ إلى ذلك مع التَّحجب ومع العفَّة والبُعد عن أسباب الفتنة جاز ذلك.\nفإذا وُجد مرضٌ أو عِلَّةٌ من العلل لم يُوجد لها طبيبٌ، أو تعسر وجود الطبيب؛ لاشتغال الطبيب بأمورٍ أخرى، ودعت الحاجةُ إلى أن تراه الطبيبة، وأن تُعالجه الطبيبة؛ فلا بأس، مع الحشمة التي فعلها المؤمنات، وابتعدوا بها عن أسباب الفتنة.\nولا يجوز أن يُقاس هؤلاء على أولئك، هؤلاء الخطر منهم عظيم؛ لقلة الصيانة، وقلة التحفظ، وقلة الحجاب، وضعف الدين، وأولئك قد توفرت فيهم الأسباب الطيبة، والخصال الحميدة: من الحجاب والدين والأمانة والبُعد عن أسباب الخطر، فلا يستوي هؤلاء وهؤلاء، والضَّرورات لها أحكامها، ونحن في حاجةٍ إلى أطباء للرجال، وإلى طبيبات لنسائنا، فيجب أن يكون هؤلاء لهؤلاء، وهؤلاء لهؤلاء، والضَّرورات التي لا حيلةَ فيها لها أحكامُها.","link":"https://binbaz.org.sa/fatwas/21126/حكم-اختلاط-المراة-بالرجال-في-بعض-الاعمال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0922يرى بعض الناس جوازعمل المرأة مع الرجل ويستدلون بأن من الصحابيات من شارك في ضميد الجرحى.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":1134,"question":"ما حكم الخُلوة مع الطبيب للعلاج بوجود الأم؟","title":"ما حكم الخُلوة مع الطبيب للعلاج بوجود الأم؟","answer":"الجواب:\nإذا كان معها أمٌّ ما في خلوةٍ، الخلوة إذا كانت وحدها، يقول النبيُّ ﷺ: لا يخلونَّ رجلٌ بامرأةٍ، فإنَّ الشيطان ثالثهما، إذا كانت معها أمّها أو أخوها فليس بحرامٍ.","link":"https://binbaz.org.sa/fatwas/21198/ما-حكم-الخلوة-مع-الطبيب-للعلاج-بوجود-الام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0994أمرأة تسأل ما حكم الخلوة مع الطبيب للعلاج بوجود الأم؟ ابن باز.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":1202,"question":"ما الحكم في ردِّ المرأة على الرجل غير المَحْرَم لها: كأن تذهب إلى صيدلية المُستوصف، ولم يكن بها إلا رجلٌ طيبٌ؟ علمًا بأنَّ الصيدلية للنِّساء والرجال، ولكم جزيل الشُّكر.","title":"ما حكم كلام المرأة مع الرجل الأجنبي؟","answer":"الجواب:\nلا بأس أن ترد عليه، كان الصحابةُ يردون على النبي ﷺ، صحابيات يرددنَ على الصحابة، تقول: السلام عليكم، ويقولون: وعليكم السلام، وإذا سلَّم تقول: وعليكم السلام، كيف حالك؟ كيف أولادك؟ لا بأس، كما تقول لأخي زوجها وزوج أختها: كيف حالك؟ كيف أولادك؟ كيف أختي؟ ما في بأس، مع الحجاب والتَّستر وعدم التَّغنج وعدم الخضوع في القول، والله يقول: فَلَا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32]، يكون بصوتٍ معتدلٍ، ما فيه خضوع، ولا فيه تكسُّر، ولكن يكون بصوتٍ معتدلٍ في السلام، وفي الكلام، تشتري حاجتها لكن من دون خلوةٍ، تشتري من الصيدلي بدون خلوةٍ، عند الباب من ظاهرٍ، إلا إذا كان معها أحدٌ، لا تخلو به، ولا حرج في ذلك، لا مع زوج أختها، ولا مع أخي زوجها، ولا غيرهم، بالكلام، لكن لا تُصافحه، لا تُصافح الذي ما هو محرم لها، لا تُصافح أخا زوجها، ولا عمه، ولا خاله، ولا تُصافح زوج أختها، تُصافح محارمها لا بأس، تُصافح أخاها، عمَّها، زوج أمها، زوج بنتها، لا بأس، أما أن تُصافح أجنبيًّا فلا، ولو من دون ثوبٍ، لا تُصافحه أبدًا: السلام عليكم، وعليكم السلام، فقط من دون مصافحةٍ.","link":"https://binbaz.org.sa/fatwas/21267/ما-حكم-كلام-المراة-مع-الرجل-الاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1127ما حكم كلام المرأة للرجل الأجنبي؟ ابن باز فتاوى.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":1213,"question":"أنا أمٌّ لأيتامٍ، وأرغب في العمل، ولكن هذا العمل فيه اختلاطٌ بالرجال، فماذا يلزمني أن أفعل؟ وأنا ولله الحمد مُتدينة.","title":"حكم عمل المرأة في مكان تختلط فيه بالرجال؟","answer":"الجواب:\nلا تعملي مع الرجال، وأبشري بالخير إن شاء الله، دوِّري على عملٍ آخر بين النساء، وأبشري بالخير: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]، أما مع الرجال: ممرضة مع الممرضين، أو غير ذلك، فلا، هذه فتنةٌ وخطرٌ عظيمٌ على دينك، وعلى عرضك، لا تكوني مع الرجال في العمل، ابتعدي، ولا تكوني سكرتيرة للرجل، ولا مع الطبيب: سكرتيرة الطبيب، ولا تُعاونينه، كل هذا خطر عظيم، مع النساء، مع الطبيبات والممرضات لا بأس، وغيرهم  في أعمال النساء، أما مع الرجال فلا، ولو أكلتِ الترابَ، اتَّقي الله وأبشري بالخير: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا.","link":"https://binbaz.org.sa/fatwas/21269/حكم-عمل-المراة-في-مكان-تختلط-فيه-بالرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1125أنا أم لإيتام وأرعب في العمل ولكن هذا العمل فيه أختلاط للرجال فماذا أفعل؟ ابن باز.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":1265,"question":"نعلم جميعًا النِّعم التي امتَنَّها الله علينا ، ومن هذه النِّعَم: نعمة البصر، فهل يجوز للدكتور أو المُمرض أو المريض أو المُرافق للمريض أن ينظر إلى المُمرضات بحكم عمله أو بحكم طلبه منها بعض الأمور؟","title":"حكم النظر بين الرجال والنساء بالعمل الطبي","answer":"الجواب:\nيقول الله جلَّ وعلا: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ [النور:30]، ويقول النبيُّ ﷺ لعليٍّ في نظر الفجأة: اصرف بصرك، فإنَّ لك الأولى، وليست لك الأخرى، إذا فاجأتك المرأةُ اصرف بصرك، فليس للطبيب ولا غير الطبيب أن ينظر، بل يغضّ بصره، ويأمر بما يُريد مع غضِّ البصر وعدم تحديد النظر إليها، بل يأمر بما يُريد منها إذا دعت الحاجةُ.\nوتقدم أن الواجب أن تكون الممرضات تبع النساء، وأن يكون الممرضون تبع الرجال، وأن الواجب ألا يكون له سكرتيرة ولا ممرضة تبعًا له، يجب أن يكون التَّابعون للطبيب رجالًا: سكرتير وممرض وغير ذلك؛ حتى يبتعد عن الفتنة، وحتى تسلم هي أيضًا من الفتنة، وأن تكون الطبيبات للنساء، ومعهن الممرضات.  لكن إذا بُلي بشيءٍ من هذا: ممرضة أو طبيبة، ودعت الحاجةُ إلى أن يُكلِّمها، فعليها الاحتجاب، وعليه غضّ البصر، عليها أن تحتجب بالبرقع ونحوه، وعليه غضّ البصر إذا لم تحتجب، وعليه أن يسألها ويُكلِّمها فيما يُريد مع طرح البصر.","link":"https://binbaz.org.sa/fatwas/21340/حكم-النظر-بين-الرجال-والنساء-بالعمل-الطبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1083بحكم عملي في المستشفى هل يجوز آن آنظر إلى الطبيبات والمريضات والممرضات؟.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":1557,"question":"لو أذن الرجلُ لأناسٍ يدخلون على امرأته وليسوا بمحارم لها؟","title":"حكم الإذْن بدخولغير المحارم على الزوجة","answer":"الجواب:\nإذا كان ما في خلوة ما في بأس، أما الخلوة فلا، فإذا كان يخلو بها واحدٌ منهم فلا، أما إذا كانوا أقارب له...\nس: في مجلسٍ مستقلٍّ؟\nج: لا بأس، تتحجب وتدخل، أو تقوم إلى مكانٍ آخر، يعني: قد يأذن لبني عمه، وأقارب له، وأصهارٍ له، ما في بأس.","link":"https://binbaz.org.sa/fatwas/21659/حكم-الاذن-بدخول-غير-المحارم-على-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أذن لأناس في الدخول على امرأته وليسوا من محارمهما.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":1634,"question":"بعض المحلات التّجارية تضع ورقةً تقول فيها مثلًا: ممنوع دخول النّساء إلا بمحرم؟","title":"حكم اشتراط المَحْرَم للنساء في المحلات","answer":"الجواب:\nلا، ما على هذا دليل، المَحْرَم للسفر فقط، إذا دخلت بدون مَحْرمٍ ولم يكن هناك خطرٌ فلا بأس، تدخل للبيع والشراء، أو معها امرأة: أختها، أو جارتها، أو نحو ذلك، فالمَحْرَم للسفر.","link":"https://binbaz.org.sa/fatwas/21739/حكم-اشتراط-المحرم-للنساء-في-المحلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اشتراط المحرم للنساء في المحلات.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":1783,"question":"استقدام الخادمات هل يجوز بغير مَحْرَم؟","title":"هل يجوز استقدام الخادمات بلا مَحْرَم؟","answer":"الجواب:\nالأصل وجوب المَحْرَم، الرسول ﷺ قال: لا تسافر المرأة إلا مع ذي مَحْرَم، هذا الأصل، لكن إذا أرسلها أهلها بغير مَحْرَم فالإثم عليهم، ما هو عليه، هو إذا كان ملتزمًا بالمَحْرَم ولكن ما أطاعوه فالإثم عليهم.\nس: استقدام الناس الخادمات الآن؟\nج: على كل حالٍ، عند الحاجة لا بأس، لكن يجب أن يكون معها مَحْرَم.\nس: إذا لم يكن معها مَحْرَم ما يجوز استقدام الخادمة؟\nج: لا يجوز استقدام الخادمة إلا بمَحْرَم، ولا الزوجة تُستقدم من محلٍّ إلى محلٍّ إلا بمحرم، ولا البنت، ولا الأخت، إلا بمَحْرَم، لا بدّ، الرسول ﷺ قال: لا تسافر امرأةٌ هذا عام يعم كل الحريم، إلا بمَحْرَم، سواء زوجته، أو بنته، أو أخته، لا يستقدمها إلى بلدٍ إلا بمَحْرَم: مع أخوها، مع زوجها، مع ولدها، هذا عام، ولو لحاجةٍ.","link":"https://binbaz.org.sa/fatwas/21890/هل-يجوز-استقدام-الخادمات-بلا-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم استقدام الخادمات بلا محرم.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":1810,"question":"مَن ابتُلِيَ بخادمةٍ وكذلك مُرَبِّيَة، ويتساهل في النظر إليها، وكذلك أنها مثلًا تُقَدِّم لهم الطعام وتخدمهم، وأحيانًا تكون وحدها في البيت مع المَحْرَم، وتكون الأم مثلًا مُدَرِّسة أو نحو ذلك، ويخلو بها، ما رأيكم؟","title":"حكم الخُلْوَة بالخادمة والمُرَبِّيَة والنظر إليهن","answer":"الجواب:\nالواجب عليه غضُّ البصر، وأمرها بالحجاب وعدم الخلوة، كل هذه يجب أن يُراعيها، وعلى المرأة أن تجلس في بيتها ولا تذهب لعملها وتتركه يخلو بالمرأة، أو تكونا ثنتين حتى لا يصير خلوة، وإلا فتجلس، ما يلزم التدريس، تحفظ بيتها وأولادها وتَدَع التدريس.\nس: كذلك التساهل بالنظر إليها، يقول مثلًا: هذه خادمة؟\nج: ولو، ولو، قد يشتهيها، لكل ساقطةٍ لاقطة، قد تُشْتَهَى حتى العجوز، ولهذا قال جل وعلا في العجائز: وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لَا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ وهن عجائز  [النور:60].","link":"https://binbaz.org.sa/fatwas/21918/حكم-الخلوة-بالخادمة-والمربية-والنظر-اليهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الخلوة بالخادمة والمربية والنظر إليهن.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":1811,"question":"إذا كان الأعمى غيرَ مَحْرَمٍ هل يجوز أن يخلو بالمرأة؟","title":"ما حكم الخُلْوَة والحجاب مع الرُّجل الأعمى؟","answer":"الجواب:\nلا يخلو، الرجل ما يخلو بالمرأة، سواء كان أعمى أو لا، لكن ما يلزمها الحجاب عنه.","link":"https://binbaz.org.sa/fatwas/21919/ما-حكم-الخلوة-والحجاب-مع-الرجل-الاعمى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الخلوة بالرجل الأعمى.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":1812,"question":"بالنسبة للرجل الأعمى إذا كان مدرسًا في إحدى مدارس البنات، أحيانًا تكون الطالبات أو المعلمات يَتَطَيّبن، فما الحكم؛ لأنه يشم رائحتهن؟","title":"حكم تَعَطُّر النساء عند المدرس الأعمى","answer":"الجواب:\nهذا عليهنَّ هن، فعليهنَّ ترك الطِّيب، ويُخاطبن هن إذا كن يُخالطن الرجال، سواء معلمات أو غير معلمات، عليهن ترك الطِّيب.","link":"https://binbaz.org.sa/fatwas/21920/حكم-تعطر-النساء-عند-المدرس-الاعمى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تطيب النساء عند المدرس الأعمى.mp3","categories":["قضايا المرأة","النظر والخلوة والاختلاط","اللباس والزينة"]},{"id":1818,"question":"إذا كان المَحْرَمُ لا يخاف الله  فهل يجوز أن يخلو بمحرمه؟","title":"حكم الخلوة بالمَحْرَم الذي لا يخاف الله","answer":"الجواب:\nالأصل الجواز، لكن إذا كانت تخشى منه لا تخلو به، إذا كان قليل الدين أو معدوم الدين؛ لا تخلو به، ما يجوز، هذه العلة موجودة؛ نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21926/حكم-الخلوة-بالمحرم-الذي-لا-يخاف-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الخلوة بالمحرم الذي لا يخاف الله.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":1978,"question":"خُلُوُّ الرجل بالمرأتين منهيٌّ عنه؟","title":"حكم خُلْوَة الرجل بالمرأتين","answer":"الجواب:\nما فيه بأس، الخُلُوُّ بواحدةٍ فقط، أما إذا كانوا ثلاثةً من دون فتنةٍ ومن دون تهمةٍ فلا بأس؛ لأنَّ النبي عليه الصلاة والسلام قال: لا يَخْلُوَنَّ رجلٌ بامرأةٍ، فإنَّ الشيطان ثالثهما، فإذا كانتا اثنتين أو أكثر زالت الخُلْوة، إلا إذا كانت هناك تُهمة.\nس: ولو كانت المرأةُ كبيرةً؟\nج: ولو كبيرة، فالحديث عام، لكل ساقطةٍ لاقطة.","link":"https://binbaz.org.sa/fatwas/22094/حكم-خلوة-الرجل-بالمراتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم خلو الرجل بالمرأتين.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":3661,"question":"هل من خصائص النبي ﷺ الخلوة بالأجنبية والنظر إليها؟","title":"هل من خصائص النبي الخلوة بالأجنبية؟","answer":"الجواب: ما عليه دليل، المعروف أن أم حرام كانت محرمًا له من جهة المَخْوَل أو من جهة الرضاعة كما نبه على هذا جمع من أهل العلم. وحديث الرُّبَيّع ما فيه دليل على الخلوة، ما فيه وجود أنه خلا بها، فالأصل العموم حتى يتبين شيء، النص واضح.","link":"https://binbaz.org.sa/fatwas/23849/هل-من-خصاىص-النبي الخلوة-بالاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/خلوة النبي بالرّبيّع بنت معوّذ.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":3681,"question":"هل يجوز للرجل النظر إلى المرأة في البيع والشراء؟","title":"حكم نظر الرجل للمرأة في البيع والشراء","answer":"الجواب: لا، يغض بصره، لا ينظر، إلا إذا كانت جارية يبغي يشتريها، إن كانت أمة يبغي يشتريها لا بأس ينظر ما يحتاج إليه، أما البيع والشراء لا، عليها التستر وعليه غض البصر.  أما النظرة في المجتمعين مثل قصة الحبشة أو المرور في الأسواق تنظر لحاجاتها في الأسواق أو في المسجد لا بأس؛ لأن هذا ما هو بنظر شهوة، نظر للطريق أو نظر لعموم الواقفين أو المصلين أو اللاعبين؛ ولهذا أقرها النبي ﷺ أن تنظر من عند كتفه عليه الصلاة والسلام للعبهم. ويدل على جواز اللعب بالحراب والسيوف والبنادق إذا كان ما فيها خطر على أحد؛ لأن هذا من باب التمرن على الجهاد والاستعداد للجهاد؛ ولهذا أقرهم ﷺ في ذلك حتى في المسجد.","link":"https://binbaz.org.sa/fatwas/23870/حكم-نظر-الرجل-للمراة-في-البيع-والشراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم نظر الرجل للمرأة في البيع والشراء.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":3727,"question":"حكم نظر الرجال للنساء بدون ريبة؟","title":"هل يجوز نظر الرجال للنساء بدون ريبة؟","answer":"الجواب: يجب غض البصر، لكن إذا دعت الضرورة إلى هذا مثل: يدوّر ضالة؛ بنت له ضالة، في أناس مكشوفين، جارية له ضالة، إذا دعت الحاجة إلى هذا لا بأس، أو إذا دعت الحاجة، بنت له ضائعة، زوجة له ضائعة، جارية له ضائعة، في بلاد لا يستترون؛ له النظر.. لعلها بنته أو زوجته أو جاريته.\nالطالب: الشارح يقول إن المصنف ظاهر الترجمة أنه يذهب إلى جواز نظر المرأة إلى الأجنبي بخلاف عكسه.\nالشيخ: بغير ريبة يكفي، من غير ريبة، مثل النظر العام أو النظر للتعرف هو أخوها أو أبوها أو زوجها، أما إذا كان لريبة فهذا الذي يمنع.","link":"https://binbaz.org.sa/fatwas/23919/هل-يجوز-نظر-الرجال-للنساء-بدون-ريبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نظر الرجال للنساء بدون ريبة.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":3730,"question":"هل يحرم للمرأة أن تختلي بزوج ابنتها؟","title":"ما حكم خلوة المرأة بزوج ابنتها؟","answer":"الجواب: زوج ابنتها مَحْرَمٌ لها، لكن بعض النساء عندها شدة حياء كثير، والأوْلى ألا تحتجب منه، وأن تأخذ بالرخصة إن الله يحب أن تؤتى رخصه، فهذا يكون عيبًا في المرأة كونها تمتنع من محارمها.  أما إذا كان هناك سبب آخر بأنه رجل لا يُؤْمَن وأنه يفعل كذا وترى منه شيئًا ما يناسب؛ فهذا حقها أن تمتنع إذا كان له أسباب.","link":"https://binbaz.org.sa/fatwas/23922/ما-حكم-خلوة-المراة-بزوج-ابنتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/خلوة المرأة بزوج ابنتها.mp3","categories":["النظر والخلوة والاختلاط","المحرمات من النساء","قضايا المرأة"]},{"id":3732,"question":"إذا ذهبت مع السائق ومعها أطفال صغار هل تنتفي الخلوة؟","title":"هل تنتفي الخلوة بوجود الأطفال؟","answer":"الجواب: الأطفال ما ينفعون، لا بدّ من محرم أو امرأة أخرى معها ممن يوثق بها أو رجل آخر، أما الأطفال ما ينفعون.\nس:... لو في سن البلوغ يا شيخ؟\nالشيخ: في المحرمية، في السفر أو إزالة الخلوة، إزالة الخلوة أسهل قد يكون دون المحرمية لكن به إزالة الخلوة، لكن السفر لا، السفر أشد...... لكن إذا صار ابن أربعة عشر وما حولها؛ في البيت ينفع.","link":"https://binbaz.org.sa/fatwas/23924/هل-تنتفي-الخلوة-بوجود-الاطفال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تنتفي الخلوة بوجود الأطفال.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":3973,"question":"بالنسبة للسلام على بنات العم أو بنات الخالة؟","title":"ما حكم السلام على بنات العم والخالة؟","answer":"الجواب: من الأقارب من الرحم التي توصل، لكن من دون مصافحة ومن دون تقبيل، بالكلام بس، مع الحجاب وعدم الخلوة.","link":"https://binbaz.org.sa/fatwas/24201/ما-حكم-السلام-على-بنات-العم-والخالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم السلام على بنات العم أو بنات الخالة.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":5040,"question":"مَن منع السلام على الشابة؟","title":"ما حكم إلقاء السلام على المرأة الشابة؟","answer":"الجواب: لا، ما له أصل، لا بأس به، لكن دون مصافحةٍ.","link":"https://binbaz.org.sa/fatwas/29001/ما-حكم-القاء السلام-على-المراة-الشابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم إلقاء السلام على المرأة الشابة؟.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":5043,"question":"أحيانًا يصير لها سائق بدون زوجته أن تكون معه، فمثلًا لو قال: الأحسن أن تأتي ..؟","title":"ما حكم السائق والخادم للمرأة بدون مَحْرَم؟","answer":"الجواب: زوجته حتى لو كانت معه ما هي بمَحْرَم.\nس: مثلًا لو قال: الأحسن أن تأتي زوجة السائق معها بدل أن يذهب بها وحدها؟\nج: على كل حال، تزول الخلوة، وإلا ما هي بمَحْرَم في السفر، ما يجوز، أما من محلٍّ إلى محلٍّ، من بيتٍ إلى بيتٍ، من المدرسة في البلد؛ هنا تزول الخلوة إذا كان معه زوجته، أو معها امرأة أخرى، أو رجل آخر؛ تزول الخلوة، الخلوة تكون باثنين: لا يخلُوَنَّ رجلٌ بامرأةٍ إلا كان الشيطانُ ثالثهما.\nس: إذا كانت لهم كبيرة عجوز ربما يأتي لها بخادمٍ في المنزل، ما لها إلا هذا الخادم؟\nج: والله هذا خطر، إن كان ما عندهم أحد؛ خطر أن يخلو بها وفتنة، لكن إذا صارتا اثنتين في البيت كان أسهل.","link":"https://binbaz.org.sa/fatwas/29085/ما-حكم الساىق-والخادم-للمراة بدون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم السائق والخادم للمرأة بدون محرم؟.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":5176,"question":"يقول: ما حكم الشرع بالنسبة للسَّائقين الأجانب الذين يختلون بالنِّساء خارج منازلهم، والذهاب بهنَّ إلى الأسواق والمُنتزهات، وفي بعض الأوقات خارج المدينة بحجَّة أنه سائقٌ لديهم؟","title":"ما حكم الخلوة بسائق الأسرة الأجنبي؟","answer":"الجواب: السائق إذا كان ليس مَحْرمًا للمرأة لا يجوز أن يخلو بها، بل يجب أن يكون معهما غيرُهما ثالث، فإذا أراد السوق أو المدرسة يكون معهما ثالث، لا يذهب بالبنت إلى المدرسة وحده، ولا بالمرأة إلى السوق وحده، وليكن معهما آخر: من أخيه، أو أمه، أو زوجته، أو رجل ثالث، أو امرأة أخرى يحصل بها عدم الخلوة؛ لقول النبي ﷺ: لا يخلونَّ رجلٌ بامرأةٍ، فإنَّ الشيطان ثالثهما، فلا يجوز أن يخلو بها، لا بذهابه بها إلى المدرسة، ولا في غير ذلك، بل يكون معهما مَن تزول معه الخلوة وما يحصل معه الطُّمأنينة وتزول الريبة.","link":"https://binbaz.org.sa/fatwas/30107/ما-حكم-الخلوة-بساىق-الاسرة-الاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 134.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":5199,"question":"سماحة الشيخ، نرجو التكرم بتوجيه كلمة للنساء عن خطر التَّبرج والسُّفور؟","title":"ما أخطار التَّبرج والسُّفور على المجتمع؟","answer":"الجواب: الواجب على كل امرأةٍ الحذر من التبرج والسُّفور وأسباب الفتنة؛ لأن المرأة عورة، والرجال ميَّالون إليها، وهي ميَّالة إليهم، والمعصوم مَن عصمه الله، والمحفوظ مَن حفظه الله. فالواجب على الرجال الحذر، وعلى النساء الحذر، الرجل يحذر ويغُضّ بصره، ويحذر الخلوة، ويحذر كل أسباب الفتنة، والمرأة كذلك عليها أن تحذر أسباب الفتنة: من الخلوة بالرجل، والتبرج في الأسواق بإظهار المحاسن والمفاتن، والسفور الذي عند الأجانب، يقول الله جلَّ وعلا: وَقَرْنَ فِي بُيُوتِكُنَّ أي: الزمنَ بيوتكن، وَلَا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَى [الأحزاب:33]. قال العلماء: معنى التبرج: إظهار المحاسن والمفاتن من الرأس والرقبة والوجه والصدر والأقدام والسّيقان، كل هذه فتنة، فالواجب التَّستر، ولهذا قال : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، أطهر لقلوب الجميع من وراء حجاب، يعني: من وراء بابٍ أو سترٍ أو جدارٍ أو ملابس تستر، وقال جلَّ وعلا في النساء: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ الآية [النور:31]. فعلى الجميع التعاون على البر والتقوى: المرأة عليها أن تحتجب، وأن تبتعد عن التبرج، وألا تخرج إلى الأسواق إلا للحاجة، وإذا خرجت للحاجة تكون متسترةً بعيدةً عن الفتنة، سواء لبيتٍ أو للسوق أو لغير ذلك من الحاجات، فتكون متسترةً بعيدةً عن أسباب الفتنة، وعلى الرجال غضّ البصر، والحذر من مُغازلة النساء ومُتابعتهن، فعلى الرجل أن يحذر ويبتعد عن الفتنة، قال تعالى: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ الآية [النور:30]، ويقول سبحانه: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ [النور:31].","link":"https://binbaz.org.sa/fatwas/30143/ما-اخطار-التبرج-والسفور-على-المجتمع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 172.mp3","categories":["النظر والخلوة والاختلاط","نصائح وتوجيهات"]},{"id":5232,"question":"","title":"جواب وافٍ للشيخ ابن باز حول الحجاب والسّفور","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلَّى الله وسلَّم على رسول الله، وعلى آله وأصحابه. أما بعد: تكميلًا لسؤال مَن سأل عن الحجاب والسّفور: تقدم أنَّ الواجب هو التَّحجب والبُعد عن أسباب الفتنة على النساء غير القواعد، وتقدمت الأدلةُ في هذا الأمر، وأنَّ مَن أجاز للمرأة التي ليست من القواعد السفور فقد غلط، سواء حسن قصده أو ساء قصده، ومَن اجتهد في هذا فله أجر الاجتهاد، وإن فاته أجر الصواب. وقد تعلَّق المُبيحون للسُّفور بأحاديث جاء فيها بعضُ سفور النساء، وظنوا أنَّ هذا بعد الحجاب، وليس الأمر كذلك، بل الأحاديث التي فيها السفور إنما كان قبل الحجاب، بعدما نزل الحجابُ تقيدت المؤمنات بذلك وتحجبن. ومما تعلَّقوا به أيضًا حديث الخثعمية التي قالت للرسول ﷺ في يوم النحر في ليلة مزدلفة ليلة النحر: \"إنَّ فريضة الله على عباده أدركت أبي شيخًا كبيرًا لا يثبت على الراحلة، أفأحجّ عنه؟ قال: حُجِّي عن أبيك، وكانت تُخاطب النبيَّ ﷺ وهو على الراحلة، وردفه الفضل بن العباس، فجعل الفضل ينظر إليها وتنظر إليه، وجعل النبيُّ ﷺ يصرف وجه الفضل إلى الشقِّ الآخر، قالوا: هذا دليلٌ على أنها كانت سافرةً، وهذا بعد الحجاب، وفي آخر حياة النبي ﷺ. والجواب عن هذا: المنع، ليس هناك دليلٌ على أنها سافرة، فمجرد نظره إليها ونظرها إليه لا يتضمن السفور، ولا يستلزم السفور، فقد تنظر إليه من وراء الحجاب، وينظر إليها من وراء الحجاب، هذا أمرٌ واقعٌ، فينظر إلى قدّها وقامتها، وإلى ما يسمع من صوتها، وإلى غير ذلك، فلا يلزم من هذا أن تكون سافرةً. ثم لو فُرض أنها سافرة لكان هذا حجّة لمَن قال: يجوز السفور في الحجِّ خاصةً؛ لقوله ﷺ: ولا تنتقب المرأة، ولا تلبس القفازين، فنهاها أن تنتقب وهي محرمة في الحج والعمرة، فلو قُدر أنَّ هذه سافرة لكان هذا يتعلق بحال الإحرام، مع أن الصواب في حال الإحرام أنها لا تُسفر أيضًا، وأن عليها الحجاب حتى في حال الإحرام، وأن قوله ﷺ: لا تنتقب يعني: لا تلبس النِّقاب، وهو شيء يُصنع للوجه، ويُستر به الوجه، وفيه نقب للعين أو للعينين، هذا نُهيت المرأةُ أن تلبسه، كما نُهيت عن لبس القفازين، وهما غشاءان يكونان في اليدين، وهي نُهيت عن هذا وقت الإحرام في الحج والعمرة: لا تلبس القفازين، ولا تلبس النقاب الذي هو مصنوعٌ للوجه. أما أنها تُرخي خمارها أو جلباها على وجهها فهي غير ممنوعةٍ من هذا، ويحصل به الستر، ولهذا في حديث عائشة في حجّة الوداع قالت: \"كنا مع النبي ﷺ، فإذا دنا منا الرجالُ سدلت إحدانا جلبابها من فوق رأسها على وجهها، فإذا بعدوا كشفنا\"، وبينت أنهم كانوا يحتجبون ويخبؤون الوجوه حتى في حجّة الوداع، فدلَّ ذلك على أنَّ الوجه يُستر بعد الحجاب ويخمر، ولو في الحجِّ والعمرة. فعُلم بهذا أنَّ حديث الخثعمية لا حجَّة فيه لأصحاب السُّفور والقائلين بالسُّفور. ويتعلَّقون أيضًا بحديثٍ رواه أبو داود عن عائشة رضي الله عنها قالت: \"دخلتْ عليَّ أسماء بنت أبي بكر\" يعني: أختها رضي الله عن الجميع، زوجة الزبير، قالت: \"وعليها ثياب رقاق، فأعرض عنها النبيُّ ﷺ وقال: يا أسماء، إنَّ المرأة إذا بلغت المَحِيضَ لم يصلح أن يُرى منها سوى هذا وهذا وأشار إلى وجهه وكفيه\"، قالوا: فهذا دليلٌ على أنَّ المرأة تكشف وجهها وكفّيها للرجال الأجانب؛ لقوله ﷺ لأسماء: إنَّ المرأة إذا بلغت المحيض لم يصلح أن يُرى منها سوى هذا وهذا وأشار إلى وجهه وكفيه. والجواب: أنَّ هذا ضعيفُ الإسناد، منكر المتن، لا حجَّة فيه، أما نكارة المتن فلأنه لا يليق بأسماء وهي من خواصِّ المُهاجرات ومن خواص المؤمنات أن تكون بهذه المثابة، وأن تلبس ثيابًا رقاقًا عند الرسول ﷺ زوج أختها! لا يليق بها مع إيمانها وتقواها. أما من جهة الإسناد فهو ضعيفٌ عند أهل العلم لثلاث عللٍ في الإسناد، علل ثلاث تدل على ضعفه وعدم صحَّته: إحداها: أنه من رواية سعيد بن بشير، وهو ضعيفٌ لا يُحتج به. الثانية: أنه من رواية خالد بن بن دُرَيْك عن عائشة، ولم يسمع منها، فهو منقطع. الثالثة: أنه من رواية قتادة عن خالد بالعنعنة، وقتادة مدلس، وإذا عنعن لا تُقبل روايته، ولا يُحتج بها في غير \"الصحيحين\". فهذه ثلاث عللٍ في هذا الحديث، مع نكارة متنه. ولو فُرض أنه صحيحٌ لكان هذا قبل الحجاب، فإنَّ قبل الحجاب لا بأس للمرأة أن تكشف وجهها وكفّيها عند الرجال، ثم نُسخ ذلك، ومُنع ذلك بعد الحجاب؛ لأنه ليس في الحديث صراحة بأنَّ هذا كان بعد الحجاب، فيحتمل أنه قبل الحجاب لو صحَّ. فعُلم بهذا أنه لا حجَّة فيه؛ لضعفه ونكارة متنه، ولأنه ليس صريحًا في أنه بعد الحجاب، فلم تبقَ في أيدي هؤلاء المُدَّعين لسفور المرأة، وأنه لا بأس به، لم تبقَ في أيديهم حجَّة تُعارض الأدلة من الكتاب والسنة الدالة على وجوب الحجاب للمرأة بعد نزول آية الحجاب، وأنه الحق، ثم ما يُعلم عند أهل العلم والبصيرة ما في كشف الوجه من الفتنة وأسباب الخطر، فهذا المعنى الذي نزلت من أجله آيةُ الحجاب موجودٌ في كشف الوجه وإبرازه، فإن كشف وجوه الجميلات من النساء فتنة عظيمة، ومن حكمة الله  أن حرَّم ذلك، وسدَّ الباب، وقطع دابر هذا الشر؛ لما جاء به الكتاب العزيز والسنة المُطهرة. وأما القواعد من النساء -وهن العجائز- فأمرهن آخر، قال تعالى: وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لَا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ [النور:60]، فإذا كن بهذه المثابة: عجوز لا ترجو النكاح ولا تبرج بزينةٍ، فلا حرج عليها أن تكشف؛ لأنها ليست محلًّا للفتنة؛ لكونها عجوزًا غير متبرجةٍ بالزينة، ولا ترجو النكاح، ثم قال بعد ذلك: وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ [النور:60]، فبيَّن سبحانه أن تحجبهنَّ واستعفافهنَّ خيرٌ لهن ولو كن عجائز، وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ [النور:60]، فإذا كان استعفاف العجائز خيرًا لهن فكيف بحال الشابات ومَن في حكم الشابات؟! فالخطر واضح، والحكمة واضحة في المنع، والله جلَّ وعلا ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/30176/جواب-واف-للشيخ-ابن-باز-حول-الحجاب-والسفور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 296.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":5652,"question":"المُميِّز الذي فوق السبع إذا كان يعرف أمور النساء يُمنع من الدخول؟","title":"ما حكم دخول الصبي فوق سبعسنين على النساء؟","answer":"الجواب: هذا يرجع إلى المصلحة، يرجع إلى ولي الأمر، القرآن قال: وَإِذَا بَلَغَ الْأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا [النور:59]، إذا بلغ الحُلم، أما قبل ذلك فيُمنع في الأحوال الثلاثة التي بيَّنها الله في سورة النور.[1]","link":"https://binbaz.org.sa/fatwas/31689/ما-حكم-دخول-الصبي-فوق-سبع-سنين-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/albidayat walnihaya 002.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":5722,"question":"منذ زمن دعت وسائل الإعلام بأشكالها خارج البلاد الإسلامية إلى ظهور المرأة في ميدان الرجل للتقدم، ثم تلتها صحف بلدنا بالدعوة، فهل بقاء المرأة في حدودها الحالية يعتبر تخلفًا للأمة، وهل يدوم سكوت العلماء حتى تشتد نزعة المرأة إلى ما لا يحمد عقباه؟","title":"خطورة مخالطة المرأة للرجال","answer":"الجواب: وهذا من الداء الذي ينشره الأعداء، ويستغل الأعداء جهل الجاهلين، وجهل الكثير من الشباب، فينشرون بينهم هذه الدعوة إلى ظهور المرأة، وبروزها في ميدان العلم بين الرجال، وفي المدارس، وفي كل مكان مع الصبي جنبًا إلى جنب حتى تكثر الفاحشة، ويعم الفساد، وتنحدر الأخلاق إلى أخلاق سافلة، أخلاق بهيمية، هذه مقاصد أعداء الله. فالواجب هو بقاء المرأة على حالها الإسلامية، أن تكون في بيتها معلمة لأولادها، وأطفالها مصلحة لبيتها، معتنية بزوجها، وإذا كانت عندها فضل تنفع المسلمين في تعليم البنات في مدارس البنات، في الطب، والتمريض للنساء فيما يتعلق بالنساء، هذه حدودها، وبهذا يكون لها النجاة، ويكون لشعبها، ومجتمعها الخير والفوز والصلاح. أما إذا خالطت الشباب في مدارسهم، وفي مجتمعاتهم، وصرن كاتبات في المكاتب ... وتعمل جنبًا إلى جنب مع الرجل، صار ذلك الفساد، وصار الخراب، والدمار، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/1026/خطورة-مخالطة-المراة-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_48.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":5735,"question":"خروجها مع السائق إلى المدرسة؟","title":"حكم خروج المرأة مع السائق","answer":"الجواب:  هذا خطر، نبهنا عليه غير مرة، مع السائق وغير السائق، مع أجنبي كونها تكون معه في غرفة، أو في حجرة يخلو بها ما يجوز، أو في السيارة مع السائق ما يجوز، بل لا بدّ أن يكون معها غيرها، أو السائق معه محرم، أو يكون معها امرأة، أو رجل آخر، حتى لا تصير خلوة، النبي ﷺ قال: لا يخلون رجل بامرأة فإن الشيطان ثالثهما نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/1055/حكم-خروج-المراة-مع-الساىق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_72.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":5785,"question":"تقولون في قصة عبدالرحمن بن عوف: أنه عندما قال له أخوه: انظر إلى إحدى زوجاتي؛ فهل النظر بالنسبة للخاطب في المرأة حلال؟","title":"هل نظر الخاطب لمخطوبته جائز؟","answer":"الجواب:  نعم، النبي ﷺ أمر الخاطب أن ينظر، قال: إذا خطب أحدكم امرأة فإن استطاع أن ينظر إلى ما يدعوه إلى نكاحها فليفعل، فإن ذلك أقرب إلى أن يؤدم بينكما فالنظر إلى المخطوبة لا بأس به، من غير خلوة.  وجاءه رجل ذكر له أن زواج امرأة، أي أراد الزواج بها، أو عقد عليها، فقال: أنظرت إليها؟ قال: لا، قال: اذهب، فانظر إليها رواه مسلم في الصحيح، فهذا لا بأس به، بل هذا من أسباب الأدم بينهما، يعني: الجمع بينهما، واستقامة النكاح بينهما إذا تيسر ذلك، إذا سمح له أهله بذلك من غير خلوة، بل مع وجود محرمها، أو أمها، ونحو ذلك ممن حضوره ينافي الخلوة.  وقد ذكر جابر بن عبدالله الأنصاري  أنه خطب امرأة، فأراد أن ينظر إليها، قال: فجعلت أتتبع النخل، وهي في النخل في مزارع الأنصار، نخلة خلف نخلة يختبي لها وراء النخل، حتى رأى منها ما أعجبه، فخطبها.  فالمقصود: أنه إذا تيسر أن يراها بالإذن، والعلم فلا بأس، وإن لم يتيسر ذلك، ورآها من غير علمها، من فرجة، أو من وراء النخل، أو من كذا، أو من كذا من الطرق التي ليس فيها محذور في الشرع، وليس فيها خلوة فلا بأس. السؤال: الأهل يأثمون إذا لم يمكنوا الخاطب من الرؤية؟ الجواب: الظاهر لا يأثموا، ولكن الأولى، والأفضل أن يمكنوه؛ لأن هذا من أسباب الإدام بينهما، والجمع بينهما، والنبي أمر به -عليه الصلاة والسلام- قال: اذهب فانظر إليها فلما أمره أن ينظر؛ دل ذلك على أنه يستحب لهم أن يمكنوه، ما دام أمر به النبي فتمكين الرجل الذي أمره النبي أن ينظر تمكينه أولى. لكن بعض الناس من عاداتهم ألا يفعلوا، ويصعب عليهم ذلك، وبعضهم يقول: أخشى أن يراها فلا تعجبه، ثم يتحدث بين الناس، ثم ينفر الناس منها بعد ذلك، لهم تأويلات في هذا.","link":"https://binbaz.org.sa/fatwas/1120/هل-نظر-الخاطب-لمخطوبته-جاىز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_127.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":5893,"question":"تزوجت امرأة، وألح بها زوجها، وهي من جيزان ألا تتستر عن إخوانه، وإلا فيطلقها، ماذا تفعل مع أنها خائفة من الطلاق؟ ويفعل هذه الأفعال أهل الجنوب كلهم، فنرجو مشكورين رسالة لمن يبعدهم الجهل عن هذا، وخاصة أهل جيزان، وعسير؟","title":"حكم كشف المرأة وجهها أمام إخوان زوجها","answer":"الجواب: لا يجوز للرجل أن يفتح المجال لزوجته في الظهور للرجال، هذا لا يجوز له، ولا يليق منه أن يكون هكذا ضعيفًا متساهلًا مع أهله حتى يكشفن لإخوانه، أو لأعمامه، أو لزوج أخته، أو لبني عمها، وما أشبه ذلك، كما يفعل في الجنوب، وفي غير الجنوب، هذا غلط! لا يجوز هذا، وليس لها طاعته؛ إنما الطاعة في المعروف، فعليها أن تتحجب، وتتستر، ولو طلقها إذا طلقها فسوف يعطيها الله خيرًا منه -إن شاء الله- قال الله -جل وعلا-: وَإِنْ يَتَفَرَّقَا يُغْنِ اللَّهُ كُلًّا مِنْ سَعَتِهِ [النساء:130].  وروي عنه -عليه السلام- أنه قال: من ترك شيئًا لله؛ عوضه الله خيرًا منه وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] ولا يجوز للزوج أن يتوعدها بالطلاق إذا تحفظت، وتعاطت ما هو من أسباب العفة، والسلامة، والبعد عن الدياثة، والله المستعان. وفي رسالة في الحجاب موجزة سوف تنشر -إن شاء الله- في الجنوب، وفي غير الجنوب.","link":"https://binbaz.org.sa/fatwas/1251/حكم-كشف-المراة-وجهها-امام-اخوان-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_247.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":5902,"question":"تزوجت امرأة، وألح بها زوجها، وهي من جيزان ألا تتستر عن إخوانه، وإلا فيطلقها، ماذا تفعل مع أنها خائفة من الطلاق؟ ويفعل هذه الأفعال أهل الجنوب كلهم، فنرجو مشكورين رسالة لمن يبعدهم الجهل عن هذا، وخاصة أهل جيزان، وعسير؟","title":"حكم كشف المرأة وجهها أمام إخوان زوجها","answer":"الجواب: لا يجوز للرجل أن يفتح المجال لزوجته في الظهور للرجال، هذا لا يجوز له، ولا يليق منه أن يكون هكذا ضعيفًا متساهلًا مع أهله حتى يكشفن لإخوانه، أو لأعمامه، أو لزوج أخته، أو لبني عمها، وما أشبه ذلك، كما يفعل في الجنوب، وفي غير الجنوب، هذا غلط! لا يجوز هذا، وليس لها طاعته؛ إنما الطاعة في المعروف، فعليها أن تتحجب، وتتستر، ولو طلقها إذا طلقها فسوف يعطيها الله خيرًا منه -إن شاء الله- قال الله -جل وعلا-: وَإِنْ يَتَفَرَّقَا يُغْنِ اللَّهُ كُلًّا مِنْ سَعَتِهِ [النساء:130].  وروي عنه -عليه السلام- أنه قال: من ترك شيئًا لله؛ عوضه الله خيرًا منه وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] ولا يجوز للزوج أن يتوعدها بالطلاق إذا تحفظت، وتعاطت ما هو من أسباب العفة، والسلامة، والبعد عن الدياثة، والله المستعان. وفي رسالة في الحجاب موجزة سوف تنشر -إن شاء الله- في الجنوب، وفي غير الجنوب.","link":"https://binbaz.org.sa/fatwas/1251/حكم-كشف-المراة-وجهها-امام-اخوان-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_247.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":5923,"question":"......؟","title":"حكم جلوس الرجال والنساء في مجلس واحد للتحدث","answer":"الجواب: إذا كان النساء مع النساء، والرجال مع الرجال ما في كشف للرجال، ولا إظهار زينة؛ لا بأس. أما أن يجتمعوا جميعًا من غير تحجب، ومن غير مبالاة؛ فلا يجوز هذا، بل إذا كانت النساء مع النساء في وقت ما ليس فيه سهر، ولا إضاعة أوقات، ولا يجتمعن على باطل، لا بأس، إذا زار النساء الجيران، هذا طيب بين الجيران، لكن بشرط أن يكون ذلك على غير سوء، على غير عمل صالح، يعني حتى لا يكون هذا على عمل سيئ، ولا يكون معه التكشف للجار، أو لزوج الجارة، أو ما أشبه ذلك، بل يكون معه احتشام، وتستر، وحجاب، والنساء مع النساء، والرجال مع الرجال في غير معصية، بل زيارات مناسبة في حد مناسب، وفي اجتماع مناسب للتنفيس عن النفس، والترويح عنها، وللتحدث الذي جرت به العادة بين الجيران، فهذا لا بأس به.","link":"https://binbaz.org.sa/fatwas/1268/حكم-جلوس-الرجال-والنساء-في-مجلس-واحد-للتحدث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_255.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":6015,"question":"أفيدوني عن كشف المرأة عن أخي زوجها، وكذلك زوجة العم، والخال، جزاكم الله خير الجزاء؟","title":"حكم كشف المرأة لأخي زوجها وعمه وخاله","answer":"الجواب:  العم، والخال، وأخو الزوج كلهم ليسوا محارم، فليس لها أن تكشف لأخي زوجها، ولا لعم زوجها، ولا لخال زوجها؛ لأنهم ليسوا محارم.  وإنما المحارم أبو الزوج، وابن الزوج، وابن ابنه، أولاده، وآباؤه هم المحارم، فلها أن تكشف لأبي زوجها، ولابن زوجها، ولها أن تكشف لأبناء زوجها، وأبناء أبناء زوجها، وأبناء بنات زوجها؛ لأنهم أولاده؛ لقوله -جل وعلا-: أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ [النور:31] فالبعولة هم الأزواج. وأما الإخوة، إخوة الزوج، وأخواله، وأعمامه فليسوا محارم، ولا يجوز الكشف لهم، ولا الخلوة بأحد منهم.","link":"https://binbaz.org.sa/fatwas/1395/حكم-كشف-المراة-لاخي-زوجها-وعمه-وخاله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_351.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":6169,"question":"إذا طلب الزوج مقابلة المرأة دون خلوة، فما هو الدليل على ذلك، والرسول ﷺ يقول: كل المرأة عورة؟","title":"حكم النظر إلى المخطوبة وضوابط ذلك","answer":"الجواب: لا حرج فيها، المرأة عورة، مثل ما جاء في الحديث، لكن استثنى النبي ﷺ من ذلك ما يتعلق بالخاطب إذا خطب، وأحب أن ينظر فلا بأس، النبي ﷺ قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها ما يدعوه إلى نكاحها فليفعل إذا استطاع أن ينظر، ولو من بعد من غير علمها، فلا بأس، خطب جابر بن عبدالله الأنصاري  امرأة من الأنصار ولم يرها قال: فجعلت أتتبع النخل لعلي أراها حتى رأى منها ما أعجبه منها فتزوجها. فالمقصود: أنه إذا تيسر له أن يراها ولو من بعيد، ولو من طريق وجوده في بيت أهلها، فتمر وهم راضون بذلك، وما أشبه ذلك، وإذا تيسر أن أباها، أو أخاها يحضرونه عندهم، ويدخلونها عليه، ويراها بغير خلوة بحضرة أبيها، أو أخيها، أو أمها، أو نحو ذلك فلا بأس، هذا أذن فيه النبي ﷺ ورخص.","link":"https://binbaz.org.sa/fatwas/1628/حكم-النظر-الى-المخطوبة-وضوابط-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_519.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":6177,"question":"إذا طلب الزوج مقابلة المرأة دون خلوة، فما هو الدليل على ذلك، والرسول ﷺ يقول: كل المرأة عورة؟","title":"حكم النظر إلى المخطوبة وضوابط ذلك","answer":"الجواب: لا حرج فيها، المرأة عورة، مثل ما جاء في الحديث، لكن استثنى النبي ﷺ من ذلك ما يتعلق بالخاطب إذا خطب، وأحب أن ينظر فلا بأس، النبي ﷺ قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها ما يدعوه إلى نكاحها فليفعل إذا استطاع أن ينظر، ولو من بعد من غير علمها، فلا بأس، خطب جابر بن عبدالله الأنصاري  امرأة من الأنصار ولم يرها قال: فجعلت أتتبع النخل لعلي أراها حتى رأى منها ما أعجبه منها فتزوجها. فالمقصود: أنه إذا تيسر له أن يراها ولو من بعيد، ولو من طريق وجوده في بيت أهلها، فتمر وهم راضون بذلك، وما أشبه ذلك، وإذا تيسر أن أباها، أو أخاها يحضرونه عندهم، ويدخلونها عليه، ويراها بغير خلوة بحضرة أبيها، أو أخيها، أو أمها، أو نحو ذلك فلا بأس، هذا أذن فيه النبي ﷺ ورخص.","link":"https://binbaz.org.sa/fatwas/1628/حكم-النظر-الى-المخطوبة-وضوابط-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_519.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":6244,"question":"إذا حضرت أنا وزوجتي، وأخي، وزوجته في مجلس واحد فهل هذا جائز؟","title":"حكم اجتماع الأخوين مع زوجتيهما في مجلس واحد","answer":"الجواب: لا بأس أن تجتمع العائلة في مجلس واحد، لكن مع الحجاب، والتستر، والبعد عما حرم الله، والمرأة زوجة أخيك عندكم، أو زوجة خالك، أو زوجة عمك، أو ما أشبه ذلك عندكم في المجلس، أو في البيت، فهذا لا محذور فيه، هذا من عهد النبي إلى يومنا هذا، الناس يتزاورون، ويزور بعضهم بعضًا، ويلتقي بعضهم بعضًا، ويزور الأجنبي بلاد أصدقائه، وبيت أصدقائه، ولو كان غير أخ، ويكون نساؤه مع نسائهم، وربما اجتمعوا جميعًا، لكن مع الحجاب، والستر، والبعد عن الكلمات الخبيثة النابية، هذا كله لا حرج فيه. السؤال: وإذا لم يكن هناك حجاب؟ الجواب: ما يجوز يجب عليها أن تستر، وإلا تبتعد، لا تجلس معهم، وإذا كانت لا بدّ من جلوسها فيقم هو الذي ليس محرمًا لها، أو يغض بصره، ويعرض عنها؛ حتى يكون امتثل أمر الله.","link":"https://binbaz.org.sa/fatwas/1736/حكم-اجتماع-الاخوين-مع-زوجتيهما-في-مجلس-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_579.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":6304,"question":"بعض الأسر يأكل بعضهم مع البعض الآخر، مثال ذلك: أهل البيت الواحد، الإخوة كل منهم عنده زوجته، فيأكل بعضهم مع بعض، وإذا قيل لهم: هذا لا يجوز؛ يحتجون بأن الدين يُسر، وليس بعسر، وفصل الزوجات عن الإخوة هذا فيه عُسر، فنرجو بيان الحق بدليله؟","title":"ما حكم اختلاط الأقارب بدعوى أن الدين يُسْر؟","answer":"الجواب: هذا من تزيين الشيطان أيضًا كونهم يدعون أن الدين يُسر، ويبيحون المعاصي، هذا من البلاء، هو يُسر فيما يسَّر الله، لا في إباحة المعاصي، يُسرٌ إذا مرضت؛ تفطر في رمضان، إذا عجزت عن القيام؛ تصلي قاعدًا، إذا عجزت عن الماء؛ تصلي بالتيمم، هذا معنى اليُسر، ما هو معنى اليسر أنك إذا اشتقت إلى النساء تنظر إليهن، وتجلس معهن، وتخلو بهن، لا.  اليُسر في حفظ محارم الله، وترك ما حرم الله، وأداء ما أوجب الله، هذا هو اليسر، وإذا عجز عن شيء؛ أبدله الله شيئًا آخر، أيسر عليه في شريعة الله تيسيرًا من ربنا  وأما أنه يبيح لك المعاصي، ويبيح لك التمتع بزوجة أخيك، بزوجة عمك، بزوجة جارك، هذا منكر، هذا كله من المفاسد، يفضي إلى الزنا، والفواحش، ولكن أكثر الناس لا يشعرون، ولا يعقلون. وليس للرجل أن تأكل معه زوجة أخيه، أو زوجة عمه، وهي ليست مَحْرمًا له، بل يجلس النساء، وحدهن، والرجال وحدهم.","link":"https://binbaz.org.sa/fatwas/1907/ما-حكم-اختلاط-الاقارب-بدعوى-ان-الدين-يسر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_690.mp3","categories":["النظر والخلوة والاختلاط","الأخلاق المذمومة"]},{"id":6318,"question":"بعض الأسر يأكل بعضهم مع البعض الآخر، مثال ذلك: أهل البيت الواحد، الإخوة كل منهم عنده زوجته، فيأكل بعضهم مع بعض، وإذا قيل لهم: هذا لا يجوز؛ يحتجون بأن الدين يُسر، وليس بعسر، وفصل الزوجات عن الإخوة هذا فيه عُسر، فنرجو بيان الحق بدليله؟","title":"ما حكم اختلاط الأقارب بدعوى أن الدين يُسْر؟","answer":"الجواب: هذا من تزيين الشيطان أيضًا كونهم يدعون أن الدين يُسر، ويبيحون المعاصي، هذا من البلاء، هو يُسر فيما يسَّر الله، لا في إباحة المعاصي، يُسرٌ إذا مرضت؛ تفطر في رمضان، إذا عجزت عن القيام؛ تصلي قاعدًا، إذا عجزت عن الماء؛ تصلي بالتيمم، هذا معنى اليُسر، ما هو معنى اليسر أنك إذا اشتقت إلى النساء تنظر إليهن، وتجلس معهن، وتخلو بهن، لا.  اليُسر في حفظ محارم الله، وترك ما حرم الله، وأداء ما أوجب الله، هذا هو اليسر، وإذا عجز عن شيء؛ أبدله الله شيئًا آخر، أيسر عليه في شريعة الله تيسيرًا من ربنا  وأما أنه يبيح لك المعاصي، ويبيح لك التمتع بزوجة أخيك، بزوجة عمك، بزوجة جارك، هذا منكر، هذا كله من المفاسد، يفضي إلى الزنا، والفواحش، ولكن أكثر الناس لا يشعرون، ولا يعقلون. وليس للرجل أن تأكل معه زوجة أخيه، أو زوجة عمه، وهي ليست مَحْرمًا له، بل يجلس النساء، وحدهن، والرجال وحدهم.","link":"https://binbaz.org.sa/fatwas/1907/ما-حكم-اختلاط-الاقارب-بدعوى-ان-الدين-يسر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_690.mp3","categories":["النظر والخلوة والاختلاط","الأخلاق المذمومة"]},{"id":6485,"question":"أنا إنسان -والحمد لله- مستقيم ولا أزكي نفسي، ولكن عندما أرى النساء أميل إليهن ببصري، وليس مستمرًا، وبعد ذلك النظر أتبعه بالاستغفار، والصلاة، وأندم، ولكن سريعًا ما أرجع للنظر مرة ثانية، علمًا بأنني لا أزني، ولا أميل للزنا؟","title":"نصيحة لمن يبتلى بالنظر إلى النساء","answer":"الجواب: عليك يا عبدالله أن تغض بصرك، وأن تجتهد في غض بصرك؛ لأن الله يقول: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ [النور:30] فأنت مأمور بغض الأبصار، والحرص، والنبي ﷺ سئل عن نظر الفجأة، فقال: لك الأولى، وليست لك الأخرى قال: اصرف بصرك فإذا ابتلي بالنظر؛ فليصرف بصره، ولا يتبع النظرة النظرة، هذا لا يجوز، ولو كنت تستغفر بعد ذلك، ليس لك أن تتبع النظرة النظرة، بل عليك أن تغض بصرك، وتعرض عما تبتلى به من النساء إعراض المؤمن الذي يخاف الله  وأما كونك تستغفر بعد هذا، هذا عمل صالح طيب، واجب عليك، لكن عليك قبل هذا أن تعرض عن المعصية، وأن تبتعد عن المعصية أولًا قبل أن تقع، وعليك أن تغض بصرك، وتصرف بصرك، وتحذر شر النظرات، فكم من نظرة أعقبت حسرات -والعياذ بالله- وكم من نظرة أعقبت شرًا عظيمًا، وفسادًا كبيرًا، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2238/نصيحة-لمن-يبتلى-بالنظر-الى-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_858.mp3","categories":["النظر والخلوة والاختلاط","الرقائق"]},{"id":6504,"question":"ابتلينا في بلادنا بالمدارس المختلطة بين البنين والبنات، فتيان وفتيات، وأنا شاب متدين والحمد لله، وعينت مدرسًا بإحدى هذه المدارس المختلطة، حيث لا يوجد مدرس للبنين فقط في بلدنا، ولكن توجد مدرسة بعيدة عن بلدي، تحتاج لمجهود شاق طوال اليوم، ومصاريف كثيرة، وراتبي صغير وقليل، فهل أبقى في المدرسة المختلطة، أم أطلب النقل إلى المدرسة الأخرى، ولو دفعت مالًا للقائمين؟","title":"حكم التدريس في المدارس المختلطة","answer":"الجواب: انظر ما هو أصلح لقلبك، إذا كان تخشى على نفسك؛ فانتقل عنها، وإذا كنت ترى أن وجودك فيه صلاح للمدرسة، وحثهم على طاعة الله، وتحث البنات على الستر، وتغض بصرك، وتعمل ما ينفع الأمة تفعل.  اعمل ما هو الأصلح إن كنت تخشى على نفسك من وجود البنات، فاتق الله، واحذر، وانتقل عن هذه المدرسة، إلى مدارس أخرى، أو إلى عمل آخر، وإن كنت ترى أن وجودك في المدرسة فيه مصلحة للمسلمين، ونفع للمسلمين، وتستطيع أن تغض بصرك، وأن تأمرهن بالحجاب، والتستر، وتجتهد مع إخوانك الباقين في هذا الأمر، فأنت على ثغر عظيم من ثغور الإسلام، فاتق الله في ذلك، واعمل ما تستطيع من الخير، وإلا فانتقل.","link":"https://binbaz.org.sa/fatwas/2261/حكم-التدريس-في-المدارس-المختلطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_884.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":6507,"question":"هل يجوز مراسلة الخطيب لخطيبته قبل أن يعقد عليها؟ وهل الخطبة مشروعة؟","title":"حكم مراسلة الخاطب لخطيبته قبل العقد","answer":"الجواب: لا بأس كأن يراسلها بشيء ينفعها، هدية، أو غير ذلك، لا بأس إذا كان تم الخطبة بينهما، أو أراد أن يرغبهما في ذلك؛ أرسل إلى أهلها، وإليها بهدايا يرجوهم أن يوافقوا على الزواج؛ لا بأس بذلك، المهم أن يكون ذلك عن طريق شرعية، لا عن طريق خلوة، ولا عن طريق مقابلة خبيثة، ولكن عن طريق التودد إلى أهلها، وإليها بالهدايا حتى يستجيب لرغبته؛ لا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/2268/حكم-مراسلة-الخاطب-لخطيبته-قبل-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_891.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":6526,"question":"ابتلينا في بلادنا بالمدارس المختلطة بين البنين والبنات، فتيان وفتيات، وأنا شاب متدين والحمد لله، وعينت مدرسًا بإحدى هذه المدارس المختلطة، حيث لا يوجد مدرس للبنين فقط في بلدنا، ولكن توجد مدرسة بعيدة عن بلدي، تحتاج لمجهود شاق طوال اليوم، ومصاريف كثيرة، وراتبي صغير وقليل، فهل أبقى في المدرسة المختلطة، أم أطلب النقل إلى المدرسة الأخرى، ولو دفعت مالًا للقائمين؟","title":"حكم التدريس في المدارس المختلطة","answer":"الجواب: انظر ما هو أصلح لقلبك، إذا كان تخشى على نفسك؛ فانتقل عنها، وإذا كنت ترى أن وجودك فيه صلاح للمدرسة، وحثهم على طاعة الله، وتحث البنات على الستر، وتغض بصرك، وتعمل ما ينفع الأمة تفعل.  اعمل ما هو الأصلح إن كنت تخشى على نفسك من وجود البنات، فاتق الله، واحذر، وانتقل عن هذه المدرسة، إلى مدارس أخرى، أو إلى عمل آخر، وإن كنت ترى أن وجودك في المدرسة فيه مصلحة للمسلمين، ونفع للمسلمين، وتستطيع أن تغض بصرك، وأن تأمرهن بالحجاب، والتستر، وتجتهد مع إخوانك الباقين في هذا الأمر، فأنت على ثغر عظيم من ثغور الإسلام، فاتق الله في ذلك، واعمل ما تستطيع من الخير، وإلا فانتقل.","link":"https://binbaz.org.sa/fatwas/2261/حكم-التدريس-في-المدارس-المختلطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_884.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":6549,"question":"إخوة يجلسون مع بعض زوجاتهم في جلسة واحدة لتناول القهوة، أو للذكر، فهل هذا جائز؟ وإن كان جائزًا فما حكم من لم يكونوا إخوة وهم على هذه الصورة ؟","title":"جواز جلوس الإخوة مع زوجاتهم بشرط التزام الحجاب الشرعي","answer":"الجواب: ليس لزوج الأخت، ولا زوجة الأخ، ونحو ذلك بالجلوس مع أخي زوجها، وليس للمرأة مع زوج أختها أن تبدي له شيئًا من محاسنها، لا وجه، ولا غيره، بل عليها التستر بالحجاب، فإن جلست معهم مع الحجاب، والتستر، وعدم التبرج؛ فلا بأس، إذا جلست، وسلمت عليهم باللسان مع الحجاب الشرعي في وجهها، وسائر بدنها؛ فلا بأس ولا حرج. أما أن تجلس وهي تبدي لهم محاسنها، ما يجوز، حتى ولو كانت غير جالسة معهم، ولو كانت في مكان آخر، ليس لها أن تبدي محاسنها، بل عليها أن تحتجب عن زوج أختها، وعن أخي زوجها، وعن عم زوجها، وعن سائر أقاربها غير المحارم مطلقًا.","link":"https://binbaz.org.sa/fatwas/2378/جواز-جلوس-الاخوة-مع-زوجاتهم-بشرط-التزام-الحجاب-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_912.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":6625,"question":"هل يجوز للأخ المسلم عند خطبته لفتاة مسلمة أن يجلس معها ليعلمها القرآن، ويتعرف على أخلاقها قبل العقد بها، والارتباط بها ؟","title":"حكم مجالسة المخطوبة للتعرف على أخلاقها","answer":"الجواب: له أن ينظر إليها فقط، أما يجلس معها، ويخلو بها ليس له ذلك، لا للقرآن، ولا لغيره، لكن ينظر إليها بحضرة أبيها، أو أخيها، أو غيرهم، لا يخلو بها، وينظر إليها؛ لعل الله يأدم بينهما؛ لعلها توافقه، ثم بعد هذا يعقد عليها إذا ناسبته، أما أنه يخلو بها، أو يجلس معها للتعليم، فالشيطان لا يؤمن أن ينزغ بينهما. السؤال: مرة، أو مرات؟ الجواب: النظرة الواحدة الكافية، وإذا مكثت ما رآها النظر الكافي، لا بأس أن ينظر مرة أخرى؛ ليتحقق عنها ما يريد.","link":"https://binbaz.org.sa/fatwas/2482/حكم-مجالسة-المخطوبة-للتعرف-على-اخلاقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_5739.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":6640,"question":"هل يجوز للأخ المسلم عند خطبته لفتاة مسلمة أن يجلس معها ليعلمها القرآن، ويتعرف على أخلاقها قبل العقد بها، والارتباط بها ؟","title":"حكم مجالسة المخطوبة للتعرف على أخلاقها","answer":"الجواب: له أن ينظر إليها فقط، أما يجلس معها، ويخلو بها ليس له ذلك، لا للقرآن، ولا لغيره، لكن ينظر إليها بحضرة أبيها، أو أخيها، أو غيرهم، لا يخلو بها، وينظر إليها؛ لعل الله يأدم بينهما؛ لعلها توافقه، ثم بعد هذا يعقد عليها إذا ناسبته، أما أنه يخلو بها، أو يجلس معها للتعليم، فالشيطان لا يؤمن أن ينزغ بينهما. السؤال: مرة، أو مرات؟ الجواب: النظرة الواحدة الكافية، وإذا مكثت ما رآها النظر الكافي، لا بأس أن ينظر مرة أخرى؛ ليتحقق عنها ما يريد.","link":"https://binbaz.org.sa/fatwas/2482/حكم-مجالسة-المخطوبة-للتعرف-على-اخلاقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_5739.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":6781,"question":"هل يجوز عمل المرأة مدرسة تعلم الرجال، والنساء، والشباب، والفتيات في مدرسة مختلطة للطلبة، والطالبات معًا؟","title":"حكم تدريس المرأة في مدرسة مختلطة","answer":"الجواب: لا، هذا يسبب الفتنة، ولكن تعلم النساء، تعلم الطالبات وتعلم أطفال الحضانة من دون السبع السنين، هذا لا بأس به، أولاد الحضانة، وأما أن تكون مدرسة للكبار، أو للمختلطين الرجال، والنساء؛ فهذا لا يجوز، وفيه من الفتنة، والشر ما فيه -نسأل الله السلامة-.","link":"https://binbaz.org.sa/fatwas/2654/حكم-تدريس-المراة-في-مدرسة-مختلطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1150.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":6999,"question":"طالبة بكلية التجارة في السنة النهائية في الدراسة، جئت إلى السعودية لأقيم مع زوجي، وأريد الآن أن أعود إلى مصر ، وأريد أن أكمل دراستي في الكلية، ولكن هناك اختلاط في الجامعة، كما أن الأوضاع داخل الجامعة غير إسلامي، مع وجود طلاب في الكلية بجوارنا،  كما أنني إذا لم أكمل دراستي، فهذا يسبب غضب والدتي علي، فماذا أفعل؟","title":"حكم دراسة البنت في الجامعة التي فيها اختلاط","answer":"الجواب:\n\nلا تكملي، ليس لها أن تكمل ما دام فيه الاختلاط، والاجتماع بالشباب، هذا يفضي إلى فساد كبير، فلا تكمل، تكمل في بيتها ما يسر الله لها من التعليم، وتسمع من الإذاعة الشيء الطيب، إذاعة القرآن في السعودية، والإذاعات الأخرى التي فيها كلام طيب، تقرأ القرآن تستفيد، ولو غضب أبواها، فإن الطاعة إنما هي لله ولرسوله، قال النبي ﷺ: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق.\n\nفالإنسان لا يطيع والده في المعصية، ولا أمه في المعصية، ولا أميره في المعصية، ولا يطيع زوجته في المعصية، ولا تطيع زوجها في المعصية، إنما الطاعة في المعروف، طاعة الله مقدمة على الجميع، فإذا كان الدرس في الجامعة يفضي بها إلى الفساد، واختلاطها بالشباب؛ فهذا محرم عليها، وقد أعطاها الله من العلم في الثانوي، وفي ما قبله ما يكفيها -إن شاء الله والحمد لله-.\n\nالسؤال: هي في سنة رابعة في الكلية، وما بقي إلا سنة واحدة فقط؟\n\nالجواب: ولو ولو، يكفيها الذي حصل -إن شاء الله-. \n\nالسؤال: إذا كان في طلبة داخل الجامعة، لكن فيه فصل، يعني الطلبة يجلسون لحالهم، والطالبات... فقط، ما في جدار بينهم، والدكتور أمامهم وهل..؟\n\nالجواب: هذا قد يقال بالجواز إذا كانوا على جانب، وهن متسترات، ومحتجبات، أما مع عدم ذلك فالشر حاصل، والبلاء حاصل، ثم خروجهم جميعًا، ودخولهم جميعًا يفضي إلى ذلك، فالذي يظهر أنه ممنوع حتى ولو كانوا على جانب؛ لأن اختلاطهم بهن عند الدخول، والخروج، والإشارات تفضي إلى شر كثير.","link":"https://binbaz.org.sa/fatwas/2916/حكم-دراسة-البنت-في-الجامعة-التي-فيها-اختلاط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1364.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":7001,"question":"هل زوج الأخت يعتبر محرمًا للأخت الأخرى مؤقتًا، بحيث يجوز أن يختلي بها، وكذلك عمة البنت؟","title":"حكم الخلوة بزوج الأخت وعمة الزوجة","answer":"الجواب:\n\nلا، زوج الأخت ليس محرمًا لها، ليس محرمًا لأخت زوجته، زوج الأخت ونحوه، وكذلك العمة التي يحرم عليه نكاحها مع البنت، لا يجمع بينهما، وهكذا خالتها، لأن هذا تحريم مؤقت، فلا يكون محرمًا، زوج أختها، وهكذا زوج عمتها، وهكذا زوج خالتها، وهكذا .. عمة الزوجة، وأخت الزوجة، وخالة الزوجة، لسن محارم للزوج؛ لأنهن محرمات عليه، فلو طلق أختهن، أو بنت أخيهن، أو بنت أختهن؛ جاز له النكاح بعد العدة.\n\nفالحاصل: أن بعض الرجال يتساهل مع بعض النساء، مع زوج أختها، ويتساهل بعض الناس مع  أخي زوجها، أو عم زوجها، وهذا غلط، لا يجوز، لا يجوز للمرأة أن تتساهل مع أخي زوجها، ليس محرمًا لها، وليس عمه محرمًا لها، ولا خاله. \n\nأبوه وولده هما المحارم، أما أخو الزوج، وعم الزوج، وابن عم الزوج، وخال الزوج، فليسوا محارم، وكذلك زوج الأخت، وزوج العمة، وزوج الخالة، ليسوا محارم، المحرم زوج بنتها، وزوج أمها، هذا هو المحرم، أما زوج أختها، أو زوج عمتها، أو زوج خالتها فليسوا محارم، يجب الحجاب والتحفظ عنه.\n\nالسؤال: كان بعض الناس.. محرما لها؟\n\nالجواب: ماذا؟\n\nالطالب: بعض الناس ينسب كلاما للشافعي على أن زوج أختها محرم لها؟\n\nالجواب: لا ما قاله الشافعي ولا غيره، محرم إجماعًا لا الشافعي، ولا غيره... لأن هذا تحريم مؤقت ما تحريم مطلقًا.","link":"https://binbaz.org.sa/fatwas/2945/حكم-الخلوة-بزوج-الاخت-وعمة-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1393.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":7011,"question":"هل زوج الأخت يعتبر محرمًا للأخت الأخرى مؤقتًا، بحيث يجوز أن يختلي بها، وكذلك عمة البنت؟","title":"حكم الخلوة بزوج الأخت وعمة الزوجة","answer":"الجواب:\n\nلا، زوج الأخت ليس محرمًا لها، ليس محرمًا لأخت زوجته، زوج الأخت ونحوه، وكذلك العمة التي يحرم عليه نكاحها مع البنت، لا يجمع بينهما، وهكذا خالتها، لأن هذا تحريم مؤقت، فلا يكون محرمًا، زوج أختها، وهكذا زوج عمتها، وهكذا زوج خالتها، وهكذا .. عمة الزوجة، وأخت الزوجة، وخالة الزوجة، لسن محارم للزوج؛ لأنهن محرمات عليه، فلو طلق أختهن، أو بنت أخيهن، أو بنت أختهن؛ جاز له النكاح بعد العدة.\n\nفالحاصل: أن بعض الرجال يتساهل مع بعض النساء، مع زوج أختها، ويتساهل بعض الناس مع  أخي زوجها، أو عم زوجها، وهذا غلط، لا يجوز، لا يجوز للمرأة أن تتساهل مع أخي زوجها، ليس محرمًا لها، وليس عمه محرمًا لها، ولا خاله. \n\nأبوه وولده هما المحارم، أما أخو الزوج، وعم الزوج، وابن عم الزوج، وخال الزوج، فليسوا محارم، وكذلك زوج الأخت، وزوج العمة، وزوج الخالة، ليسوا محارم، المحرم زوج بنتها، وزوج أمها، هذا هو المحرم، أما زوج أختها، أو زوج عمتها، أو زوج خالتها فليسوا محارم، يجب الحجاب والتحفظ عنه.\n\nالسؤال: كان بعض الناس.. محرما لها؟\n\nالجواب: ماذا؟\n\nالطالب: بعض الناس ينسب كلاما للشافعي على أن زوج أختها محرم لها؟\n\nالجواب: لا ما قاله الشافعي ولا غيره، محرم إجماعًا لا الشافعي، ولا غيره... لأن هذا تحريم مؤقت ما تحريم مطلقًا.","link":"https://binbaz.org.sa/fatwas/2945/حكم-الخلوة-بزوج-الاخت-وعمة-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1393.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":7049,"question":"يرى بعض من يدعي التجديد في الدين أن الأصل في الإسلام اشتراك المرأة، ومشاركتها في المجتمع، وفي مختلف جوانب الحياة السياسية، والاقتصادية، وأنه لا ينبغي لأمر سد الذرائع أن يمنع هذا الأصل، ويقول: إن سبب عجز النساء على الرجال هو سبب عدم طهر المجتمع، والفتنة هي مناط الأمر في الاختلاط، أو عدمه، نرجو تعليقكم على هذا الرأي؟","title":"دعوى مشاركة المرأة للرجل في مختلف جوانب الحياة","answer":"الجواب:\n\nهم دعاة للفساد، ودعاة للاختلاط، كثيرون في الصحف والإذاعات وغيرها، لا ينبغي أن يغتر بهم، فالمرأة لها شغل كامل، لها شغل في بيتها مع زوجها، ومع أولادها، ولها شغل في مدرستها، في التعلم والتعليم، ولها شغل في المستشفى في الطب، والتمريض للنساء، لها شغل كثير لم تعطل، ولكن كذب دعاة الفساد، كذب دعاة قولهم: إن نصف المجتمع معطل، هذا من التلبيس والخداع، والدعوة إلى الفساد.\n\nومن قال إنها معطلة! ما كانت معطلة في عهد النبي ﷺ، ما هناك إذاعة، ولا هناك تبرج، ولا هناك فساد، وهي مشغولة في بيتها بصنع الطعام، بتربية الأولاد، بالعناية بالأولاد، بتعلم دينها، والتفقه في دينها،، إلى غير ذلك، فهي غير معطلة، لها شغلها وللرجل شغله.\n\nلها شغلها في بيتها، وتربية أولادها، والقيام بخدمة زوجها، ولها شغلها في التعلم والتعليم، والمشاركة في تدريس البنات والنساء والتعلم، لها شغلها في الأشياء الأخرى، كطب النساء إلى غير ذلك، فهي عليها أن تعمل في حدود مملكتها، في حدود ما يجوز لها، أما أن تكون مع الرجل سكرتيرة، أو قريبة له في عمله، حتى يتقرب منها .. يلزم من الفساد هذا هو عندهم، الطيب عند دعاة الفساد، وعند دعاة الاختلاط، والفتنة لا يرضون إلا أن تكون المرأة كالرجل معه في كل شيء، حتى يتمكن من فعل الفاحشة معها أينما كان، وحتى يعطل زوجته ويعطل بيته -نسأل الله السلامة- ولا حول ولا قوة إلا بالله.\n\nالسؤال: حق المرأة في الصورة العامة، وكيفية تحقيق ذلك؟\n\nالجواب: حقها أن تعلم دينها.","link":"https://binbaz.org.sa/fatwas/3040/دعوى-مشاركة-المراة-للرجل-في-مختلف-جوانب-الحياة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1438.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":7120,"question":"نرجو نصح سماحتكم فيما يحصل من مدينة جيزان أنه إذا حصل عندهم مناسبة زواج، أو ختان؛ يدخلون الرجال يطبلون، ويسمونهم مزلفين، ويطبلون هؤلاء في وسط النساء، والنساء ينثرن عليهم النقود، وهم يرقصون بدون حياء من الله؟","title":"حكم دخول الرجال بين النساء في مناسبات الزواج","answer":"الجواب:\n\nهذا قد بُيِّنَ لهم، وكتب لهم في هذا، والدعاة الذين هناك مكلفون بهذا الشيء، ببيان هذا الشيء، ونسأل الله أن يهدي الجميع. \n\nكثير من الناس قد يسمع النصيحة ولا يلتفت إليها، ويرى أن العادة التي اعتادها شيئًا لازمًا، يقدمها على ما قاله الله ورسوله، وهل عودي الرسل والمصلحون إلا بالعوائد الضارة، العوائد المخالفة للشرع، عوائد الجاهلية هي التي عودي بها الرسل، وعودي بها المصلحون. \n\nفالواجب على المسلم أن يبتعد عن العادة السيئة المخالفة للشرع، وألا يغتر بما عليه أسلافه إذا كان شيئًا باطلًا، فالعوائد لا يحتج بها، بل تعرض على الأدلة الشرعية، فإن جادت؛ أخذ بها، وإلا وجب طرحها وإن كانت عادة للآباء والأسلاف.\n\nولا ينبغي للعاقل أن يكون مثل ما قال الجاهلون من الكفار: إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِمْ مُقْتَدُونَ [الزخرف:23] هذه حجة الكفرة التي احتجوا بها على الرسل إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِمْ مُقْتَدُونَ [الزخرف:23] هذه حجة داحضة باطلة، ما يجوز لأي مسلم أن يحتج بها، بل يجب أن يعرض ما أشكل عليه على الأدلة الشرعية، ويسأل أهل العلم بالشرع عن ذلك، ولا يقول هذه عادة أبي، أو جدي، أو أهل بلدي، ويكتفي بها، ولو خالفت الشرع.\n\nالسؤال: العامة قلت تكتبون لهم، وأنا في روحة أهلي وجدتهم لا زالوا على حالتهم وأشد؟\n\nالجواب: ولو، الرسائل جاءتهم عدة رسائل في هذا، وقرأها عليهم الدعاة، ولكن العادات مثل ما قيل قاهرات، قل من يتركها، نسأل السلامة، نسأل الله أن يهدينا وإياهم.","link":"https://binbaz.org.sa/fatwas/3168/حكم-دخول-الرجال-بين-النساء-في-مناسبات-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1526.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7142,"question":"فضيلة شيخي! جنوب المملكة يستبيحون كشف الوجه لأخي الزوج وأقاربه، فما هو الرد على هؤلاء مع أمرها بذلك؟","title":"حكم كشف الوجه لأخي الزوج وأقاربه","answer":"الجواب:\n\nهذا في الجنوب وفي غير الجنوب، الرسول ﷺ قال: إياكم والدخول على النساء قيل: يا رسول الله أرأيت الحمو؟ قال: الحمو الموت الحمو: أخو الرجل، وعم الرجل.\n\nفإذا تساهلت في الكشف له هذا من وسائل الشر، إذا تساهلت؛ دل على ضعف إيمانها، ودعاه ذلك إلى الطمع فيها، فلا يجوز لها أن تكشف لا لأخي زوجها، ولا لعم زوجها، ولا لخال زوجها، وليس لها أن تكشف أيضًا لزوج أختها، ولا زوج خالتها، ولا زوج عمتها، كلهم أجانب بالنسبة إليها.\n\nإنما الكشف يكون لأبي زوجها، لجد زوجها، لأولاد زوجها، هؤلاء هم المحارم: أولاد الزوج، وأولاد أولاده، وأولاد بناته، هم المحارم، أما زوج الأخت، زوج العمة، زوج الخالة، هؤلاء ليسوا محارمًا، المحارم زوج بنتها، وزوج أمها، هؤلاء محارم.","link":"https://binbaz.org.sa/fatwas/3167/حكم-كشف-الوجه-لاخي-الزوج-واقاربه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1525.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7153,"question":"ما حكم الجلوس مع بنات العم، وبنات الخال مع حضور المحرم؟","title":"حكم الجلوس مع بنات العم أو الخال","answer":"الجواب:\n\nإذا كن متسترات، ولا في فتنة؛ فلا بأس، أما إذا كان الحضور لأجل الفتنة ولأجل التمتع بالنظر إليهن وهن سافرات؛ لا يجوز هذا.\n\nأما الجلوس معهن للسلام عليهن، أو السؤال عن حال مريضهن، وهن متسترات متحجبات بعيدات عن الفتنة على طريق الحشمة؛ فلا بأس، هكذا المسلمون فيما بينهم.","link":"https://binbaz.org.sa/fatwas/3184/حكم-الجلوس-مع-بنات-العم-او-الخال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1542.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7157,"question":"هل يجوز أن أصافح عمات وخالات زوجتي؟","title":"حكم مصافحة عمات وخالات الزوجة","answer":"الجواب:\n\nليس لك أن تصافح لا عماتها ولا خالاتها ولا أخواتها أيضًا، ليس لك ذلك، إنما هذا مع الأم، مع أمها، أو بنتها بعد الدخول بها، أما عماتها وخالاتها وأخواتها فليسوا محارم، وإنما تسلم عليهن بالكلام فقط، كيف حالكم؟ كيف أنتم؟ السلام عليكم، وعليكم السلام، من دون مصافحة.","link":"https://binbaz.org.sa/fatwas/3185/حكم-مصافحة-عمات-وخالات-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1543.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7229,"question":"معظم أقاربي من والدي المتوفيين، وكذلك أقارب زوجتي تعودوا على الاختلاط بين الرجال والنساء، واعتبروا ذلك منهاجًا وعرفًا، فالرجال يصافحون النساء، ويجلسون معهم، ولذلك لا أذهب إليهم مع زوجتي أبدًا، حاولت أن أذهب وحدي حتى أصلهم، ولكن أخذت نساؤهم يحاولن مصافحتي من باب المضايقة؛ لعلمهن بأنني لا أصافح النساء، وبدؤوا يعملون أشياء تضايقني، فامتنعت أنا أيضًا عن زيارتهم.والآن هناك بيننا شبه قطيعة، وأخشى على نفسي من أن أدخل ضمن قاطع الرحم، وفي نفس الوقت لا أستطيع التصرف، ماذا أفعل بارك الله فيكم؟","title":"حكم مصافحة النساء الأجنبيات والنظر إليهن","answer":"الجواب:\n\nلست بقاطع يا أخي هم القاطعون، أنت لست بقاطع هم القاطعون، من أدام المنكر، وثبت على المنكر، وأبى أن يقبل؛ فهو القاطع، ما هو أنت.\n\nإن استطعت أن تنصحهم من دون مصافحة للنساء، ومن دون نظر إلى النساء الكاشفات، تغض بصرك، ولا تصافح، وتنصح، وتقول الحق؛ فافعل، واجتهد، فإن لم تستطع؛ فأنت معذور، وهم القاطعون، ولست بقاطع أنت.","link":"https://binbaz.org.sa/fatwas/3305/حكم-مصافحة-النساء-الاجنبيات-والنظر-اليهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1630.mp3","categories":["النظر والخلوة والاختلاط","الأخلاق المذمومة"]},{"id":7335,"question":"تقدمت للعمل في إحدى المستشفيات كمترجم، وفي هذه المستشفى كما في المستشفيات الأخرى الاختلاط موجود بين الرجال والنساء، سؤالي: هو بحكم عملي اضطر إلى مخالطة النساء المرضى والعاملات، فما رأي فضيلتكم في هذا الموضوع، أفيدونا -جزاكم الله خيرًا- علمًا أنني في حاجة ماسة إلى هذه الوظيفة؟","title":"حكم العمل في أماكن الاختلاط","answer":"الجواب:  إذا كان عملك يجعلك تختلط بالنساء؛ فابتعد واحذر، احذر لئلا تُفترس، يفترسك الشيطان بواسطتهن، احذر. أما إذا كان عملك بعيدًا عنهن، إنما أنت مترجم لما يساق إليك، ويوصل إليك في مكتبك، تترجمه وتعطيهم إياه؛ فلا بأس، أما أنك تختلط بالنساء، بمريضات، وغير مريضات، وربما سبب لك ذلك مشاكل كثيرة، وأخطارًا كثيرة، وهن شبه عاريات، وكثير منهن لا يبالي بالستر والحجاب، أو كلهن، فأنت على خطر، فاحذر وابتعد، والرزق عند الله.","link":"https://binbaz.org.sa/fatwas/3414/حكم-العمل-في-اماكن-الاختلاط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1726.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7379,"question":"نشأت يتيم الأب والأم، وتولى رعايتي عمي، فرباني وأحسن رعايتي، وذلك من صغري، وعمري سبع سنوات، وشاركته في ذلك امرأته الحنونة، فلبثت عندها حتى أصبح عمري عشرين عامًا، وعمي تولى رعايتي، وأنفق عليَّ أثناء دراستي رغم فقره، والسؤال هنا: هل يجوز أن تكشف علي امرأة عمي، أم لا يجوز؟ وأنا اعتبرها أخت بحيث أنها لم تحتجب مني قبل ذلك وظلت تكشف علي إلى آخره؟","title":"حكم الكشف والمصافحة لزوجة العم التي ربته","answer":"الجواب: هذا عمل طيب من عمك جزاه الله خيرًا، الذي أحسن إليك، ورباك، وأنفق عليك، فالعم مثل الأب لا يستغرب، العم بمنزلة الأب كما قال النبي ﷺ: إن عم الرجل صنو أبيه فإذا أحسن إليك ورباك وأنفق عليك؛ فهذا عمل مشكور، وعليك أن تدعو له وتشكره على هذا العمل، سواء كان حيًّا أو ميتًا.  وأما زوجته التي أحسنت إليك فهي بمنزلة أمك، ما هي أختك، بمنزلة الأم التي ربتك وأحسنت إليك، لكن لا تكشف لك، وليست محرمًا لك، لكن تدعو لها، وتشكرها على عملها الطيب مع زوجها، ولكن لا تخلو بها، ولا تكشف لك، بل تحتجب عنك، هي أجنبية إلا إذا كانت أرضعتك، أو أرضعتك بنتها، أو أختها؛ تكون خالة لك، لا بأس، إذا كان بينك وبينها رضاعة، إما أرضعتك هي وأنت صغير، أو أرضعتك أختها؛ تكون خالة لك، أو أرضعتك بنتها؛ تكون جدة لك، لا بأس، أما مجرد كونها ربتك ما تكون محرمًا لك، ولا تكشف لك، بل عليها أن تحتجب عنك وعليك أن لا تنظر إليها، ولكن عليك أن تشكرها وتحسن إليها، وتعرف قدرها، وإحسانها، وإحسان زوجها -عمك هذا- عليك؛ لأن النبي ﷺ يقول: من صنع إليكم معروفًا؛ فكافئوه، فإن لم تجد ما تكافئوه فادعوا له حتى تروا أنكم قد كافأتموه ويقول النبي ﷺ: من لا يشكر الناس لا يشكر الله. السؤال: وإن كانت كبيرة؟ الجواب: إلا إذا كانت عجوزًا يعني ما تشتهى، ولا تزين، ولا شيء مثل ما قال الله: وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لَا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ [النور:60] إذا كانت عجوزًا كبيرة، لا تتعاطى الزينة؛ فلا بأس، أما إذا كانت تتعاطى الزينة، ويظهر منها ما قد يميل الرجال إليها؛ فلا يجوز لها أن تكشف، وليس لأحد أن ينظر إليها. والمصافحة لا يصافح الرجل النساء لا، المصافحة بين الرجل والرجال، أو بين الرجل ومحارمه، كأمه وخالته، أما أن يصافح النساء لا، النبي ﷺ قال: إني لا أصافح النساء لا كبيرة ولا صغيرة، كل ساقطة لها لاقطة.","link":"https://binbaz.org.sa/fatwas/3462/حكم-الكشف-والمصافحة-لزوجة-العم-التي-ربته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1766.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7391,"question":"امرأة مات عنها زوجها، وترك لها أولادًا، ولا يوجد من يصرف عليهم، فخرجت لتسعى على أولادها في حقل العمل بين الرجال والنساء، فما حكم ذلك؟","title":"عمل المرأة للحاجة في وظيفة مع الاختلاط","answer":"الجواب: عليها أن تسعى للعمل، وتقوم على أولادها، لكن بالطرق المباحة، العمل في ميدان النساء، لا في ميدان الرجال، لا بأس، أما أن تكون بين الرجال لا، الله -جل وعلا- جعل فيما أباح غنية عما حرم  فتعمل ممرضة للنساء خاصة، تعمل في بيت مأمون بأجر معلوم، حاجات تقوم بها، إلى غير هذا من الطرق السليمة البعيدة عن الخطر.","link":"https://binbaz.org.sa/fatwas/3493/عمل-المراة-للحاجة-في-وظيفة-مع-الاختلاط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1797.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":7392,"question":"لي أخت متزوجة وزوجها يجبرها على أن لا تحتجب من إخوانه، فهل يحق لي مقاطعتهم، علمًا بأنني نصحت لهم وللزوج خاصة، ولكن الزوج رفض، فماذا علي أنا؟ وماذا على الزوجة؟","title":"حكم كشف المرأة وجهها أمام إخوة زوجها","answer":"الجواب: عليها أن تحتجب ولو لم يرض، ليس لها طاعته في المعصية، يقول النبي ﷺ: إنما الطاعة في المعروف فإذا كان ضعيف الغيرة وأمرها أن تكشف لإخوانه وأعمامه وأصحابه وأصدقائه؛ فليس لها طاعته في ذلك -نسأل الله للجميع الهداية-.","link":"https://binbaz.org.sa/fatwas/3510/حكم-كشف-المراة-وجهها-امام-اخوة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1814.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7398,"question":"إن الاختلاط يتم ولا بد منه في المدارس الابتدائية، وفي المعاهد الثانوية، والجامعات في غير هذا البلد الذي حفظه الله، فهل تتعلم الفتاة المسلمة داخل هذا الوسط الذي يختلط فيه الحابل بالنابل، أم ترونها تنقطع عن الدراسة، وهل في انقطاعها عن التعليم إخلال بحقها في التعليم المشروع لها لتقوي إيمانها وثقافتها الإسلامية؟","title":"دراسة الفتاة في المدارس والجامعات التي فيها اختلاط","answer":"الجواب: نعم نعم، إذا كان التعلم بالاختلاط تنقطع عن التعليم، وتنقطع عن التعلم، وتبقى في بيتها ويعلمها أبوها أو أخوها أو زوجها -والحمد لله- أصل الدين والمعلومات التي تلزمها قليلة متيسرة في البيت، الناس يريدون التوسع حتى يتوظفوا، أما تعلم الفاتحة وما تيسر من كتاب الله وتعلم العقيدة وتعلم الصلاة كله ميسر، أما أنها تذهب تدرس مع الشباب بالاختلاط فلا.  أما إذا كان في الحضانة فيما دون السن الذي فيه الفتنة والشهوة دون التسع هذا عند الضرورة، ولاسيما دون السبع في أول الدراسات في الحضانات أمرها سهل، لكن إذا فتح الباب في الابتدائي انجر إلى المتوسط، ثم انجر إلى الثانوي، وهكذا، هذا بلاء عظيم، لكن بقاءها في البيت، ويعلمها أبوها أو أمها أو أختها أو جاب لها معلمة، ولو بالدين، ولو بالمال؛ فهذا خير لها وأصلح، ولا يجوز أن تتورط مع الشباب أبدًا.","link":"https://binbaz.org.sa/fatwas/3494/دراسة-الفتاة-في-المدارس-والجامعات-التي-فيها-اختلاط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1798.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":7409,"question":"امرأة مات عنها زوجها، وترك لها أولادًا، ولا يوجد من يصرف عليهم، فخرجت لتسعى على أولادها في حقل العمل بين الرجال والنساء، فما حكم ذلك؟","title":"عمل المرأة للحاجة في وظيفة مع الاختلاط","answer":"الجواب: عليها أن تسعى للعمل، وتقوم على أولادها، لكن بالطرق المباحة، العمل في ميدان النساء، لا في ميدان الرجال، لا بأس، أما أن تكون بين الرجال لا، الله -جل وعلا- جعل فيما أباح غنية عما حرم  فتعمل ممرضة للنساء خاصة، تعمل في بيت مأمون بأجر معلوم، حاجات تقوم بها، إلى غير هذا من الطرق السليمة البعيدة عن الخطر.","link":"https://binbaz.org.sa/fatwas/3493/عمل-المراة-للحاجة-في-وظيفة-مع-الاختلاط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1797.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":7410,"question":"لي أخت متزوجة وزوجها يجبرها على أن لا تحتجب من إخوانه، فهل يحق لي مقاطعتهم، علمًا بأنني نصحت لهم وللزوج خاصة، ولكن الزوج رفض، فماذا علي أنا؟ وماذا على الزوجة؟","title":"حكم كشف المرأة وجهها أمام إخوة زوجها","answer":"الجواب: عليها أن تحتجب ولو لم يرض، ليس لها طاعته في المعصية، يقول النبي ﷺ: إنما الطاعة في المعروف فإذا كان ضعيف الغيرة وأمرها أن تكشف لإخوانه وأعمامه وأصحابه وأصدقائه؛ فليس لها طاعته في ذلك -نسأل الله للجميع الهداية-.","link":"https://binbaz.org.sa/fatwas/3510/حكم-كشف-المراة-وجهها-امام-اخوة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1814.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7479,"question":"أيضاً هناك سؤال ثالث ولعله السؤال الأخير من أسئلة الأخت (ع . ع ) من السودان، تقول: تقام رحلات في أيام الأعياد ترفيهية لنا، وتقول: نتناول الوجبات ويتناول الأساتذة الطعام معنا، وإدارة المعهد تريد إزالة الخجل بين الطالبة وأساتذتها، هل لنا أن نأكل معهم، أو هل الأكل معهم حرام؟ وما موقفنا نحن؟","title":"حكم الرحلات المختلطة بالطالبات والمدرسين","answer":"الجواب:  هذه الرحلات أيضاً فيها شر كثير، ما دام فيها اختلاط بين الرجال والنساء ويأكلون جميعاً، هذه يخشى منها الفتنة بين الرجال والنساء، فلا تجوز، بل يجب أن يكون للنساء جهة خاصة وللرجال جهة خاصة، يكون فيها طعامهن وحاجاتهن، أما اختلاطهن مع الرجال فهذا يفضي إلى الفتنة، ويفضي إلى أن يرى الرجل منها ما لا ينبغي أن يرى من وجهها ومن ذراعها ومن شعرها، .. تسبب فتنة كثيرة، ثم مدها يدها للأكل وحضورها معهم يرى وجهها، ويرى فمها، ويرى يدها حين تأكل بها، كل هذا فتنة لا يصلح؛ لأن ستر الوجه واجب والتحجب واجب، وهذا يفضي إلى عدم التحجب. أما لو كن يأكلن في جهة من المكان والرجال في جهة من المكان لا يرى بعضهم بعضاً فلا بأس، ولو كان مكاناً واحداً، إذا كان النساء في جهة والرجال في جهة وهم الأساتذة مثلاً، ولا يرى بعضهم بعضاً ... عليهن يعني: الجلابيب أو العباءة أو ما أشبه ذلك، ويأكلن ووجوههن إلى جهةٍ أخرى، لا يراهن الرجال، فلا بأس. أما اختلاطهن على نفس المائدة ويرى بعضهم بعضاً في الأكل وما وراء ذلك؛ من رؤية بعض الشعر، أو بعض القلائد، أو بعض .. كل هذا لا يجوز. نعم.","link":"https://binbaz.org.sa/fatwas/4324/حكم-الرحلات-المختلطة-بالطالبات-والمدرسين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_004/00404.mp3","categories":["قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":7655,"question":"أيضاً يقول: هل من الشر أن يختلط الإنسان بالنساء شابات وشيب في حالات الفرح؟","title":"حكم الاختلاط بالنساء في الأفراح","answer":"الجواب: لا شك أنه من الشر اختلاطه بالنساء، لا شك أنه من أعظم أسباب الفساد والفتنة، فالواجب التميز، وأن يكون الناس على حدة، الرجال على حدة والنساء على حدة، في الفرح مثل الأعراس، يكون الرجال في محل خاص يتناولون طعامهم وما جرت به عاداتهم من الأمور التي لا تخالف الشرع، والنساء على حدة في محلهم وفيما يتعلق بفرحهم ودفهم وغناهم الخاص فيما بينهم الذي لا يؤذي أحداً ولا يكون فيه مكبرات الصوت بل يكون هادئ، هذا لا بأس به، كله من باب إظهار النكاح الشرعي وإعلانه.\nأما الاختلاط فلا يجوز، كونه يختلط الرجل مع النساء، شابات أو غير شابات لا يجوز؛ لأن هذا يفضي إلى الفساد والزنا والفواحش، وهذا منكر بإجماع المسلمين. نعم.","link":"https://binbaz.org.sa/fatwas/4815/حكم-الاختلاط-بالنساء-في-الافراح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_037/03704.mp3","categories":["قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":7670,"question":"أيضاً يسأل عن الملابس يقول: أنتم تعرفون ملابس فتيات زماننا هذا من الملابس الجذابة أو التي تجعل أجسامهن جذابة، ولا نستطيع غض البصر، وإذا عدت إلى المنزل ندمت وتأسفت، فما الحكم في ذلك؟","title":"نصيحة لمن أطلق بصره بالنظر إلى النساء","answer":"الجواب: لا شك أن هذا الذي يقوله هذا الشاب هو يقوله غيره، ولا شك أنه مرض خطير في المجتمع في أي مجتمع، ولا شك أيضاً أن الواجب على الفتيات أن يتقين الله في ذلك، وأن يحرصن على ستر أجسامهن من الملابس الساترة، وأن يتحجبن عن الرجال من جهة جميع البدن ومن جهة الرأس حتى لا تفتن الناس، وحتى لا يتعلق بها الشباب وغير الشباب، فيسبب ذلك حادثة الفاحشة وركوب المحارم، هذا هو الواجب على جميع الفتيات أينما كن، عليهن جميعاً أن يتقين الله، وأن يحرصن كل الحرص على الحجاب، وستر جميع الجسد، وأن لا تبدي رأساً، ولا وجهاً، ولا صدراً، ولا غير ذلك، فتكون مستورة محجبة بستر جيد يستر مفاتنها ويستر بدنها، حتى لا تضر نفسها، ولا تضر الشباب الذي قد ينظر إليها.\nوعلى الرجال شباباً كانوا أو غير شباب، عليهم أن يتقوا الله، وأن يغضوا الأبصار، وأن يجاهدوا أنفسهم في ذلك؛ لأن الله قال سبحانه: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ [النور:30].\nولما سئل النبي ﷺ عن النظر نظر الفجأة قال: اصرف بصرك فإنما لك الأولى وليس لك الأخرى، فالذي يفجأه نظر المرأة من غير قصد، بأن تخرج عليه من شارع، أو أن تنزل من سيارة ما فطن لها، فإن عليه أن يصرف بصره بعد ذلك، وليس له أن يتابع النظرة النظرة، بل يجب عليه صرف النظر وغضه، وهي عليها كذلك، ولا يجوز لها أبداً أن تتساهل في اللباس كما يفعل بعض النساء، بل عليها أن تستر بدنها في بيتها إذا كان عندها أخو زوجها، أو عم زوجها، أو نحو ذلك، وفي الأسواق أن تستر بدنها عن جميع أهل السوق من الرجال حتى لا تفتن ولا تفتن، هذا هو الواجب عليها، والله سبحانه وتعالى يقول في حق النساء: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية، فليس لها إبداء الزينة إلا لهؤلاء المحارم، أما الأجانب فلا، عليها التستر والتحفظ، وقال جل وعلا: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53].\nفالتستر والتحجب أطهر لقلوب الجميع، أطهر لقلوب الرجال، وأطهر لقلوب النساء، فدل ذلك على أن عدم التستر وعدم التحجب من أسباب نجاسة القلب ومرضه، فالقلب قد ينجس ويمرض بالشهوات المحرمة، ويطهر ويزكو باجتنابها والبعد عنها والتوبة إلى الله منها.\nوالواجب على الرجال والنساء أن يحرصوا جميعاً على طهارة القلوب، وسلامتها وزكائها، وأن يحذروا ظلمتها وفسادها ومرضها وخبثها وانحرافها، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/4869/نصيحة-لمن-اطلق-بصره-بالنظر-الى-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_039/03903.mp3","categories":["قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":7696,"question":"يقول أيضاً: هل يحل للبنت أن تكشف الحجاب أو تجلس مع ابن عمها أو ابن خالها، وهل يستمر الحال كذلك إذا تزوجت؟","title":"حكم كشف المرأة وجهها لابن العم أو الخال","answer":"الجواب: أما الكشف لابن عمها وابن خالها سواء قبل الزواج أو بعد الزواج لا يجوز هذا؛ لأنه ليس محرماً لها، فلا يجوز للبنت أن تكشف وجهها أو شيئاً من زينتها لابن خالها أو لابن عمها أو لجيرانها أو لأخي زوجها، أو زوج أختها، كل هذا لا يجوز؛ لأنه ليس بمحرم، وهي مأمورة بالحجاب والستر، فليس لها أن تكشف وجهها ولا شيئاً من زينتها لهؤلاء، بل عليها أن تحتجب حجاباً كاملاً عن هؤلاء. \nوالوجه أعظم الزينة، فليس لها أن تكشف وجهها إلا لمحارمها، أما ابن عمها وابن خالها وزوج أختها وأخو زوجها كلهم أجانب ليسوا محارم لها، فليس لها أن تكشف لهم، ولكن تكلمهم.. ترد عليهم السلام، تكلمهم الكلام العادي، لا حرج في ذلك، نعم. لكن من غير خلوة، لا يخلو أحد بها. نعم.","link":"https://binbaz.org.sa/fatwas/4895/حكم-كشف-المراة-وجهها-لابن-العم-او-الخال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_028/02807.mp3","categories":["قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":7717,"question":"أيضاً تقول: هل الاختلاط الموجود في بعض المدارس بين الطلبة والطالبات في بعض البلدان حرام أم غير حرام؟ إذا كانت الطالبة المسلمة تدرس مع الطلبة بزيها الإسلامي هل تعتبر آثمة، أم لا؟","title":"مفاسد الاختلاط بين الطلاب والطالبات في المدارس","answer":"الجواب: اختلاط الطلبة والطالبات في المدارس لا يجوز؛ لما فيه من الفتنة، والشغل عن الدروس، فإن الطالبة إذا جلست بجوار الطالب لتلقي الدروس فإنه يترتب على هذا من الفتن والفساد الكبير ما لا يحصى، فلا يجوز اجتماعهم في درس، بل يجب أن تكون الطالبات على حدة والطلاب على حدة، فلا تكون الطالبة مع الطالب في كرسي واحد، ولا في حجرة واحدة يدرسون جميعاً مختلطين؛ لأن وجودهم جميعاً يسبب فتنة وشراً كثيراً، وكل واحد يشتغل بالآخر فيشغله عن درسه ويشغله عن الفائدة، وربما أفضى إلى مواعيد ضارة وإلى اجتماعات غير طيبة، والواجب أن تكون دراسة كل صنف على حدة، هذا هو الواجب؛ حذراً من الفساد الذي لا يخفى على من تأمل الواقع. نعم.","link":"https://binbaz.org.sa/fatwas/4916/مفاسد-الاختلاط-بين-الطلاب-والطالبات-في-المدارس ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_031/03103.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":8043,"question":"سؤاله الثاني يقول: باستطاعة الإنسان أن يمنع نفسه من جميع ما يشين ويستقبح فعله، إلا النظر إلى النساء، وخاصةً المتبرجات في الأسواق، وإن كانت هذه الظاهرة في بلدنا قليلة جداً، فماذا تنصحون بفعله لتجنب ذلك؟","title":"لزوم غض البصر عن النساء المتبرجات وغيرهن والإنكار عليهن","answer":"الجواب: الواجب في كل حال تجنب النظر إلى المتبرجات، وغض البصر؛ لأن الله أمر بذلك كما قال سبحانه: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ [النور:30]، فالمؤمن يغض بصره، ويتقي ربه ويسأل الله العافية، ومع هذا ينكر عليهن، يقوم بواجب الإنكار، ينكر عليهن وينصحهن ويبين لهن أن هذا حرام ومنكر، فلعل الله أن يهديهن به مع غض البصر، فيجمع بين الأمرين: يغض بصره وينكر المنكر، وإذا لم ينفع ذلك يرفع الأمر إلى الهيئة الحسبة حتى تقوم بالواجب في بلده. نعم.","link":"https://binbaz.org.sa/fatwas/5842/لزوم-غض-البصر-عن-النساء-المتبرجات-وغيرهن-والانكار-عليهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_081/08108.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":8051,"question":"سؤاله الثاني يقول: باستطاعة الإنسان أن يمنع نفسه من جميع ما يشين ويستقبح فعله، إلا النظر إلى النساء، وخاصةً المتبرجات في الأسواق، وإن كانت هذه الظاهرة في بلدنا قليلة جداً، فماذا تنصحون بفعله لتجنب ذلك؟","title":"لزوم غض البصر عن النساء المتبرجات وغيرهن والإنكار عليهن","answer":"الجواب: الواجب في كل حال تجنب النظر إلى المتبرجات، وغض البصر؛ لأن الله أمر بذلك كما قال سبحانه: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ [النور:30]، فالمؤمن يغض بصره، ويتقي ربه ويسأل الله العافية، ومع هذا ينكر عليهن، يقوم بواجب الإنكار، ينكر عليهن وينصحهن ويبين لهن أن هذا حرام ومنكر، فلعل الله أن يهديهن به مع غض البصر، فيجمع بين الأمرين: يغض بصره وينكر المنكر، وإذا لم ينفع ذلك يرفع الأمر إلى الهيئة الحسبة حتى تقوم بالواجب في بلده. نعم.","link":"https://binbaz.org.sa/fatwas/5842/لزوم-غض-البصر-عن-النساء-المتبرجات-وغيرهن-والانكار-عليهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_081/08108.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":8177,"question":"سؤاله الثاني يقول: ما حكم مشاهدة التماثيل التي تعرض في الفيديو أو السينما أو ما في حكم ذلك ولا سيما وهو معروف أن في تلك التمثيليات كثير من النساء المتبرجات؟","title":"حكم مشاهدة المسلسلات في التلفاز ونحوه","answer":"الجواب: مشاهدة الصور في التلفاز أو في الأفلام والصور الخليعة للنساء أو للرجال الذين لم يتستروا أو على فعل الفاحشة أو على فعل بعض المنكرات كل هذا لا يجوز، فلا يجوز لمسلم أن يشاهد صور النساء غير متحجبات ولا شبه العاريات ولا صور الرجال الذين قد كشفوا أفخاذهم أو يلعبون بما حرم الله من القمار أو بالملاهي آلات الملاهي أو يتعاطون الغناء المحرم كل هذا يجب تركه والحذر منه لأنها منكرات مشاهدتها لا تجوز، ولأن مشاهدتها أيضاً قد تجر إلى فعلها واستحسانها فينبغي للمؤمن أن يصون نفسه عن ذلك وإنما يرى من التلفاز ما فيه المصلحة كمشاهدة ندوات علمية أو صناعية أو غير هذا مما ينفعوا المشاهد، أما كونه يشاهد أشياء محرمة فلا يجوز. نعم.","link":"https://binbaz.org.sa/fatwas/5984/حكم-مشاهدة-المسلسلات-في-التلفاز-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_105/10505.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":8188,"question":"هذه رسالة وردتنا من شلوي محمد العلي من الرياض، يقول في رسالته: أرجو عرض رسالتي هذه على سماحة الشيخ عبد العزيز بن باز حفظه الله خاصة، ونرجو أن يعالج هذه الرسالة معالجة وافية، يقول: بعض المبتعثين إلى الخارج يذهبون بزوجاتهم معهم، فمنهم من يجبر زوجته على التكشف؛ خشية الضحك عليهم والتندر بهم من الغرب، حتى إن الزوجات يجتمعن مع أزواجهم جميعاً، ويأكلون ويشربون ويتندرون، بل إن بعضهم يقبل زوجة صديقه أو زميله وهو ينظر، ولا بأس عندهم في ذلك، نرجو معالجة ذلك عبر برنامجكم نور على الدرب، وفقكم الله؟","title":"حكم إجبار المبتعثين لزوجاتهم على التكشف والاختلاط في الخارج","answer":"الجواب: لاشك أن هذا الأمر الذي ذكره السائل منكر ولا يجوز، فإن الواجب على الرجل أن يكون عنده غيرة، وأن يكون عنده حرص على عفة زوجته، وبعدها عن مواضع الخطر، وأن تكون بعيدة عن التبذل وعدم الحجاب، بل يلزمه أن يقوم عليها وأن يوجهها إلى الخير، وأن تحتجب أينما كانت، سواء كانت في بلاد المسلمين، أو في بلاد الكافرين مع زوجها، الواجب على الجميع التأدب بالآداب الشرعية، والتقيد بها في كل مكان، ومن ذلك الحجاب، وعدم الاختلاط بالأجناب من أزواج الزملاء، وإذا وقع التقبيل من الشخص لزوجة زميله هذا منكر عظيم.\nالمقصود أن هذه الأشياء التي ذكرها السائل منكر، فلا يجوز كشف الوجه أو الشعر عند زملاء الزوج، ولا يجوز لزيد أو عمرو من الزملاء أن يقبل زوجة صديقه أو زميله، أو ينظر إليها، بل يجب غض البصر، ويجب الامتناع من التقبيل، ويجب الامتناع أيضاً من الاختلاط الذي يفضي إلى ذلك، بل يجلس النساء وحدهن في أكلهن وشربهن، والرجال وحدهم في أكلهم وشربهم، وتحافظ المرأة على الحجاب، والرجل على غض البصر أينما كان، هذا هو الواجب على المسلمين، ويجب على الدول الإسلامية التي تخاف الله أن تمنع هذا، وأن تقوم على من يفعله حتى يزول هذا البلاء.\nوالابتعاث إلى بلاد الكفر فيه خطر عظيم، فيجب منعه مهما أمكن، وأن تكون الدراسة في الداخل، وأن يسلم الناس من شر هذا الابتعاث، الذي يفضي إلى فساد كثير، إلى فساد العقيدة، وإلى إفساد الأخلاق، وإلى اختلاط الرجال بالنساء، وإلى قلة الغيرة، وإلى تمتع الرجال بأزواج غيرهم ونساء غيرهم، وربما أفضى إلى الفاحشة والملامسة والتقبيل بغير حق، وهذا كله بلاء عظيم، وهو خطر، هذا الابتعاث خطر في العقيدة والأخلاق جميعاً على الرجال والنساء، فالواجب منعه منعاً باتاً من دولتنا وفقها الله، ومن جميع الدول الإسلامية، وعلى آباء المبتعثين نصيحتهم لهذا، وألا يوافقوا على ابتعاثهم مهما أمكن، ولو على حساب الآباء، أو حساب المؤسسات، أو ما أشبه ذلك، بل يجب التقيد بالتعلم في بلاد الإسلام، وفي المدارس الإسلامية، والجامعات الإسلامية التي فيها الخير وفيها الكفاية، وإذا كان هناك ضرورة للابتعاث ليس هناك ما يغني عنه، فليبتعث الرجل العاقل الدين، المعروف بالاستقامة والعقل الرزين، والغيرة الإسلامية، والبعد عن أسباب الشر، فيبتعث هذا وحده أو مع زوجته المستقيمة عند الضرورة، هذا لا حرج فيه إن شاء الله عند الضرورة، يكون داعية إلى الله، وموجهاً إلى الخير، ويتعلم الشيء الذي تدعو الضرورة إلى تعلمه، وزوجته معه تعينه على العفة والسلامة، ويتحدث معها وتتحدث معه، ويعلمها ويفيدها ويوجهها إلى الخير، وإذا سافر بدون الزوجة فلا بأس.\nالمقصود أن هذا ينبغي أن يعالج بأمرين: الأمر الأول: منع الابتعاث بالكلية، فإذا دعت الضرورة إليه؛ لعدم وجود الحاجة التي يبتعث لأجلها، فلابد أن ينظر في الشخص المبتعث، ولا يبتعث كل أحد، بل لا يبتعث إلا الرجل المعروف بالاستقامة، والعقل الجيد والأخلاق الفاضلة، والاتزان والعلم والفضل، حتى لا يخشى عليه الوقوع في الباطل بإذن الله، وإذا كان معه زوجة فلينظر أيضاً فإن كانت جيدة صينة، فلا بأس باصطحابها مع نصيحتها ومع ملاحظتها حتى لا تقع في باطل، وإن كانت ليست جيدة لم يذهب بها وتركها عند أهله خوفاً عليها من وقوع ما لا تحمد عقباه؛ فإنه ليس دائماً عندها. نعم.","link":"https://binbaz.org.sa/fatwas/5998/حكم-اجبار-المبتعثين-لزوجاتهم-على-التكشف-والاختلاط-في-الخارج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_092/09204.mp3","categories":["النظر والخلوة والاختلاط","الأخلاق المذمومة"]},{"id":8260,"question":"قضية الحاجة إلى عمل المرأة في مكان معين سماحة الشيخ، وقضية محرمها قضية لعل لسماحتكم فيها وجهة نظر ونصيحة، ماذا تقولون لو تكرمتم؟","title":"التحذير من سفر المرأة بغير محرم والاختلاط في العمل","answer":"الجواب: لا ريب أن هذا عمل خطير، وأن مجيء النساء بدون محارم فيه خطر وفتنة، فالذي ننصح أخواتنا في الله الحذر من ذلك وأن لا يقدمن إلا بمحارم، وننصحهن أيضاً بالحذر من الاختلاط مع الرجال والعمل مع الرجال ، أو الخلوة بالرجال، كونها تخلو برجل ليس محرماً لها، كل هذا مما يجب الحذر منه، سواء كان في المستشفيات أو في غير المستشفيات.\nفنصيحتي للجميع ألا تقدم امرأة إلا بمحرم، وألا تسافر إلا بمحرم وألا تعمل بين الرجال، وألا تخلو بأي رجل من غير محارمها؛ لأنه طريق للفتنة، والرسول ﷺ منع ذلك وحرمه، وقال: لا يخلون رجل بامرأة فإن ثالثهما الشيطان.\nفالمقصود من هذا: أن الواجب على المرأة وعلى أوليائها الحرص على سلامة العرض، والبعد عن أسباب الفتنة، وأما العمل فلا بأس أن تعمل بين النساء ممرضة أو خياطة أو خادمة أو غير ذلك في عمل مباح لا يضر دينها ولا يسبب فتنة مع الرجال، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/6070/التحذير-من-سفر-المراة-بغير-محرم-والاختلاط-في-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_098/09810.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":8273,"question":"هنا رسالة وصلت إلينا من جمع من الأخوات: ميمونة وأفنان وآسيا من الوشم أشيقر يقلن: إن لدينا خادمة كافرة، فهل لنا أن نأكل مما تصنع وأن نشرب مما تصنع؟ وهل لوالدنا البقاء معها وأن يأكل ويشرب مما تصنع أيضاً، أفيدونا في مثل هذا لو تكرمتم؟","title":"حكم الأكل والشرب مما تصنع الخادمة الكافرة والخلوة بها","answer":"الجواب: الأكل مما صنعت والأكل مما قدمت لكم لا حرج فيه، إذا كانت لا تذبح وإنما تطبخ وتقدم الطعام لا حرج في ذلك، أما الذبح فيتولاه المسلم، إلا أن تكون كتابية يعني نصرانية فذبيحتها صحيحة إذا ذكرت اسم الله عليها ولم تعمد تركها فهذا لا يضر ولو ذبحت أيضًا، لكن لا يجوز لكم بقاؤها عندكم، يجب إبعادها؛ لأن الرسول ﷺ أوصى بإخراج الكفرة من هذه الجزيرة، وأمر بإخراج اليهود والنصارى من هذه الجزيرة.\nفالواجب عليكم إخراجها وردها إلى أهلها، واستبدالها بمسلمة، إلا أن يهديها الله على أيديكم فتسلم، فالحمد لله.\nأما أبوك أيها السائلة فليس له أن يختلي بها، بل يحرم عليه ذلك، وهو مثلكم في أكل طعامها ونحو ذلك، لكن ليس له الخلوة بها، ولا النظر إلى محاسنها، بل يجب عليه غض البصر فيما قد يبدو له منها، وعليه ألا يخلو بها كغيرها من الأجنبيات، وهكذا أخوك وهكذا عمك كلهم عليهم الحذر من النظر إليها أو بالخلوة بها.\nوعليكم جميعاً أن تتقوا الله وأن تبعدوها إلى بلادها، وأن تستبدلوها إذا احتجتم بغيرها من المسلمات، إلا أن يهديها الله بأسبابكم إلى الإسلام فالحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6098/حكم-الاكل-والشرب-مما-تصنع-الخادمة-الكافرة-والخلوة-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_100/10010.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":8313,"question":"عوداً على بدء سماحة الشيخ! المرأة والأقارب من غير المحارم كثيراً ما يسأل الإخوة عن هذا، وكثيراً ما يعرضون لأشياء وأشياء قد لا يجوز أن نذكرها في هذا المقام، فمن الذين يسألون أحد الإخوة رمز إلى اسمه بالحروف (ج. م) من المدينة المنورة: هل للمرأة أن تقابل أخا زوجها، وخال زوجها، وأزواج أخواتها وهي محتجبة، وطريق المقابلة مثل: أن تأتي بالشاهي وتراهم ويرونها دون الكلام معهم، ويسلموا عليها بيدها، هل يجوز هذا، أو لا؟","title":"حكم مقابلة المرأة لأقاربها وأقارب زوجها ومصافحتهم","answer":"الجواب: ليس للمرأة أن تقابل أخا زوجها ولا عم زوجها ولا خال زوجها ولا أزواج أخواتها ولا أزواج خالاتها ولا أزواج عماتها ولا بني عمها ولا جيرانها، ليس لها أن تقابلهم مكشوفة الوجه، أو تصافحهم، كل هذا ليس لها، بل عليها أن تحتجب وعليها أن تبتعد عن مصافحة الرجال، أما كونها تسلم عليهم، وتجلس معهم من دون فتنة ولا أسباب فتنة، بل السلام عليكم، كيف حالك يا فلان، كيف حالك يا فلان لا بأس من دون خلوة، لا تخلو بأحد منهم، لكن مع المجموعة مع إخوانها بحضرة إخوانها بحضرة أخواتها بحضرة أمها بحضرة غيرهم، يعني مع المجموعة لا بأس تسلم عليهم، وتسألهم عن أحوالهم وعن أخواتها وعن غير ذلك لا بأس.\nأما الكشف وعدم الحجاب أو المصافحة هذا لا يجوز، الواجب التحجب، وأن تكون مستورة البدن، مستورة الرأس، مستورة الوجه، مستورة الأيدي والقدم، تكلمهم بالكلام فقط من غير مصافحة، هذا هو المشروع وهذا الذي جائز، وقد كان النساء يسألن النبي صلى الله عليه وسلم ويخاطبنه وهن مستورات، وهكذا يسألن أبا بكر وعمر وغيرهم وهن متحجبات، ويحضرن الصلاة مع النبي صلى الله عليه وسلم وهن متحجبات، كل هذا لا بأس به، أما كونها تصافح فلا النبي عليه السلام قال: إني لا أصافح النساء، وقالت عائشة رضي الله عنها في البيعة: ما مست يد رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام والله يقول: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًاا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فهي متحجبة تحضر وتجلس وتكلم وتسلم ثم تذهب إلى حاجاتها لا بأس نعم، أما من يدور بالقهوة يدور بها المحرم يدور بها الرجل، يدور بالقهوة الرجل أو المحارم كأختهم وعمتهم ونحو ذلك نعم.\nالمقدم: ولا سيما وملابس النساء اتخذت أشكالاً أخرى اليوم سماحة الشيخ؟\nالشيخ: كذلك الضيقة والقصيرة شر آخر هذا، حتى عند المحارم ينبغي أن تكون ملابس ضافية كافية؛ لأن المحارم قد يفتنوا قد يفتنوا بالمرأة إذا تساهلت، وإن كانت أختاً أو عمة أو بنت أخت، فينبغي للمرأة أن تكون حريصة على التستر والحشمة حتى مع المحارم، لكن لا يلزمها غطاء الوجه ولا غطاء الكفين عند المحارم ولا غطاء القدمين، لكن ينبغي لها أن تبتعد عن الثياب القصيرة والضيقة؛ لئلا يفتن بها بعض محارمها. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6118/حكم-مقابلة-المراة-لاقاربها-واقارب-زوجها-ومصافحتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_108/10808.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":8344,"question":"شيخ عبد العزيز ! نعود في بداية هذا اللقاء إلى رسالة الأخت (د. م. ع) من القصيم العين، أختنا أثارت خمسة أسئلة في حلقةٍ مضت، وها نحن نعود إلى بقية أسئلتها في هذا اللقاء، فتقول في سؤال لها: لقد تمادى الناس وتساهلوا في ذهاب بناتهم مع أصحاب النقل إلى مدارس خارج بلدتهم، وذلك بدون محرم مع السائق، ولا يرى الجميع من بد في ذلك، فحبذا لو عالجتم هذه المشكلة أنتم يا رجال الدين ويا أهل العلم، جزاكم الله عنها وعن المسلمين خير الجزاء، وجعل لما تقولون أذناً واعية وقلوباً صاغية؟","title":"حكم ركوب الطالبات مع سائق المدرسة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفقد ثبت في السنة عن رسول الله عليه الصلاة والسلام بالنهي عن سفر المرأة بدون محرم، فإذا كان سفر البنات الطالبات في المدارس يبلغ السفر الشرعي حرم على البنت أن تذهب إلا بمحرم، أما ما دام في أرجاء البلد وأطراف البلد وما لا يعد سفراً فإن هذا لا حرج فيه، أن تذهب في سيارات النقل مع البنات إلى المدارس لا حرج في ذلك، ما دام ذلك في أرجاء البلد وفي أطراف البلد، كل ذلك لا حرج فيه ولا يسمى سفراً، وليس له أن يخلو بواحدةٍ منهن، بل يكن جميعات، يكن معهن جماعة يكون معه جماعة، ينقلهن إلى المدارس، كل هذا لا حرج فيه.\nوإذا كان هناك انفراد بواحدة حرم عليه ذلك، بل عليه أن يتحرى أن ينزل آخر شيء ثنتين أو أكثر حتى لا يحصل خلوة بشيءٍ منهن، على السائق أن يلاحظ ذلك، إلا إذا كانت معه زوجته أو أمه أو أخته أو نحو ذلك فإنه لا يحصل بذلك خلوة، ولو كان الباقي واحدة. نعم.","link":"https://binbaz.org.sa/fatwas/6162/حكم-ركوب-الطالبات-مع-ساىق-المدرسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_113/11301.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":8388,"question":"رسالة وصلت إلى البرنامج من الرياض، وباعثها أخونا (محمد . ن. ش) أخونا يسأل مجموعةً من الأسئلة، من بينها سؤال يقول: ما حكم مشاهدة النساء في الفيديو؟","title":"حكم مشاهدة النساء السافرات في الفيديو","answer":"الجواب: الفيديو خطره عظيم، ولا يجوز.. أن تشاهد فيه النساء العاريات وشبه العاريات، والسافرات، بل يجب غض النظر عن ذلك، وعدم النظر إليهن؛ لأن هذا فتنة، ومن أسباب فساد القلوب وانحرافها عن الهدى، فلا يجوز للمؤمن أن يتفرج على النساء الكاسيات العاريات، أو شبه العاريات، أو السافرات، في الفيديو، أو في التلفاز، أو في غير ذلك، بل يجب عليه غض البصر، والإعراض عن النظر إليهن؛ لقول الله : قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ [النور:30] وفي الحديث، يقول المصطفى عليه الصلاة والسلام:  النظر سهم من سهام إبليس فالنظر له خطر عظيم، فينبغي الحذر. نعم.","link":"https://binbaz.org.sa/fatwas/6254/حكم-مشاهدة-النساء-السافرات-في-الفيديو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_116/11607.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":8431,"question":"رسالة مطولة باعثها أحد الإخوة من العراق يقول علي حسين محسن العامري ، محافظة واسط مدينة الكرامة العراق، أخونا مشكلته كالتالي: يقول: أنا شاب في الثالثة والعشرين من عمري متزوج ولي طفل، قمت خلال عملي في إحدى الدوائر من خلال المخالطة اليومية مع الناس، تعلقت بإحدى الفتيات، وهي كذلك، المهم تقدمت إلى أهلها للزواج منها فرفضوا بحجة أنني متزوج وكذلك أسكن المنطقة الريفية، وكررت الحالة أكثر من مرة فلم تتم موافقتهم على الزواج، فلما يئست منهم قررت ترك تلك الفتاة، وفعلاً قلت لها: إننا سوف نفترق؛ لأن الأمور تأزمت إلى حيث الأصعب، ومن المستحيل أن أطلق زوجتي الأولى وأترك ولدي إنني أخاف من الله، إخوتي في الدين: لما عرفت هي بذلك قررت الانتحار، والله يعلم بذلك، وفعلاً تناولت السم، ونقلت إلى المستشفى على إثرها، ثم فرجت بعد أسبوع، فكررت الخطبة للمرة الثالثة فلم يوافقوا، فحاولت الانتحار ثانية، ونقلت إلى المستشفى ثانية، ويستمر على هذا المنوال سماحة الشيخ إلى أن يقول في نهاية الرسالة: ماذا أفعل للمشكلة؟ أريد حلاً يرضي الله ورسوله والناس، هل يجوز لي أن أتزوج وأهرب بها معي؟ أم ماذا أفعل أرشدوني للطريق الشرعي وفقكم الله، ويبدو أن للموضوع صلة بالاختلاط سماحة الشيخ؟","title":"حكم محاولة الانتحار لعدم موافقة الولي على الزواج","answer":"الجواب: لا ريب أن الانتحار جريمة عظيمة، ومن كبائر الذنوب، يقول النبي ﷺ: من قتل نفسه بشيء عذب به يوم القيامة، والله يقول: وَلا تَقْتُلُوا أَنفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا [النساء:29].\nفهذه الفتاة حرام عليها الانتحار، والواجب عليها الصبر والاقتناع بما قسم الله لها، والتماس زوج آخر.\nوأما الأهل فالواجب عليهم أن ينظروا في الأمر، أهل الفتاة، الواجب عليهم أن ينظروا في الأمر، فإذا كان الرجل صالحاً للزواج فينبغي أن يزوجوه، ولو كان معه زوجة، والحمد لله قد أباح الله للمسلم أربعاً من النساء، فالواجب على أهل الفتاة أن يخافوا الله، وأن يراقبوا الله، وأن يزوجوها إذا خطبها الكفء، وإن كان عنده زوجة أو زوجتان أو ثلاث وهي رابعة لا يضر؛ فقد جاء عنه ﷺ أنه قال: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه - في لفظ: وأمانته- إلا تفعلوه تكن فتنة في الأرض وفساد كبير، فالمشروع لهم أن يزوجوا من خطب منهم إذا كان أهلاً لذلك، ولو كانت عنده زوجة، إذا كان ديناً مسلماً، الله يقول جل وعلا: يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13].\nوالنبي صلى الله عليه وسلم زوج فاطمة بنت قيس القرشية ، زوجها من أسامة بن زيد وهو مولى عتيق أعتقه النبي عليه الصلاة والسلام، وزوج عبد الرحمن بن عوف القرشي الزهري بلال بن رباح الحبشي أخته أخت عبد الرحمن وهي زهرية قرشية ، فالأمر في هذا واسع بحمد الله، وزيد بن حارثة تزوج زينب بنت جحش بنت عمة النبي عليه الصلاة والسلام.\nفالأمر في هذا بحمد الله واسع المهم الدين، فإذا كانت المرأة ترغبه فهي ترغب هذا وهو دين وهو معروف بالدين فالحمد لله، الواجب أن لا يلجئوها إلى الانتحار وإلى هذا الشر العظيم.\nوالواجب عليها هي أن تحذر الانتحار، وأن تتقي الله، وأن تبتعد عن هذا الشر العظيم.\nوعليك أيها الخاطب! أن تقنعها، وأن تخوفها من الله، وأن ترغبها في الخير، وأن تقول لها: لا، إذا تيسر الزواج بالطريقة الشرعية فالحمد لله، وإلا فالواجب علي وعليك طاعة الله ورسوله، والحذر مما نهى الله عنه ورسوله من الانتحار وغيره، هذا هو نصيحتي لجميع أهلها نصيحتي لهم أن يزوجوها، ونصيحتي لك أيضاً أن تقنعها أنت، وأن تنصحها وتوصيها بالخير والصبر حتى يقنع أهلها بالزواج، وعليك أن تنصحها أيضاً من جهة الانتحار وأنه محرم، كبيرة من كبائر الذنوب، ومن أسباب دخول النار، فالواجب عليها الحذر من ذلك، نسأل الله للجميع الهداية.\nأما أخذها بالقوة والهروب فهذا منكر لا يجوز، هذا لا يجوز لك ولا لها أيضاً، بل عليكما مراعاة الأمور الشرعية والحذر مما حرم الله عليكما جميعاً، والله المستعان. نعم.\nالمقدم: جزاكم الله خيراً، نتج هذا سماحة الشيخ عن الاختلاط كما ........ ؟\nالشيخ: الاختلاط شره عظيم، الواجب على المرأة أن تبتعد عن الاختلاط بالرجال، والواجب على الرجل أن يبتعد عن الاختلاط بالنساء، والواجب على المرأة أن تتستر، وأن تبتعد عن أسباب الفتنة، يكون عليها الستر والحجاب وعدم التبرج هذا هو الواجب، الله ما شرع لنا هذا إلا لمصلحة الجميع، ولهذا قال سبحانه: وَقَرْنَ فِي بُيُوتِكُنَّ وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33]، فلولا أن التبرج يضر الجميع لما نهى عنه سبحانه وتعالى، والتبرج هو إظهار المحاسن، هو إظهار الزينة، فالواجب على النساء التستر، والحجاب، والبعد عن مخالطة الرجال إلا بالحشمة، والحجاب، والكلام الطيب، والأسلوب الحسن البعيد عن الفتنة، وهكذا الرجل يجب عليه أن يبتعد عن الاختلاط بالنساء الكاشفات العاريات أو شبه العاريات، يجب عليه أن يبتعد عن ذلك، وأن يبتعد عن كل أسباب الفتنة، يخاف الله ويراقبه سبحانه وتعالى، نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/6315/حكم-محاولة-الانتحار-لعدم-موافقة-الولي-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_119/11908.mp3","categories":["النظر والخلوة والاختلاط","شروط وأركان الزواج"]},{"id":8443,"question":"رسالة وصلت من جمهورية مصر أيضاً، وباعثتها إحدى الأخوات من هناك، تقول: الفقيرة إلى الله (ع. ع. أ) أختنا لها أربعة أسئلة، تقول في سؤالها الأول: هل يجوز أن أظهر على ابن عم لي مع وجود محرم مكشوفة الوجه، مع العلم أنني منقبة؟ وما الفرق بين الحجاب والخمار والنقاب؟ وما هو الواجب شرعاً؟","title":"حكم ظهور المرأة أمام بني العم والخال مع وجود المحرم","answer":"الجواب: الظهور والبروز للسلام على ابن العم وابن الخال والجيران والأقارب غير المحارم لا بأس به، تظهر وتسلم عليهم، لا مانع لك من السلام على أقاربك من أولاد الخال وأولاد الخالة وأولاد العم وأولاد العمة، لكن مع الستر، مع الحجاب، تسلمين عليهم وتردين عليهم السلام، وتسألينهم عن أهلهم وأولادهم لا بأس وعن أحوالهم، هذا كله طيب، وهذا كله من حسن الخلق، «البر حسن الخلق»، والله جل وعلا شرع لنا السلام ... بدءاً ورداً، ولكن عليك الحجاب، سواء كان بخمار أو بنقاب أو بغير هذا من أنواع الستر، فالمرأة عليها الحجاب عن الأجانب ولو كانوا بني عم، ولو كانوا بني خال، أو بني خالة، كما قال الله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، والحجاب يكون من وراء الباب، ومن وراء الستر، ومن وراء في داخل الخيمة، من وراء الخمار على الوجه، تستر نفسها، تستر شعرها وبدنها بالخمار وهي جالسة مع الجماعة تسلم عليهم وترد عليهم، لكنها مستترة بحجابها بخمارها بجلبابها بغير ذلك.\nوالنقاب إذا كان ساتراً ما عدا العين أو العينين يكفي، ولكن الخمار أفضل منه وأتم ستراً، والواجب على المرأة في مثل هذا تقوى الله سبحانه وتعالى، والحرص على البعد عن أسباب الفتنة، لا تفتن ولا تفتن، هذا هو الواجب عليها، ويقول جل وعلا: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ ... [النور:31] الآية، فالله وضح لعباده ما ينبغي، وشرع لهم ما ينبغي، ونهاهم عما يضرهم سبحانه وتعالى، والزينة تشمل الوجه والشعر وغير ذلك، فلا يجوز إبداؤها إلا للمحارم، وأما التحدث مع الأقارب فلا بأس به إذا كانوا غير محارم كما تقدم، لكن لا تصافح، تسلم عليهم ترد عليهم السلام لكن من دون مصافحة، المصافحة تكون للمحرم لأخيها عمها خالها أو للنساء، أما مصافحة الرجال الأجانب ولو كانوا بني عم فلا تجوز، يقول النبي ﷺ لما أرادت بعض النساء أن تصافح في البيعة قال: إني لا أصافح النساء، وقالت عائشة رضي الله عنها: ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام، هذا هو المحفوظ عنه عليه الصلاة والسلام، ولنا فيه أسوة، كما قال الله : لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ لِمَنْ كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الآخِرَ وَذَكَرَ اللَّهَ كَثِيرًا [الأحزاب:21]؛ ولأن المصافحة فيها من الخطر ما فيها، حتى قال بعض أهل العلم: إنها أشد من النظر، رزق الله الجميع التوفيق والهداية. نعم.","link":"https://binbaz.org.sa/fatwas/6327/حكم-ظهور-المراة-امام-بني-العم-والخال-مع-وجود-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_120/12008.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":8499,"question":"أخت لنا من المغرب تقول عائشة تسأل مجموعة من الأسئلة سماحة الشيخ:ففي سؤالها الأول: علام تجب تغطية الوجه؟","title":"ممن تغطي المرأة وجهها؟","answer":"الجواب: يجب أن يغطى الوجه عن الرجال الأجانب في أصح قولي العلماء، سواء كان الأجنبي ابن عم أو ابن خال أو من الجيران أو غيرهم، لقول الله سبحانه يخاطب المسلمين في عهده ﷺ ومن بعدهم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] وهذا يعم أزواج النبي ﷺ وغيرهن من المؤمنات كما قال سبحانه: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكََ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] (والجلابيب): ما يوضع على الرأس والبدن من الجلباب من اللحاف الذي يغطى به الرأس والوجه والبدن، وما يوضع على الرأس يقال له: الخمار، فهي تغطي وجهها بالجلباب أو بالخمار؛ لأنه معظم زينتها وأهم زينتها ويعرف به جمالها أو دمامتها هذا هو الصواب، وقال جل وعلا: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31] الآية.\nفقوله إِلَّا مَا ظَهَرَ مِنْهَا فسره ابن مسعود وجماعة: بالملابس الظاهرة وفسره قوم: بالوجه والكفين، ولكن التفسير الأول أصح؛ لأنه موافق للأدلة الشرعية.\nوحمل بعضهم قول من فسره بالوجه والكفين على أن هذا كان قبل الحجاب، أما بعد الحجاب فيجب ستر الوجه والكفين في جميع الأحوال عن الرجل الأجنبي.\nثم قال سبحانه: وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ [النور:31] (والخمر): جمع خمار، وهو ما يستر به الرأس وما حوله، سمي خماراً لأنه يستر ما وراءه كما سميت الخمر خمراً لأنها تستر العقول وتغيرها، فالخمار يستر الوجه؛ ولهذا قال: وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَىى جُيُوبِهِنَّ [النور:31] (والجيب): الشق الذي في الثوب يخرج منه الرأس فإذا ألقت الخمار على وجهها ورأسها فقد سترت الجيب، وإذا كان هناك شيء من الصدر سترته أيضاً ثم قال: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] والزينة: تشمل الوجه تشمل الرأس تشمل بقية البدن، فيجب عليها أن تغطي هذه الزينة حتى لا تفتن وحتى لا تفتن. نعم.","link":"https://binbaz.org.sa/fatwas/6559/ممن-تغطي-المراة-وجهها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_126/12613.mp3","categories":["اللباس والزينة","النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":8587,"question":"هذه رسالة وردتنا من السائل علي دليم غرامة الأسمري من محايل تهامة عسير إدارة التعليم، يقول الأخ علي دليم في رسالته: أنا رجل متزوج وعندي ثلاثة أطفال، يوجد لدي عمتي أم زوجتي طلقها زوجها الذي هو عمي منذ عشر سنوات، وأبرزها بصك شرعي وساكنة معي، وأقوم بالإنفاق عليها، ولا يخفى على فضيلتكم أن عمي أبو زوجتي غير متزوج ويجيء عندنا غالب الأوقات، وعندما يجيء إلى بيتي تقابله عمتي فتباشر عليه بالقهوة والطعام وتجالسه وتتحدث معه، وفي كثير من الأوقات تذهب إلى بيته وتجلس عنده مدة نصف نهار، وقد نصحتها عن هذا العمل فأثارت مشكلة بيني وبين زوجتي، وتأمر على زوجتي بالذهاب إلى والدها علماً أن بيته يبعد عنا بحوالي اثنين كيلو متر وهي غير مغطية -أو مغطاة كما كتب- ولا أسمح لها بالذهاب وعندما أمنعها تقوم عمتي فتسعى بالنميمة بيني وبين زوجتي وتمنعها مني وتهجرني لمدة أكثر من شهرين وتجبرني أن أذهب إلى أسواق الذهب وأشتري لها أنواعاً من الصيغة الذهبية بمبالغ هائلة وأنا لا أستطيع أستمر على هذا العمل، أرجو من فضيلتكم إفادتي في هذا أفيدوني أفادكم الله؟","title":"حكم خلو الرجل بمطلقته طلاقاً بائناً","answer":"الجواب: هذا العمل من أم زوجتك لا يجوز، ليس لها أن تذهب إلى بيته وهو ما عنده أحد في بيته، إذا كان ما عنده أحد في بيته ليس لها أن تذهب إليه؛ لأن هذه تهمة، والخلوة بها أمر محرم ومنكر، ووسيلة إلى فعل الفاحشة، كذلك ليس لها أن تخلو معه في بيتك، وتتحدث إليه وتقدم له الطعام معه وحدها، ليس معه أحد، أما إذا كانت جلست حوله تتحدث وبنتها عندها أو عندها غيرها من غير خلوة مع الحجاب والستر فلا بأس، أما أن تكشف له ولا تتحجب عنه هذا لا يجوز، لأنها لما طلقها واعتدت بانت منه، إذا كان طلاقها رجعياً فإنها تبين منه بعد خروجها من العدة، وتكون أجنبية ليس له الخلوة بها، وليس له النظر إليها، وليس لها أن تكشف وجهها ولا رأسها ولا شيء من بدنها له، بل عليها أن تحتجب كسائر الأجانب، فعليك أن تنصحها وتوجهها إلى الخير، وتطلب من الناس الطيبين الذين تعرفهم أن ينصحوها وأن يحذروها من مغبة عملها وأنه أمر لا يجوز.\nوإذا كانت تؤذيك وتسبب مشاكل بينك وبين زوجتك، فلك أن تمنعها من دخول بيتك، لك أن تمنعها من دخول بيتك وتذهب إلى حيث شاءت؛ لأنها تضرك حينئذٍ، وإن صبرت عليها ونصحت فأنت مأجور. نعم.","link":"https://binbaz.org.sa/fatwas/6672/حكم-خلو-الرجل-بمطلقته-طلاقا-باىنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_209/20911.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":8622,"question":"تقول: إن لها أولاد عم، ولم ترهم منذ فترة طويلة، وهم في الخمسينات وهي صغيرة هل لها أن تصافحهم وأن تجالسهم؟","title":"حكم مصافحة ومجالسة الأجانب من الأقرباء","answer":"الجواب: لها أن تسلم عليهم وترحب بهم، تدعو لهم وتجلس معهم، للسؤال عنهم وعن أحوالهم مع الحجاب والحشمة وعدم التبذل وعدم إبداء شيء من عورتها، أما المصافحة فلا، لا تصافح المرأة الرجال، يقول النبي ﷺ: إني لا أصافح النساء وقالت عائشة رضي الله عنها لما بايع النبي ﷺ النساء تقول رضي الله عنها: والله ما مست يده يد امرأة قط، ما كان يبايعهن إلا بالكلام فإذا جلست المرأة مع أقربائها، أو مع جيرانها مع الحشمة والحجاب وسترت بدنها ووجهها ورأسها وبدنها، وكلمتهم وكلموها وسلمت عليهم وسلموا عليها لا بأس بهذا من دون خلوة، لا تخلو بالأجنبي أبداً، لكن مع جماعة الأقارب أو الجيران أو مع أمها أو مع أخيها لا بأس بهذا من دون مصافحة نعم. ومن دون كشف الوجه وغيره. نعم.\nالمقدم: بارك الله فيكم، سنعود إلى رسالتك يا أختنا من المغرب في حلقة قادمة إن شاء الله.","link":"https://binbaz.org.sa/fatwas/6754/حكم-مصافحة-ومجالسة-الاجانب-من-الاقرباء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_129/12911.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":8639,"question":"هذه رسالة وردتنا من السائل (ع. ب. ع) من ينبع البحر، يقول في رسالته: أنا رجل متزوج، وزوجتي في يوم من الأيام سافرت أنا وإياها إلى أهل زوجة أخي، وكنا جالسين فضحكت زوجتي ضحكاً كثيراً ولم أرض بهذا وفي أثناء هذا ضربتها في ساقها فغضبت مني وذهبت تنام مع أخت زوجة أخي وهذه معها أخوها عازب وناموا سوياً إلى الصباح، فما حكم هذا في الشرع وقد بقي عندي شك في زوجتي، أفيدوني أفادكم الله؟","title":"حكم نوم المرأة مع أخرى في وجود رجل أجنبي","answer":"الجواب: على كل حال الضحك الكثير أنت محسن في نهيها عن هذا الشيء وضربها إذا كان الضرب خفيف قليل لا يضرها، ونومها مع المرأة وعندها أجنبي هذا غلط ولا ينبغي لك التهمة؛ لأن المرأة قد تغفل وتتساهل إذا كانت مستورة متحجبة ومستورة، لكن نومها في محل فيه رجل غير محرم لها غلط منها؛ لأنها قد ينكشف منها شيء، قد يرى منها شيء، فلا ينبغي لها أن تنام في محل فيه رجل أجنبي، ولكن هذا لا يوجب عليك سوء الظن ولا طلاقها بل تنصحها وتوجهها حتى لا تعود لمثل هذا ولا حرج إن شاء الله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6779/حكم-نوم-المراة-مع-اخرى-في-وجود-رجل-اجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_212/21206.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":8681,"question":"هذه رسالة وردتنا من السائل حسن عبد الله الحسن من السودان مدينة الأبيض، يقول في رسالته: أنا معلم ملتزم بالكتاب والسنة ومتمسك بسيرة السلف الصالح رضوان الله عليهم أجمعين، أعمل بمدرسة مختلطة بها معلمين ومعلمات، وقوة المعلمات أكبر من قوة المعلمين -يقصد العدد- ورغم أن كل شيء منفصل مكاتبنا وغيرها، إلا أننا نجتمع اجتماعات عديدة لمناقشة سير الدراسة والعمل، هل هذا يضر مع الحذر، وهل أجلس مع زملائي وزميلاتي المتبرجات في مثل هذه الاجتماعات أم لا، أفيدوني أفادكم الله؟","title":"حكم التدريس في المدارس المختلطة","answer":"الجواب: هذا الاجتماع فيه خطر عظيم، فإن الاجتماع بالنساء المتبرجات فيه فتنة عظيمة، وقد قال عليه الصلاة والسلام في الحديث الصحيح: ما تركت بعدي فتنة أضر على الرجال من النساء فالذي أنصحك به أن لا تبقى معهم، وأن يكون الرجال على حدة والنساء على حدة، وأن يدرس الرجال الرجال والنساء النساء.\nهذا هو الواجب على أهل المدرسة، وهذا الواجب عليكم معشر المدرسين، وهذا الواجب على المدرسات أيضاً، أن يخفن الله وأن يبتعدن عن الرجال، فيكون عملهن وحدهن مع البنات ويكون عملكم وحدكم مع الرجال، ولا يكون لكم اجتماع إلا في المسائل التي تدعو الحاجة إليها من دون تبرج النساء ومن دون تكشفهن، بل يكن مستورات متحجبات بعيدات عن أسباب الفتنة، عند الحاجة إلى سؤالهن عن شيء أو إفادتهن بشيء أو نصيحتهن أو نحو ذلك، أما الاجتماع معهن على أنهن مدرسات وأنتم مدرسون مع تبرجهن وإظهار محاسنهن فهذا شره عظيم، وخطره كبير وهو منكر ظاهر.\nفالواجب تغييره وعلى أهل المدرسة أن يعتنوا بهذا الأمر وأن يخافوا الله وأن يراقبوا الله، وأن يفصلوا البنين عن البنات، وأن يكون مدرسو البنين هم الرجال وأن يدرس البنات المدرسات من النساء، هذا هو طريق النجاة وهو طريق السلامة وهو الواجب على الجميع؛ لأن الله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6825/حكم-التدريس-في-المدارس-المختلطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_215/21512.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":8756,"question":"هذه رسالة وردت إلينا من المرسل عطية الجهني من جدة يقول في رسالته: أنا شاب بحمد الله أصلي وأصوم وأحج ولم أرتكب فاحشة ولله الحمد، إلا أنني أحب النظر إلى النساء والتحدث، ولكن الأكثر هو النظر، فهل عملي هذا يبطل أعمال الخير التي أقوم بها كالصلاة وغيرها، أفيدوني أفادكم الله؟","title":"حكم النظر إلى النساء والتحدث معهن","answer":"الجواب: المعصية لا تبطل أعمال الخير، ولكن يخشى من المعاصي إذا كثرت أن ترجح بالحسنات، فالواجب على المؤمن أن يحذر جميع المعاصي ومن جملتها النظر للنساء والتحدث للنساء للشهوة هذا منكر، والله جل وعلا قال: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ [النور:30].\nفعليك أن تغض البصر وتجاهد نفسك لله عز وجل وتحذر؛ لأن النظر سهم من سهام إبليس ، وربما جرك النظر إلى الفعل والمعصية الكبرى وهي الزنا، فعليك أن تتقي الله وأن تغض بصرك وأن تحذر شر نفسك وهواك، وهكذا التحدث إليهن لقصد الشهوة أو لقصد النظر إليهن أو لقصد الخلوة بهن أو لأي قصد فاسد عليك الحذر.\nأما التحدث في أمور مباحة كسؤالها سؤال المرأة عن أهلها أو عن أولادها أو سلعة اشتريتها منها أو بعتها عليها في الأمور العادية المعروفة التي ليس فيها فتنه وليس فيها شهوة وليس فيها نظر إلى ما حرم الله، وإنما هو حديث مباح أو حديث شرعي هذا لا بأس به.\nأما التحدث الذي يفضي إلى الفساد أو يقصد منه التلذذ بصوت المرأة، والمعرفة لما لديها من أشياء أخرى تتعلق بميلك إليها فهذا لا يجوز، لأنه يفضي إلى شر. وعلى المؤمن دائماً أن يحذر ما حرم الله عليه، ولكن ليست المعصية تبطل الأعمال، وإنما يبطل الأعمال الكفر بالله الردة عن الإسلام هي التي تبطل الأعمال، كما قال الله سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88].\nقال سبحانه: وَمَنْ يَكْفُرْ بِالإِيمَانِ فَقَدْ حَبِطَ عَمَلُهُ [المائدة:5] فالكفر بالله والشرك هو الذي يحبط الأعمال، أما النظر أو الغيبة أو النميمة أو الزنا هذا لا يحبط الأعمال، ولكن فيه خطر عظيم من جهة أن السيئات متى كثرت يخشى على صاحبها من الطبع على قلبه، ويخشى على صاحبها أن تكون وسيلة إلى كفره وردته، ويخشى على صاحبها في الآخرة أن ترجح سيئاته بحسناته نسأل الله السلامة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6917/حكم-النظر-الى-النساء-والتحدث-معهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_217/21712.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":8799,"question":"السؤال الثالث في رسالة الإخوة من العراق من محافظة أربيل، يقولون فيه: فينا من هو في الجامعة يتلقى العلوم ولكنه يحب أن يعلم موقف الإسلام منه وهو محيط بالنساء؛ لأن الدراسة في هذه الكلية مختلطة أي: أنها للذكر والأنثى، مع العلم أن نساءنا أي: الطالبات أكثرهم من غير المتحجبات، وتلبسن ما يحلو لهن، أفيدونا أفادكم الله؟","title":"حكم الدراسة في الجامعات المختلطة","answer":"الجواب: نصيحتي للطالب في هذا ألا يدرس مع الطالبات وألا يختلط بهن؛ لأن هذا وسيلة إلى الفتنة بهن، فالواجب عليه أن يلتمس طريقاً آخر للتعلم، أما دراسته مع البنات فهي وسيلة إلى خطر عظيم، والواجب عليه الحذر من ذلك، والدراسة المختلطة فيها شر عظيم وفساد كبير، ولا يجوز لولي الأمر التساهل فيها، بل يجب على ولاة الأمور أن تكون الدراسة غير مختلطة، هكذا يجب على ولاة أمر المسلمين، أن تكون الدراسة للبنات على حدة مع الصيانة والتحفظ، وأن تكون الدراسة للبنين على حدة، هذا في مكان وهذا في مكان، مع العناية بأسباب السلامة، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/6951/حكم-الدراسة-في-الجامعات-المختلطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_221/22104.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":8807,"question":"هذه رسالة بعث بها مرسلها ويبدؤها بقوله: بسم الله الرحمن الرحيم، والصلاة والسلام على أشرف المرسلين، السلام عليكم ورحمة الله وبركاته، أخوكم في الله (ح. س. ع) من تونس يقول في سؤاله: يوجد عندنا في تونس الفساد بأنواعه وأشكاله، وأنا كشاب مسلم أقرأ في المعهد وأركب الحافلة والسيارة وأدخل السوق، ففي المعهد -مثلاً- مهما أغض بصري لا بد أن أرى عورات الطالبات؛ وذلك لأنهن لا يرتدين الزي الإسلامي، وربما أتكلم أنا وطالبة؛ وذلك لأن هذه الحالة في مجتمعنا التونسي عادية، وفي الركوب في الحافلة أو السيارة في أكثر الأيام يحدث زحام شديد فيلتصق جسد الأنثى بجسد الذكر، وأنا يحدث لي ذلك دائماً، وفي بعض الأحيان يلتصق بي شارب خمر فأشم منه رائحة الخمر، وفي السوق أرى وأسمع كل ما أكره، هذه الحالة التي أعيشها وأنا كمسلم ملتزم بديني وأعرف أن هذه الحالة مخالفة لديني، وعرضت عليكم حالتي فبماذا تفيدوني وتساعدوني يرحمكم الله؟","title":"نصيحة لمن يعيش في بيئة اختلاط وتبرج","answer":"الجواب: نسأل الله لنا ولجميع المسلمين التوفيق وصلاح الحال، ونسأله أن يوفق الحكومة التونسية والعلماء والمسئولين فيها لما فيه صلاح العباد والبلاد، وأن يصلح أحوال الشعب التونسي وأحوال المسئولين وأن يوفقه لما يرضيه وأن يعين المسئولين جميعاً على أداء حق الله والقيام بأمره سبحانه وتعالى.\nأما أنت أيها السائل! فالواجب عليك غض البصر، والأمر بالمعروف والنهي عن المنكر حسب طاقتك، فغض بصرك عن النساء في المعهد وغيره، وإذا كانت الدراسة مختلطة في المعهد فاترك هذه الدراسة وانتقل إلى دراسة غير مختلطة في تونس أو غيرها؛ لأن الاختلاط بين البنين والبنات فيه خطر عظيم ويخشى منه عاقبة وخيمة، فينبغي لك يا أخي أن تحرص على أن تكون دراستك في محل غير مختلط، وإذا بليت بهذه الدراسة فعليك بغض البصر والحذر، والواجب عليك فيما أرى أن تلتمس دراسة غير مختلطة حتى تسلم من مغبة هذا الاختلاط.\nوهكذا في السيارة وفي القطار وفي أي حافلة عليك أن تجتهد في غض البصر والنصيحة لإخوانك المسلمين، فإذا رأيت المرأة التي قد تكشفت وتبرجت تنصحها لله وتقول لها: يا أمة الله! هذا لا يجوز اتق الله راقبي الله تستري، البسي كذا وافعلي كذا، وإذا رأيت من يشرب الخمر أو رأيت منه رائحة الخمر تنصحه لله، وتخبره أن الخمر محرمة وأنها لا تجوز، وأن الواجب على المسلم طاعة الله ورسوله، وتبين عواقبها السيئة وما فيها من الشر العظيم، وهكذا التدخين تبين أنه منكر وأنه يضر ضرراً عظيماً، فالمؤمن هكذا ينصح يقول الله : وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] هذه صفة المؤمنين والمؤمنات.\nفعليك أنت يا أخي! وعلى كل مؤمن وعلى كل مؤمنة التناصح في الحافلة في القطار في السيارة، في المدرسة في المعهد في كل مكان التناصح واجب بين المسلمين، وبهذا يقل الشر ويكثر الخير، وهكذا قوله جل وعلا: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُوْلَئِكَ هُمُ الْمُفْلِحُونَ [آل عمران:104] وهكذا قوله سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللَّهِ [آل عمران:110] وهكذا قوله ﷺ في الحديث الصحيح: من رأى منكم منكراً فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه وذلك أضعف الإيمان.\nفعليك يا أخي! وعلى جميع إخوانك المسلمين التناصح فيما بينكم في تونس وغيرها، وعليكم جميعاً التآمر بالمعروف والتناهي عن المنكر بالحكمة بالكلام الطيب بالأسلوب الحسن حسب الطاقة، نسأل الله للجميع التوفيق والهداية.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/6962/نصيحة-لمن-يعيش-في-بيىة-اختلاط-وتبرج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_222/22209.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":8820,"question":"نعود في بداية هذا اللقاء إلى رسالة الأخ حسين فالح القضاع، من الزهران، أخونا يسأل مجموعة من الأسئلة، كلها تدور حول محور واحد، حول تعامل الرجل مع المرأة، ولا سيما إذا كانت زميلته في العمل كما يعبر، فأخونا في سؤاله الأول يقول: كيف يعامل الرجل المسلم المرأة الأجنبية، بصرف النظر عن ديانتها إذا كانت زميلة عمل، ويحتاج التحدث إليها بشئون العمل أثناء العمل؟وفي سؤاله الثاني يقول: بالنسبة للمرأة المسلمة العاملة المتبرجة، هل يجوز إفشاء السلام عليها أو الرد على تحيتها من قبل الرجل المسلم، وكيف تحدد العلاقة بين الرجل والمرأة أثناء الدوام؟وفي سؤاله الثالث: طبيعة العمل تفرض على المسلم مخالطة النساء العاملات ومراجعة بعضهن بخصوص العمل، وأحياناً يلمح منهن ما لا يجوز له أن يرى من المرأة دون قصد وخصوصاً إذا كان لباسهن غير محتشم، فهل يلحقه إثم بذلك، فإذا أراد هذا المسلم مخاطبة المرأة فهل ينظر إليها أم ينظر إلى الأرض؟وسؤاله الرابع: حول نفس الموضوع تقريباً إذا كان طبيعة العمل تفرض على الرئيس المسلم التحدث إلى الموظفة العاملة على انفراد، هل يقفل باب المكتب عليهما حتى لا يسمع أحد الحديث أم ماذا يعمل؟والسؤال الأخير: طبيعة مأمورات الشراء التباحث مع التجار على انفراد مما يضطرها إلى قفل غرفة الاجتماع على ممثل التاجر، ومأمورة الشراء وأحياناً تكون المأمورة وحدها مجتمعة مع رجلين أو ثلاثة في غرفة مقفلة، فما هو الحكم في تلك الأمور؟وأرجو أن تتفضلوا بمعالجة هذا جزاكم الله خيراً.","title":"الواجب على موظف في مقر عمله نساء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذه المسائل التي ذكرها السائل كلها مهمة والواجب قبل كل شيء أن لا يعمل المؤمن في وسط النساء، فإذا كان العمل بين الناس فالواجب الحذر من ذلك وأن يلتمس عملاً آخر؛ لأن هذا المكان مكان فتنة ومكان خطر، فإذا كان بين العاملات من النساء فلاشك أنه في خطر عظيم؛ لأن الشيطان حريص على إيقاع الفتنة بين الرجل والمرأة، وحريص على أسباب الفاحشة، فالواجب على المؤمن أينما كان أن لا يرضى بأن يكون عاملاً بين العاملات من النساء، وهكذا الطالب في الجامعات والمدارس المختلطة يجب عليه أن يحذر ذلك، وأن يلتمس مدرسة وجامعة غير مختلطة؛ لأن وجوده مع الفتيات على الكراسي.. كراسي الدراسة وسيلة لشر عظيم وفساد كبير.\nوالجواب عن هذه الأسئلة التي ذكرها السائل: الواجب عليه عند الابتلاء بهذا الأمر إلى أن يجعل الله فرجاً ومخرجاً أن يغض بصره وأن يحذر من النظر إليها، أو إلى محاسنها أو إلى مفاتنها، بل يلقي بصره إلى الأرض ولا ينظر إليها ومتى صادف شيئاً من ذلك أعرض وصرف بصره.\nثبت عن رسول الله عليه الصلاة والسلام أنه سئل عن نظر الفجأة، فقال للسائل: اصرف بصرك، وفي اللفظ الآخر: فإن لك الأولى وليست لك الأخرى، يعني: لك الأولى التي جاءت صدفة من غير قصد، أما الثانية التي عن قصد للنظر فهذه لا تجوز، والله يقول سبحانه: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ [النور:30]، ويقول سبحانه: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ [النور:31].\nفعلى المؤمن أن يغض بصره فإن صادف شيئاً من غير قصد صرف بصره، إذا فاجأته قابلها في الباب، أو قابلته في الباب فإنه يصرف بصره ويعفو الله عن الأولى التي صادفها ولم يقصدها.\nكذلك إذا بلي بها في التحدث إليها في شيء يتعلق بالعمل فإنه يتحدث إليها لكن من غير أن يقابل وجهها، من غير أن ينظر إلى محاسنها، بل يعرض عنها أو يلقي بصره إلى الأرض ويتكلم حتى يقضي حاجته وينصرف، وهذا من الأمور الواجبة التي تجب على المؤمن العناية بها.\nوكذلك إذا ذهبت إلى الشراء والبيع ليس لها أن تخلو بالرجل ولا مع الرئيس ولا مع المدير، ليس له أن يخلو بها سواء كان مديراً أو رئيساً أو وزيراً أو صاحب دكان ليس له الخلوة بها؛ لأن هذا خطر عظيم، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: لا يخلون رجل بامرأة إلا ومعها ذو محرم، وقال ﷺ: ما خلا رجل بامرأة إلا كان الشيطان ثالثهما، أو كما قال وفي اللفظ الآخر: لا يخلون رجل بامرأة فإن الشيطان ثالثهما.\nفالمقصود أن الخلوة فيها خطر عظيم فلا يجوز للمؤمن أن يخلو بها وليس لها أن تخلو به، ولو كانت في حاجات تتعلق بها أو بوظيفتها.\nفإذا كان ولابد فليكن الباب مفتوحاً باب المكتب مفتوحاً إذا لم يتيسر من يشارك في المجلس فليكن الباب مفتوحاً لا مغلقاً، حتى يراهما من يمر، وإذا أمكن إيجاد ثالث يحضر معهم ولو بعيداً لا يسمع الكلام لكنه في المجلس ينظر فهذا هو الواجب حتى لا تقع الخلوة المحرمة، فيستدعي من يكون ثالثاً ويبتعد عنهم حتى لا يسمع الكلام الذي يتعلق بالعمل وهو سر حتى لا تكون هناك فرصة للشيطان.\nنسأل الله للجميع العافية والهداية ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: جزاكم الله خيراً. إنما من حيث المبدأ تعتبر كل هذه الصور التي ذكرها أخونا تعتبر محرمة؟\nالشيخ: نعم، ما يجوز.\nالمقدم: من حيث المبدأ؟\nالشيخ: من حيث المبدأ لا يجوز له أن يكون في مكتب أو مدرسة أو جامعة مختلطة، نسأل الله السلامة. نعم.","link":"https://binbaz.org.sa/fatwas/6975/الواجب-على-موظف-في-مقر-عمله-نساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_136/13601.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":8879,"question":"هنا رسالة باعثها أحد الإخوة المستمعين وقضيته هي قضية كثيراً ما يسأل عنها سماحة الشيخ أخونا من القنفدة، ورمز إلى اسمه بالحروف (ح. م. ع. ق) أخونا يقول في قضيته: هل يجوز لي الجلوس مع زوجات إخواني والتحدث معهم، وإيصالهم مثلاً إلى المستوصف أو إلى بيوت أهلهم أو إلى أحد الأقارب؟ ثم يقول أيضاً: إن لي زوجة وأغيب عنها لمدة أسبوعين أو ثلاثة وفي حالة وجودي معها سواء طال الجلوس أو كثر لا أتحدث إليها ولا يخدمني إلا زوجات إخواني، ويرجو التوجيه من سماحة الشيخ حول هذه القضية؟","title":"حكم تحدث الرجل مع زوجات إخوانه","answer":"الجواب: زوجات الإخوة لسن محارم لحميهن، وليس له أن يخلو بواحدة منهن ولا أن يذهب بها وحدها إلى بيت أهلها أو إلى المستوصف أو المستشفى؛ لأن الخلوة ممنوعة، يقول النبي ﷺ: لا يخلون رجل بامرأة إلا ومعها ذو محرم ، ويقول ﷺ: لا يخلون رجل بامرأة فإن الشيطان ثالثهما .\nفالواجب على زوجات الأخ التستر والحجاب وعدم كشف الوجه، ولا غيره من محاسنهن بل عليهن التستر والحجاب وليس له الخلوة بواحدة منهن، أما التحدث إليهن عند اجتماعهن أو بحضور الأزواج لا بأس مع الستر والحجاب وعدم الفحش في القول، يعني: التحدث الطيب السليم الذي لا فحش فيه لا بأس بذلك، أما أن يخلو بواحدة منهن أو ينقلها إلى مستشفى أو غيره وحدها فلا يجوز؛ لأن هذا من أسباب الخطر، ومن أسباب تزيين الشيطان للوقوع فيما حرم الله، فلا يجوز للمؤمن أن يعرض نفسه للخطر فيعصي رسول ربه عليه الصلاة والسلام ويقع في الفتنة والتهمة، أما إذا كن ثنتين أو ثلاث لا يخلو بواحدة فلا بأس، إذا حمل ثنتين أو ثلاث إلى أهلهن أو إلى مستشفى من دون أن يتهم من دون ريبة فلا بأس بذلك، أو تحدث إليهن أو إليهما فلا بأس بذلك لعدم الخلوة، الخلوة إنما تكون بالواحدة، وكذلك إذا كان هناك ريبة يتجنب الريبة، إذا كان إخوانه يتهمونه ولا يرضون منه بأن ينقل زوجاتهم إلى بيوت أهليهن أو إلى المستشفى فلا يتعرض ذلك ويبتعد عن أسباب التهمة.\nوكذلك زوجته الواجب عليه أن يحسن عشرتها وأن يستخدمها هي لا يستخدم زوجات إخوانه، يستخدمها هي ويتلطف بها ويحسن عشرتها، ويحدثها وتحدثه، هكذا يقول الله : وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] ، ويقول سبحانه: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنََّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] ، ويقول ﷺ: خيركم خيركم لأهله وأنا خيركم لأهلي.\nفالواجب عليك أيها السائل أن تتقي الله وأن تحسن العشرة لزوجتك، وأن تستخدمها وأن لا تحقرها وأن لا تستخدم زوجات إخوانك بدلاً منها بل استخدمها هي وانتفع بها واستمتع بها وأحسن عشرتها وابتعد عن أسباب التهمة، هدى الله الجميع.\nالمقدم: سماحة الشيخ! لعل سماحتكم يتذكر الفتوى التي تفضلتم بها بخصوص السائق الأجنبي والنساء ولا سيما إذا كن داخل المدن، البعض فهم أن ذلك جائز، يجوز للسائق أن يأخذ المرأة طالما أنه داخل المدينة ويذهب بها إلى المستشفى أو إلى المدرسة ونحو ذلك، لا أدري سماحة الشيخ هل هناك من توضيح أكثر؟\nالشيخ: تقدم التنبيه على هذا في بعض الأجوبة الماضية وذلك أنه لا يجوز، لا يجوز للسائق أن ينقل المرأة إلى المستشفى أو إلى غير المستشفى أو إلى المدرسة وحدها بل عليه أن يكون معها غيرها؛ لأن الخلوة فيها الخطر العظيم الذي أشار إليه النبي ﷺ.\nفالحاصل أن الخلوة بالمرأة سواء كان في البيت أو في السيارة لا تجوز، والواجب على أهلها أن ينتبهوا لهذا الأمر ولو كانت ثقة، ولو كانت مدرسة لا تذهب وحدها فالشيطان قد ينزغ بينهما في مواعيد ضارة، فالواجب أن تكون معها امرأة أخرى أو يكون معها رجل آخر أو أم السائق أو زوجة السائق أو غيرهما، لابد يكون معهم ثالث حتى لا تقع الخلوة. نعم.\nالمقدم: وينطبق الحكم أيضاً حتى بالنسبة للحمو؟\nالشيخ: نعم، حتى أخو الزوج نعم، وعم الزوج لا يخلو بها، أما أبوه محرم، أبوه وابنه محرم. نعم.\nالمقدم: وسواء كان ذلك داخل المدن أو خارجها؟\nالشيخ: نعم، إذا كان سفر ما يجوز مطلقاً، لكن هذا في داخل المدن أسهل إذا كان معهم ثالث لا بأس ولو كان غير محرم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7035/حكم-تحدث-الرجل-مع-زوجات-اخوانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_139/13905.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":8885,"question":"الواقع في سؤالها الأخير سماحة الشيخ تذكر بعض المعاناة التي تجدها ولا سيما إذا جاءها أناس زوار في المنزل وهي لا تريد السلام عليهم بأنهم أجانب كما تقول إلا أن أهلها يمقتون فعلها، وترجو التوجيه أيضاً؟","title":"حكم طاعة البنت لأمها في السلام على الأجانب","answer":"الجواب: هذا فيه التفصيل، إن كان القادم نساء فلا مانع من الاتصال بهم، إرضاء للوالدة ونصيحتهم وتوجيههم إلى الخير فهذا من باب الدعوة إلى الله، فلا ينبغي لك أن تمتنعي من هذا، ولعل الله أن يهدي بك هؤلاء فتفلحي وتنجحي في هذا الأمر، أما إن كانوا رجالاً هذا محل تفصيل، إن كان المقصود السلام عليهم لأنهم أقارب أو جيران فلا مانع من السلام عليهم ورد السلام عليهم مع الاحتفاظ بالحجاب الشرعي وعدم إبداء شيء من الزينة أو التبرج، تكونين مستورة في شعورك وبدنك كله ووجهك ونحو ذلك، وتردين السلام والتحية وتسألينهم عن أهليهم لا بأس بهذا، وإذا تمكنت من النصيحة لهم والدعوة إلى الله  فافعلي وهذا لا يضرك.\nأما إن كان الحضور يقتضي المشاركة في محرم أو تبرج بما حرم الله، أو كشف لشيء من العورة أو مشاركة فيما حرم الله من شرب مسكر أو غير هذا مما حرم الله فهذا لا تطيعيهم فيه واعتذري، وقولي: إن هذا لا يجوز لك، وإنك تنصحينهم أن يتركوا ما حرم الله، وأن المشاركة فيما حرم الله أمر لا يجوز، فإن عذروا فالحمد لله، وإن لم يعذروا فأنت معذورة من جهة الله ولا يضرك كيدهم ولا يضرك غضبهم، والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/7041/حكم-طاعة-البنت-لامها-في-السلام-على-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_139/13911.mp3","categories":["قضايا المرأة","بر الوالدين","النظر والخلوة والاختلاط"]},{"id":8937,"question":"كثيرًا من الرجال في بعض الأسر يسمح لزوجته أو ابنته أو أخته بالظهور أمام الرجال غير المحارم كجماعته وأصدقائه وزملائه والجلوس معهم والتحدث إليهم كما لو كانوا محرمًا لها، وإذا نصحناهم قالوا: إن هذه عاداتهم وعادات آبائهم، كما أنهم يزعمون أن قلوبهم نظيفة، ومنهم أيضاً المكابر والمعاند وهو يفهم ذا الحكم، ومنهم من يجهله. أرجو أن تتوجهوا بنصيحة إلى إخواننا حول هذا الموضوع؟","title":"حكم ظهور النساء أمام الرجال غير المحارم","answer":"الجواب: الواجب على كل مسلم أن يعلم أن العادات يجب أن تعرض على الشرع المطهر، وأنها يكون فيها الخير الطيب ويكون فيها الشيء الرديء، وليس اعتياد الناس للشيء يدل على حله، وليس اعتيادهم له يحله أيضاً، كثير من العادات التي يعتادها الناس في بلادهم أو في قبائلهم يجب عرضها على كتاب الله وسنة رسوله عليه الصلاة والسلام، فما أباحها الله ورسوله فلا بأس فهو مباح والحمد لله، وما نهى الله ورسوله عليه الصلاة والسلام وجب تركه وإن كان عادة للناس، فإذا اعتاد الناس التساهل بالخلوة بالأجنبية أو اعتاد الناس أنها تكشف وجهها لغير محارمها هذه عادة باطلة يجب أن تزال، كما لو اعتاد الناس الزنا واللواط وشرب المسكر وجب عليهم تركه، وليس للعادة حجة لهم في ذلك بل الشرع فوق الجميع.\nفعلى من هداه الله للإسلام أن يبتعد عما حرم الله عليه من الخمر.. الزنا.. السرقة.. العقوق.. القطيعة، وسائر ما حرم الله .\nوهكذا يجب على الأسرة أن تحترم أمر الله ورسوله، وأن تبتعد عما حرم الله ورسوله، فإذا كان من عادتهم كشف نسائهم لهم هذه عادة سيئة يجب أن تزول، فليس للمرأة أن تكشف لابن عمها ولا لزوج أختها ولا لإخوان زوجها ولا لأعمامه ولا لأخواله بل يجب عليها الاحتجاب وأن لا يرى منها شيئاً، فتستر بدنها.. تستر وجهها.. تستر رأسها، تستر جميع بدنها حتى لا يبقى منها شيء مكشوف.\nأما الكلام فلا بأس أن تكلمه في الحاجات: ترد عليه السلام، تبدأه بالسلام لا بأس، لكن مع الصيانة ومع الحجاب ومع البعد عن الخلوة، قال الله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53].\nوكذلك لابد من كلام عادي كلام متوسط ليس فيه تغنج ولا تكسر ولا خضوع بل يكون كلامها كلاماً عادياً، لقول الله سبحانه: يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32]، فنهى سبحانه وتعالى نساء النبي ﷺ أن يخضعن بالقول؛ وهو تليينه وتكسيره حتى يطمع فيها من في قلبه مرض الشهوة، ويظن أنها مواتية وأنه لا مانع عندها، فالواجب أن يكون قولها قولاً وسطاً لا منكر وعنف ولا خضوع وتكسر وتغنج ولكن بين ذلك قول عادي في سلامها وكلامها ونحو ذلك ليس فيه شيء من التكسر والخضوع.\nوليس لها الخلوة بأخي زوجها أو عمه، وليس لها أن تكشف له وجهها ولا يديها ولا قدميها ولا رأسها بل تستر بدنها، لعموم قوله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، فأخبر سبحانه أن الحجاب أطهر لقلوب الجميع، وقال سبحانه: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا [الأحزاب:59].\nوالجلباب: ثوب يطرح على الرأس والبدن، تطرحه المرأة على رأسها تغطي به وجهها وبدنها فوق ثيابها، وقال سبحانه في سورة النور: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ أَوْ نِسَائِهِنَّ أَوْ مَا مَلَكَتْ أَيْمَانُهُنَّ .. [النور:31] الآية، هؤلاء هم المحارم الذين يباح إبداء الزينة لهم كالوجه والكفين والقدمين والرأس ونحو ذلك.\nأما أخو الزوج وزوج الأخت وزوج العمة وزوج الخالة وعم الزوج وخاله فكل هؤلاء أجناب لا تبدى لهم الزينة، لا يجوز إبداء الزينة لهم، بل تكلمهم عند الحاجة من وراء حجاب.. تسلم عليهم من وراء حجاب، ترد عليهم السلام، تسألهم عن الحاجة التي تريد لكن مع الحجاب ومع التستر ومع الحشمة.\nوهكذا يجب الحذر من التبرج وهو إظهار المحاسن والمفاتن، لقوله جل وعلا: وَقَرْنَ فِي بُيُوتِكُنَّ وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى وَأَقِمْنَ الصَّلاةَ وَآتِينَ الزَّكَاةَ وَأَطِعْنَ اللَّهَ وَرَسُولَهُ [الأحزاب:33].\nفالواجب على النساء تقوى الله سبحانه وتعالى والحذر مما حرم الله من إبداء الزينة لغير المحارم والتبرج الذي حرمه الله، يجب الحذر من ذلك؛ لأن هذا أطهر للقلوب وأسلم للمجتمع من الفتن وأبعد عن وقوع الفواحش وعن التهم إلا العجوز التي لا تشتهي النكاح ولا يطمع فيها ولا تتزين فلها أن تكشف وجهها لقوله : وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ [النور:60].\nفالقواعد: هن العجائز، اللاتي لا يرجون نكاحاً، يعني: ما عندهن رغبة في النكاح لكبر سنهن وتقدم سنهن ومع ذلك غير متبرجات بزينة، أما إن كن متبرجات فلا، ليس لهن الكشف، أما إذا كن عجائز لا يرجين النكاح ومع ذلك غير متبرجات بزينة فلا حرج من وضع الحجاب عن وجهها ويديها؛ لأنه لا مطمع للناس فيها.\nولكن استعفافها أولى حتى ولو كانت عجوز استعفافها و تسترها أولى وأفضل، ولهذا قال سبحانه: وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ[النور:60]؛ لأن كل ساقط له لاقط، قد يطمع فيها من هو من جنسها من الكبار، قد يقع شيء من الفتنة، فإذا استعفت واحتجبت كان أفضل وأصلح، فإذا كان هذا في العجائز غير المتبرجات يكون الحجاب لهن أفضل فكيف بحال الشباب من الفتيات؟! الأمر فيهن أشد وأعظم؛ ولهذا وجب عليهن الحجاب والبعد عما حرم الله عز وجل من وسائل الشر، والحرص على أن تكون بعيدة عن كل فتنة وعن سبب كل فتنة، تكون كاملة للستر، كاملة الحجاب، لا تخلو بالرجل ولو كان أخا زوجها ولو كان عم زوجها.\nولهذا قال ﷺ: إياكم والدخول على النساء، إياكم والدخول على النساء، فقال رجل من الأنصار: أرأيت الحمو؟ قال صلى الله عليه وسلم: الحمو الموت، يعني: يخشى منه أكثر؛ لأن المرأة قد تتساهل عنده وقد يدخل عليها ولا يستنكر؛ لأنها زوجة أخيه أو زوجة عمه، فربما أبدت له شيء من محاسنها وتساهلت فيقع الشر، فلهذا قال ﷺ لما سألوه عن الحمو؟ قال: الحمو الموت، فيجب الحذر من الخلوة به أو إبداء الزينة له؛ لأن الخطر منه أكثر.\nأما أبو زوجها فهو محرم لها؛ أبوه وجده، وابنه، وأولاد ابنه كلهم محارم، فأبو الزوج وجد الزوج كلهم محارم، أما زوج أمه فليس محرماً زوج الأم ليس محرماً وإنما أبوه أبو الزوج وجد الزوج وابن الزوج وابن بنته وابن ابنه كلهم محارم ولكن بعض المحارم قد يخشى شره.\nفينبغي للمرأة أن تحذر أيضاً ولاسيما في عصرنا هذا، بعض المحارم قد لا يكون عنده من التقوى والعفة ما يصونه، فينبغي للمرأة أن تكون حذرة وأن تكون فطنة وأن تحذر أسباب الشر، فإذا كان المحرم كابن الزوج أو أبي الزوج، أو ابن ابن الزوج يخشى منه شر فلتكن على حذر فلا تخلو به، ولا تبدي له محاسنها بل يكفي وجهها ونحوه من دون توسع في ذلك ومن دون خلوة إذا خافت من شره، فإن بعض المحارم يخشى شره، فينبغي لها أن تكون حذرة وأن تكون بعيدة عن أسباب الشر، نسأل الله للجميع العافية. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7095/حكم-ظهور-النساء-امام-الرجال-غير-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_144/14403.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":9017,"question":"ما حكم مصافحة المرأة أخي زوجها أو عمه أو خاله؟","title":"حكم مصافحة المرأة لأخي زوجها وعمه وخاله","answer":"الجواب: ليس للمرأة أن تصافح الرجل الأجنبي ولو كان أخا زوجها ولو كان عم زوجها ولو كان خال زوجها؛ لأنهم أجناب ليسوا محارم، وهكذا زوج أختها ليس لها أن تصافحهم ولكن ترد عليهم السلام، تبدأهم بالسلام.. ترد عليهم السلام، تسألهم عن أحوالهم وأحوال أولادهم لا بأس، أما المصافحة فلا، لقول النبي ﷺ: إني لا أصافح النساء، وقالت عائشة رضي الله عنها: والله ما مست يد رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام ، عليه الصلاة والسلام.\nفالمقصود أن المصافحة فيها خطر، فيها فتنة فلا تجوز نعم، إلا للمحارم: أخيها.. لعمها.. لخالها.. لولدها.. لوالدها لا بأس.. أبي زوجها.. جد زوجها نحو ذلك، المحارم نعم، أو مع النساء لا بأس.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7175/حكم-مصافحة-المراة-لاخي-زوجها-وعمه-وخاله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14710.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":9360,"question":"من العراق رسالة بعثت بها إحدى الأخوات من هناك تقول: (س. س) أختنا تسأل وتقول: متى يحل للرجل أن يخلو بالمرأة؟ وهل يحق أن يخلو بها بعد أن اتفق والدها ووالده على قبول تزوجيهما وبحضور شاهدين آخرين، أي هل أصبحا زوجين مع العلم أنه لم يتم تسجيل هذا العقد في المحكمة؟","title":"حكم الخلوة بالمرأة بعد العقد عليها","answer":"الجواب: الخلوة محرمة بالمرأة الأجنبية؛ لقول النبي ﷺ: لا يخلون رجل بامرأة إلا ومعها ذو محرم ولقوله عليه الصلاة والسلام: لا يخلون رجل بامرأة فإن الشيطان ثالثهما لكن إذا تم العقد وتم الزواج من الولي من الخاطب بحضرة الشاهدين صارت زوجة له، لو خلا بها لا شيء عليه، ولكن ينبغي له أن يمتنع من جماعها حتى يدخل بها الدخول الشرعي؛ لئلا يظن أنه من غيره، فينبغي في مثل هذه الأحوال أن يكون جماعه لها واتصاله بها الاتصال الجنسي يكون بعد الخلوة الرسمية التي يعترف بها أهلها.\nأما كونه يخلو بها لا حرج عليه في الخلوة بها؛ لأنها زوجة، لكن الجماع لها ينبغي تأخيره إلى الدخول الرسمي الذي يعرفه الناس، حتى لا يقع تهمة لو حملت، فيقال: هذا ليس من زوجها، أو يجحده هو أو ما أشبه ذلك. نسأل الله السلامة. نعم.","link":"https://binbaz.org.sa/fatwas/7524/حكم-الخلوة-بالمراة-بعد-العقد-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/18602.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":9380,"question":"قضية تثيرها أختنا هي قضية كثير من النساء المسلمات تقول: كثير من إخواتي في الله يدرسن في الجامعات، وبعض الجامعات مختلطة، تجد الشباب الشيوعي -كما تصفهم سماحة الشيخ- والنصراني والذي ينتمي للأحزاب غير الإسلامية -أيضًا هذا هو قولها- فهل يحق للمرأة السلفية، أي: التي تنتهج منهج السلف هل يحق لها الدراسة في هذا المجال، وهل دراستهن ضرورة للقانون والأحياء والرياضيات، هل هذا ضرورة تبيح للمرأة المسلمة الدراسة مع الشباب سالفي الذكر، مع العلم بأن الدارسات يقلن إنهن سلفيات ويدرسن في هذا الجو المختلط، وأيضًا بحجة الضرورة، فهل يبيح لهن الشرع ذلك، مع أنهن لا يلتزمن أيضًا بلبس النقاب ذلك بأنه ليس بضرورة كما يقلن، وترجو التوضيح في هذه القضايا جزاكم الله خيرا؟","title":"حكم دراسة المرأة في الجامعات التي فيها اختلاط","answer":"الجواب: هذه قضية عظيمة وأمر خطير وليس للنساء أن يدرسن في المدارس والمعاهد والكليات المختلطة؛ لما فيه من الفتنة العظيمة والفساد الكبير؛ ولأنه وسيلة قريبة إلى وقوع ما حرم الله ، فليس لهن أن يدرسن في هذه المدارس أو الكليات أو المعاهد بل يلتمسن الدراسة في جو آخر من المدارس السليمة التي ليس فيها اختلاط، أو بالمكاتبة بينها وبين أهل العلم حتى تسأل عن دينها أو بحضور حلقات العلم في المساجد وهن متحجبات مستورات كما كان في عهد النبي ﷺ، كان النساء في عهد النبي ﷺ يصلين معه ﷺ وهن متحجبات، فإذا صلين خرجن، يسمعن الخطبة ويسمعن العلم، أما دراستهن مع الرجال مختلطات فهذا لا يجوز أبدًا حتى ولو تحجبن، فكيف إذا كن غير متحجبات؟! يكون الشر أكبر وأعظم.\nثم ليس هناك ضرورة إلى أن تدرس ما لا حاجة لها في دينها دراسة الجيولوجيا أو الحساب أو الرياضيات أو غير ذلك، إنما تدرس ما تحتاج إليه في دينها، صلاتها وصومها والمعاملات .. النكاح .. الطلاق، إلى غير هذا مما تحتاج إليه في دينها، وأهم شيء العقيدة، ودرس القرآن الكريم، ومعرفة ما حرم الله وما أوجب الله هذا هو المطلوب، وما زاد على ذلك فالرجال يقومون بذلك وليست في حاجة إلى أن تدرس ذلك.\nلا مانع من دراسة الطب حتى تطب أخواتها النساء، فالشيء الذي هناك للمجتمع حاجة فيه لا بأس في المرأة من جنس تعلم الطب لتطب أخواتها هذا لا حرج فيه وطيب ونافع لكن بشرط عدم الاختلاط، أما إذا كان اختلاط فلا.\nوهذا هو الواجب على المؤمنة أن تتقي الله وأن تبتعد عن أسباب الفتنة، وأن لا تتخذ رأيها وهواها سبيلًا إلى ما حرم الله ، بل تسأل أهل العلم وتستفيد مما عندهم من العلم، والله جل وعلا قال: وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33] وقال: فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32] وقال سبحانه: وَقَرْنَ فِي بُيُوتِكُنَّ [الأحزاب:33] فالمرأة مأمورة بأن تبقى في بيتها إلا إذا ظهرت المصلحة في خروجها، ومنهية عن التبرج، ومنهية عن الخلطة بالرجال، والخلوة بالرجال، والخضوع للرجال بالقول كل هذا مما يضرها في دينها وأخلاقها، وقد قال عليه الصلاة والسلام: صنفان من أهل النار لم أرهما: رجال بأيديهم سياط كأذناب البقر يضربون بها الناس، ونساء كاسيات عاريات مائلات مميلات رءوسهن كأسنمة البخت المائلة لا يدخلن الجنة ولا يجدن ريحها وإن ريحها ليوجد من مسيرة كذا وكذا فبين ﷺ أن هذا الصنف من النساء وهن الكاسيات العاريات المائلات عن الحق والمميلات إلى الباطل، هم من أهل النار من المتوعدين بالنار لعدم قيامهن بواجب الستر والحجاب، ولتساهلهن بما يجر الفتنة عليهن ويسبب وقوعهن في الفاحشة ولا حول ولا قوة إلا بالله، فنسأل الله لأخواتنا في الله الهداية والتوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/7544/حكم-دراسة-المراة-في-الجامعات-التي-فيها-اختلاط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_187/18703.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":9382,"question":"سؤال بقي لأخينا (د. م. م) يقول فيه: إذا أردت الزواج من بنت وهي ملتزمة بالحجاب ولكن ليست من منطقتي ولا أعرف هل هي جميلة أم لا، هل يصح النظر إليها إذا كان قد عزمت على الزواج منها، وكيف يكون ذلك جزاكم الله خيرًا؟","title":"حكم نظر الرجل إلى المرأة التي يريد خطبتها","answer":"الجواب: نعم، يشرع لك النظر إليها، إذا خطبت امرأة أو أردت أن تخطبها يشرع لك النظر إليها إذا تيسر ذلك، النبي ﷺ قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل وذكر له رجل أنه خطب امرأة فقال: أنظرت إليها؟ قال: لا، قال: اذهب فانظر إليها فالمشروع لك أن تنظر إليها إن تيسر ذلك، وإلا ففي إمكانك تبعث من ثقات النساء، أو من محارمها إن كنت تعرف محارمها من يعطيك الخبر، فتبعث المرأة من أقاربك كأمك وخالتك وعمتك أو أختك تنظر إليها ثم تعطيها صفاتها، أو تسأل محارمها يعطونك صفاتها، وإذا تيسر لك النظر إليها من دون خلوة فلا بأس، تطلب من أبيها أو أمها أو أخيها أو نحو ذلك أن يسمح لك بالنظر إليها لكن من دون خلوة، فتنظر إليها بحضرة أبيها أو أمها أو أخيها أو غيرهم من الناس من دون خلوة. نعم.","link":"https://binbaz.org.sa/fatwas/7546/حكم-نظر-الرجل-الى-المراة-التي-يريد-خطبتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_187/18705.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":9473,"question":"تقول في آخر رسالتها: وليت سماحة الشيخ يوضح للمستمعات ويبين لهن من من الرجال يجوز أن تخرج معهم المرأة، خاصة أن كثيراً من النساء في هذه الأيام يخرجن مع الرجال الأجانب من سائق وغيره وحدهن؟","title":"حكم خروج المرأة مع السائق الأجنبي لوحدهما","answer":"الجواب: نعم، لا يجوز للمرأة أن تخرج مع السائق وحدها ولا مع أخي زوجها وحده، ولا مع عم زوجها وحده، ولا مع غيرهما من الأجانب، أما مع محرمها كأبيها وعمها وخالها وأبي زوجها وابن زوجها وجد زوجها وابن بنت زوجها وابن ابن زوجها لا بأس به، هؤلاء محارم، أما الخروج مع أجنبي سواء كان السائق أو غير السائق فلا يجوز؛ لأن هذا خلوة، وجوده معها في السيارة خلوة ويخشى منها شر كثير، فلا يجوز لها أن تذهب مع السائق الأجنبي وحدها، بل لابد أن يكون معهما ثالث ممن يؤمن به ضرر هذا الركوب، ويحصل به عدم الخلوة من زوجة السائق، أم السائق، امرأة أخرى، رجل آخر ممن يوثق به لا بأس بذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7640/حكم-خروج-المراة-مع-الساىق-الاجنبي-لوحدهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_241/24104.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":9686,"question":"لنفس السائل سليمان من المدينة المنورة أيضاً سؤال آخر يقول فيه: نحن عائلة نجلس على مائدة واحدة أثناء الطعام، وهذه المجموعة تتكون من الإخوان وبناتهم وأبنائهم وأبناء الخالات وأبناء العمات، نساء ورجال طبعاً نجلس على سفرة واحدة، فهل في هذا حكم شرعي يمنع الاختلاط، هذا والحقيقة أنا غير مرتاح لكن العادة والتقليد تأصلت فينا، أفيدونا، وماذا نعمل ولعل العائلة تسمع أفيدونا بارك الله فيكم؟","title":"حكم اجتماع النساء مع غير المحارم أثناء الطعام","answer":"الجواب: هذه العادة عادة سيئة، يجب تركها، ولا يجوز أن يجلس الرجل مع امرأة غير محرم له، كبنت عمه، أو بنت خاله، أو بنت خالته، بل يجب أن يكون النساء على حدة في مائدة أخرى، وأن يكون الرجال على حدة، أما الجلوس مع زوجته مع أمه مع خالته مع عمته مع أخته لا بأس، لكن نساء لسن محارم له ليس له الجلوس معهن، على المائدة الواحدة، بل يجلسن في مائدة أخرى ولا يجوز هذا الاختلاط الذي يفضي إلى ملاصقة المرأة لغير محرمها، أو رؤيته لها وما يتبع ذلك، فالمرأة عورة كلها فليس لها أن تجلس مع غير محرمها، فإنه يرى أكلها، يرى وجهها، يرى يدها، يرى شيئاً آخر.\nفالمقصود أن هذا منكر يجب التخلص منه، وكل عادة سيئة يجب تركها، والعادات تحكم بالشريعة، ولا يجوز أن تقدم على الشريعة، الواجب أن تعرض العادات على الشريعة، فما وافق الشريعة قبل وبقي، وما خالف الشريعة وجب تركه من جميع العادات، نسأل الله للجميع الهداية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7854/حكم-اجتماع-النساء-مع-غير-المحارم-اثناء-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_252/25211.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":9700,"question":"وهذه رسالة وردت من السائلة (م. ع. ق) من الدرعية تقول: ما حكم مشاهدة المباراة ومتابعتها وحبها وتشجيع النوادي الرياضية للمرأة؟ وهل في نظرها إلى الرجال اللاعبين وهم عراة الأفخاذ حرج، أفيدونا أفادكم الله؟","title":"حكم مشاهدة المرأة للاعبين مكشوفي الأفخاذ","answer":"الجواب: نعم، ينبغي لها تجنب هذا الشيء؛ لأنها قد تفتن بأحد منهم؛ ولأن النظر في الأصل ممنوع قال تعالى: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ [النور:31] فهذا النظر إلى اللاعبين مكشوفي الأفخاذ قد يفضي بها إلى فتنة، فالأحوط لها أن تدع ذلك، أما لو كانوا مستوري العورات ولا تخشى الفتنة فلا حرج، فقد ثبت أن عائشة رضي الله عنها نظرت إلى الحبش يلعبون في المسجد من وراء النبي عليه الصلاة والسلام، فإذا كان اللعب لا يخشى فيه فتنة من أناس مستورين، ولا تضيع به صلاة، ولا يقع به فتنة فلا حرج، ولكن النظر إلى رجال مكشوفي الأفخاذ فيه حرج وفيه خطر، فالواجب ترك ذلك؛ لئلا تقع الفتنة ولأنها تشاهد عورة بارزة والله المستعان. نعم.\nالمقدم: يعني لو كانت هذه المباريات مثلاً في المذياع أخف من ....؟\nالشيخ: إذا كانت في المذياع أو مستوري العورات لا تخشى الفتنة .... في النظر. فالنظر في العامة لا تحس بفتنة فلا حرج في ذلك ............ عمومي.\nالمقدم: والانشغال في الرياضة بحد ذاتها إلى درجة الإفراط؟\nالشيخ: الواجب أن يكون له حد محدود، فإن كانت تشغل عن الفريضة حرمت، أو الصلاة في الجماعة مع المسلمين حرمت، يجب أن تكون في وقت خاص، أو تقام الجماعة في أثناء الملعب حتى لا تضيع الجماعة، أما أن يضيعوا الجماعة ويضيعوا الوقت هذا منكر، يلعبون ثم يتفرقون ويتركون الجماعات وقت الصلاة في الصلاة في وقتها هذا لا شك أنه منكر. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7840/حكم-مشاهدة-المراة-للاعبين-مكشوفي-الافخاذ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_252/25201.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":9761,"question":"تقول: فتاة متزوجة، هل يجوز لزوجة أبيها أن تكشف على زوجها؟","title":"حكم كشف زوجة الأب وجهها لزوج ابنة زوجها","answer":"الجواب: زوجة أبيها لا تكشف على زوجها، لأنها ليست ابنة لها، إنما المحرم أمها وجداتها، أما زوجة أبيها فليست محرماً لزوجها بل أجنبية، نعم.\nالمقدم: جزاكم الله خيراً، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/7930/حكم-كشف-زوجة-الاب-وجهها-لزوج-ابنة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_257/25704.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":9781,"question":"له سؤال ثان يقول فيه: أنا شاب ملتزم، أؤدي ما أمرني الله به وأجتنب المحرمات قدر استطاعتي، لكنني أكثر من الصداقات والعلاقات العامة مع الناس رجالاً ونساء، وأتحرج الحقيقة في علاقتي مع النساء، إلا أن لي صداقات كثيرة معهن وبعد سفري من بلادي لا زلت أواصل علاقتي بأصدقائي رجالاً ونساءً بالمراسلة، وأخشى إن قطعت مراسلتي عن بعضهم يظنون أنني تكبرت عليهم أو تغيرت، فهل علي إثم في ذلك، أفيدوني أفادكم الله وكيف أتخلص من هذا؟","title":"حكم إقامة الصداقات مع النساء والرجال","answer":"الجواب: أما المصادقة مع الرجال والصحبة مع الرجال الطيبين هذا معلوم لا بأس به، كونه يتخذ أصحاباً طيبين أهل علم أهل عبادة أهل ورع أهل تقوى، ليسوا بالعصاة المجاهرين، ولكنهم من المعروفين بالخير والستر فلا بأس، أما الصداقة مع المتجاهرين بالمعاصي والمتساهلين بأمر الله، فلا ينبغي اتخاذهم أصدقاء، بل ينبغي البعد عنهم والحذر من شرهم، حتى لا يجروك إلى معاصيهم.\nوأما النساء خطرهن كبير، فإذا كانت الصداقة على دين وتقوى من دون خلوة ومن دون تكشف ولا رؤية لمفاتنهن بل مع الحجاب ومع عدم الخلوة لأنهن أقارب أو لأنهن جيران، فيحسن إليهن لفقرهن أو لحاجتهن لبعض المئونة على وجه واضح لا شبهة فيه ولا ريبة فيه، إما لقرابة وإما لجوار وإما لكونهن من أصدقاء الوالدين أو ما أشبه ذلك، فلا بأس بهذا يصلهم ويحسن إليهم، ولو بالمكاتبة.\nأما إذا كانت الصداقة مع النساء على وجه الريبة، أو الخلوة بإحداهن أو المغازلة للطمع في اتصاله بها أو ما أشبه ذلك، هذا منكر ومحرم، ولا يجوز أن يتعاطى هذه الصداقة التي قد توقعه في الفواحش، قد تجره إلى ما حرم الله.\nفالحاصل أن الصداقة إذا كانت على وجه واضح وجه شرعي لا شك فيه، ولا ريبة فيه لقرابة منه أو من والديه أو جوار، أو فقر وحاجة، فيصلها ويكاتبها بالمساعدة لفقرها وحاجتها، أو لقرابتها من دون أن يكون هناك بينه وبين المرأة خلوة، أو تكشف منها يرى مفاتنها ويرى وجهها أو نحو ذلك، فهذه الصداقة لا بأس بها من جهة الدين، ليصلها أو يحسن إليها أو نحو ذلك.\nفأما صداقة تجره إلى الفواحش أو إلى الخلوة بالمرأة، أو المغازلة معها فيما يتعلق ما بين الرجل وأهله فهذا كله محرم، كله منكر لا يجوز.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7954/حكم-اقامة-الصداقات-مع-النساء-والرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_259/25907.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":9789,"question":"له سؤال ثان يقول فيه: أنا شاب ملتزم، أؤدي ما أمرني الله به وأجتنب المحرمات قدر استطاعتي، لكنني أكثر من الصداقات والعلاقات العامة مع الناس رجالاً ونساء، وأتحرج الحقيقة في علاقتي مع النساء، إلا أن لي صداقات كثيرة معهن وبعد سفري من بلادي لا زلت أواصل علاقتي بأصدقائي رجالاً ونساءً بالمراسلة، وأخشى إن قطعت مراسلتي عن بعضهم يظنون أنني تكبرت عليهم أو تغيرت، فهل علي إثم في ذلك، أفيدوني أفادكم الله وكيف أتخلص من هذا؟","title":"حكم إقامة الصداقات مع النساء والرجال","answer":"الجواب: أما المصادقة مع الرجال والصحبة مع الرجال الطيبين هذا معلوم لا بأس به، كونه يتخذ أصحاباً طيبين أهل علم أهل عبادة أهل ورع أهل تقوى، ليسوا بالعصاة المجاهرين، ولكنهم من المعروفين بالخير والستر فلا بأس، أما الصداقة مع المتجاهرين بالمعاصي والمتساهلين بأمر الله، فلا ينبغي اتخاذهم أصدقاء، بل ينبغي البعد عنهم والحذر من شرهم، حتى لا يجروك إلى معاصيهم.\nوأما النساء خطرهن كبير، فإذا كانت الصداقة على دين وتقوى من دون خلوة ومن دون تكشف ولا رؤية لمفاتنهن بل مع الحجاب ومع عدم الخلوة لأنهن أقارب أو لأنهن جيران، فيحسن إليهن لفقرهن أو لحاجتهن لبعض المئونة على وجه واضح لا شبهة فيه ولا ريبة فيه، إما لقرابة وإما لجوار وإما لكونهن من أصدقاء الوالدين أو ما أشبه ذلك، فلا بأس بهذا يصلهم ويحسن إليهم، ولو بالمكاتبة.\nأما إذا كانت الصداقة مع النساء على وجه الريبة، أو الخلوة بإحداهن أو المغازلة للطمع في اتصاله بها أو ما أشبه ذلك، هذا منكر ومحرم، ولا يجوز أن يتعاطى هذه الصداقة التي قد توقعه في الفواحش، قد تجره إلى ما حرم الله.\nفالحاصل أن الصداقة إذا كانت على وجه واضح وجه شرعي لا شك فيه، ولا ريبة فيه لقرابة منه أو من والديه أو جوار، أو فقر وحاجة، فيصلها ويكاتبها بالمساعدة لفقرها وحاجتها، أو لقرابتها من دون أن يكون هناك بينه وبين المرأة خلوة، أو تكشف منها يرى مفاتنها ويرى وجهها أو نحو ذلك، فهذه الصداقة لا بأس بها من جهة الدين، ليصلها أو يحسن إليها أو نحو ذلك.\nفأما صداقة تجره إلى الفواحش أو إلى الخلوة بالمرأة، أو المغازلة معها فيما يتعلق ما بين الرجل وأهله فهذا كله محرم، كله منكر لا يجوز.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7954/حكم-اقامة-الصداقات-مع-النساء-والرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_259/25907.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":9814,"question":"وهذه رسالة وردت إلى البرنامج من المرسل (ع. أ. ع) صومالي مقيم في مدينة الرياض يقول السائل في رسالته: هل يجوز لامرأة مسلمة أن تذهب مع رجل أجنبي وقد اتفقا على الزواج، سواء رفض والدها أم وافق، وفي حالة رفض الوالد لسبب ما فيذهب الاثنان إلى منطقة بعيدة مسافة القصر، وهناك يتم عقد النكاح، وكلنا نعلم أن الخلوة الأولى حرام أفيدونا أفادكم الله؟","title":"حكم سفر المرأة مع خطيبها والزواج بدون إذن الولي","answer":"الجواب: هذا العمل لا يجوز، ليس للرجل أن يسافر بامرأة ليست محرماً له، ولو كان خاطباً لها، وهذا السفر وهذه الخلوة متهمان فيها، فلا يجوز أبداً لا يخلو بها ولا يسافر معها، بل يجب عليه الحذر من ذلك وعليها الحذر من ذلك، وليس لها الزواج إلا بوليها، النبي عليه السلام قال: «لا نكاح إلا بولي» فليس لها أن تزوج بالشخص لا بعد ذهابها مسافة قصر ولا في غير ذلك إلا بالولي، وهو أبوها أو من يوكله أبوها ممن يصلح للوكالة، وأما سفرها مع خاطبها قبل الزواج قبل العقد فهذا لا يجوز، وليس لها أن تسافر معه إلا بإذن أهلها ولو بعد العقد، إلا بإذن أهلها حتى لا يكون هناك شيء مما تسوء عاقبته.\nفالحاصل: أن سفرها مع هذا الخاطب أمر منكر ولا يجوز، وهو من وسائل الفاحشة، وليس لها التزوج إلا بإذن وليها، فإذا أبى وليها أن يزوجها ففي إمكانها أن تطلب من المحكمة النظر في الأمر، أما أن تزوج نفسها فهذا ليس إليها، وليس للخاطب أن يسافر بها أو يخلو بها أو يلجئها إلى الزواج به من غير وليها، كل هذا منكر. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7981/حكم-سفر-المراة-مع-خطيبها-والزواج-بدون-اذن-الولي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_260/26002.mp3","categories":["النظر والخلوة والاختلاط","شروط وأركان الزواج"]},{"id":9825,"question":"هو أضاف أخيراً ويقول: أنا خرجت من البيت الخاص والذي خلفه والدي، وتسكن فيه والدتي وسكنت في بيت بعيد عن والدتي تلافياً للمشاكل، فهل علي إثم في خروجي هذا؟","title":"حكم مفارقة الأم في السكن","answer":"الجواب: إذا كانت الوالدة سمحت بذلك فليس عليك إثم، أما إذا كانت الوالدة غير سامحة وهي في حاجة إليك فالواجب عليك أن ترجع إليها وأن تبقى معها، لقضاء حوائجها وإيناسها والحرص على برها، فإن برها من أهم المهمات ومن أعظم الواجبات.\nأما إذا سمحت عنك فلا بأس.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7990/حكم-مفارقة-الام-في-السكن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_260/26011.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":9880,"question":"تقول هذه السائلة من السودان: إذا كنت محتشمة بالزي الإسلامي في البيت ولا أترك الخمار عن رأسي، فهل يجوز لي أن أجلس مع أولاد عمي وأولاد خالي ونحوهم، إذا كنا جميعاً ذكوراً وإناثاً نجلس في مكان واحد.","title":"جلوس المرأة مع غير المحارم","answer":"الجواب: لا مانع من الجلوس مع أبناء العم وأبناء الخال ومع أهل الحارة مع الحشمة والستر والحجاب حتى الوجه، الوجه عورة على الصحيح، يجب ستره والرأس من باب أولى يجب ستره، فإذا جلست مع أقاربها من بني خال أو بني عم أو جيران، في الأحاديث الطيبة الدينية، والأحاديث التي لا محذور فيها، مع الستر والحجاب وعدم إبداء شيء منها لا وجه ولا غيره فلا حرج في ذلك، ولا يكفي ستر الرأس، بل لا بد من ستر الوجه أيضاً، فينبغي أن تحتشم المرأة وتبتعد عن أسباب الفتنة لا مع بني خالها ولا مع بني عمها، ولا مع غيرهم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8048/جلوس-المراة-مع-غير-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_264/26405.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":9917,"question":"وأولى رسائل هذه الحلقة وردت من السائل (م. م) من أبو ظبي يقول هذا السائل: أكتب إليكم بهذه المسألة التي تعذبني ليلاً ونهاراً، وذلك أنني أحببت فتاةً تعمل معي في نفس المكان الذي أعمل به، وهي كذلك أحبتني وقد اتفقنا على الزواج، لكن قبل الزواج لعب بنا الشيطان وعملنا عملاً ينافي الإسلام والدين وبعدما سافرت إلى بلاد بعيدة ثم رجعت فخطبتها وتزوجتها والحمد لله نحن سعداء الآن، ولكن نريد أن تدلونا على أمر نكفر به عن ما حصل منا، وهل يؤثر هذا على زواجنا القائم حالياً أفيدونا أفادكم الله؟","title":"حكم اتصال الرجل بالمرأة قبل الزواج وتأثيره على الزواج","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله نبينا وإمامنا وسيدنا وعلى آله وأصحابه وأتباعه بإحسان.\nأما بعد: فلا ريب أن اتصال الرجل بالمرأة قبل الزواج أمر محرم، وليس له أن يتصل بها لا بقبلة ولا لمس ولا غير ذلك، وليس لها أن تتصل به وليس له أن ينظر إلى عورتها وليس لها أن تنظر إليه، قال الله : قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ ۝ وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ [النور:30-31] الآية.\nوقال : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] الآية. فالذي فعلتم سابقاً منكر وعليكم التوبة إلى الله من ذلك، عليك وعليها التوبة إلى الله سبحانه مما فعلتما من الاتصال والمباشرة، والتوبة تجب ما قبلها، متى تاب كل منكما توبة صادقة مضمونها الندم على الماضي والعزيمة أن لا تعودا في ذلك، فهذا يكفر الله به ما مضى، حتى الكفر إذا تاب الكافر وأسلم تاب الله عليه، فهكذا المعاصي إذا تاب منها المسلم بالندم على الماضي والإقلاع منها والحذر منها تعظيماً لله سبحانه وحذراً من عقابه، وعزم عزماً صادقاً على عدم العود تاب الله عليه، وإن كان الذنب يتعلق بحق المسلم في ماله أو دمه أو عرضه استحله من ذلك أو أعطاه حقه، فالحاصل أنك أنت والمرأة عليكما التوبة مما مضى والتوبة تجب ما قبلها، وذلك بالندم على ما فعلتما سابقاً وعدم العود إلى ما حرم الله عليكما، والعزم الصادق على أن لا تعودا في مثل ذلك، أما النكاح فلا يتأثر بالماضي، النكاح إذا استوفت شروطه فلا بأس ونسأل الله أن يجعله نكاحاً مباركاً والحمد لله على السلامة من أسباب غضب الله .\nوهذا الذي فعلتما هذا من آثار الخلطة؛ فإن وجود المرأة مع الرجل في المكتب من أسباب وقوع الفاحشة، ولهذا نص العلماء على تحريم عمل المرأة مع الرجل في مكتب واحد وعمل واحد، يتمكن من الخلوة بها والنظر إليها والنظر إلى ما حرم الله منها ونظرها إليه نظر الشهوة والفتنة هذا من المحرمات، ومن الواجب الحذر منه وتركه، ..... المرأة لها أعمال تكون مع أخواتها ومع جنسها والرجل له أعمال مع إخوانه وجنسه، أما خلطهما وجعلهما في مكتب واحد وفي عمل واحد فهو يفضي إلى شر كثير وإلى فساد عظيم يجب الحذر منه، وهكذا السكرتيرة للكاتب أو للمدير أو للطبيب أو ما أشبه ذلك كلها أمور منكرة كلها محرمة كلها مفضية إلى الفساد والزنا والفاحشة، فيجب الحذر من ذلك، يجب على حكام المسلمين وعلى أولياء الأمور أن يحذروا هذه الأمور المنكرة، وأن يجعلوا النساء مع النساء والرجال مع الرجال، فالسكرتير يكون للرجل رجلاً، ويكون للمرأة امرأة، فالطبيبة تكون معها النساء وتكون مع النساء والممرضة كذلك مع النساء، وهكذا الممرض والطبيب يكون للرجال.\nالمقصود أن الواجب إبعاد هذا عن هذا والحذر من قرب هذا من هذا، ولا سيما في الأعمال التي يتصل فيها الرجل والمرأة ويخلو بها فإن شرها عظيم وعاقبتها وخيمة، والله المستعان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8080/حكم-اتصال-الرجل-بالمراة-قبل-الزواج-وتاثيره-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_268/26801.mp3","categories":["الرقائق","النظر والخلوة والاختلاط"]},{"id":9919,"question":"وأولى رسائل هذه الحلقة وردت من السائل (م. م) من أبو ظبي يقول هذا السائل: أكتب إليكم بهذه المسألة التي تعذبني ليلاً ونهاراً، وذلك أنني أحببت فتاةً تعمل معي في نفس المكان الذي أعمل به، وهي كذلك أحبتني وقد اتفقنا على الزواج، لكن قبل الزواج لعب بنا الشيطان وعملنا عملاً ينافي الإسلام والدين وبعدما سافرت إلى بلاد بعيدة ثم رجعت فخطبتها وتزوجتها والحمد لله نحن سعداء الآن، ولكن نريد أن تدلونا على أمر نكفر به عن ما حصل منا، وهل يؤثر هذا على زواجنا القائم حالياً أفيدونا أفادكم الله؟","title":"حكم اتصال الرجل بالمرأة قبل الزواج وتأثيره على الزواج","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله نبينا وإمامنا وسيدنا وعلى آله وأصحابه وأتباعه بإحسان.\nأما بعد: فلا ريب أن اتصال الرجل بالمرأة قبل الزواج أمر محرم، وليس له أن يتصل بها لا بقبلة ولا لمس ولا غير ذلك، وليس لها أن تتصل به وليس له أن ينظر إلى عورتها وليس لها أن تنظر إليه، قال الله : قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ ۝ وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ [النور:30-31] الآية.\nوقال : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] الآية. فالذي فعلتم سابقاً منكر وعليكم التوبة إلى الله من ذلك، عليك وعليها التوبة إلى الله سبحانه مما فعلتما من الاتصال والمباشرة، والتوبة تجب ما قبلها، متى تاب كل منكما توبة صادقة مضمونها الندم على الماضي والعزيمة أن لا تعودا في ذلك، فهذا يكفر الله به ما مضى، حتى الكفر إذا تاب الكافر وأسلم تاب الله عليه، فهكذا المعاصي إذا تاب منها المسلم بالندم على الماضي والإقلاع منها والحذر منها تعظيماً لله سبحانه وحذراً من عقابه، وعزم عزماً صادقاً على عدم العود تاب الله عليه، وإن كان الذنب يتعلق بحق المسلم في ماله أو دمه أو عرضه استحله من ذلك أو أعطاه حقه، فالحاصل أنك أنت والمرأة عليكما التوبة مما مضى والتوبة تجب ما قبلها، وذلك بالندم على ما فعلتما سابقاً وعدم العود إلى ما حرم الله عليكما، والعزم الصادق على أن لا تعودا في مثل ذلك، أما النكاح فلا يتأثر بالماضي، النكاح إذا استوفت شروطه فلا بأس ونسأل الله أن يجعله نكاحاً مباركاً والحمد لله على السلامة من أسباب غضب الله .\nوهذا الذي فعلتما هذا من آثار الخلطة؛ فإن وجود المرأة مع الرجل في المكتب من أسباب وقوع الفاحشة، ولهذا نص العلماء على تحريم عمل المرأة مع الرجل في مكتب واحد وعمل واحد، يتمكن من الخلوة بها والنظر إليها والنظر إلى ما حرم الله منها ونظرها إليه نظر الشهوة والفتنة هذا من المحرمات، ومن الواجب الحذر منه وتركه، ..... المرأة لها أعمال تكون مع أخواتها ومع جنسها والرجل له أعمال مع إخوانه وجنسه، أما خلطهما وجعلهما في مكتب واحد وفي عمل واحد فهو يفضي إلى شر كثير وإلى فساد عظيم يجب الحذر منه، وهكذا السكرتيرة للكاتب أو للمدير أو للطبيب أو ما أشبه ذلك كلها أمور منكرة كلها محرمة كلها مفضية إلى الفساد والزنا والفاحشة، فيجب الحذر من ذلك، يجب على حكام المسلمين وعلى أولياء الأمور أن يحذروا هذه الأمور المنكرة، وأن يجعلوا النساء مع النساء والرجال مع الرجال، فالسكرتير يكون للرجل رجلاً، ويكون للمرأة امرأة، فالطبيبة تكون معها النساء وتكون مع النساء والممرضة كذلك مع النساء، وهكذا الممرض والطبيب يكون للرجال.\nالمقصود أن الواجب إبعاد هذا عن هذا والحذر من قرب هذا من هذا، ولا سيما في الأعمال التي يتصل فيها الرجل والمرأة ويخلو بها فإن شرها عظيم وعاقبتها وخيمة، والله المستعان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8080/حكم-اتصال-الرجل-بالمراة-قبل-الزواج-وتاثيره-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_268/26801.mp3","categories":["الرقائق","النظر والخلوة والاختلاط"]},{"id":9935,"question":"وهذه رسالة من الجمهورية العراقية محافظة بغداد من السائل (ع. ك. ج) يقول في رسالته: توجد امرأة متزوجة ومطلقة ومتزوجة من شخص آخر، ولديها بنات من زوجها السابق وتدخل على بيت زوجها السابق وتراه ويراها، ونفس الحالة مع ابنتها الكبيرة، فهي متزوجة ومطلقة ولها ولد من زوجها السابق وزوجها السابق يراها وتراه، ما الحكم في ذلك؟الشيخ: مع الأسف فإنه ..!المقدم: أعيد السؤال؟الشيخ: نعم.المقدم: السؤال مرة أخرى امرأة مطلقة ومتزوجة من شخص آخر، ولها بنات منه وهو يدخل عليها وتراها ويراه زوجها السابق، وكذلك ابنتها الكبرى نفس الحالة مطلقة ومتزوجة بشخص آخر وزوجها السابق يراها وتراه؟","title":"حكم ظهور المرأة المطلقة على زوجها السابق","answer":"الجواب: هذا فيه التفصيل، إن كان دخوله عليها لرؤية بناته وهكذا المرأة الأخرى يدخل الرجل عليها لأجل بنته بحضور أبيها بحضور أخيها بحضور زوجها الثاني على وجه لا شبهة فيه ولا فتنة فلا بأس بهذا ولا ريبة في هذه الحال، إذا كان الدخول دخولًا واضحًا شريفًا ليس فيه شيء ليرى بناته ولو سلمت عليه لا بأس مع الحجاب مع التحجب عنه، تسلم عليه لابد أن يكون حاضرًا من تزول معه التهمة.\nأما دخوله على زوجته السابقة من أجل بناته مطلقًا من دون حضور أحد هذا لا يجوز؛ لأنه قد يفضي إلى فتنة وقد يفضي إلى تهمة ولاسيما إذا كانت بنات صغارًا فإن الفتنة تكون أكبر.\nفالحاصل أنه لا يدخل عليها إلا إذا كان معه من تزول معه التهمة من زوجها الجديد أو أبيها المأمون أو أخيها المأمون الذي لا يتهم فلا بأس بهذا.\nأما الدخول الذي تكون معه التهمة فيمنع ؛ لأن الشيطان يجري من ابن آدم مجرى الدم، وقد تتفق معه على شيء قد تقول لبناتها: اذهبوا إلى كذا واذهبوا إلى كذا، فالشيطان موجود وتلبيسه كثير وتزيينه كثير للفساد والشر، فالواجب على المؤمن التحرز من هذا الشيء وأن لا يقدم عليه إلا بطريقة سليمة ليس فيها تهمة، هذا هو الواجب في هذه المسائل. نعم.\nالمقدم: طيب جزاكم الله خيرا إذًا نفهم من هذا أنه إذا أراد أن يراها وتراه لابد من وجود محرم حتى لا يكون هناك خلوة ولابد أن تحتجب منه؟\nالشيخ: الحجاب لابد منه، أما المحرم ما هو بلزوم لابد من وجود أناس لا يتهم معهم في الدخول.\nالمقدم: يعني حتى تنتفي الخلوة؟\nالشيخ: مثلًا إذا دخل ومعه ناس معروفون أو عندها يعني نساء معروفات مثل أخواتها مثل أمها وجدتها مثل ناس يعني تزول معهم التهمة ولكن إذا كان محرم فهو أكمل كأخيها وأبيها وعمها المأمون، يكون أكمل ولو دخل عليها وعندها النساء المأمونات من أم أو أخوات ونحو ذلك المقصود نساء تزول معهن التهمة، على طريقة لا تهمة فيها، هذا الضابط أن تكون الطريقة لا تهمة فيها. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8099/حكم-ظهور-المراة-المطلقة-على-زوجها-السابق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_199/19909.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":10015,"question":"رسالة بعثت بها إحدى الأخوات المستمعات تسأل جمعاً من الأسئلة، في أحدها تقول: هل ركوب المرأة مع السائق الأجنبي في وسط المدينة يجوز أو لا يجوز، جزاكم الله خيرًا؟","title":"ركوب المرأة وحدها مع سائق أجنبي","answer":"الجواب: ركوب المرأة مع السائق وحدها لا يجوز لأنه من الخلوة، ولو كان يذهب بها من مكان إلى مكان؛ لأن هذا يعتبر خلوة، وفي إمكانه الذهاب بها حيث يشاء، وفي إمكانه التحدث معها فيما يريد، فلا يجوز لها أن تذهب مع السائق وحدها، بل يجب أن يكون معهم ثالث، أخوها أو أختها أو أمها أو غير ذلك، يكون معهم ثالث حتى تزول الخلوة، يقول النبي ﷺ: لا يخلون رجل بامرأة فإن الشيطان ثالثهما.\nفالحاصل أن ذهابها مع السائق فيه خطر عظيم، وكم من امرأة ذهب بها السائق ثم انفرد بها حيث شاء، فالحاصل أنه لا يجوز أن تذهب مع السائق ولا مع غير السائق وحدها، لابد أن يكون معها شخص ثالث أو أكثر حتى تزول الخلوة، وحتى تزول الفتنة. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8184/ركوب-المراة-وحدها-مع-ساىق-اجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27603.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":10020,"question":"بالنسبة لركوب المرأة وحدها للضرورة أو مع أخ صغير عمره ثمان سنوات؟","title":"حكم ركوب المرأة مع سائق أجنبي بمفردها أو مع طفل","answer":"الجواب: تقدم أنه لا يجوز، لابد أن يكون معها ثالث، ثالث مكلف أو مراهق بحيث يحصل منه زوال الخلوة، أو امرأة أخرى ثالثة، يعني يكون الراكبون ثلاثة، السائق ومعه اثنان ما يكون خلوة، فإن الواحد تكون المرأة معه في خلوة؛ لأن الرسول قال ﷺ: لا يخلون رجل بامرأة فإن الشيطان ثالثهما، فإذا كان معهما ثالث أمها أو أختها أو جارتها أو أخو السائق أو غير ذلك، المقصود إذا وجد ثالث لا بأس. نعم.\nالمقدم: لكن يشترط أن يكون مكلف؟\nالشيخ: مكلفاً أو مراهقاً نعم، يحصل به يعني عدم الخلوة. نعم.\nالمقدم: الذي عمره ثمان سنوات ....\nالشيخ: لا ليس بشيء.\nالمقدم: الله المستعان، الله المستعان. جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8189/حكم-ركوب-المراة-مع-ساىق-اجنبي-بمفردها-او-مع-طفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27608.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":10275,"question":"في سؤال طويل، يسأل سماحة الشيخ! عن كشف زوجته لأخيه، هل لها ذلك أو لا؟","title":"حكم كشف المرأة لأخي زوجها","answer":"الجواب: ليس للمرأة أن تكشف لأخي زوجها، ولا لعمه ولا لخاله، ولا ابن عمه؛ لأنهم ليسوا محارم، بل عليها أن تحتجب عن الجميع، وإنما تكشف لأبيه، وجده، وابنه، وابن ابنه، وابن بنته ما يخالف، هؤلاء الفروع والأصول لا بأس، تكشف لهم؛ محارم.\nأما أخو زوجها، وعم زوجها، وخال زوجها، ونحوهم، ليسوا محارم، ليس لها الكشف لهم، ولا الخلوة بواحدٍ منهم، كما أنه لا يجوز لها الخلوة بأحد جيرانها، أو بني عمها، أو زوج أختها، أو زوج عمتها، أو زوج خالتها، كلهم أجناب، لكن زوج أمها محرم لها، زوج بنتها محرم لها، وزوج أمها كذلك؛ إذا كان قد دخل بها إذا كان قد وطئ أمها يكون محرماً لها؛ لأنها من الربائب، وزوج بنتها كذلك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8451/حكم-كشف-المراة-لاخي-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_311/31106.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":10285,"question":"في سؤال طويل، يسأل سماحة الشيخ! عن كشف زوجته لأخيه، هل لها ذلك أو لا؟","title":"حكم كشف المرأة لأخي زوجها","answer":"الجواب: ليس للمرأة أن تكشف لأخي زوجها، ولا لعمه ولا لخاله، ولا ابن عمه؛ لأنهم ليسوا محارم، بل عليها أن تحتجب عن الجميع، وإنما تكشف لأبيه، وجده، وابنه، وابن ابنه، وابن بنته ما يخالف، هؤلاء الفروع والأصول لا بأس، تكشف لهم؛ محارم.\nأما أخو زوجها، وعم زوجها، وخال زوجها، ونحوهم، ليسوا محارم، ليس لها الكشف لهم، ولا الخلوة بواحدٍ منهم، كما أنه لا يجوز لها الخلوة بأحد جيرانها، أو بني عمها، أو زوج أختها، أو زوج عمتها، أو زوج خالتها، كلهم أجناب، لكن زوج أمها محرم لها، زوج بنتها محرم لها، وزوج أمها كذلك؛ إذا كان قد دخل بها إذا كان قد وطئ أمها يكون محرماً لها؛ لأنها من الربائب، وزوج بنتها كذلك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8451/حكم-كشف-المراة-لاخي-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_311/31106.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":10464,"question":"رسالة بعث بها أحد الإخوة المستمعين يقول: أنا السائل من حضرموت أحمد جمعان دحدح ، يقول: إنني أعمل في أحد المعارض، وفي رمضان يشتد العمل عندنا، وأحياناً تدخل النساء منهن المتبرجة ومنهن غير المتبرجة، وبعض الزبائن يسأل عن مكان صناعة البضاعة الفلانية، فنجيبه بأنها صنعت في البلد الفلاني ونحن غير متأكدين من ذلك، بسبب الزحام لم نتمكن من النظر في البضاعة، هل علينا إثم، وهل كثرة النظر إلى النساء حرام؛ لأن عملنا يتطلب ذلك؟ جزاكم الله خيراً؟","title":"حكم النظر إلى النساء في المعارض التجارية","answer":"الجواب: ليس لكم أن تخبروا إلا عن يقين، وإلا أخبروا بالظن، قولوا: نظنها في كذا، لا تجزموا إلا إذا كنتم تعلمون أنها صنعت في المحل الفلاني، أما إذا كنتم لا تجزمون قولوا: نظن أو يغلب على الظن أنها صنعت في البلد الفلاني، حتى تسلموا من الكذب.\nوالنظر إلى النساء غير المحارم ما يجوز، تعمد النظر إليهن بشهوة وتلذذ لا يجوز، وهكذا إذا خاف الفتنة لا يجوز، أما النظر إليهن نظرا عارضا ليس معه شهوة بل لأسباب اقتضت ذلك، فلا يضر إن شاء الله، الإنسان مأمور بغض البصر، لكن إذا دعت الحاجة إلى النظر مثلما يمشي في الأسواق وينظر في المساجد من غير قصد الفتنة ولا قصد التلذذ فلا يضره ذلك، لا للمرأة ولا الرجل جميعاً، ولهذا أذن النبي ﷺ لـعائشة أن تنظر الناس وهم يلعبون في المسجد بالدرقة والحراب.\nفالحاصل أن نظر العامل الذي ليس معه شهوة ليس هو المقصود بالنهي، المقصود بالنهي النظر الذي يقصد للتلذذ أو يخشى منه الفتنة، فهذا ممنوع وينهى عنه لقوله جل وعلا: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ ۝ وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ [النور:30-31] ولما سئل ﷺ عن نظر الفجأة قال: اصرف بصرك فالإنسان يغض بصره إلا من حاجة تدعو له بغير تلذذ ولا خوف الفتنة، بل نظر عارض من غير قصد. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8641/حكم-النظر-الى-النساء-في-المعارض-التجارية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32007.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":10582,"question":"المستمع: (ح. م. ع) بعث برسالة وضمنها قضية يقول فيها: أنا شاب متزوج، ولي من الأولاد طفلان: هاجر وعبد الله ، وأعيش مع أهلي في الدار، وبين إخوتي وأولاد عمي، زوجتي تحس بالضيق نظراً للاختلاط الذي يحصل بينها وبين إخوتي وأولاد عمي، بم تنصحونني؟ هل تنصحونني باختيار دار أخرى، جزاكم الله خيراً؟","title":"ضابط سكن المرأة مع إخوان زوجها","answer":"الجواب: انظر ما هو الأصلح فإذا كانت زوجتك متحفظة وفي إمكانها السلامة من الاختلاط بما يسيء بها الظن فلا بأس أن تبقى مع أهلك، أما إن كان الاختلاط يخشى منه الفتنة بإخوانك أو ببني أعمامك، وأن عليها مشقة في التحرز من ذلك، فكونك تستقل في بيت وحدك هذا أصلح لك ولها، وأبعد عن الخطر، أما إذا كان بيتاً واسعاً وفي إمكانها التحرز من الاختلاط بإخوتك وبني عمك، الاختلاط الذي يخشى منه الفتنة، فهذا لاحاجة فيه إلى الانفراد وتبقى مع أهلك في محلك الخاص وشقتك الخاصة إذا كان البيت واسعاً، وليس على زوجتك خطر من الاختلاط؛ لأنه واسع وفي إمكانها الاستقلال والبقاء في محلها من دون اختلاط، ومن دون حرج. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8759/ضابط-سكن-المراة-مع-اخوان-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_324/32407.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":10711,"question":"يقول: عندنا يعيش في بعض البيوت أكثر من أربعة إخوة وهم متزوجون، وكل واحد له مكان عند النوم فقط، والأسرة مختلطة بعض الأحيان يأكلون في صحن واحد، هل يجوز هذا؟ وإذا كان لا يجوز فماذا يفعل إذا لم يقدر الواحد على أن يبني له سكناً خاصاً؟","title":"حكم اجتماع الإخوة بزوجاتهم في بيت واحد","answer":"الجواب: لا مانع من الاجتماع في بيت واحد، ويكون الرجال طعامهم وحدهم، والنساء طعامهن وحدهن، لا يجتمعون على طعام واحد، ينظر الرجل لمرأة أخيه، لا، بل النساء وحدهن في إناء واحد، والرجال وحدهم، هكذا ينبغي، يجب على كل واحد أن يعرف الأمر الشرعي، وأن يحكم شرع الله في نفسه وفي أهل بيته، فلا ينظر إلى زوجة أخيه ولا يخلو بزوجة أخيه، بل النساء يكن على حدة في طعامهن مستريحات يأكلن مستريحات، والرجال وحدهم هكذا، أما أن تأكل مع أخي زوجها ومع عمه تأكل معه، يرى وجهها ويرى أكلها ويرى يدها، هذا غلط، الله جل وعلا يقول: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، والمسلم يلتمس الطهارة لقلبه ولقلب أهل بيته، فتكون زوجة أخيه مع زوجته، مع أمه، مع بناته على حده، يأكلون جميعاً، والرجال وحدهم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8894/حكم-اجتماع-الاخوة-بزوجاتهم-في-بيت-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_343/34309.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":10830,"question":"تقول في سؤال آخر: فتاة متدينة، وتجاوزت العشرين من عمرها والحمد لله تؤدي كل واجباتها الدينية، إلا أنها تكشف وجهها أمام أزواج أخواتها، وذلك لأنها ليس لها رغبة في الزواج؛ لأن بها عاهة خلقية منذ الولادة، فهل عليها إثم في ذلك؟","title":"ما حكم كشف الوجه بالنسبة لامرأة بها عاهة خلقية؟","answer":"الجواب:  عليها التوبة إلى الله من ذلك؛ لأن كشفها لأزواج أخواتها لا يجوز، فينبغي لها في مثل هذا الندم والاستغفار والحمد لله، إلا إذا كانت العاهة في الوجه، فتكون مثل القاعدة، مثل العجوز الكبيرة التي لا تشتهى، ولا شيء عليها، إن شاء الله.  أما إذا كان وجهها سليمًا والعاهة داخلية، والوجه سليم فعليها التوبة والاستغفار؛ لأنه ليس لها الكشف، بل عليها أن تحتجب عن أزواج أخواتها، وعن كل أجنبي لقول الله  في كتابه العظيم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] ولقوله سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية، والوجه من أعظم الزينة، بل هو أبرز الزينة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8994/ما-حكم-كشف-الوجه-بالنسبة-لامراة-بها-عاهة-خلقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_354/35405.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":10926,"question":"هل يمكن للمرأة أن تختلي عند الضرورة برجل تأمنه، كزوج الأخت، مثلًا: عندما يقوم بتوصيلها من مكان لآخر؟","title":"حكم اختلاء المرأة بزوج أختها للضرورة داخل المدينة","answer":"الجواب:  لا يجوز للمرأة أن تختلي بالرجل، سواء كان زوج أختها، أو كان أخا زوجها، أو غيرهما؛ لأن ذلك فيه خطر عظيم، ومخالفة للسنة الثابتة عن النبي ﷺ، حيث قال -عليه الصلاة والسلام-: لا يخلون رجل بامرأة فإن الشيطان ثالثهما، وقال -عليه الصلاة والسلام-: لا يخلون رجل بامرأة إلا ومعها ذو محرم،. فالواجب على المرأة أن تحذر الخلوة بالرجل مطلقًا، ولو كان ثقةً ليس لها الخلوة بالرجل؛ لأن هذا مخالف لصريح السنة عن النبي ﷺ؛ ولأن الشر لا يؤمن على الجميع. فالواجب الأخذ بالسنة، والتمسك بما شرع الله، والحذر مما حرم الله، وأن لا تخلو برجل لا في طريقها إلى مدرسة، ولا في طريقها إلى وليمة، ولا غير ذلك، بل يكون معهما ثالث، إما امرأة ثقة، أو رجل ثقة، أو نحو ذلك ممن يزول به حكم الخلوة، وقد خطب النبي ﷺ ذات يوم فقال -عليه الصلاة والسلام-: لا يدخلن أحد بعد يومي هذا على امرأة إلا ومعه رجل أو رجلان. والمقصود من هذا البعد عن الخلوة، وعن الريبة، فالحاصل أن دخول الإنسان على المرأة، أو الجلوس معها وحدهما، أو حملها في السيارة وحدها ليس معها ثالث فيه خطر، وفيه خلوة لا تجوز، نعم. المقدم: جزاكم الله خيرًا، سواءً كان ذلك داخل المدينة، أو خارجها؟ الشيخ: نعم، لكن إذا كان في السفر يكون أشد تحريمًا، إذا كان سفرًا يكون أشد في التحريم؛ لقوله ﷺ: لا تسافر امرأة إلا مع ذي محرم. أما في داخل المدينة فلا بأس أن يكون معهما ثالث؛ لأنه لا يسمى سفرًا ولو كان غير محرم، كالسواق ومعه أمه، أو معه أخوه، أو معه رجل آخر، أو امرأة أخرى تزول به الخلوة على وجه ليس فيه ريبة، يعني: على طريقة ليس فيها ريبة، ولا شبهة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9110/حكم-اختلاء-المراة-بزوج-اختها-للضرورة-داخل-المدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_362/36207.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":10930,"question":"يقلن أيضًا: المرأة التي تسكن مع أهل زوجها في بيت واحد، وللزوج إخوة ذكور بالغون، هل يحق لها أن تبدي شيئًا من زينتها أمامهم؟ أي: هل يحق لها التبرج أمامهم؟ وهل الكحل من التبرج المنهي عنه؟","title":"حكم إبداء الزوجة للزينة لإخوة زوجها البالغين","answer":"الجواب:  الواجب عليها التحجب عن إخوان زوجها، وأن لا تبدي لهم شيئًا من زينتها؛ لقوله : وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ أَوْ نِسَائِهِنَّ ... [النور:31] الآية من سورة النور، وليس إخوان الزوج من هؤلاء. والبعولة: هم الأزواج، فإخوان الزوج ليسوا من هؤلاء، وهكذا أعمامه، وهكذا أخواله، وهكذا أزواج الأخوات ليسوا من هؤلاء، فليس للمرأة أن تبدي زينتها لهؤلاء لا الوجه، ولا الحلي التي في العنق، ولا في اليد، ولا القدم، ولا الساق، عليها أن تستر الجميع بجلبابها أو بعباءتها أو نحو ذلك حتى لا يرى إخوان زوجها منها شيئًا، كما في الآية الأخرى، يقول : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، فالتحجب أطهر لقلوب الجميع، النساء والرجال جميعًا. أما السلام بالكلام فلا بأس، لكن من دون مصافحة، تسلم على أخي زوجها، وعم زوجها، وخال زوجها بالكلام، ترد عليه السلام، تسأله عن حاله، وعن حال بيته ما يخالف، لكن لا تصافحه، ولا تكشف له عن زينتها، بل تحتجب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9107/حكم-ابداء-الزوجة-للزينة-لاخوة-زوجها-البالغين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_362/36204.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":10961,"question":"يسأل أخونا أيضًا سؤالًا آخر ويقول: على حياة والدي -رحمه الله- وعندما كنت صغيرًا لم أتجاوز الرابعة عشرة من عمري، كنت أغضبه، ولم أكن أستمع لكلامه، فهل يعتبر هذا عقوقًا؟ وهل عليَّ كفارة؟ لأنني أخشى أن يكون توفي وهو غاضب علي، أرجو الإفادة جزاكم الله خيرًا.","title":"هل يؤاخذ الأبن على عصيانه لوالديه قبل بلوغه للحلم.","answer":"الجواب:  نعم هذا من العقوق إلا إذا أمرك بشيء لا يجوز شرعًا فخالفته، ليس هذا من العقوق؛ لأن الطاعة في المعروف لا في المعصية، فإذا عصيت والدك في المعروف هذا عقوق، وإذا أمرك بالصلاة، ولم تصل فهو عقوق، وإذا أمرك ببر والدتك وأبيت فهذا عقوق، وإذا نهاك عن سب الناس، وعن ظلم الناس وأبيت هذا عقوق ومعصية أيضًا لله . فالخلاصة أنه إذا أمرك بما ينفعك، ونهاك عن ما يضرك، أو أمرك بما ينفعك ولا مشقة عليك، بل تستطيع ذلك، فمخالفته عقوق، وسبه عقوق. أما إذا كان ذلك في معاصي الله فإنه لا يجوز لك أن تطيعه في معاصي الله، إذا قال لك: لا تصل في الجماعة ما يلزمك طاعته، أو قال لك: اشرب الخمر، ما يلزمك طاعته، أو قال لك: استعمل الدخان ليس لك طاعته بهذا؛ لقول النبي ﷺ: إنما الطاعة في المعروف وقوله -عليه الصلاة والسلام-: لا طاعة لمخلوق في معصية الخالق. وعليك أن تستغفر الله، وتتوب إليه مما قصرت في حق والدك، وإذا كنت لم تبلغ الحلم فالأمر أسهل، إذا كنت حين معصيتك له صغير، لم تبلغ الحلم، فالأمر أسهل، ولكن مع هذا كله تدعو له كثيرًا تستغفر له كثيرًا، وتتصدق عليه إذا استطعت، وتستغفر الله من تقصيرك؛ لأنك قد تكون تساهلت في ذلك بعد الحلم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9141/هل-يواخذ-الابن-على-عصيانه-لوالديه-قبل-بلوغه-للحلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_364/36408.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":11024,"question":"الأخوان: عبدالسلام أحمد محمد يوسف، وعبدالمعطي حمدي بعثا برسالة يسألان فيها عن قضيتين الأولى: كونهم يعيشون في بيت واحد وهم خمسة إخوة، ويجتمعون على المأكل والمشرب النساء والرجال، ويأكلون جميعًا، ويسألون عن حكم هذا جزاكم الله خيرًا؟","title":"حكم اجتماع الإخوة مع زوجاتهم للطعام","answer":"الجواب:  اجتماعهم في بيت واحد لا حرج إذا كان فيه مصلحة لهم، وليس فيه شيء مما يضرهم، وليس فيه شيء من المنكرات التي تسبب غضب الله عليهم، أما إذا كان اجتماعهم قد يجر إلى الشر والفساد فتفرقهم أفضل، أما اجتماعهم على الأكل نساءً ورجالاً فلا يجوز، بل الرجال يأكلون وحدهم والنساء وحدهن؛ لأن المرأة تحتاج إلى كشف وجهها للأكل، وأخذ اللقمة بيدها معهم، وربما كشفت، فالواجب أن تكون على حدة لتأخذ حريتها في أكلها، ولئلا يرى الرجال وجهها، أو يدها وهي عورة. فالمقصود: أن النساء يأكلن وحدهن، والرجال وحدهم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9202/حكم-اجتماع-الاخوة-مع-زوجاتهم-للطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_367/36703.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":11035,"question":"يقول في سؤاله الأخير: هذا الأخ من السودان، علمت بأن النظر إلى المرأة محرم، فإذا كانت لي ابنة عم، تسكن معنا، وتطهو الطعام، ونتناوله معًا وأنظر إليها؛ فماذا يلزمني فهل عملي صحيح؟ وجهوني بهذا سماحة الشيخ.","title":"حكم النظر إلى ابنة العم وتناول الطعام معها","answer":"الجواب:  لا يجوز لك ذلك، الواجب عليك غض البصر، والواجب عليها التستر هي، ولا تأكل معكم، تأكل وحدها مع النساء، ابن عمك ما هي بمحرم لك، لك أن تتزوجها، فالواجب عليك غض البصر، والواجب عليها التستر، والواجب عليك عدم الخلوة بها، وعدم النظر إليها، نعم؛ لأن هذا فتنة، ومن أسباب الشر. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9213/حكم-النظر-الى-ابنة-العم-وتناول-الطعام-معها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28717.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":11094,"question":"السائلة أم عبدالمجيد من جدة تقول: بأنني أذهب إلى جماعة تحفيظ القرآن الكريم، وعند العودة إلى المنزل أعود مع السائق مع أخوات لي في الله، ثم تذهب كل واحدة إلى منزلها، وأبقى وحدي مع السائق والمسافة تستغرق حوالي خمس دقائق حتى أصل إلى المنزل، هل هذه خلوة يا سماحة الشيخ، نرجو الإفادة؟","title":"حكم ركوب المرأة مع السائق لوحدها لمدة يسيرة","answer":"الجواب:  الواجب على المؤمنة عدم الخلوة بالرجل الأجنبي، لا في السيارة، ولا في غيرها، ولا شك أن جلوس المرأة مع الرجل خمس دقائق، أو أقل، أو أكثر وحدهما خلوة، فالواجب النظر في الأمر، وأن ينزلكن جميعًا، أو تبقى اثنتان تنزلان جميعًا حتى تحصل السلامة من الخلوة؛ لقول النبي ﷺ: لا يخلون رجل بامرأة فإن الشيطان ثالثهما، نهى ﷺ عن الخلوة إلا مع محرم. فالواجب على المرأة أن تتحرى هذا الأمر، وأن تحرص على الامتثال، وأن تحذر الوقوع فيما نهى الله عنه في السيارة وغيرها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9272/حكم-ركوب-المراة-مع-الساىق-لوحدها-لمدة-يسيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29002.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":11098,"question":"هذه السائلة تقول: أختكم في الله من الرياض (ص. ب. أ) تقول: هل يجوز لي أن أكشف وجهي وشعري أمام أبناء عمي الذين لم يبلغوا مبلغ الرجال؟ جزاكم الله خيرًا.","title":"حكم كشف المرأة لوجهها وشعرها أمام الأطفال","answer":"الجواب:  نعم، إذا كانوا ما بعد بلغوا الحلم كأبناء العشر، وأشباههم لا حرج؛ لقول الله -جل وعلا-: وَإِذَا بَلَغَ الأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا [النور:59]، فجعل من لم يبلغ الحلم طفلًا، فإذا كان الولد مراهقًا؛ ...... يقع ...... الثلاث فينبغي للمؤمنة الاحتياط، وعدم الخلوة به، وعدم التساهل للكشف لوجهها، وشيء من بدنها عنده. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9276/حكم-كشف-المراة-لوجهها-وشعرها-امام-الاطفال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29006.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":11187,"question":"هل للمرأة أن تركب مع ابن خالها، ومعه بعض محارمه؟","title":"هل للمرأة أن تركب مع ابن خالها، ومعه بعض محارمه؟","answer":"الجواب:  لا بأس للمرأة أن تركب مع السائق الأجنبي إذا كان معهما ثالث يطمأن إليه ويوثق به ولا يتهم بشيء فلا بأس؛ لأن الخلوة تزول بذلك إذا كان معه زوجته، أو معه أمه، أو معه أخوه وهم لا يتهمون، فإن المسألة لا حرج فيها، إذ المقصود عدم الخلوة، النبي  يقول: لا يخلون رجل بامرأة فإن الشيطان ثالثهما، فإذا كان مع السائق أمه أو زوجته أو شخص آخر ممن لا يتهم، فإن الخلوة تزول ولا حرج في ذلك في غير السفر، أما السفر لا، لابد من محرم، لكن هذا في البلد. نعم. المقدم: نعم هي تسأل عن السفر سماحة الشيخ؟ الشيخ: لا، السفر لابد من المحرم، نعم، لا بد من محرم. المقدم: لابد من محرم لها، ولو كان السائق معه أناس من محارمه؟ الشيخ: ولو ولو لا بد من محرم لها، لا تسافر إلا بمحرم، ولو كان معها سائق معه زوجته أو معه أمه أو معه أخواته، ليس محرمًا لها، أما في البلد لا بأس في البلد غير السفر، إذا كانت تقضي الحاجة، إلى حاجة في المستشفى إلى حاجة في السوق، لا بأس أن تكون معه ثالثًا معه شخص ثالث أو رابع، يعني: لا يتهم. نعم. المقدم: الله المستعان! جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9361/هل-للمراة-ان-تركب-مع-ابن-خالها-ومعه-بعض-محارمه ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37206.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":11267,"question":"في سؤالها الثاني تقول: بأنها امرأة مطلقة وتقيم مع أولادها في بيت الزوج، فهل يجوز لها البقاء في بيته أم تخرج، وهل يجوز أن تأكل من الطعام الذي يحضره الزوج لأولادها وجزاكم الله خيرًا؟","title":"حكم بقاء المرأة المطلقة مع أولادها عند أبيهم","answer":"الجواب:  نعم، لا بأس أن تقيم مع أولادها إذا كان على وجه ليس فيه خلوة ولا فتنة، أما إذا كان الطلاق رجعيًا فلا بأس، السنة بل الواجب، والله جل وعلا قال: وَلا يَخْرُجْنَ [الطلاق:1] قال: لا تُخْرِجُوهُنَّ [الطلاق:1] فإذا كان الطلاق رجعيًا طلقة واحدة أو طلقتين تجلس لعله يراجعها، فإن كانت الطلقة الأخيرة بائنة أو مخالعة فإن جلست للحاجة على وجه ليس فيه خلوة مع أولادها فلا حرج في ذلك، وإن خرجت في محل آخر ابتعادًا عن الفتنة فلا بأس، لكن بعض النساء قد يحتجن إلى هذا، قد تكون ما لها أحد فتبقى عند أولادها وتجلس مع أولادها، ولكن لا يخلو بها، ولا بأس أن يتحدث معها أو تتحدث معه، لكن مع الحجاب ومع عدم الخلوة. نعم.","link":"https://binbaz.org.sa/fatwas/9448/حكم-بقاء-المراة-المطلقة-مع-اولادها-عند-ابيهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_292/29203.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":11503,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول المرسل: (أ. ح. م. الودعاني) أخونا رسالته مطولة بعض الشيء، يقول فيها: التزمت بالشريعة الإسلامية أنا وزوجتي من قبل ثلاث سنوات فقط، حيث قطعنا حبل الاختلاط بغير المحارم، ومنعت نفسي من مصافحة النساء، والتزمت زوجتي بالحجاب، وأخبرتها أن مصافحة الرجال غير المحارم حرام، فاقتنعت، ولم تسلم على الرجال الذين ليسوا بمحارم، لكن أقاربي، وأقارب زوجتي لم يرضوا بذلك، وقاطعونا إلا أن نعود إلى الاختلاط والمصافحة، وكشف الحجاب، ونحن لا يمكن أن نعود إلى ما يدعونا إليه من معصية الله بعد أن وفقنا الله للطريق الصحيح، غير أن زوجتي متأثرة، وليست مرتاحة، وأمها قاطعتنا، وأقسمت أننا لا نسلم عليها لا أنا، ولا بنتها حتى نعود للماضي القديم، ونسلم على القريب والبعيد، كما كنا نفعل من قبل، وهذا لا يكون؛ لأنه عمل مخالف للشريعة الإسلامية، و لا طاعة لمخلوق في معصية الخالق فأرجو أن توضحوا لنا يا سماحة الشيخ وتوضحوا لهؤلاء الناس حتى لا تصاب قلوبنا بالمرض، جزاكم الله خيرًا.","title":"نصيحة لمن ابتلي بأقارب يجيزون الاختلاط ومصافحة النساء","answer":"الجواب:  لقد أحسنتم والحمد لله، ونسأل الله لكم الثبات على الحق، والعافية من مضلات الفتن، ونوصيكم بالبقاء والثبات على ما أنتم عليه، وعدم طاعة أولئك، ولو قاطعوكم، لا تطيعوهم ولو قاطعوكم للحديث الذي ذكرت في السؤال، يقول النبي ﷺ: لا طاعة لمخلوق في معصية الخالق ويقول ﷺ: إنما الطاعة في المعروف.  فأنتم التزموا بما أنتم عليه من الاستقامة، وعدم المخالطة لمن يعصي الله، وعدم مصافحة المرأة للرجال الأجانب، وهكذا عدم التساهل بالصلاة، وعدم السفر الذي لا يرضاه الله، كل ذلك عليكم بالاستقامة دائمًا في صحبة الأخيار، وعدم صحبة الأشرار، والمحافظة على الصلاة في أوقاتها في الجماعة، وعدم مصافحة النساء، لا الرجل يصافح المرأة، ولا المرأة تصافح الرجل الأجنبي، تصافح محارمها، كأخيها وعمها لا بأس، أما الأجانب فلا، الرجل لا يصافح المرأة الأجنبية، والمرأة لا تصافح الرجل الأجنبي، فعليكم بتقوى الله، وعليكم بالثبات، وأبشروا بالخير، ولو قاطعكم الناس، ولو قاطعوكم، ولو هجروكم، أنتم على الحق وهم على الخطأ، نسأل الله لنا ولكم الثبات على الحق، ونسأل الله الهداية للجميع. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9697/نصيحة-لمن-ابتلي-باقارب-يجيزون-الاختلاط-ومصافحة-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_384/38413.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":11525,"question":"بعد هذا رسالة وصلت إلى البرنامج من السودان، باعثها مستمع يقول: أخوكم في الله: أحمد المبارك أحمد، أخونا أحمد يقول: هل يجوز أن أمنع زوجتي من زيارة بيت؛ خوفًا من الاختلاط، علمًا بأن أهل ذلك البيت لا يبالون بالاختلاط، وليس فيه إلا أولاد وأمهم؟ وجهوني جزاكم الله خيرًا.","title":"حكم منع الزوج زوجته من زيارة بيت فيه اختلاط","answer":"الجواب:  نعم، إذا خشيت عليها الشر؛ فامنعها من زيارة البيت المختلط، وغيره مما تخشى فيه الشر، امنعها من كل ما يضرها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9713/حكم-منع-الزوج-زوجته-من-زيارة-بيت-فيه-اختلاط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_385/38509.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":11560,"question":"رسالة مطولة من إحدى الأخوات المستمعات ضمنتها ما يقرب من خمسة أسئلة، في أحدها تذكر أن زوجها يسكن مع إخوته وأبيه في منزل واحد، وأنها كثيرًا ما تتعرض للكشف أمام إخوانه، وقد أبدت زوجها في ذلك الموضوع، لكنه لم يبال، وتسأل سماحتكم كيف تتصرف؟ جزاكم الله خيرًا.","title":"حكم عدم تحجب المرأة أمام إخوة الزوج","answer":"الجواب:  الواجب عليك تقوى الله  وأن تتحفظي من إخوانه حسب الطاقة، فلا تجلسي مع واحد منهم خلوة، ولا تكشفي لأحد منهم، أما إذا كان صدفة، خرجت من باب صدفة، ما أردت فرآك، أو من مطبخ فرآك من غير إيقاع عمد منك؛ فلا حرج عليك، النبي ﷺ: لما سئل عن نظر الفجاءة؟ قال: اصرف بصرك. فأنت كذلك إذا رأيت أحدًا منهم، تغشي تغطي عنهم، والحمد لله، والشيء الذي وقع من غير قصد؛ يعفو الله عنه، لا منك ولا منهم، إذا رآك أحد منهم فجأة؛ فلا حرج أن يصرف بصره، وإذا أنت ظهرت وأحد منهم أمامك، ولم تشعري به؛ فبادري بالحجاب، والحمد لله، والشيء الذي ليس في اختيارك لا يضرك ولا يضرهم: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9743/حكم-عدم-تحجب-المراة-امام-اخوة-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29709.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":11574,"question":"(أم عبد الله . ف. س. السبيعي) بعثت برسالة تقول فيها: ما هي المسافة المحددة شرعًا للركوب فيها مع سائق ما، علمًا بأنني موظفة، وأعمل بمدرسة تبعد عن مقر سكني ما يقارب خمس عشرة دقيقة بالكثير فقط، ومعي مجموعة من المدرسات، ومن نفس الحي الذي أسكن فيه، ومعي في نفس المدرسة، فهل علينا حرج في ذلك؟ مع العلم -أيضًا- أن زوجة السائق متواجدة، والخادمة أيضًا في المنزل، ولكن يصعب علي ذهابها معنا؛ لأن لدي أطفال في البيت، ووجودها -كما يعلم فضيلتكم- واجب، أرجو أن توجهوني في هذا الموضوع، جزاكم الله خيرًا.","title":"حكم ركوب أكثر من امرأة مع سائق أجنبي","answer":"الجواب:  ليس هناك حرج في الذهاب إلى المدرسة مع السائق إذا لم يكن هناك خلوة، إذا كنتن جماعة فالحمد لله، الممنوع السفر، لا تسافر المرأة إلا مع محرم، السفر يمنع إلا مع المحرم، أما في البلد إلى المدرسة، أو إلى زيارة بعض الأحباب والأقارب؛ هذا لا بأس، لكن لا تكن وحدها مع السائق، بل يكون معهم ثالث زوجته، أو رفيقة لها معها، لقوله ﷺ: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما فالخلوة لا تجوز. فإذا كان مع السائق ثالث: زوجته، أو أمه، أو معك امرأة أخرى؛ فلا حرج في الخروج من البيت إلى المدرسة مسافة ربع ساعة، أو ثلث ساعة، أو أقل، أو أكثر هذا ما يسمى سفرًا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9757/حكم-ركوب-اكثر-من-امراة-مع-ساىق-اجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38607.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":11580,"question":"تذكر حالها مع زوج أختها سماحة الشيخ وتقول: إنه يعرفها منذ الصغر، والآن لما كبرت؛ أصبحت في حرج، هل تتحجب عنه أو لا؟ ولاسيما إذا رآها تود أن تحتجب بدأ يداعبها ويقول: هذه البنت مطوعة، وما أشبه ذلك، فما هو توجيه سماحة الشيخ؟","title":"حكم لبس المرأة الحجاب أمام زوج الأخت","answer":"الجواب:  الواجب عليك الاحتجاب، ولو كان يعرفك في الصغر، الواجب عليك الاحتجاب؛ لأنه غير محرم، زوج الأخت ليس بمحرم، وهكذا زوج العمة والخالة ليس محرمًا.  فالمقصود: الواجب عليك الاحتجاب، والحذر من الخلوة به، والمداعبة التي قد تفضي إلى الشر، عليك السلام الشرعي، والكلام الشرعي المؤدب، والحذر من التساهل مع وجوب الحجاب، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9764/حكم-لبس-المراة-الحجاب-امام-زوج-الاخت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38610.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":11664,"question":"أيضًا تقول: ابن أخي له بنات متزوجات، هل أزواجهن محارم لي؟","title":"هل أزواج بنات ابن الأخ من المحارم؟","answer":"الجواب:  مثلما تقدم لا، أزواج بنات الأخ، وبنات الأخت ليسوا محارم تقدم، المحرم زوج البنت، وزوج بنت البنت، زوج بنت الابن -بنت ولد المرأة- وإن نزل، هؤلاء هم المحارم، وهكذا زوج الأم محرم لبنتها إذا كانت قد دخل بها، إذا كانت الأم قد وطئها يعني، لقوله سبحانه: وَرَبَائِبُكُمُ اللَّاتِي فِي حُجُورِكُمْ مِنْ نِسَائِكُمُ اللَّاتِي دَخَلْتُمْ بِهِنَّ فَإِنْ لَمْ تَكُونُوا دَخَلْتُمْ بِهِنَّ فَلا جُنَاحَ عَلَيْكُمْ [النساء:23]، فالدخول: الوطء، فزوج أمها محرم لها إذا كان قد وطئ أمها، ولو كانت ليست في حجرها، وصف الحجر وصف أغلبي، وهكذا زوج جدتها من أمها، أو من أبيها هو أيضًا محرم لها، إذا كان قد دخل بالأم. نعم.","link":"https://binbaz.org.sa/fatwas/9847/هل-ازواج-بنات-ابن-الاخ-من-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_298/29816.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":11854,"question":"مستمع أو مستمعة الرمز (ع. هـ. ح. ك)، بل شاب يقول: أنا شاب، ولله الحمد ملتزم بدين الله تعالى، وأعيش في أسرتي المكونة من الوالدة والوالد وإخواني، ولنا أقارب في نفس المكان الذي نحن فيه، ولكن هؤلاء الأقارب وأسرتي في خصام، وقتال دائم، والكل منهم لا يرضى عن الآخر، مع العلم بأن هؤلاء الأقارب على أخلاق سيئة، ومعاملتهم معنا سيئة، وأنا أقف حيران إذا ذهبت إليهم؛ لأصل ما أمر الله بوصله من صلة الرحم، غضب الوالد والوالدة، وإذا لم أذهب حتى أرضي والدي ووالدتي أخشى من عقوبة قطيعة الرحم، فبماذا توجهونني؟ جزاكم الله خيرًا.","title":"حكم طاعة الوالدين في عدم صلة الأرحام","answer":"الجواب:  إذا كان الأقارب عندهم منكرات ظاهرة يستحقون عليها الهجر؛ فلا تذهب إليهم، لكن لو ذهبت إليهم للنصيحة والتوجيه إلى الخير، والأمر بالمعروف، والنهي عن المنكر؛ فهذا طيب، لعلهم يهتدون، ولو ما أعلمت والديك، فإذا لم تجد النصيحة، ولم ينفع فيهم التوجيه؛ فحينئذٍ يشرع هجرهم؛ لإصرارهم على المعصية، ومع ذلك ترضي والديك بهذا الأمر. أما إذا رجوت أن الله ينفعهم بنصيحتك وتوجيهك؛ فاذهب إليهم، وانصحهم، وأمرهم بالمعروف، وانههم عن المنكر؛ لعل الله يهديهم بذلك، ولو لم يرض والداك لكن إذا تيسر إخفاء ذلك عن والديك، تجمع بين المصلحتين؛ فحسن، يقول النبي ﷺ: إنما الطاعة في المعروف فإذا ذهبت إلى أقاربك للنصح والتوجيه والأمر بالمعروف والنهي عن المنكر؛ هذا عمل طيب، ومشروع ولو لم يرض والداك، لكن إذا تيسر أن تخفي ذلك عنهما، فتجمع بين المصلحتين: بين إرضاء والديك، وبين القيام بما شرع الله لك من النصيحة والتوجيه، فهذا كله حسن، نعم.","link":"https://binbaz.org.sa/fatwas/10052/حكم-طاعة-الوالدين-في-عدم-صلة-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39715.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":11885,"question":"المستمع (م. ف. ع) مقيم في الرياض بعث برسالة وضمنها سؤالين، ملخص ما في سؤاله الأول: السؤال عن حكم إدخال رجل إلى بيته ليعلم أولاده وهو غائب، لكن الأولاد وأمهم في البيت، هل يجوز ذلك، أو لا؟","title":"حكم تعليم الأجنبي أولاداً في منزلهم والأب غائب","answer":"الجواب:  إذا كان الأولاد كبارًا؛ فلا بأس، أما إذا كانوا صغارًا دون السبع السنين؛ فلا، لابد من وجود من يزيل الخلوة، فلا يدخل على بيته من يعلم أولاده وهم صغار، وليس عند امرأته أحد من الكبار؛ لأن هذه خلوة، أما إذا كانوا كبارًا، أبناء سبع، فأكثر؛ فلا حرج -إن شاء الله- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10069/حكم-تعليم-الاجنبي-اولادا-في-منزلهم-والاب-غاىب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42506.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":11934,"question":"إذا اشترى لنا والدي بعض الأشياء للبيت، ووالدتي ولِيَّةُ ذلك، فأخذنا منه أنا وإخوتي بدون علم منها، فما حكم ذلك؟","title":"حكم أخذ شيء من حاجات البيت بدون إذن الأب","answer":"الجواب:  إذا كنتم في بيوت مستقلة؛ فليس لكم الأخذ إلا بإذن الوالد؛ لأنه اشترى لبيته، والوالدة لا تعطيكم شيئًا إلا بإذنه، إلا إذا كنتم تعلمون أنه يسمح، وليس عنده في هذا مانع؛ فلا بأس، فإذا اشترى لحمة لبيته؛ لا تأخذوا منها شيئًا، أو فاكهة للبيت؛ لا تأخذوا إلا بإذنه، النطقي، أو العرفي إذا كان من عرفكم المعروف بينكم أنه يتسامح، وأنه لا يهمه هذا الأمر؛ فلا بأس، وإلا فليس لكم الإقدام على هذا الشيء الذي اشتراه لبيته، وعند زوجته، أو عائلته الصغار، وأنتم في بيوت مستقلة، لا تأخذوا منه شيئًا إلا بإذنه. والوالدة كذلك لا تعطيكم إلا بإذنه، إلا إذا كان هناك إذن معروف من والدكم، إذن صريح، أو تدل عليه شواهد الحال، ومعروف من حالته وسماحه، وأنه لا يأبى أن يؤخذ من هذا الشيء، إذا عرف هذا؛ فلا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10118/حكم-اخذ-شيء-من-حاجات-البيت-بدون-اذن-الاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_427/42711.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":12048,"question":"يسأل أحد الإخوة المستمعين فيقول: هل يجوز أن أجلس مع زوجة أخي ونحن في المسكن وحدنا؟","title":"حكم الجلوس مع زوجة الأخ","answer":"الجواب:  لا يجوز لك ذلك، لا يجوز لك أن تخلو بالمرأة، لاسيما زوجة أخيك، لابد أن يكون معكما ثالث، كأمك، أو أختك، أو خادمة، أو ما أشبه ذلك من الذين يثلثون غيرك؛ لقول النبي ﷺ: لا يخلون رجل بامرأة فإن الشيطان ثالثهما فإذا كان معكما رابع ما صار الشيطان ثالث، فلا بأس أن تجلسوا أنت وزوجة أخيك ومعكما الوالدة، معكما أخواتك لا بأس، مع تحجبها وابتعادها عن أسباب الفتنة. وهكذا ابنة عمك وخالك ونحو ذلك، وهكذا وجود المرأة من الجيران في البيت، ومع أهلك تكلمك وتكلمها، فيما يتعلق بمسائل الجيران، أو بالتحية والسلام، أو ما أشبه ذلك، على وجه ليس فيه تهمة، ولا ريبة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10233/حكم-الجلوس-مع-زوجة-الاخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_433/43317.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12077,"question":"هل زوجة خالي، أو زوجة عمي تعد من المحارم بالنسبة لي؟","title":"بيان أن زوجة الخال والعم ليستا من المحارم","answer":"الجواب:  زوجة عمك وخالك أجنبيات مثل زوجة أخيك، أخوك أقرب، ومع هذا زوجته أجنبية، ليست محرمًا لك، فزوجة الخال والعم من باب أولى أنهما أجنبيتان، ليس لك أن تخلو بهما، وليس لهما أن يكشفا لك، وليس لك أن تصافحهما؛ لأنها أجنبية، زوجة خالك، زوجة أخيك، زوجة عمك، كلهن أجنبيات. أما زوجة أبيك لا، لا حرج، زوجة أبيك، وزوجة جدك من النسب والرضاع محارم، جد جدك كذلك، زوجة ابنك محرم لك من النسب، والرضاع، زوجة ابن بنتك، حتى ابن بنتك زوجته محرمًا لك من النسب والرضاع، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10262/بيان-ان-زوجة-الخال-والعم-ليستا-من-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_435/43510.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12134,"question":"هل أم خطيبتي قبل كتابة العقد تعتبر من المحارم؟ وهل يجوز أن أسلم عليها؟","title":"حكم السلام على أم المخطوبة قبل العقد","answer":"الجواب:  ليست من المحارم حتى يتم العقد، إذا تم العقد ....... النساء، أما قبل ذلك فهي أجنبية، تسلم عليها، تسأل عن حالها، وعلى خطيبتك سلامًا لا يتضمن كشفًا، ولا خلوة ولا فتنة، سلامًا عاديًا مثلما تسلم على الأجنبيات الأخريات، إذا كان ذلك ليس فيه فتنة، ولا يخشى منه الفتنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10319/حكم-السلام-على-ام-المخطوبة-قبل-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_439/43903.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12141,"question":"تقول: إن أهل زوجي يدخلون في البيت دون وجود زوجي، ولكن معي طفل كبير عمره أربع عشرة سنة، فهل يجوز دخولهم والحال ما ذكر؟ جزاكم الله خيرًا.","title":"حكم دخول الأجانب على المرأة مع وجود ولدها المقارب للبلوغ","answer":"الجواب:  نعم هذا ما يمنع الخلوة، هذا رجال قد قارب الاحتلام، هذا يمنع الخلوة إذا دخل الداخل أجنبيًا كأخ الزوج، أو عم الزوج، والولد عندك؛ فلا بأس، مع الحذر من نزغات الشيطان، مع الحذر من نزغات الشيطان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10326/حكم-دخول-الاجانب-على-المراة-مع-وجود-ولدها-المقارب-للبلوغ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_439/43910.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12154,"question":"أيضًا تقول عن والدها هذا: إنه لم يسمح لهن بالاحتجاب عن زوج الأخت، وعن ابن العم؛ بحجة أنهم من المحارم، وقد وضحنا له ذلك، وقلنا: ليسوا من المحارم، فغضب علينا غضبًا شديدًا، ولاسيما وأننا دائمًا نستمع إلى هذا البرنامج، وننقل إليه ما نسمع، لكنه غير مقتنع، فما هو توجيهكم لنا تجاه والدنا ذلكم؟ جزاكم الله خيرًا.","title":"هل زوج الأخت وابن العم من المحارم؟","answer":"الجواب:  زوج الأخت ليس محرمًا، إلا أن تكون هناك رضاعة بينه وبين البقية، وإلا ليس محرمًا؛ لأن زوج الأخت ليس محرمًا، لكن لو كان بينه وبين أخواتها رضاعة شرعية؛ صرن محارم له، دون زوجته. المقصود: أن زوج الأخت، وزوج العمة، وزوج الخالة ليسوا محارم، المحرم زوج الأم، زوج البنت، زوج الجدة، زوج بنت البنت، بنت الابن هذا محرم، أما زوج الأخت، وزوج الخالة، وزوج العمة، وزوج بنت العمة هذا ليس محرمًا. وهكذا ابن العم ليس محرمًا، لا، ابن العم وابن الخالة ليسا محرمًا، أما ابن الأخت هذا محرم، ابن الأخت محرم، لأن المرأة خالته، يكون محرمًا، يكون محرمًا لها، وهكذا ابن أخيها تكون عمته محرمًا لها. والواجب على أبيك أن يتقي الله، وأن يساعد على الخير، نسأل الله له الهداية، الواجب عليه أن يتقي الله، وألا يفتي بغير علم، وألا يمنعكن من الحق، فالواجب عليكن التستر والحجاب، ولا يجوز طاعته في المعصية، يقول النبي ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق. فالواجب عليكن طاعة الله ورسوله، وليس طاعة الأب، ولا غير الأب في المعصية، فعليكن الاحتجاب من زوج الأخت، ومن ابن العم، ومن ابن الخال، وابن الخالة، إلا أن يكون بينكم وبينه رضاعة، عليكن أن تحتجبن عنه مثل بقية ..... هذا هو الواجب، الله يقول -جل وعلا- في كتابه العظيم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] الآية من سورة الأحزاب، ويقول سبحانه في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] والبعولة: الأزواج إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ [النور:31] هؤلاء المحارم، وهكذا الأخوال والخالات مما ذكرت في النور أيضًا من آخرها. المقصود: أن المحارم لا بأس بأن تكشف لهن المرأة، تكشف عن وجهها، عن يديها، عن قدميها؛ لا بأس بهذا، والحشمة للبقية أحسن وأحوط، الحشمة للرأس ونحوه، حتى لا تقع فتنة، وإلا محرمها لو رأى رأسها، أو رأى صدرها؛ ما يضر، لكن إذا كانت محتشمة، إنما تبدي وجهها وكفيها، فيكون هذا أفضل وأحوط وأحسن، وأبعد عن الشر. المقصود: أن زوج الأخت ليس محرمًا، وابن العم ليس محرمًا وابن الخالة ليس محرمًا، وابن العمة ليس محرمًا، وهكذا الجار ليس محرمًا، الجيران ليسوا محارم إلا إذا كانوا من أقارب المحارم، أخولًا أو أعمامًا أو أخوة أو أزواجًا، أو آباء، أزواجًا أو ما أشبه ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، كيف يقابلن غضب الوالد ذلكم، جزاكم الله خيرًا؟ الشيخ: الواجب على كل حال المخاطبة الطيبة، والرفق به، وأن يكلم مثلًا الطيب، يخبرنه بالفتاوى التي تنشر من طريق نور على الدرب، أو من طريق فتوى أهل العلم، حتى يتبين له الصواب، وإذا تيسر أن بعض أهل العلم ممن تعرفون تقلن له: ينصحه، ويتصل به، ولد من طريق الهاتف، أو من طريق المكاتبة؛ لا بأس، أو تنصحونه يسمع \"نور على الدرب\" يسمع الشريط الذي فيه هذه المسائل؛ لعل الله يهديه.  المقصود: أن الواجب عليكن الرفق، والكلام الطيب مع الوالد، حقه كبير، وإن أساء إليكن؛ فعليكن أنتن بالكلام الطيب، والرفق، والسيرة الحميدة مع الوالد، ومع الوالدة، أبدًا دائمًا دائمًا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، لكن لا يطعنه في الكشف على غير المحارم؟ الشيخ: لا يطاع الأب، ولا الأم، ولا غيرهما في المعصية، لا في هذا، ولا في غيره: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10339/هل-زوج-الاخت-وابن-العم-من-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_441/44104.mp3","categories":["قضايا المرأة","بر الوالدين","النظر والخلوة والاختلاط"]},{"id":12225,"question":"نعود مع مطلع هذه الحلقة إلى رسالة إحدى الأخوات المستمعات تقول في نهايتها أختكم في الله نالة العسيري من الطائف، أختنا نالة عرضنا بعض أسئلة لها في حلقة مضت، وفي هذه الحلقة لا زال لها جمع من الأسئلة، تسأل في أحدها وتقول: ما حكم النظر إلى الرجال، ونظر الرجال إلى النساء، حيث ورد في تفسير ابن كثير أنه يجوز النظر بغير شهوة، كما ثبت في الصحيح أن الرسول ﷺ جعل ينظر إلى الحبشة وهم يلعبون بحرابهم يوم العيد في المسجد، وعائشة أم المؤمنين وراءه تنظر إليهم، وهو يسترها حتى تعبت، ثم رجعت، وقد سمعت أن ذلك محرم، أرشدونا إلى الصحيح جزاكم الله خيرًا.","title":"حكم نظر المرأة إلى الرجال","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فقد أمر الله -جل وعلا- عباده المؤمنين بغض الأبصار، وأمر أيضًا المؤمنات بغض البصر، قال -جل وعلا- قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ ۝ وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ [النور:30-31].  فغض البصر مطلوب، وإذا رأت المرأة الرجال من غير شهوة؛ فلا حرج في ذلك، كما تنظر إليهم في الأسواق، وفي المساجد؛ لا حرج في ذلك، لكن كونها تغض البصر احتياطًا حتى لا تقع الشهوة، وحتى لا تقع الفتنة هذا مطلوب عند الحاجة إليه. أما إذا كان النظر ليس معه شهوة، كنظرها في الأسواق، النظر العادي، وفي المسجد إذا دخلت المسجد تصلي مع الناس، النظر العادي، أو للاعبين مثلما نظرت عائشة للحبشة من غير شهوة؛ فلا حرج في ذلك، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10413/حكم-نظر-المراة-الى-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_447/44701.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12236,"question":"رسالة وصلت إلى البرنامج من مكة المكرمة، وباعثتها إحدى الأخوات من هناك، سمت نفسها أم عبدالله من مكة، أختنا أم عبدالله تقول في أحد أسئلتها: امرأة تسأل عن حكم ركوبها مع السائق الأجنبي منفردة لقضاء أغراض أسرتها، فزوجها كبير في السن، وأبناؤها مشغولون بالدراسة، أو بحياتهم الخاصة، وهي تذهب معه داخل المدينة، وقد تخرج معه لضاحية قريبة من المدينة حوالي عشرة كيلو مترًا لمتابعة شؤون دار تعمرها هناك، وضحوا لها الحكم، جزاكم الله خيرًا.","title":"حكم ركوب المرأة مع سائق أجنبي","answer":"الجواب:  لا يجوز للمرأة أن تخرج مع السائق لا في داخل البلد، ولا في ضاحية البلد؛ لأن هذا خلوة، والخلوة محرمة، والرسول ﷺ يقول: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما ويقول ﷺ: لا يخلون رجل بامرأة إلا ومعها ذو محرم فلا يجوز لها أن تذهب مع السائق؛ لأن هذا فيه خطر عظيم، وربما خانها السائق، وربما فعل منكرًا. فالمقصود أنه لا يجوز، ولو كان السائق من خير الناس، ومن أصلح الناس، فإنه لا يجوز لها أن تذهب معه وحدها، بل لابد يكون معها ثالث، إما زوجة السائق، أو أمه، أو أمها هي، أو أختها، أو إحدى جاراتها، أو أحد جيرانها، لابد يكون معهم ثالث؛ لأنها في هذه الحالة لا يكون الشيطان ثالثهما، إذا كان معهم ثالث ما كان الشيطان ثالثهما، الرسول ﷺ يقول: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما يعني يزين لهما الفاحشة. فالواجب الحذر، وألا تخرج أبدًا إلا ومعها ثالث، أو ثالث ورابع، ولو تعطلت حاجتها، لا تخرج مع السائق أبدًا، لا لمدرسة، ولا للمحكمة، ولا للسوق، ولا لغير ذلك، كل هذا منكر، وفيه خطر عظيم، نسأل الله للجميع الهداية والسلامة، نعم. المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10424/حكم-ركوب-المراة-مع-ساىق-اجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_447/44712.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12278,"question":"من مرسى مطروح في جمهورية مصر العربية رسالة بعث بها مستمع من هناك، رمز إلى اسمه بالحروف (ع. ع) يقول: من العادات والتقاليد عندنا أن يظل الابن أو الأبناء مع والدهم في مسكن واحد حتى ولو تزوج الأبناء، ولو كانت حالتهم المادية تسمح بغير ذلك، سكنت في سكن مستقل عن والدي وشقيقي؛ فغضب والدي كثيرًا وكان الدافع لذلك هو الآتي: أنني تزوجت والمنزل لا يتسع لثلاث أسر في آن واحد، رفضي لبعض العادات كالأكل المختلط، وكشف الزوجة لأخي زوجها، فهل علي إثم في هذا؟ وهل البقاء مع الوالد في سكن واحد أمر يحتمه الشرع، ويخطئ تاركه؟ أرجو الإفادة والتوجيه، جزاكم الله خيرًا.","title":"حكم من ترك السكن مع والده لضيق المنزل والاختلاط","answer":"الجواب:  إذا كان الواقع هو ما ذكرت من الضيق، والتحرج من وجود العادة السيئة في الاختلاط في الأكل من غير تستر؛ فأنت مصيب بهذا، ولا حرج عليك، والواجب على أبيك ألا يغضب، وأن يرضى بما شرع الله، والرسول  يقول: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق والله يقول في كتابه العظيم: وَلا يَعْصِينَكَ فِي مَعْرُوفٍ [الممتحنة:12] النبي ﷺ. فإذا كان الحال ما ذكرت من الضيق، والعادة السيئة في الاختلاط، والكشف؛ فأنت معذور في انفرادك في بيت مستقل، والواجب على أبيك ألا يغضب وألا يزعل، والواجب عليك أنت أن تأخذ بالحق، وأن تستقيم عليه، ولو لم يرض والدك، أو والدتك، أو غيرهما، فالحق أحق بالاتباع والطاعة إنما تكون في المعروف، لا في المعصية، وعلى الوالد أن يسمح، وأن يرضخ للحق. وعليك أن تستعمل الأسلوب الحسن الطيب مع والدك، بالكلام الطيب والأسلوب الحسن، وتقول له: يا والدي! سامحك الله هذا شيء واجب علي، وأنا فعلته من أجل الدين، ومثلك يعينني على الخير، وهكذا أخوك يعينك على الخير، وليس الجلوس مع الوالد في بيت واحد متحتمًا حتى ولو كان واسعًا، فكيف إذا كان ضيقًا؟!  فالواجب على الولد، وعلى كل إنسان أن يعمل ما هو أصلح في دينه، فإذا كان بقاؤه مع قوم يضره في دينه، ولو أنه أبوه؛ فليس له البقاء معهم، ولو مع أبيه وأمه، يجب عليه أن يسعى في سلامة دينه، والأخذ بما يرضي الله عنه، وإن غضب أبوه وأمه، إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق. والواجب على الأب والأم أن يرضيا بالحق، وألا يغضبا لأنفسهما، وعليهما أن يتقبلا الحق ممن جاء به، وأن يسألا أهل العلم عما أشكل عليهما؛ حتى يدلهما أهل العلم على ما شرع الله في ذلك، نسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10478/حكم-من-ترك-السكن-مع-والده-لضيق-المنزل-والاختلاط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_451/45103.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12296,"question":"تقول: لدينا من التقاليد بحيث أن أهل العروس مثل والده وإخوته وعمه أو خاله يحضرون معه ليلة الزفاف لأخذ العروسة من بيت أهلها، ويدخلون عليها وهي في أكمل زينتها، فماذا عليها في ذلك، علمًا بأن هذا عندهم هو شيء مشرف لأهل العروسين؟","title":"حكم كشف المرأة ليلة الزفاف زينتها أمام أقارب الزوج","answer":"الجواب:  إذا كان الزوج ليس معه إلا أبوه أو ولده أو جده؛ فلا بأس؛ لأنهم محارم للزوجة، فلا بأس أن يروها، أما إذا كان معه غيرهم معه إخوة، أو أصدقاء، فالواجب عليك أن تكوني محتجبة، على الزوجة الواجب أن تكون محتجبة حتى يخرج هؤلاء ويبقى الزوج، لا تكشف لهم عن زينتها وجمالها عن وجهها أو شعرها، ولكن تكون مستورة محتجبة، فإذا خرج غير المحارم؛ فالحمد لله تكشف لأبي زوجها، أو لجده، أو لولده هؤلاء محارم، ولا يجوز أن ترضى بهذه العادة وتكشف عن زينتها وجمالها لهؤلاء الذين مع الزوج ليلة الزفاف، والله يقول سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ أَوْ نِسَائِهِنَّ [النور:31] الآية. فأخو الزوج ليس محرمًا، وهكذا عمه، وهكذا جيرانه، وهكذا أزواج أخواته فليسوا محارم، والعادة المخالفة للشرع لا يجوز الرضا بها، ولا الخضوع لها، فعلى المرأة المزوجة وقت الزفاف إذا كان مع الزوج غير محارمها أن لا تكشف لهم حتى يخرجوا. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10496/حكم-كشف-المراة-ليلة-الزفاف-زينتها-امام-اقارب-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45302.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12339,"question":"رسالة وصلت إلى البرنامج من المستمع (م. ع. الجعفري) من اليمن يقول في رسالته: هل يصح لزوجة عمي والد زوجتي وهي ليست والدة زوجتي، بل زوجة أبيها، هل يصح لها أن تجلس وتتحدث معي وهي كاشفة الوجه، أم لا؟ أرجو الإفادة، جزاكم الله خيرًا.","title":"حكم الجلوس مع زوجة أبي الزوجة","answer":"الجواب:  ليست محرمًا لك، ليس لها ذلك، ليس لك أن تخلو بها، وليس لها أن تكشف لك؛ لأنها ليست محرمًا لك، المحرم أم الزوجة، وجدتها، أما زوجة أبيها فليست محرمًا لك، فالواجب أن تنصحها، وتبين لها الحكم الشرعي؛ حتى تحتجب عنك، ولا تخلو بها أيضًا، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10539/حكم-الجلوس-مع-زوجة-ابي-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_454/45410.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12383,"question":"يقول: أمي تذهب إلى المقابر مع جمع من النساء، وهذا في كل عام، ويذهبون بالأكل والأطعمة، وما أشبه ذلك، وقد غضبت من هذا العمل، ونصحتها، ولكنها لم تنته، بماذا توجهونني؟ جزاكم الله خيرًا.","title":"حكم زيارة المقابر للنساء","answer":"الجواب:  نوصيك بالاستمرار في النصيحة، وطلب النصيحة من أهل العلم عندكم حتى ينصحوهم، حتى ينصحوا أمك ومن معها، لأن الرسول ﷺ: لعن زائرات القبور فلا يجوز للنساء زيارة القبور، لا في السنة، ولا في أقل من السنة. الرسول ﷺ: لعن زائرات القبور فأنت تنصحهن، وتقول: ليس لهن الزيارة للقبور، ولكن يشرع لهن الدعاء للأموات في بيوتهن، وفي كل مكان، الدعاء طيب، أما زيارة القبور للنساء فهذه منهي عنها، والرسول ﷺ: لعن زائرات القبور فأنت تستمر في النصيحة، وتطلب من إخوانك، أو جيرانك الطيبين، أو بعض أهل العلم الذين عندكم أن ينصحوهن، وأن يبينوا لهن أن ذلك لا يجوز، ولا مانع أن تقرأ عليهن بعض الكتب التي تتحدث ذلك بيان منع الزيارة للنساء، وعندكم كتابي التحقيق والإيضاح لو قرأت عليهن ما ذكرته فيه لعلهن يستجبن لذلك، وكذلك ما يذاع في إذاعة القرآن في هذا البرنامج إذا أسمعتهن إياه؛ لعل الله يهديهن بذلك، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10584/حكم-زيارة-المقابر-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40103.mp3","categories":["زيارة القبور","النظر والخلوة والاختلاط"]},{"id":12396,"question":"هل يجوز كشف الوجه لأخي الزوج؟","title":"حكم كشف المرأة وجهها أمام إخوة زوجها","answer":"الجواب:  أخو الزوج ليس محرمُا، ولا عمه، ولا خاله، المحرم ابنه، وأبوه، وجده، هؤلاء محارم، أما أخوه ليس بمحرم، لا تكشف له، ولا لأخيه، ولا لولد خاله، ولا لعمه، ولا لزوج أختها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10595/حكم-كشف-المراة-وجهها-امام-اخوة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40114.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12449,"question":"يسأل: هل جلوس الزوجة مع زوج أختها في المنزل ومعهم الأولاد، وأختها أيضًا على الأكل، هل هو جائز، أو لا بدون حجاب؟","title":"حكم أكل المرأة مع زوج أختها","answer":"الجواب:  لا يجوز جلوس المرأة مع الأجنبي في الأكل، ولا غيره بدون حجاب، بل يجب أن تحجب، ولا تأكل معه؛ لأن أكلها ما يفضي إلى .... قد يرى وجهها، وقد يرى يدها، فلا ينبغي، ولا يجوز أن تفعل ذلك، بل يكون أكلها وحدها مع النساء والرجال وحدهم، حتى لا تكون هناك فتنة، نعم، ولا رؤية لبعض ما يجب حجبه عن الرجل الأجنبي، ولا شك أن الأكل معه يفضي إلى أن يرى وجهها، أو شيئًا من وجهها، ويرى يدها، كل هذا لا يجوز. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10650/حكم-اكل-المراة-مع-زوج-اختها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_403/40315.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12508,"question":"يسأل سماحتكم عن حكم اختلاط الرجال بالنساء في الزفاف، وكذلك دق الطبول، ويرجو توجيه المسلمين في هذا الموضوع؟","title":"حكم اختلاط النساء بالرجال في الأعراس وغيرها","answer":"الجواب:  لا يجوز اختلاط الرجال بالنساء لا في الأعراس، ولا في غير الأعراس، بل يجب التميز، فإذا دعت الحاجة إلى وجود المرأة في السوق، أو في المسجد مع الناس تكون متسترة، وتكون في معزل عن الرجال، خلف الرجال في الصلاة، وتكون في الأسواق، لهن سوق وحدهن، وإذا دعت الحاجة إلى سوق الرجال لحاجة تكون متسترة غير متبرجة، بعيدة عن أسباب الفتنة لقضاء حاجتها. أما الاختلاط في عرس، أو غيره بالتبرج، أو بالمشاركة في الطبول، أو في غير ذلك، هذا كله منكر لا يجوز، يجب على النساء أن يكن على حدة، والرجال على حدة، إذا دعت الحاجة إلى ذلك كما في الصلاة، كما يصلين خلف الرجال متسترات، بعيدات عن أسباب الفتنة، وعن الطيب، وهكذا في الأسواق يكن لهن سوق وحدهن في حاجاتهن، وإذا دعت الحاجة إلى أن تخرج المرأة إلى السوق سوق الرجال، فلتكن متسترة، بعيدة عن أسباب الفتنة؛ حتى تقضي حاجتها. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10718/حكم-اختلاط-النساء-بالرجال-في-الاعراس-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40712.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12582,"question":"يسأل أخونا سؤالًا آخر فيقول: اختلاط الرجال بالنساء، ومصافحة الرجال والنساء لبعضهم بعضًا، وهم ليسوا من المحارم، بل تجد الرجل يجلس مع زوجة أخيه، ويصافحها، ما حكم الإسلام في ذلك؟ وهل هذا قد يؤدي إلى فتن خطيرة جدًا؟ وما هو الزي الإسلامي الذي يجب على المرأة أن ترتديه؟","title":"حكم اختلاط الرجال بالنساء وما يترتب على ذلك","answer":"الجواب:  لا شك أن اختلاط الرجال بالنساء على وجه ليس فيه حشمة، وليس فيه حجاب من أعظم أسباب الفتنة، وذلك لا يجوز، بل لابد أن يكون النساء محتجبات مستورات بعيدات عن أسباب الفتنة إذا خالطن الرجال لحاجة من الحاجات، أو لشراء متاع، أو لأشباه ذلك، ولا يجوز لها الخلوة بالرجل كابن عمها، أو أخي زوجها، أو زوج أختها، لا يجوز لها الخلوة به؛ لقوله ﷺ: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما. فالواجب على النساء التحجب، والحذر من أسباب الفتنة، وألا يخالطن الرجال مخالطة تحصل بها الفتنة، وأن لا تخلو المرأة بالرجل وأن لا تسافر معه، كل هذا من أسباب الفتنة. وهكذا المصافحة ليس لها أن تصافح الرجل، إلا إذا كان محرمًا لها، كأخيها وعمها؛ لأن المصافحة فيها فتن أيضًا، فليس لها أن تصافح الرجل إلا إذا كان محرمًا لها، كعمها وأخيها، ونحو ذلك، وعند الحاجة إلى الاختلاط بالرجال تكون مستورة، متحجبة، بعيدة عن أسباب الفتنة، حتى تأخذ حاجتها من السوق، ثم تنصرف. يقول الله -جل وعلا- لأزواج نبيه ﷺ: وَقَرْنَ فِي بُيُوتِكُنَّ وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33] معنى قرن، يعني: اقررن في بيوتكم، يعني: الزمن البيوت إلا إذا كان الخروج لحاجة ومصلحة، ثم نهاهن عن التبرج، فقال: وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33].  فالتبرج: هو إظهار المحاسن والمفاتن، هذا هو التبرج، إظهار محاسنها، ومفاتنها بين الرجال، كوجهها، أو شعرها، أو رقبتها، أو يدها وقدمها وصدرها، كل هذا من أسباب الفتنة.  فالواجب أن تكون مستورة متحجبة بعيدة عن أسباب الفتنة، وهكذا التغنج بالقول، والخضوع بالقول يمنع؛ لقوله  في كتابه العظيم: يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32] يعني: مرض الشهوة، فالخضوع بالقول للرجال واللين من أسباب الفتنة، بل يجب أن يكون الصوت معتدلًا، ليس فيه عنف، وليس فيه خضوع، ولكن صوت عادي .... مع الرجال، لا بأس بالصوت مع الرجال، ليس بعورة، وإنما العورة خضوعها، وتغنجها، وتكسرها بصوتها مما قد يطمع الرجال فيها، أما الصوت العادي فلا حرج في ذلك، كان النساء يكلمن النبي ﷺ ويسألنه، ويستفتينه، ويكلمن الصحابة  لا بأس بهذا. نعم.","link":"https://binbaz.org.sa/fatwas/10797/حكم-اختلاط-الرجال-بالنساء-وما-يترتب-على-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_412/41212.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12651,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: (م. ك. م) من محافظة أراك، تقول في رسالتها: كنت صائمة، وجاء صديق أخي وصافحني، بالرغم أني تهربت منه، والله شاهد على هذا، هل علي إعادة الصوم؟","title":"حكم صيام المرأة التي صافحها أجنبي","answer":"الجواب:  المصافحة للأجنبية لا تجوز، يقول النبي ﷺ: إني لا أصافح النساء وقالت عائشة -رضي الله عنها-: والله ما مست يد رسول الله ﷺ يد امرأة قط -يعني: في البيعة- ما كان يبايعهن إلا بالكلام وهو سيد الخلق، وأكملهم إيمانًا.  فهكذا ينبغي للناس أن يتأدبوا بالآداب الشرعية، وألا يصافحوا النساء إلا إذا كانت محرمًا له، كأخته وعمته ونحو ذلك. أما الصوم فلا يبطل بذلك، ولا يفسد بذلك، الصوم صحيح والمصافحة للأجنبي لا تبطل الصوم، سواء كان أخا الزوج، أو زوج الأخت، أو ما أشبه ذلك، لكن لا يجوز، يجب ترك ذلك والحذر منه، إلا إذا كانت حصل منها مَنيٌ عند المصافحة؛ فهذا تقضي اليوم؛ لأن المصافحة نوع من المباشرة، فإذا باشرت الرجل، وحصل منها مَنيٌ عند المباشرة بالمصافحة، أو بالتقبيل من زوجها مثلًا، حصل مَنيٌ منه، أو منها، فإن الصوم يبطل، وعليها القضاء، تمسك ويمسك الرجل، لا يفطر. لكن يقضي إذا باشر امرأته، أو امرأة أجنبية محرمة عليه -والعياذ بالله- ثم حصل المني؛ فإنه يقضي ذلك اليوم مع التوبة، وهكذا المرأة إذا صافحت إنسانًا، أو قبلت زوجها، أو لامسته، أو كررت النظر في إنسان، فأمنت؛ فإن عليها القضاء، هذا الذي عليه عامة أهل العلم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10861/حكم-صيام-المراة-التي-صافحها-اجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45803.mp3","categories":["قضايا المرأة","ما لا يفسد الصيام","النظر والخلوة والاختلاط"]},{"id":12753,"question":"تقول أختنا (م. ص. ع) من الأردن، هل يجوز النوم في بيت أختي إن كان زوجها ابن خالتي، وأنا مع صغار أختي في غرفة لوحدنا أنا وأولاد أختي، هل يجوز ذلك، أو لا؟","title":"حكم مبيت المرأة في بيت زوج أختها","answer":"الجواب:  لا حرج في ذلك إذا لم يكن في ذلك خطر، أما إذا كان هناك خطر بأن زوج أختك متهم، أو تخشين منه الشر؛ فلا تبيتي عندهم، ولا تجلسي عندهم، أما إذا كان المحل آمنًا؛ فلا حرج أن تبيتي في بيت أختك، في غرفة وحدك بلا خلوة، أو مع أولادها إذا دعت الحاجة إلى ذلك. نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10967/حكم-مبيت-المراة-في-بيت-زوج-اختها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41902.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12891,"question":"من السودان المستمع: يوسف محمد علي القائد بعث يسأل ويقول: ما هو قولكم -حفظكم الله- في مصافحة النساء، هل هي حرام، أو مكروهة؟","title":"هل مصافحة الرجال للنساء حرام؟","answer":"الجواب:  الصواب: أنها حرام، وهي أشد من النظر، فإن لمسه ليدها قد تسبب فتنة أكثر من مجرد النظر، كما صرح بهذا بعض أهل العلم، وقد قال ﷺ: إني لا أصافح النساء وهو معروف منزلته من الدين -عليه الصلاة والسلام- وهو أتقى الناس، وأكرم الناس، وأفضل الناس، وأكملهم إيمانًا، ومع هذا لا، قال: لا أصافح النساء وقالت عائشة -رضي الله عنها-: والله ما مست يد رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام. فلا يجوز للرجل أن يصافح الأجنبية، سواء كانت بنت عمه، أو زوجة أخيه، أو أجنبية أخرى، ليس له أن يصافح إلا محرمه، كخالته، وعمته، وابنته لا بأس، المحارم يصافحهن، أما الأجنبية ولو كانت زوجة أخيه، أو أخت زوجته، أو عمتها أو خالتها، لا، لا يصافحها، أما أمها لا بأس، أمها وجدتها محرم، بنتها محرم، إذا كان قد دخل بأمها، بنتها محرم، بنت بنتها، بنت ولدها محرم، إذا كان قد دخل بالأم، أمها، جدتها، جداتها محارم؛ لا بأس أن يصافحهن، أما أختها وعمتها وخالاتها لسن محارم، ليس له أن يصافحهن، وليس له أن يخلو بواحدة منهن، وليس لها أن تكشف له، بل يجب الحذر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11106/هل-مصافحة-الرجال-للنساء-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_467/46706.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12911,"question":"أختنا تقول: أنا أحتجب عن أزواج أخواتي إلا واحدًا تربيت معه، هل يجوز ذلك، ولا سيما إذا كان يصلي بي وبأخواتي، وجهوني حول هذا الموضوع؟ جزاكم الله خيرًا.","title":"حكم تحجب المرأة من زوج أختها الذي تربت معه","answer":"الجواب:  عليك التحجب عن الجميع حتى الذي تربى معك، كونه تربى معك لا يكون محرمًا، فعليك أن تحتجبي من أزواج أخواتك مطلقًا، حتى الذي تربى معك، ولو كان يصلي بكن، تحجبن عنه وقت الصلاة، وهكذا في جميع الأحوال. وليس لك أيضًا الخلوة به وحدكما؛ لأن الخلوة من أسباب الشر، يقول النبي ﷺ: لا يخلون رجل بامرأة، فإن الشيطان ثالثهما ولو كان قد تربى معك، ولو كان زوج أختك، أو زوج عمتك، لا تكشفي له، ولا تحصل خلوة معه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11126/حكم-تحجب-المراة-من-زوج-اختها-الذي-تربت-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46813.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12913,"question":"رسالة وصلت إلى البرنامج من السودان حلفا الجديدة، وباعثها مستمع يقول (محمد. م. د. هـ) الأخ محمد يقول في أحد أسئلته: تزوج والدي امرأة بعد وفاة والدتي -رحمها الله- وهذه المرأة لها بنات، ولكن طلق والدي هذه المرأة، ولم ينجب منها، هل يجوز لنا أن نصافح بناتها، وبنات بناتها؟","title":"حكم الربيبة بالنسبة لأولاد الزوج","answer":"الجواب:  لسن محارمًا لكم، إنما هن محارم لأبيك؛ لأنه زوج أمهن، فهن ربائب، إذا كان قد وطئ أمهن، أما أنتم فهن أجناب، لكم التزوج بهن، لسن أخوات، ولسن ربائب لكم، وإنما هن ربائب لأبيكم. فالحاصل: أن هؤلاء البنات أجنبيات من أولاد الزوج، نعم.","link":"https://binbaz.org.sa/fatwas/11128/حكم-الربيبة-بالنسبة-لاولاد-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46815.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12943,"question":"هذا السائل يوسف حسن يقول: هل يجوز لي أن أصافح امرأة كبيرة في السن، أنا في الثالثة عشر من العمر، أفيدوني بذلك؟","title":"حكم مصافحة المرأة الأجنبية كبيرة السن","answer":"الجواب:  ليس لك أن تصافح النساء، أنت مراهق الآن فلا تصافح النساء، ولو كانت عجوزًا يقول النبي ﷺ: إني لا أصافح النساء وتقول عائشة -رضي الله عنها-: والله ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام والمصافحة فيها خطر؛ لأنها قد تسبب الشهوة والفتنة فهي أعظم من الكلام. فالواجب على الرجل البعد عن المصافحة، لا مع شابة، ولا مع عجوز، لا يصافح، لكن يكلم من دون مصافحة، إذا كانت المرأة غير محرم له. أما إذا كانت أخته، أو عمته أو زوجته لا بأس، لكن إذا كانت أجنبية كزوجة أخيه، أو بنت عمه، أو إحدى جيرانه؛ يكلمها كلامًا من دون مصافحة، مع الحجاب، وعدم الخلوة.","link":"https://binbaz.org.sa/fatwas/11159/حكم-مصافحة-المراة-الاجنبية-كبيرة-السن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50203.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":12951,"question":"السائلة من أسئلتها تقول: هل يجوز للمرأة أن تعمل في مكان قريب من المنزل، وهذا المكان يوجد فيه رجل، أو أكثر، وليس معها محرم، فهل هذا الاختلاط وهذا العمل للضرورة جائز؟","title":"حكم عمل المرأة في مكان فيه اختلاط","answer":"الجواب:  إذا كانت تعمل مع النساء؛ فلا يضرها وجود رجل في البيت، أما تختلط بالرجال، لا، لكن إذا كانت تعمل مع النساء في محل ليس فيه اختلاط بالرجال، ولا فتنة؛ فلا حرج، ولو كان في البيت، أو في القصر، أو في المبسط ... إذا كانت في محل بعيد عنهم، ما فيه اختلاط بالرجل، النساء في جهة، والرجال في جهة، أو الرجل في جهة، أما تعمل معه جنبًا إلى جنب، وليس محرمًا لها؛ لا يجوز؛ لأن هذا من أسباب الفتنة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11168/حكم-عمل-المراة-في-مكان-فيه-اختلاط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50210.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":12979,"question":"من الجمهورية العراقية رسالة وصلت إلى البرنامج بتوقيع إحدى المستمعات من هناك تقول: أختكم (ش. م) لها جمع من الأسئلة، من بينها سؤال يقول: ما حكم الشرع في خروج المرأة للعمل، وكسب الرزق، ومخالطتها للرجال، والتحدث لهم بحكم طبيعة عملها، مع العلم أنها ملتزمة، ومحجبة، وتعرف حدود الله؟","title":"حكم عمل المرأة في أماكن الاختلاط بالرجال","answer":"الجواب:  لا بأس أن تخرج للعمل تطلب الرزق في المكاسب المباحة، في محلات النساء، أو في محلات منفردة، ليس فيها خطر، كل هذا لا بأس به، خياطة، أو طبيبة، أو غير ذلك من الأعمال، الله -جل وعلا- شرع لنا طلب الرزق، وقال النبي ﷺ: احرص على ما ينفعك، واستعن بالله الإنسان مأمور أن يطلب الرزق، الله يقول: فَابْتَغُوا عِنْدَ اللَّهِ الرِّزْقَ وَاعْبُدُوهُ [العنكبوت:17] والنبي  يقول: احرص على ما ينفعك، واستعن بالله، ولا تعجزن هذا يعم الرجال والنساء. لكن لا يجوز لها أن تكون في محل فيه خطورة بين الرجال، أو في محل لا تأمن فيه بسبب ما حولها من الرجال؛ لأنهم يتهمون بالتسلط عليها، لا تخاطر بنفسها تكون في محل آمن لا بأس، أما بين الرجال في عملهم بحيث تختلط بهم، وتتصل بهم؛ فهذا لا يجوز؛ لأن وجودها معهم فتنة، ولو مع الاحتجاب، لأن المماسة والمخالطة والمجالسة الدائمة والكثيرة سبب للشر. فإذا كانت في محل خاص، أو في عمل نسائي مع النساء؛ فلا بأس، أما كونها مع المدرسين مدرسة مع المدرسين، أو عاملة مع العمال تذهب معهم، وتجيء معهم، وتنقل معهم الحجر، أو اللبن، وتخالطهم في ذهابهم وإيابهم؛ فهذا فيه خطر عليها. فالواجب الحذر من ذلك؛ لأن هذه المخالطة قد تفضي إلى فتنة، والرسول ﷺ أمرها بأن تبتعد عن أسباب الفتنة، نهى عن الخلوة -عليه الصلاة والسلام- ونهى عن التبرج، والمخالطة قد تدعو إلى خلوة، وقد تدعو إلى تبرج، وإبداء بعض الزينة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11196/حكم-عمل-المراة-في-اماكن-الاختلاط-بالرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_470/47010.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":13001,"question":"تقول هذه السائلة: هل يجوز الكشف عند أبي الزوج من الرضاعة، وهل هو من المحارم؟","title":"حكم كشف المرأة عند أب الزوج من الرضاعة","answer":"الجواب:  نعم، أبو الزوج من الرضاعة محرم، كأبيه من النسب، وهكذا ابنه من الرضاعة محرم، نعم.","link":"https://binbaz.org.sa/fatwas/11218/حكم-كشف-المراة-عند-اب-الزوج-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_504/50414.mp3","categories":["النظر والخلوة والاختلاط","المحرمات من النساء","قضايا المرأة"]},{"id":13009,"question":"من المملكة الأردنية الهاشمية عمان الوحدات رسالة بعثت بها إحدى الأخوات، وقعت في نهاية الرسالة بقولها: مستمعة من الأردن، تقول في رسالتها: هل يجوز كشف الوجه أمام ابن العم والأقارب من غير المحارم، مثل زوج الأخت، وابن الخال، وأخو الزوج، وغيرهم؟","title":"حكم كشف المرأة وجهها لغير المحرم","answer":"الجواب:  ليس للمرأة الكشف لهؤلاء؛ لأن زوج الأخت، وأخا الزوج، وابن العم، وابن الخال، وأشباههم كلهم ليسوا محارم، كلهم في حكم الأجنبي، فليس لها أن تكشف لهؤلاء، ولكن تكلمهم، وتسلم عليهم من دون كشف ،ولا مصافحة، حياك الله يا فلان، السلام عليكم.. وعليكم السلام.. كيف حالك.. كيف أهلك.. كيف أولادك.. وما أشبه ذلك، من دون أن تصافح، ومن دون أن تكشف؛ لأن أعظم زينة المرأة وجهها، هو أعظم الزينة، والله يقول -جل وعلا- في كتابه العظيم:  وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53].  ويقول سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31] البعولة: الأزواج أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ أَوْ نِسَائِهِنَّ [النور:31] وليس أخو الزوج، ولا زوج الأخت من هؤلاء، وليس ابن العم، وليس ابن الخال من هؤلاء، وليس الصديق من هؤلاء، الواجب على المرأة أن تحذر ما حرم الله عليها، وأن تبتعد عن أسباب الفتنة، وألا تطيع الزوج فيما حرم الله، ولو تساهل الزوج، عليها أن تسعى لخلاص ذمتها، وبراءة دينها من الوقوع فيما حرم الله؛ لأن الرسول  قال: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق. فلا مانع من السلام من دون مصافحة، ومن دون كشف، كذلك لا تجوز الخلوة، لا تجلس مع أخي زوجها وحدهما، ولا مع زوج أختها وحدهما؛ لقول النبي ﷺ: لا يخلون رجل بامرأة فإن الشيطان ثالثهما فالواجب الحذر، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11226/حكم-كشف-المراة-وجهها-لغير-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47105.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":13021,"question":"مع مطلع هذه الحلقة نعود إلى رسالة الأخوات من الجمهورية اليمنية (أ. و. ن. د. الأحمدي)، الأخوات عرضنا بعض أسئلتهن في حلقة مضت، وفي هذه الحلقة لهن سؤالان.السؤال الأول يقول: ما حكم جلوس الفتاة المسلمة مع أبناء عمها في وجود الأهل ولباسها للحجاب الشرعي مع كشف الوجه فقط؟","title":"حكم جلوس المرأة مع أقاربها غير المحارم مكشوفة الوجه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فلا حرج في جلوس المرأة مع بني عمها، وأقاربها في المجلس الذي يجتمعون فيه لشرب القهوة، أو الشاي، أو نحو ذلك، لكن بشرط الحشمة، والحجاب، وعدم الفتنة، ومن الحجاب: ستر الوجه، وعدم كشفه، هذا لا بأس به إذا كانوا جماعة، أما مع الواحد فلا؛ لقوله ﷺ: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما فليس لها أن تخلو بواحد من بني عمها، أو غيرهم من غير محارمها. لكن إذا جلست مع جماعة مع أهلها، أو مع أزواج أخواتها، أو إخوة زوجها، محتشمة، بعيدة عن الفتنة، متسترة مخمرة وجهها، وبدنها؛ فلا حرج في ذلك لتناول السلام بينهم، والحديث بينهم فيما يهمهم من غير إبداء شيء من الزينة، ومن غير إبداء شيء مما يضر من الكلام السيء الذي يوجب الفتنة، فالحديث العادي الذي لا حرج فيه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11238/حكم-جلوس-المراة-مع-اقاربها-غير-المحارم-مكشوفة-الوجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47201.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":13055,"question":"السائلة أمل محمد دولة الكويت تقول: أرجو من فضيلة الشيخ عبدالعزيز أن يرد على سؤالي، السائلة طالبة جامعية تبلغ المسافة بين الجامعة، وبيتهم حوالي نصف ساعة، أو أقل بقليل، دائمًا تذهب مع والدتها مع السائق، فبعض الأحيان يتعذر على والدتها أن تذهب معها، وذلك لظروف، تقول السائلة: هل يجوز أن أذهب لوحدي مع السائق علمًا بأن الطريق يكون في الصباح مزدحمًا بالناس، فهل يجوز ذلك، أم لا، جزاكم الله خيرًا؟","title":"حكم خروج المرأة مع السائق من دون محرم","answer":"الجواب:  لا يجوز؛ لأن هذه خلوة وخطر، لا يجوز لقول النبي ﷺ: لا يخلون رجل بامرأة فإن الشيطان ثالثهما لا يجوز لك أن تذهبي مع السائق لا للمدرسة، ولا غيرها وحدك، لا بد معكما ثالث أو رابع؛ لئلا يتهم، أما وحدك فلا يجوز، نعم.","link":"https://binbaz.org.sa/fatwas/11272/حكم-خروج-المراة-مع-الساىق-من-دون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50515.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":13056,"question":"في سؤالها الثاني والأخير تقول: هناك أحاديث تؤكد جواز كشف المرأة عن وجهها بدون تزين، فهل يجوز للمرأة أن تكشف وجهها، أم أن تغطيه؟ مع أن هناك أناس أجازوا ذلك، وجزاكم الله خيرًا.","title":"حكم كشف المرأة وجهها أمام الأجانب","answer":"الجواب:  الواجب الحجاب على المرأة عند وجود الأجنبي؛ لقول الله : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فلابد من الحجاب، لكن المحرمة لا تلبس النقاب المصنوع للوجه البرقع أو النقاب المصنوع للوجه، ولكن تغطي وجهها بالخمار ونحوه من الأشياء العامة التي تسدل على الوجه. ووجه المرأة زينتها، والله يقول: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] .. الآية، والوجه هو أعظم الزينة؛ فالواجب ستره إلا من المحرم في جميع الأحوال، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11273/حكم-كشف-المراة-وجهها-امام-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50516.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":13068,"question":"سماحة الشيخ! كثر السؤال عن مصافحة المرأة للرجل، أو العكس، وأختنا سعدية تسأل أيضًا؟","title":"حكم مصافحة المرأة للرجل الأجنبي","answer":"الجواب:  تقدم في هذا البرنامج غير مرة الجواب عن هذا، وأنه لا يجوز للمرأة أن تصافح الرجال غير محارمها، غير محارمها، وليس للرجل أن يصافح غير محرمه، أما المحرم كأخته وعمته؛ فلا بأس. أما المرأة كونها تصافح الرجل الأجنبي، كابن عمها، أو أخي زوجها، أو زوج أختها هذا لا يجوز، ولو من دون حائل، يقول النبي ﷺ: إني لا أصافح النساء وتقول عائشة -رضي الله عنها-: والله ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام -عليه الصلاة والسلام- وما ذاك إلا لأنهن فتنة؛ ولأن مصافحتهن وسيلة إلى الافتتان بهن، فإن لمسك كفها، ومعرفة حال كفها قد يجر إلى فتنة حتى قال بعض أهل العلم: إن ذلك أضر وأخطر من النظر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11284/حكم-مصافحة-المراة-للرجل-الاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_473/47304.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":13474,"question":"سؤال آخر تقول: ما رأيكم في هذا العمل، وهو أن بعض الناس عندما يتزوج ابنهم يعملون له ما يسمونه بالحناء، ويكون في ليلة قبل الزفاف، ويأتي بعض الرجال والنساء إلى بيت العريس، ويجلسون العريس في الوسط، فيأخذون ويعطونه الفلوس، وبعد هذا العمل تقوم أم العريس، وتعمل له الحناء في يديه، وجهونا ووجهوهم مأجورين، جزاكم الله خيرًا؟","title":"حكم الحناء للرجال والاختلاط في الأعراس","answer":"الجواب: الحناء من خصائص النساء، من زينة النساء، فلا يجوز أن يستعمل مع العريس، ولا مع غيره من الرجال، الحناء من زينة النساء، ومما يعمله النساء، تجملًا لأزواجهن، فلا يجوز أن يعامل الرجل بذلك، ولا أن يستعمله الرجل، بل ينبغي أن يبتعد .. بل يجب أن يبتعد عن مشابهة النساء، وقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: لعن الله الرجل يلبس لبسة المرأة، ولعن الله المرأة تلبس لبسة الرجل وجاء عنه ﷺ: أنه لعن المتشبهين من الرجال بالنساء، والمتشبهات من النساء بالرجال وهذا يعم أنواع التشبه. فالواجب الحذر من التشبه بالنساء في استعمال العريس الحناء، أو غير ذلك، مما هو من خصائص النساء. أما اجتماعهم بالعريس رجالًا، ونساء يعطونه النقود، فهذا فيه تفصيل: اجتماعهم مختلطين، وليسوا محارم فيما بينهم رجال أجنبيات، هذا ما يجوز، اختلاط الرجال مع النساء إلا على وجه فيه الحشمة، والبعد عن أسباب الفتنة، والتستر، والاحتجاب كما يجتمع الناس في بيوتهم، تجتمع المرأة مع أحماء زوجها، ومع أزواج أخواتها، مع التستر والحشمة للتحدث في بعض الأمور لا بأس. أما اختلاط فيه عدم التحجب، وعدم البعد عن أسباب الفتنة هذا لا يجوز. وهكذا لا يجوز الخلوة بالعريس من امرأة أجنبية تخلو به، فلا يجوز أيضًا. أما إعطاؤه النقود.... يساعدونه في الزواج، من باب المساعدة؛ فلا بأس كون أعطوه فلوسًا، أو غير فلوس، من باب التعاون على الخير. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11777/حكم-الحناء-للرجال-والاختلاط-في-الاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47803.mp3","categories":["قضايا المرأة","النظر والخلوة والاختلاط","اللباس والزينة"]},{"id":13576,"question":"هذه السائلة تقول: امرأة ربت طفلًا صغيرًا، وكبر هذا الطفل حتى تزوج، تقول المرأة بأنها تفتش له وتقبله، فهل يعتبر لها محرمًا؟","title":"هل من ربت طفلًا يكون محرمًا لها؟","answer":"الجواب: إذا ربت المرأة صبيًا حتى بلغ الحلم، ولم ترضعه، وإنما أحسنت إليه بالتربية، والكفالة؛ فإنها لا تكون محرمًا له، ولا أمًا له، بل هو أجنبي منها، لا يجوز لها الخلوة به، ولا يجوز له تقبيلها، ولا مصافحتها، ولا كشفها له، بل عليها أن تحتجب، وتعتبره أجنبيًا. لكن السلام والكلام الطيب: كيف حالك؟ كيف أنت؟ والسلام منه عليها، ومكافأتها بالكلام الطيب، والهدية الطيبة والمال، كل هذا طيب، لكن ما تكون محرمًا له، هي أجنبية منه كسائر النساء، وكونها أحسنت إليه، وربته لا يجعلها محرمًا له، المحرمية تكون إما بالنسب كأخته، وعمته وخالته، أو بالرضاعة الشرعية خمس رضعات في الحولين، أو بالمصاهرة كونها أم زوجته، أو بنت زوجته المدخول بها، أو جدتها، هذه أسباب تحريمها عليه. أما كونها ربته فإنها لا تحرم بذلك، ولا تكون محرمًا له، ولا يكون محرمًا لها، وعليها أن تحتجب منه، وليس لها أن تخلو به، وليس له أن يقبلها، ولا أن يصافحها كسائر الأجنبيات. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11913/هل-من-ربت-طفلا-يكون-محرما-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_533/53303.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":13584,"question":"هذه السائلة تقول: امرأة ربت طفلًا صغيرًا، وكبر هذا الطفل حتى تزوج، تقول المرأة بأنها تفتش له وتقبله، فهل يعتبر لها محرمًا؟","title":"هل من ربت طفلًا يكون محرمًا لها؟","answer":"الجواب: إذا ربت المرأة صبيًا حتى بلغ الحلم، ولم ترضعه، وإنما أحسنت إليه بالتربية، والكفالة؛ فإنها لا تكون محرمًا له، ولا أمًا له، بل هو أجنبي منها، لا يجوز لها الخلوة به، ولا يجوز له تقبيلها، ولا مصافحتها، ولا كشفها له، بل عليها أن تحتجب، وتعتبره أجنبيًا. لكن السلام والكلام الطيب: كيف حالك؟ كيف أنت؟ والسلام منه عليها، ومكافأتها بالكلام الطيب، والهدية الطيبة والمال، كل هذا طيب، لكن ما تكون محرمًا له، هي أجنبية منه كسائر النساء، وكونها أحسنت إليه، وربته لا يجعلها محرمًا له، المحرمية تكون إما بالنسب كأخته، وعمته وخالته، أو بالرضاعة الشرعية خمس رضعات في الحولين، أو بالمصاهرة كونها أم زوجته، أو بنت زوجته المدخول بها، أو جدتها، هذه أسباب تحريمها عليه. أما كونها ربته فإنها لا تحرم بذلك، ولا تكون محرمًا له، ولا يكون محرمًا لها، وعليها أن تحتجب منه، وليس لها أن تخلو به، وليس له أن يقبلها، ولا أن يصافحها كسائر الأجنبيات. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11913/هل-من-ربت-طفلا-يكون-محرما-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_533/53303.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":13908,"question":"ما حكم كشف زوجة العم على ابن أخي الزوج حتى ولو كان بينهما تفاوت في السن؟","title":"حكم كشف المرأة وجهها لأقارب زوجها","answer":"الجواب: ليس لها الكشف لأخي زوجها ولا عم زوجها ولا ابن عم زوجها ولا ابن أخيه كلهم أجناب، ليس لها أن تكشف إلا للزوج أو أبيه أو جده أو أولاده، أما أخوه وأعمامه وأخواله وأبناء أخيه كلهم أجناب لا تكشف لهم، ولا تخلو بواحد منهم أيضًا هذا لا يجوز، قال الله تعالى: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] البعولة: الأزواج، أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ [النور:31]، أما أخو الزوج لا ليس منهم ولا ابن أخيه ولا عمه ليسوا من هؤلاء، أما أبو الزوج نعم؛ لأنه قال: أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] آباء البعولة: أي: آباء الأزواج، والجد أب فأب الزوج وجد الزوج كلهم محارم من الرضاعة أو من النسب.. سواء من الرضاعة أو من النسب، وهكذا أبناء الزوج من الرضاع أو من النسب محارم أيضًا، وهكذا أبناء بناته محارم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12295/حكم-كشف-المراة-وجهها-لاقارب-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48203.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":13911,"question":"ما حكم كشف زوجة العم على ابن أخي الزوج حتى ولو كان بينهما تفاوت في السن؟","title":"حكم كشف المرأة وجهها لأقارب زوجها","answer":"الجواب: ليس لها الكشف لأخي زوجها ولا عم زوجها ولا ابن عم زوجها ولا ابن أخيه كلهم أجناب، ليس لها أن تكشف إلا للزوج أو أبيه أو جده أو أولاده، أما أخوه وأعمامه وأخواله وأبناء أخيه كلهم أجناب لا تكشف لهم، ولا تخلو بواحد منهم أيضًا هذا لا يجوز، قال الله تعالى: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] البعولة: الأزواج، أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ [النور:31]، أما أخو الزوج لا ليس منهم ولا ابن أخيه ولا عمه ليسوا من هؤلاء، أما أبو الزوج نعم؛ لأنه قال: أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] آباء البعولة: أي: آباء الأزواج، والجد أب فأب الزوج وجد الزوج كلهم محارم من الرضاعة أو من النسب.. سواء من الرضاعة أو من النسب، وهكذا أبناء الزوج من الرضاع أو من النسب محارم أيضًا، وهكذا أبناء بناته محارم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12295/حكم-كشف-المراة-وجهها-لاقارب-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48203.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":14204,"question":"السائل من الجزائر يقول: المرأة عندما تكون متحجبة إذا رآها رجل غريب من غير قصد هل يعتبر هذا حرام؟","title":"حكم النظر إلى المرأة من غير قصد","answer":"الجواب: إذا كان من غير قصد لا شيء عليه، الله يعفو سبحانه عن ما لم يتعمد الإنسان.. لما سأله علي  عن نظر الفجأة؟ فقال عليه الصلاة والسلام: اصرف بصرك، فإنما لك الأولى وليس لك الثانية فإذا صادف المرأة ونظر إليها صدفة فجأة يصرف بصره عنها، لا يتابع النظرة النظرة.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12652/حكم-النظر-الى-المراة-من-غير-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54805.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":14330,"question":"السائل (ج. س) من جمهورية مصر العربية شمال سيناء يقول: أنا شاب أبلغ من العمر الثامنة عشرة وأسكن أنا وأخي في بيت واحد، وأخي متزوج وأنا غير متزوج، وزوجة أخي تقوم بأعمال وأشغال البيت، وتقوم بخدمتنا، فهل يجوز لي أن أجالسها وأن أتحدث معها، وقد سألت البعض من الناس فقالوا: لا يجوز، وجهونا في ذلك؟","title":"حكم التحدث والخلوة بزوجة الأخ","answer":"الجواب: ليس لك الخلوة بزوجة أخيك، أما التحدث معها بحضور أخيك أو بحضور شخص آخر فلا بأس؛ لقول النبي ﷺ: لا يخلون رجل بامرأة فإن الشيطان ثالثهما فليس لك أن تخلو بها وحدك ولكن مع أخيك أو مع أمها أو أختها أو خالتها أو أختك أو أمك أو نحوها لا بأس، تزول الخلوة ويزول المحذور. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12805/حكم-التحدث-والخلوة-بزوجة-الاخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55013.mp3","categories":["النظر والخلوة والاختلاط","نصائح وتوجيهات"]},{"id":14530,"question":"تسأل أيضًا وتقول: هل عملي في المؤسسة حرام أم حلال؟ مع العلم بأني متزوجة ولدي ثلاثة أطفال، ولكن راتب زوجي لا يكفي لسد حاجتنا الضرورية.","title":"ما حكم عمل المرأة في مكان مختلط؟","answer":"الجواب: أما عملك في المؤسسة بين الرجال فلا يجوز؛ لأن ذلك يعرضك للفتنة، والخطر العظيم، وقد قال -عليه الصلاة والسلام-: ما تركت بعدي فتنة أضر على الرجال من النساء وقال -عليه الصلاة والسلام-: لا يخلون رجل بامرأة، فإن الشيطان ثالثهما فالواجب عليك البعد عن المؤسسة التي فيها الاختلاط، أما في مكان وحدك أو مع النساء فلا بأس بذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13031/ما-حكم-عمل-المراة-في-مكان-مختلط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_634/nour_63413.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":14586,"question":"أحد المستمعين رمز إلى اسمه بالحروف (هـ. أ. د. ي) يسأل سؤال يقول: أنا متحمل شؤون بعض الأسر لكون آبائهم مهاجرين، وأسأل: هل لي أن أختلط بهم أو لا؟الشيخ: أعد سؤاله.المقدم: يقول: إنه متحمل لشؤون بعض الأسر، نظرًا لأن آباءهم من المهاجرين، فهل لي أن أختلط بهم أو لا؟","title":"حكم الاختلاط ببعض الأسر بسبب تحمل شؤونها","answer":"الجواب: الاختلاط فيه تفصيل:  فالاختلاط الذي مع الرجال، مع الأطفال الصغار، لحاجاتهم لا بأس به، أما الاختلاط بالنساء فهذا يحتاج إلى:\nأولًا: عدم الخلوة بواحدة منهن، لا تجوز الخلوة بواحدة منهن إذا كانت غير محرم، أما المحرم كخالتك وعمتك لا بأس، أما إذا كان غير محرم لا يجوز لك الخلوة بها. ثانيًا: ليس لك أن تختلط بهن وهن سافرات أو غير متحجبات أو غير معتنية بالستر، بل عليك أن تغض بصرك وترشدهن إلى الستر الواجب والحجاب الواجب، فإذا كن متحجبات مستورات فلا بأس أن تجلس معهن لحاجة، كنصيحة أو سؤالهم عن حاجة من حاجات البيت، أو ما أشبه ذلك مع غض البصر عما قد يبدو من نقص واحدة ومن عدم ضبطها مع النصيحة لمن قصرت حتى تكون كاملة الحجاب، وعليك أن لا تخل بواحدة منهن لقول النبي ﷺ: لا يخلون رجل بامرأة إلا ومعها ذو محرم وقوله : لا يخلون رجل بامرأة فإن الشيطان ثالثهما هذا تفصيل هذا الكلام الذي ذكرت وسألت عنه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13083/حكم-الاختلاط-ببعض-الاسر-بسبب-تحمل-شوونها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_635/nour_63506.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":14684,"question":"تقول السائلة في آخر أسئلتها: هل يجوز ضرب الدف قبل يوم الزواج أو بعده؟ علماً بأنني سمعت بأنه لا يضرب إلا في يوم الزفاف فقط.","title":"حكم ضرب الدف للنساء قبل الزواج وبعده","answer":"الجواب: السنة أن يضرب في الزفاف ليلة الزفاف، هذا هو السنة، وهكذا للجواري أيام العيد لا بأس، أما غيره فتركه أحوط، تركه الأحوط للنساء، إنما السنة ضربه بإعلان النكاح ليلة الزفاف، أو كان في يوم العيد، كما فعله بعض الجواري عند النبي ﷺ، وقال لما أنكر عليهن أبو بكر قال: دعهن فإن لكل قوم عيدًا، وهذا عيدنا أهل الإسلام فدل على أنه يسمح للجواري والنساء بضرب الدف يوم العيد، عيد الفطر عيد النحر، وهكذا في الزواج لإعلان النكاح، أما الطبل لا، لا يستمع للطبل، ولكن الدف ذو الوجه الواحد، نعم.","link":"https://binbaz.org.sa/fatwas/13172/حكم-ضرب-الدف-للنساء-قبل-الزواج-وبعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56011.mp3","categories":["النظر والخلوة والاختلاط","الزفاف ووليمة العرس","الشعر والأغاني"]},{"id":14734,"question":"يقول: اشتريت مزرعة من مالي الخاص، والذي أشقى به في الخارج، وكتبت المزرعة بعقد رسمي باسمي، فهل والدي وإخوتي البنين والبنات لهم حق في هذه المزرعة أم لا؟أفيدوني، أفادكم الله.","title":"هل يحق للوالد أن يأخذ من مال ولده؟","answer":"الجواب: نعم، والدك له حق، له حق أن يأكل منها: أنت ومالك لأبيك يقول النبي ﷺ: أنت ومالك لأبيك ويقول ﷺ: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم فللوالد أن يأكل منها، ويستفيد منها، وله أن يأخذ منها ما لا يضرك، يأخذ منها ما لا يضرك: فاكهة، تمر، حبوب شيء لا يضرك.  أما الذي يضرك ويضر عائلتك لا، لا يأخذ شيئًا يضرك.\nوأما إخوانك وأعمامك لا ليس لهم إلا بإذنك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13228/هل-يحق-للوالد-ان-ياخذ-من-مال-ولده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49007.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":14937,"question":"من جنوب المملكة وردتنا هذه الرسالة من (ع. ص) الغامدي يقول في رسالته: استمعت في إحدى الليالي إلى برنامجكم المحبوب -برنامج نور على الدرب- وكان يجيب عليها أحد المشائخ الأفاضل -وفقهم الله- وذلك حول التحجب، ويقول: أنه محرم على أخ الزوج أن يكشف على زوجة أخيه، ولكن هذه الظاهرة منتشرة في بلادنا الجنوب، ولا يقدر الأخ أن يمنع أخيه من مطالعة زوجته؛ لأنها عادة. أما أن يكون المنزل يسكنه هو وإخوانه ووالده ووالدته، وهذه عادة متصلة من الآباء والأجداد، وعادة قبلية، والرجاء من سماحتكم أن تدلونا إلى الطريق الصحيح. وفقكم الله. والسلام عليكم ورحمة الله وبركاته.","title":"حكم عادة كشف المرأة وجهها لأخي الزوج","answer":"الجواب: العادات التي تخالف الشرع يجب تركها، الرسل -عليهم الصلاة والسلام- إنما عاداهم الناس بالعوائد، عادة الجاهلية يعبدون الأصنام، ويعبدون الأوثان، ويعبدون الأشجار والأحجار، عادوا الرسل بهذا، فالعادات التي تخالف الشرع يجب تركها، ولو كانت قديمة. وليس للزوج أن يسمح لزوجته أن تكشف لأخيه، أو لعمه، أو لابن عمه، لا بل عليها التستر والحجاب؛ لأنه فتنة والوجه من أعظم الفتنة، فعليها التستر ولو كانت عادة، يجب الحجاب، ويجب على أخي الزوج أن لا يرضى بهذا، ما يرضى بالمعصية، يجب عليه غض البصر، وأن يساعد أخاه على تحجب المرأة، وأن تتحجب عن أخيه، وعن عمه وعن ابن عمه وعن خاله وابن خاله. وهكذا زوج الأخت، لا تكشف له أخت زوجته، بل تحجب عنه، وهو لا ينظر إليها، بل يغض البصر، ولا يرضى بأن تكشف له؛ لأن المسلمين مأمورون بالتعاون على البر والتقوى، مأمورون بالأمر بالمعروف والنهي عن المنكر، فالرجل ينهى زوجة أخيه أن تكشف له، ويغض بصره، والرجل ينهى أخت زوجته أن تكشف له، ويغض بصره، ويتعاون معهم على البر والتقوى، لا يفرح بالمعاصي، ولا يطالب بأن تكشف له؛ لأن هذا من أسباب الفتن، ولو كان عادات قديمة، فالعادات يعالجها الشرع، والشرع يحكمها، ولا تحكم الشرع هي، بل الشرع هو الحاكم على الجميع في العادات وغير العادات، نسأل الله للجميع الهداية والتوفيق، نعم.","link":"https://binbaz.org.sa/fatwas/13443/حكم-عادة-كشف-المراة-وجهها-لاخي-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_647/nour_64708.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":15064,"question":"من أسئلة هذه السائلة سماحة الشيخ تذكر وتقول: رجل لديه عمة، وهي ابنة عم أبيه، ليست من العجائز المقعدات، ولا من الشابات الصغيرات، هل يجوز السلام عليها؟","title":"حكم السلام على بنت عم الأب ومصافحتها","answer":"الجواب: يسلم عليها بالكلام، هذه ما تسمى عمة، تسمى بنت عم، هذه ما هي محرمًا له، أجنبية، يسلم عليها بالكلام فقط، لا يصافحها، ولا يقبل رأسها.  أما العمة فهي أخت الأب، العمة هي أخت الأب، وأخت الجد، يقال لها: عمة، أخت أبيه، أو أخت جده، هذه محرم، له أن يصافحها، ويقبل بين عينيها ورأسها. أما بنت العم، وبنت الخال ليست محرمًا له، فليس له مصافحتها، ولا تقبيل رأسها، وليس لها أن تكشف له؛ لأنها أجنبية، بنت عمه، وبنت خاله، نعم.","link":"https://binbaz.org.sa/fatwas/13551/حكم-السلام-على-بنت-عم-الاب-ومصافحتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_563/56313.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":15076,"question":"هذه أيضًا مشكلة عائلية، وسببها الأخ الحمو، يقول مرسلها المراسل فوزي محمد النجار، يقول: عندما عدت إلى بلدي بعد فترة عمل هنا -ويقصد يعني في السعودية بعد عمل ثلاثة عشر شهرًا- وبعد أن جلست فترة قالت لي زوجتي: إن أخوك يحضر إلى هنا، وأنا أقابله بملابس بدون أكمام بحسب كلامها، وقد قلت لها: إن هذا اللباس حرام، ولم أعط الأمر أي اهتمام، ولكن قبل أن أسافر بيومين قال لي صاحب المنزل الذي أسكن فيه: إن أخوك يحضر إلى منزلك الساعة اثنا عشر ليلًا، ولم يزد على ذلك بكلمة، وكان كلامه معي في مكان عام، وكنت مشغول مع والدي وبعض الناس، ومن كثرة مشاغلي بسبب تحضير أوراق السفر لم أفكر في هذا الموضوع، وعندما عدت إلى هنا لم أعط أي اهتمام، ولكن بعد فترة أخذت زوجتي ترسل إليَّ خطابات، ومن هذه الخطابات أن أخي المذكور لا يذهب لرؤية أولادي، فكتبت لها إنني علمت أن أخي يحضر إلى البيت الساعة اثنا عشر ليلًا، وهذا الوقت غير مناسب، ويمضي أيضًا في رسالته ويقول: إنني بعثت له رسالة، وعرضها على الوالد، والوالد كأنه جاء في باله أو في خاطره شيء، يسأل عن حل هذه المشكلة، وما حكم هذا العمل؟","title":"حكم الخلوة بزوجة الأخ والظهور أمامه بلباس دون أكمام","answer":"الجواب: لا شك أن خروجها إلى أخيك بلباس ليس له أكمام، وسفورها لديه بوجهها ورأسها، ونحو ذلك كله حرام، كله منكر ومن أسباب الفتنة، ومن أسباب وقوع الفاحشة، فالواجب الإنكار عليها، وتحذيرها من هذا العمل، والواجب الإنكار على أخيك أيضًا، وأن ينكر عليها، وألا يسمح لها بأن تقابله هذه المقابلة؛ لأن المسلم ينكر المنكر، ويخاف الله ويرجوه ، ولا يرضى في أهله، ولا في أهل أخيه ما حرمه الله ، وليس له أن يخلو بها، لا في الليل، ولا في النهار، وليس له أن يجيء إليها في نصف الليل، وهي في بيت وحدها، فهذا محل الريبة، ومحل الشر.  فالواجب منعه من ذلك وإخباره بأن الواجب عليه أن يأتي إليها في وقت ليس فيه خلوة، بل عند الناس عند أبيه أو أمه، ونحو ذلك، فلا يخلو بها وحدها أبدًا، لا في الليل، ولا في النهار؛ لأن النبي ﷺ قال: لا يخلون رجل بامرأة فإن الشيطان ثالثهما ولأن الخلوة وسيلة إلى وقوع الفاحشة. فالواجب عليك -أيها السائل- أن تحرص على منعها من هذه المقابلة السيئة، لا مع أخيك، ولا مع غيره، بل تكون متسترة متحجبة مع جميع الأجانب؛ لأن أخاك في حكم الأجنبي ليس بمحرم، وعليها أن تقابل غير المحارم بالستر والحجاب، وعلى أخيك أن يتقي الله وأن يحذر مقابلتها على حالة سيئة، أو المجيء إليها في وقت لا يناسب؛ لأنه يتهم في هذه الحال بما يحرم الله ؛ ولأن تركها على حالها، وعدم الإنكار عليها من باب التعاون على الإثم والعدوان، وإذا أمكنك -يا أخي- إحضارها، وأن تكون معك، فهذا هو الذي ينبغي، حتى تسلم من هذه الفتنة، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/13591/حكم-الخلوة-بزوجة-الاخ-والظهور-امامه-بلباس-دون-اكمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_664/nour_66403.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة","نصائح وتوجيهات"]},{"id":15145,"question":"هذه الرسالة وردتنا من المخلصة فاطمة بنت علي (ص. ع) بريدة، تقول في رسالتها:هل يعتبر الشخص الذي يحضر سائقًا لسيارته، ويذهب ويروح بامرأة هذا الرجل، أو بنته من غير ذي محرم، هل يعتبر هذا الرجل ديوثًا، وهذا السائق شاب أنيق، وربما يكون غير مسلم؟ علمًا أنه يجلس في البيت مع النساء ورب الأسرة غير موجود.","title":"حكم من يترك السائق يخلو بمحارمه، وحكم استقدام الكفار","answer":"الجواب: هذا عمل قبيح لا ينبغي، لكن لا يقال: إنه ديوث؛ لأنه قد يكون شُبّه عليه، وأحسن ظنه بأهله، ما يعتبر ديوثًا، لكن يخشى عليه من الإثم، وينبغي له أن يكون عنده غيرة، وعنده احتياط، وحرص على سلامة أهله، لكن لا يطلق عليه أنه ديوث؛ لأنه قد يكون له شبهة، قد يكون ما قصد الشر، وغفل بسبب جهله؛ فيعلم ويرشد، ولا يقال له: ديوث، إلا إذا تعمد الباطل، وتساهل حتى صار يرسل امرأته مع الأجنبي من دون محرم، ومن دون مخالط، ويضعه معها، فتكون معه في البيت بدون محرم، وبدون من يخالطهم؛ هذا الدياثة ظاهرة عليه. فالواجب أنه لا يذهب بالمرأة السائق الأجنبي، وليس معها أحد، بل يكون معها أحد، حتى لا يحصل خلوة، النبي ﷺ قال: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما فإذا كان معهما ثالث ممن يطمأن إليه فلا خلوة، فإذا ذهبت ومعها امرأة أخرى أو امرأتان، أو معها أخو زوجها، أو عم زوجها؛ فإنه لا خلوة حينئذٍ إذا كان الخروج ليس فيه ريبة، فلا بأس بذلك.  وفي الحديث الآخر: لا يدخلن رجل على امرأة وإلا ومعه رجل أو رجلان؛ لأن في هذا تزول الخلوة. فالخلاصة: أنه لا يجوز أن يسوق الرجل الأجنبي بالمرأة وحدها، بل يكون معها غيرها؛ حذرًا من إثم الخلوة؛ وحذرًا من مغبة هذا الشيء، وما قد يحدثه الشيطان من تزيين الباطل، ولا يجلس معها في البيت وحدها، ولا ينبغي أن تجلس معه في البيت، حتى لو كانوا جماعة؛ لأنه ينظر إلى عوراتهم، بل يكون خارج البيت في محل آخر، يكون له محل خارج البيت في الحوش، أو في محل آخر، ولا يكون مع النساء في البيت؛ لأن النساء عورات، ولو كن كثيرات، فإنه إذا كان معهن في وسط البيت قد يرى عوراتهم، وقد يتساهلون معه في أشياء، وقد يفضي إلى خلوة بإحداهن، فلا يجوز أن يكون معهم في البيت، بل يكون على حدة، وبعيد عن اختلاطه بالنساء، ولا يجوز أن يخلو بامرأة لا في البيت ولا في السيارة، بل يكون معه رجل أو امرأة أخرى أو أكثر حتى تزول الخلوة، وحتى يطمأن إلى أسباب السلامة. ولا ينبغي استخدام الكافر أبدًا، لا في الجزيرة، ولا في غيرها، في الجزيرة أشد؛ لأنها بلاد لا يجوز فيها بقاء الكفرة، الرسول ﷺ أمر بإخراج اليهود والنصارى وغيرهم من الجزيرة، فلا يجوز للمسلم أن يستقدم كافرة أو كافرًا في هذه الجزيرة لتخدم بيته، أو ليسوق بها الرجل، هذا لا يجوز، بل يجب إبعادهم عن الجزيرة، ولا يبقى في الجزيرة إلا أهل الإسلام، ويجب على الدولة أن تلاحظ هذا الشيء، وأن تجتهد في إبعادهم من الجزيرة، وأن لا يبقى فيها إلا من تدعو الضرورة إليه؛ من طبيب تدعو له الضرورة، أو مهندس تدعو له الضرورة، وأما بقية الناس من العمال وغير العمال فالواجب إبعادهم عن هذه الجزيرة. ولا يخفى ما يترتب على وجود الكفرة من الشر على المسلمين في أخلاقهم وعقائدهم، لكن يجوز استخدام الكافر في غير الجزيرة: في الشام، في مصر، في العراق، في غير الجزيرة، يستخدمه في أعمال لا تضر المسلمين، ولا سيما إذا كان أمينًا معروفًا بصدقه ومعروفًا بأمانته، فلا بأس أن يستخدمه سائقًا يسوق به، أو يستخدمه في عمارة بيت له، أو مزرعة، أو ما أشبه ذلك، والمسلم خير منه، المسلم أولى منه بكل حال في كل مكان، في كل مكان المسلم أولى، المسلم الطيب المسلم المعروف بالاستقامة أولى بكل حال، والكافر لا يؤمن، قال الله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَتَّخِذُوا بِطَانَةً مِنْ دُونِكُمْ لا يَأْلُونَكُمْ خَبَالًا [آل عمران:118] فالكافر لا يؤمن ولا يعتمد عليه، ومن طبيعته أنه لا يألونا خبالاً، يعني: نقصًا ودمارًا وتعديًا علينا، ومهما أمكن أن يكون العامل مسلمًا في أي مكان، والعاملة مسلمة في أي مكان، هذا هو الذي ينبغي وهذا هو الأحوط والأولى بعدًا عن الشر وأهله، نعم.","link":"https://binbaz.org.sa/fatwas/13649/حكم-من-يترك-الساىق-يخلو-بمحارمه-وحكم-استقدام-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_658/nour_65804.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":15148,"question":"أيضًا تقول الأخت فاطمة بنت علي من القصيم: هل يعتبر زانيًا الشخص يجعل في بيته خادمة شابة نضيرة، ويجلس معها، ويمزح معها؟ وما هو دوركم -وفقكم الله- يا فضيلة الشيخ في ذلك تقصد في ذلك جميع العلماء؟","title":"التحذير من استقدام الخادمات الجميلات والخلوة بهن","answer":"الجواب: لا يعتبر زانيًا، لكن يكون قد تسبب في الزنا، لا يعتبر زانيًا بكونه جعلها في بيته وحادثها، لكنه قد تعاطى أسباب الزنا، وفعل أمرًا منكرًا، فالذي ينبغي أن لا يستقدم إلا المرأة الكبيرة، والمرأة التي ليست نضيرة، ينبغي إذا دعت الضرورة إلى استقدامهم أن تكون امرأة طاعنة في السن، وأن تكون غير جميلة؛ لأن هذا أبعد عن الشر، ويكون في البيت من يخالطها من النساء؛ حتى لا يخلو بها.  فينبغي له أن لا يستقدم امرأة أجنبية إلا إذا كان عنده في البيت غير زوجته؛ حتى تكون الخلوة منتفية، وحتى يكون هذا أبعد عن الشر، وأن تكون طاعنة في السن وغير جميلة، كل هذه يجب أن يحتاط لها، وأن يحرص على وجودها؛ بعدًا عن الشر، واحتياطًا للدين؛ لأن الواجب على المسلم أن يحتاط لدينه، وأن يبتعد عن أسباب الشر مهما أمكن، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/13650/التحذير-من-استقدام-الخادمات-الجميلات-والخلوة-بهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_658/nour_65805.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة","نصائح وتوجيهات"]},{"id":15152,"question":"سؤالها الأخير تقول فيه: أنا شابة أدرس في المدرسة الثانوية، وأبي أحضر لنا سائقًا للسيارة، ينقلنا إلى المدرسة وإليها، وهذا السائق دائمًا يتحدث ويمزح، فهل يجوز لي الركوب معه؟ وهل على أبي وزر في هذا؟ وأنا أخشى على نفسي يومًا من الأيام، فما هي نصيحة سماحتكم لنا؟وفقكم الله.","title":"حكم ركوب الفتاة بمفردها مع السائق","answer":"الجواب: الذي أنصح به أنه لا يركب معه، ولا يجوز التساهل في هذا، إلا إذا كان معك من يزول معه الخطر، وتزول معه الريبة، كأن يكون معك شخص آخر ثقة، أو امرأة أخرى ثقة، أو أكثر، فهذا يجوز عند الحاجة؛ لأن الحاجة ماسة إلى الخروج مع السائق للمدارس وغير المدارس من الحاجات، إلا إذا تيسر المحرم، فهذا أولى، وأولى من أخ أو عم أو ابن أخ، ونحو ذلك، ولكن إذا ما تيسر فينبغي الاحتياط، وأن لا تخرجي معه إلا ومعك من يطمأن إليه، وإن لم يكن محرمًا، لكن يطمأن إليه من عم أو أخ أو خادم آخر يطمأن إليه، أو امرأة يطمأن إليها، ونحو ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/13652/حكم-ركوب-الفتاة-بمفردها-مع-الساىق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_658/nour_65806.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":15219,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات من الخبر، أختنا عرضنا لها سؤال في حلقة مضت، وفي هذه الحلقة تسأل وتقول: ما حكم كشف الوجه على بعض أبناء العمومة؛ وذلك بسبب أننا نعيش جميعًا في منزل واحد؛ إذ من الصعب تغطية الوجه، أما باقي الأعضاء فالحمد لله مغطاة، وأنا لا أضع أي نوع من المساحيق في وجهي. مع العلم أننا لا نأكل جميعًا على مائدة واحدة، بل النساء منعزلات عن الرجال، كذلك لا نتخالط كثيرًا، بل مجرد الصعود والنزول من الطابق العلوي إلى السفلي، وبالعكس، نرجو توجيهنا. جزاكم الله خيرًا.","title":"حكم كشف الوجه على أبناء العمومة","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد دلت الأدلة الشرعية من الكتاب والسنة على أن المرأة عورة، يجب عليها الحجاب عن غير محارمها، ولا يجوز لها إبداء الزينة لغير محارمها، سواء كانوا من بني العم، أو بني الخال، أو من غيرهم، يجب الحجاب عنهم، وإن كانوا أقرباء إذا لم يكونوا محارم؛ لقول الله -جل وعلا- في كتابه العظيم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] هذه الآية عامة، تعم جميع النساء، وإن كان الخطاب لأزواج النبي -رضي الله عنهن- وﷺ، ولكن غيرهن من باب أولى، فإذا أمر أتقى النساء بذلك فغيرهن من باب أولى. ثم بين العلة التي تعم الجميع قال: ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ فإذا كان أطهر لقلوب الصحابة، وهم الأخيار خير هذه الأمة بعد الأنبياء، وأطهر لقلوب الصحابيات من أمهات المؤمنين وغيرهن، فغيرهن في حاجة إلى هذه الطهارة، بل في أشد الضرورة إلى هذه الطهارة. ويقول -جل وعلا- في آية أخرى من سورة النور : وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ أَوْ نِسَائِهِنَّ [النور:31] الآية. والزينة هي الزينة الظاهرة والباطنة، وأعظمها الزينة الخلقية، زينة الوجه والشعور والذراع واليد والساق والقدم، ونحو ذلك، هذه الزينة التي تفتن الناس، أما زينة الملابس فقد تفتن لكنها دون هذه الأشياء. وإذا ظهرت إلى غير محارمها يكون عليها ملابس غير فاتنة، وهكذا في الأسواق تكون ملابس عادية، ليس فيها فتنة، ولكن أعظم من ذلك ظهور الزينة الخلقية زينة الوجه، أو اليد، أو الشعور، أو الساق أو الذراع أو القدم كل هذه تحتاج إلى ستر؛ لأن الآية عامة: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ الآية. وفي الصحيحين عن عائشة -رضي الله عنها- أنها قالت -رضي الله عنها- لما سمعت صفوان يسترجع لما رآها في السفر حين تخلفت -خلفها الغزو- يحسبوا أنها في الهودج، قالت: \"فلما سمعت صوته خمرت وجهي، وكان قد رآني قبل الحجاب، فعرفني، فلما سمعت صوته خمرت وجهي\" فدل ذلك على أن نزول الحجاب يقتضي تخمير الوجه، وأنه يخمر. وفي السنن عنها -رضي الله عنها- أنهن كن في حجة الوداع إذا دنا منهن الرجال سدلت إحداهن جلبابها على وجهها، فإذا بعدوا كشفت. هذا يدل على أن الوجه مما يستر ومن الزينة التي يجب أن تستر، وهي أعظم زينة المرأة تعرف بوجهها، إن كانت دميمة قيل: دميمة، وإن كانت جميلة قيل: جميلة من وجهها، فهو أعظم الزينة وأعظم من اليد، وأعظم من الرجل، وأعظم من الساق، وأعظم من الشعر، فإذا وجب ستر الشعر فستر الوجه من باب أولى. أما الحديث الذي يحتج به بعض دعاة السفور، وهو حديث عائشة في قصة أسماء بنت أبي بكر -رضي الله عنها- أنها دخلت على النبي ﷺ في بيت عائشة، وعليها ثياب رقاق، فأعرض عنها النبي ﷺ ثم قال: يا أسماء، إن المرأة إذا بلغت المحيض لم يصلح أن يرى منها إلا هذا وهذا وأشار إلى وجهه وكفيه، رواه أبو داود، وفي بعض الروايات عند غير أبي داود: \"وأشار إلى نصف الساعد\" هذا حديث ضعيف لا يصح عن النبي ﷺ، بل هو ضعيف وباطل من عدة أوجه: الوجه الأول: أن الراوي له عن عائشة هو خالد بن دريك، وهو منقطع، لم يسمع منها، كما قال أبو داود -رحمه الله- وغيره، والمنقطع لا حجة فيه. الثاني: أنه من رواية سعيد بن بشير، وهو ضعيف لا يحتج بروايته. الثالث: أنه من رواية قتادة بالعنعنة، وقتادة مدلس، ولا تقبل روايته إذا دلس إلا إذا صرح بالسماع، إلا فيما جاء في الصحيحين، فروايته في الصحيحين معروفة ومنتقاة. الرابع: لو صح لكان محمولًا على حال النساء قبل الحجاب، كن يبدين وجوههن وأيديهن قبل نزول الحجاب، ثم أنزل الله الحجاب، فمنعن من ذلك. خامسًا: في متنه ما يدل على نكارته؛ لأن في الحديث: أن عليها ثيابًا رقاقًا، فهل يليق بـأسماء أن تدخل على النبي ﷺ في ثياب رقاق، زوج أختها، وهي امرأة من أصلح النساء، زوجة الزبير بن العوام، هذا لا يمكن أن يقع من أسماء، بل دينها وخلقها وعفتها وإيمانها يمنعها من هذا، أن تدخل على النبي ﷺ في ثياب رقاق لا تسترها، فلا يجوز أن يظن هذا بـأسماء -رضي الله عنها وأرضاها-. فهذه وجوه خمسة، كلها تدل على عدم صحة الاحتجاج بهذا الحديث، وتدل أربعة منها على عدم صحته، وأنه غير صحيح، والخامس لو صح لكان محمولاً على ما قبل الحجاب، والله ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13711/حكم-كشف-الوجه-على-ابناء-العمومة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_497/49701.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":15224,"question":"سؤاله الثاني يقول: كما تعلمون أن الأمة الإسلامية تعيش في الاختلاط بين النساء والرجال إلا ما رحم الله، فمثلًا شاب يعيش مع عمه، أخ أبيه الشقيق، وله بنات، وهذا الشاب طالب ولعمه غرفة واحدة، أو يعني: وعمل له عمه غرفة واحدة، ومعها برندة تابعة للغرفة، وهذا الشاب لا يستطيع أن يؤجر أو يستأجر البيت، فما الحكم إذا اختلط بنساء عمه وبناته؟","title":"حكم اختلاط الرجل بنساء عمه وبناتهن للضرورة","answer":"الجواب:  الواجب على الشاب أن يتقي الله، وأن يحذر الفتنة ببنات عمه، ويغض البصر، ولا يخلو بإحداهن، فإذا فعل ذلك فلا حرج عليه حتى يوسع الله عليه، فيجد مسكنًا مستقلًا، أو يتزوج إحداهن أو غيرهن. المقصود: أن عليه تقوى الله في ذلك، وأن يحذر أسباب الشر، وأن لا يخلو بأحد منهن، وإذا مر عليهن وهن سافرات يغض بصره ويوصيهن بالتحجب عنه، وإذا لم يتيسر ذلك غض بصره، وأعرض عن النظر إليهن حتى يجعل الله له فرجًا ومخرجًا من هذا البلاء؛ لأن وجود النساء في محل غير متسترات ومحتجبات فيه مشقة كبيرة على الشاب، وخطر كبير، فعليه أن يتقي الله سبحانه، وأن يلزم العفة، وأن يسأل الله العافية، وأن يغض بصره حتى يتيسر له الزواج من إحداهن، أو من غيرهن، أو ينتقل إلى محل آخر، وإذا أمكن الزواج فهو أولى، ولعل عمه لا يتأخر عن تزويجه، فليبادر بالزواج من إحدى بنات عمه، حتى تكون سكنًا له، وحتى يكون ذلك من أسباب غض بصره، وحفظ فرجه.  فأنا أوصي السائل بذلك، وأن يبادر بالمفاتحة مع عمه، والكلام مع عمه في الزواج، حتى يحصل له الأمران والخيران؛ العفة، وغض البصر، وحفظ الفرج، مع الزواج الذي أحبه الله ورسوله، وشرع الله المبادرة إليه، نعم.","link":"https://binbaz.org.sa/fatwas/13719/حكم-اختلاط-الرجل-بنساء-عمه-وبناتهن-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_668/nour_66803.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":15408,"question":"يقول السائل من الأردن، أبو معاذ: هل يجوز أن تكشف المرأة عن خمارها لأخو الزوج؟","title":"حكم كشف المرأة وجهها لأخي زوجها","answer":"الجواب: لا يجوز للمرأة أن تكشف لأخي الزوج، ولا عم الزوج، ليسا محرمًا لها، لكن تكشف لأبيه وجده وولده لا بأس محارم، أما أخو الزوج، وعم الزوج، وخال الزوج، فليسوا محارم، وليس لها أن تخلو بواحد منهم، ولا أن تكشف لأحد منهم، أما أبوه وجده وأولاده فلا بأس. \nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13909/حكم-كشف-المراة-وجهها-لاخي-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56725.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":15576,"question":"سؤالها الآخر تقول: هل تحتجب المرأة عن خال زوجها وعمه، حيث سمعت من بعض العلماء أن معنى قوله تعالى في آية الحجاب: أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ[النور:31] أن آباء المرأة تشمل الأب والجد وعمها وخالها، فهل آباء بعولتهن تشمل أيضًا أبا البعل وجده وعمه وخاله؟","title":"هل تحتجب المرأة عن خال زوجها وعمه؟","answer":"الجواب: لا، الخال والعم ليسا محرمين، بل ليس لها أن تكشف لعم الزوج، ولا لخال الزوج، ولا لأخي الزوج، وهو أقرب أيضًا، وإنما قوله : وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ[النور:31] هذا يعم الآباء والأجداد، ولا يدخل فيه الأعمام ولا الأخوال، والذي قال: إنهما داخلان غلط، قد غلط في ذلك، وإنما الآباء هم الأب والجد وإن علا، هؤلاء هم الآباء، فأما العم عم الزوج وخاله وأخوه فهم أجانب، وليسوا بمحارم، فليس لها أن تكشف لهم، بل عليها أن تحتجب وليسوا محارم لها، لا الخال ولا العم ولا أخو الزوج جميعًا، نعم.\nالمقدم: جزاكم الله خيرًا.\nالشيخ: وإنما محرمها أبو الزوج وجد الزوج وابن الزوج وابن ابنه وابن بنته هؤلاء محارم، أبو الزوج وأجداده من جهة الأب ومن جهة الأم هؤلاء محارم، وكذلك أولاد الزوج وأولاد أولاده وأولاد بناته كلهم محارم لزوجته. نعم.","link":"https://binbaz.org.sa/fatwas/14117/هل-تحتجب-المراة-عن-خال-زوجها-وعمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_692/nour_69202.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":15680,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الرياض، وباعثتها مجموعة من الأخوات هن: (ن. م. صالح ) الأخوات يسألن هذا  يقول  متى تحتجب المرأة عن الصبيان؟ أي: كم هو عمر الصبي الذي يجب على المرأة أن تحتجب منه؟جزاكم الله خيرًا.","title":"كم عمر الصبي الذي تحتجب منه المرأة؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد قال الله -جل وعلا-: وَإِذَا بَلَغَ الأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا كَمَا اسْتَأْذَنَ الَّذِينَ مِنْ قَبْلِهِمْ [النور:59]. ويقول النبي ﷺ: إنما جعل الاستئذان من أجل النظر.\nفالاحتجاب يكون بعد البلوغ، متى بلغ الصبي خمسة عشر سنة، أو عرف أنه احتلم، أو أنبت الشعر الخشن الذي حول الفرج، صار بهذا محتلمًا، ووجب عليه الاستئذان، ووجب التحجب عنه. ولكن ينبغي للمرأة أن تحتاط، فإذا كان مراهقًا قد قارب سن الاحتلام فلتحتط، ولتحتجب منه، وليس لها الخلوة به؛ بعدًا عن الشبهة، وحذرًا من الفتنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14229/كم-عمر-الصبي-الذي-تحتجب-منه-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_572/57201.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":15706,"question":"هذه السائلة: أم سليمان تقول في هذا  أرجو إجابتي على هذا السؤال إجابة واضحة، من سماحة الشيخ، وهو يتعلق بمٍسألة الركوب مع السائق بدون محرم، بغرض إيصالي إلى مقر عملي، مع أن عملي داخل المدينة التي أسكن فيها، ولا تعتبر المسافة بين منزلي ومقر عملي سفر؛ ولقد اجتهدت في إيجاد سائق بمحرم، ولكنني لم أجد إلا بمبالغ كبيرة من الصعب أن أدفعها، مع العلم بأنني بحاجة للوظيفة، حيث أنني أصرف على أولادي، هل يجوز ذلك يا سماحة الشيخ؟","title":"حكم ركوب المرأة مع السائق الأجنبي","answer":"الجواب: يقول النبي ﷺ: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما وركوب المرأة مع السائق وحده فيه خطر عظيم مع الخلوة، خطر عظيم مع الخلوة فلا يجوز، فعليها أن يكون معها زوجة السائق، أو امرأة أخرى ثقة تكون معها تذهب معها، وترجع معها، تذهب معها، وتبقى معها في المدرسة حتى ترجع معها، أو ثنتين يذهبن معها، ثم يرجعان، ثم يأتيان مع السائق، ثنتان، أو واحدة تبقى معها في المدرسة، أو في محل عملها، ثم ترجع معها، ولا تخل بالسائق؛ لأن الرسول ﷺ نهى عن ذلك، وحذر من ذلك؛ ولما فيه من الخطورة، الرسول ﷺ قال: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما وفق الله الجميع، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/14264/حكم-ركوب-المراة-مع-الساىق-الاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57315.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":15756,"question":"تسأل سماحتكم وتقول: هل يجوز لي أن أسلم مع أقاربي، وأتكلم معهم، وأنا محتجبة، وكاشفة لوجهي، وكفي فقط، بحضور زوجي، أو بحضور عدة نساء كحماتي أو عمتي أو حماي وغير ذلك؟أفيدونا مأجورين.","title":"حكم اختلاط المرأة بأقاربها مع وجود المحرم","answer":"الجواب: لا مانع من التحدث معهم، وسماع أقوالهم، والمشاركة في الخير، والحديث المباح؛ لكن مع الحجاب للوجه والكفين، وجميع البدن، عليك بالحجاب، ولا بأس بالجلوس معهم، والاستماع لحديثهم، والمشاركة في الحديث، والسلام، والكلام كله لا بأس به، لكن من دون (ترك) حجاب، ومن دون مصافحة لغير المحرم، والله يقول -جل وعلا-: قُلْ أَطِيعُوا اللَّهَ وَالرَّسُولَ[آل عمران:32] فالواجب طاعة الله ورسوله في جميع الأحوال، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14350/حكم-اختلاط-المراة-باقاربها-مع-وجود-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74109.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":15761,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات من الإمارات العربية المتحدة، تقول: أختكم زبيدة باكستانية، مقيمة في الإمارات، أختنا لها رسالة تقول فيها: سماحة الشيخ عبدالعزيز بن عبدالله بن باز! السلام عليكم ورحمة الله وبركاته، وبعد:سماحة الشيخ، باسمي وباسم المسلمين أشكر سماحتكم على ما تبذلونه من جهود في خدمة الإسلام، وتبصير المسلمين بأمور دينهم ودنياهم، وأحيطكم علمًا بأنني أقرأ كتبكم بكثرة، حيث أن مكتبة والدي تزخر بكتبكم القيمة، نفعنا الله بها، آمين.والآن أعرض على سماحتكم السؤال التالي: تعلمون سماحتكم أنه من الصعب جدًا أن يتخلى المرء عن عاداته وتقاليد بلده، وإنه توجد في بلدنا عادات، وهي أن المرأة في بيت زوجها تجد الحمو ووالد زوجها، وبقية إخوان الزوج ووالدته وأخواته، وكما تعلمون سماحتكم أن الحمو لا يجوز كشف الوجه له، وسؤالي هو: ماذا أفعل في مثل هذه الحالة؟ وهل عليّ أن لا أضع كحلاً، ولا ألبس إلا الملابس التي لا تكون زينة في حد ذاتها، علمًا بأن زوجي لا يستطيع أن يبني بيتًا آخر، ولأن أهله لا يرضون بذلك، وهو أيضًا لا يريد أن يعيش إلا مع إخوانه ووالده ووالدته؟أفيدونا، جزيتم عنا وعن الإسلام خيرًا.","title":"توجيه للمرأة التي تعيش مع إخوة زوجها","answer":"الجواب: الواجب عليك تقوى الله، وأن تحتجبي عن حميك، وعن جميع الأحماء، وأن تصبري في ذلك، وتتقي الله -جل وعلا-، ولا حرج عليك في ذلك، والحمد لله، على زوجك وعلى أهل زوجك أن يعذرك؛ لأنك عملت الأمر المشروع، والله يقول سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53]. فالواجب عليك الحجاب والتستر عن الأحماء عند الاجتماع بهم، مع الكلام الطيب، والسلام عليهم بالكلام، لكن مع الحجاب والتستر، وعدم المصافحة إلا لمحرم، ومن استعان بالله، وصدق أعانه الله، ويسر أمره وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا[الطلاق:2]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا[الطلاق:4]. والواجب على زوجك وعلى أبيه وعلى جميع الحمو أن يعذروك في الحجاب؛ لأنك أطعت الله، وابتعدت عن الفتنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14349/توجيه-للمراة-التي-تعيش-مع-اخوة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74108.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":15783,"question":"تقول: هل أحتجب عن أبناء أخت زوجي؟","title":"هل تحتجب المرأة عن أبناء أخت زوجها؟","answer":"الجواب: نعم، أبناء أخت الزوج أجانب، وهكذا إخوانه أيضًا، إخوانه وأعمامه كلهم أجانب، عليك الاحتجاب، وأن لا تخلي، ولا يحصل خلوة بأحد منهم، المحرم أبو الزوج وجده وأولاده، أما أبناء أخي الزوج، أو إخوان الزوج، أو أعمام الزوج، هؤلاء أجانب، ليسوا محارم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14372/هل-تحتجب-المراة-عن-ابناء-اخت-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74209.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":16043,"question":"تقول: لي زميلة متزوجة، وتأتي إلينا هي وزوجها، ونجلس سويًا مع أنني ألتزم باللباس الشرعي، فهل علي إثم في ذلك؟","title":"شروط جلوس المرأة مع الأجنبي","answer":"الجواب: لا حرج إذا جلست مع أهلك، وبعض جيرانك وزوج جارتك، وأنت مستورة متحجبة في الوجه وغيره للحديث، وسماع الحديث؛ فلا بأس، لكن لا يخلو بك، لا تجلسي معه وحدك مع غير محرمك، لا مع الجار، ولا مع غير الجار. أما إذا كانوا جماعة؛ جلست معهم؛ جلسوا يتقهوون معكم، يتحدثون معكم؛ فلا حرج في ذلك، المحرم الخلوة، أو التكشف، أما إذا كان الحجاب موجودًا، والتستر موجودًا، وليس هناك خلوة؛ فلا حرج لسماع الصوت، والكلام، والتحية، والسلام، ونحو ذلك من دون مصافحة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، سماحة الشيخ! بعض الناس يعتبرون أن غطاء ما عدا الوجه والكفين يعتبر حجابًا شرعيًا، فما هو توجيهكم لهم؟ الشيخ: لابد، مثلما تقدم، لا يكون حجابًا إلا بالوجه والكفين، لا بد من الكمال، تستر الرأس، والأيدي، والأرجل، كل شيء، تكون المرأة مستورة إلا العينين؛ فلا بأس أن تلبس النقاب الذي فيه خرق للعين، أو العينين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14675/شروط-جلوس-المراة-مع-الاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74807.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":16272,"question":"من بيشة رسالة بعث بها إحدى الأخوات المستمعات تقول: (ع. ع. س) من سد وادي بيشة تقول: إنه يوجد في منطقتنا نساء، ونحن بادية، ويفد إلى هؤلاء النساء ضيوف؛ فتقوم المرأة بتكريم الضيوف إذا كان زوجها غائبًا، أو متوفيًا، وإذا كانت مطلقة، وليس هناك -بحمد الله- شك ولا ريبة، فهل في هذا شيء؟ وبم توجهون الناس؟ جزاكم الله خيرًا.","title":"حكم استقبال المرأة الضيوف وإكرامهم","answer":"الجواب: إذا كان الموضوع ليس فيه ريبة، ولا خلوة؛ فلا مانع أن تقدم لهم الضيافة، وهي متسترة، متحفظة في وجهها، ويديها، وبدنها، تقدم لهم، وتقول لهم: خذوا عندكم القهوة ،عندكم كذا، تقهووا، وافعلوا كذا.. وكلوا.. تقدم لهم الطعام، وهم يأخذونه، والحمد لله. أما إذا كان واحدًا؛ لا تخلو به، تعذر تقول: ليس عندي أحد، واعذرني يا أخي! وكذلك إذا كان هناك ريبة، تخشى ريبة؛ تعتذر إليهم، ولو كانوا أكثر من واحد، إذا كانت تخشى أن تتهم بالشر؛ فتعتذر إليهم، وتقول: اعذروني؛ صاحب البيت ليس بحاضر، إن شاء الله تراجعونه في وقت كذا، وفي وقت كذا، أما إذا كان طوفًا معروفًا عندهم، وليس فيه تهمة، ولا شر، تقدم لهم ما ينبغي من الضيافة، مع التستر، والتحفظ، والكلام الطيب، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14973/حكم-استقبال-المراة-الضيوف-واكرامهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75210.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":16286,"question":"من بيشة رسالة بعث بها إحدى الأخوات المستمعات تقول: (ع. ع. س) من سد وادي بيشة تقول: إنه يوجد في منطقتنا نساء، ونحن بادية، ويفد إلى هؤلاء النساء ضيوف؛ فتقوم المرأة بتكريم الضيوف إذا كان زوجها غائبًا، أو متوفيًا، وإذا كانت مطلقة، وليس هناك -بحمد الله- شك ولا ريبة، فهل في هذا شيء؟ وبم توجهون الناس؟ جزاكم الله خيرًا.","title":"حكم استقبال المرأة الضيوف وإكرامهم","answer":"الجواب: إذا كان الموضوع ليس فيه ريبة، ولا خلوة؛ فلا مانع أن تقدم لهم الضيافة، وهي متسترة، متحفظة في وجهها، ويديها، وبدنها، تقدم لهم، وتقول لهم: خذوا عندكم القهوة ،عندكم كذا، تقهووا، وافعلوا كذا.. وكلوا.. تقدم لهم الطعام، وهم يأخذونه، والحمد لله. أما إذا كان واحدًا؛ لا تخلو به، تعذر تقول: ليس عندي أحد، واعذرني يا أخي! وكذلك إذا كان هناك ريبة، تخشى ريبة؛ تعتذر إليهم، ولو كانوا أكثر من واحد، إذا كانت تخشى أن تتهم بالشر؛ فتعتذر إليهم، وتقول: اعذروني؛ صاحب البيت ليس بحاضر، إن شاء الله تراجعونه في وقت كذا، وفي وقت كذا، أما إذا كان طوفًا معروفًا عندهم، وليس فيه تهمة، ولا شر، تقدم لهم ما ينبغي من الضيافة، مع التستر، والتحفظ، والكلام الطيب، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14973/حكم-استقبال-المراة-الضيوف-واكرامهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75210.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق المحمودة"]},{"id":16307,"question":"ومع مطلع هذه الحلقة نعود إلى رسالة الأخ عبدالله الصالح من القصيم بريدة، أخونا عبدالله عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة بقي له بعض الأسئلة في أحدها يقول: هل يجوز للمرأة أن تركب مع رجل أجنبي في السيارة بدون محرم؛ لقضاء حاجة في السوق، أو الذهاب إلى المدرسة؛ لأن بعض الناس يتهاون في هذا الموضوع، ثم هل ولي أمرها يأثم والحال ما ذكر؟ جزاكم الله خيرًا.","title":"حكم ركوب المرأة مع السائق وحدها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا شك أن ركوب المرأة في السيارة مع السائق من دون ثالث لا يجوز، فهو فيما أعتقد معتبر من الخلوة، ويخشى من عاقبته ما لا تحمد عقباه، فالواجب عليها أن لا تخرج مع السائق إلا ومعها ثالث، امرأة ثالثة، أو رجل ممن يطمأن إليه، ليس فيه ريبة، يكون معها إذا ذهبت إلى بعض حاجاتها، أو إلى المدرسة، هذا هو الواجب، والواجب على الولي ألا يتساهل في هذا، بل يهتم بهذا، ويعتني بهذا، ويلزم موليته بذلك؛ احتياطًا للدين، وحذرًا من سوء العاقبة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14996/حكم-ركوب-المراة-مع-الساىق-وحدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81001.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":16364,"question":"أولى رسائل هذه الحلقة رسالة وصلت من أحد الإخوة المستمعين وقع في نهايتها بقوله: ابنكم مصطفى بابكر حمد، يسأل جمعًا من الأسئلة في أحدها يقول: هل تجوز مصافحة المرأة المسنة من غير المحارم؟","title":"حكم مصافحة الأجنبية الكبيرة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فإن الله -جل وعلا- شرع لعباده ما فيه الخير لهم، والعاقبة الحميدة، ونهاهم عما يضرهم، وعما يخشى منه سوء العاقبة، ومن ذلك أنه  نهى عن مصافحة النساء على يد نبيه ﷺ فلا يجوز للرجل أن يصافح المرأة التي ليست محرمًا له، وإن كانت كبيرة السن؛ لأن المصافحة قد تجر إلى ما لا تحمد عقباه، وقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: إني لا أصافح النساء وهذا يعم العجائز والشباب، وقالت عائشة -رضي الله عنها-: \"والله ما مست يد رسول الله يد امرأة قط -يعني: عند البيعة- ما كان يبايعهن إلا بالكلام\" عليه الصلاة والسلام. قال بعض أهل العلم: إن المصافحة أشد من النظر، وأخطر، فالواجب ترك ذلك مطلقًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15078/حكم-مصافحة-الاجنبية-الكبيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_811/nour_81101.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":16418,"question":"ننتقل بعد هذا إلى رسالة وصلت إلى البرنامج من اليمن الحديدة بتوقيع إحدى المستمعات تقول فاطمة (هـ. ع) فاطمة تقول عن نفسها: أنا فتاة في التاسعة عشرة من عمري، وملتزمة بالحجاب الشرعي، ولله الحمد، ولكني أجد بعض المضايقات من قبل والدي، مثل إصرارهما على ظهوري على الرجال الأقارب من غير المحارم، ومصافحتهم، مثل ابن العم، وابن الخال، وزوج الخالة، وابن عم الأم، فما حكم ذلك، وهل يعتبر رفضي لذلك عقوقًا للوالدين؟ جزاكم الله خيرًا.","title":"حكم طاعة الوالدين في الاختلاط ومصافحة الأجانب","answer":"الجواب: أنت مشكورة على عنايتك بالدين، وعلى حجابك الشرعي، وعلى سؤالك عما يهمك في دينك، أنت مشكورة على هذا، وهذا هو الواجب، الواجب على كل مسلم ومسلمة التفقه في الدين، والسؤال عما أشكل عليه، سؤال أهل العلم، يقول الله سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43] ويروى عنه -عليه الصلاة والسلام-: أن جماعة أفتوا بغير علم فقال: ألا سألوا إذا لم يعلموا، إنما شفاء العي السؤال ويقول ﷺ: من سلك طريقًا يلتمس فيه علمًا؛ سهل الله له به طريقًا إلى الجنة وإرسال الأسئلة إلى هذا البرنامج من سلوك الطريق، والذهاب إلى حلقات العلم من سلوك الطريق، والتعلم في المدارس من سلوك الطريق. ويقول النبي ﷺ في الحديث الصحيح أيضًا: من يرد الله به خيرًا؛ يفقهه في الدين فهذا يدل على أن التفقه في الدين من علامات الخير، وأن الإعراض من علامات الشر. وليس لك أيها الأخت في الله! ليس لك طاعة والديك في الكشف على الأقارب غير المحارم، كابن العم، وابن الخال، ونحو ذلك، وليس لك المصافحة لهم أيضًا، وليست معصية والديك في هذا من العقوق، النبي  يقول: إنما الطاعة في المعروف، وهذا ما هو من المعروف. ويقول ﷺ: لا طاعة لمخلوق في معصية الخالق كونك تصافحين ابن عمك، أو ابن خالك، أو غيرهما من غير المحارم الذكور، هذا لا يجوز، المصافحة خطيرة، يقول النبي ﷺ: إني لا أصافح النساء وتقول عائشة -رضي الله عنها-: \"والله ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام\" والمصافحة خطيرة. فالواجب عليك الحذر، والاعتذار إلى والديك بالكلام الطيب، اعتذري لهما بالكلام الطيب، وقولي: إني سألت بعض أهل العلم، فأخبروني أنه لا يجوز، وأرشديهم إلى هذا البرنامج يسمعونه، هذا برنامج مفيد، نوصي كل إنسان أن يسمع هذا البرنامج في كل مكان، فأنا أوصي، نوصي من يستمع من يريد الخير، ومن يطلب العلم، نوصيه أن يستمع لهذا البرنامج، فإنه يقوم عليه جماعة من أهل العلم، فنوصي كل من يريد الفائدة، والعلم أن يستمع لهذا البرنامج، نعم.","link":"https://binbaz.org.sa/fatwas/15126/حكم-طاعة-الوالدين-في-الاختلاط-ومصافحة-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_812/nour_81202.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":16455,"question":"من المستمع أحمد عبدالرحمن رسالة، وضمنها سؤالين، في أحدها يقول: خطبت ابنة عمي، وعقدت عليها، هل يحل لي الخروج معها لشراء بعض الحاجات؟ وهل يحل لي الخلوة بها، وأنا لم أدخل بها؟ أفيدوني جزاكم الله خيرًا.","title":"حكم الخلوة والخروج بالمعقود عليها","answer":"الجواب: نعم، هي زوجة، يحل الخلوة بها، والخروج بها لحاجة، لكن ترك الجماع لها أحوط؛ لأنك لم تدخل بها الدخول الشرعي، وربما حملت من جماعك لها؛ فيخشى أن تتهم بغيرك، أو أن تتهمها أنت بغيرك؛ فينبغي ألا تفعل، وينبغي في هذه الحال أن تتركها مع أهلها، وأن تشتري حاجاتها مع أهلها، تترك الخلوة بها؛ حتى لا تقع مسألة الجماع، احتياطًا، وبعدًا عن الخطر، وإلا فهي حل لك، زوجتك، لكن قد يترتب على الجماع أشياء لا تحمد عقباها. فالأولى بك، والأحوط لك ترك ذلك، حتى يتم الدخول على الوجه الشرعي -إن شاء الله- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15172/حكم-الخلوة-والخروج-بالمعقود-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_755/nour_75518.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":16559,"question":"من جازان المرسلة حليمة بعثت برسالة، وضمنتها سؤالين، في سؤالها الأول تقول: أنا -ولله الحمد- امرأة ملتزمة، ومحافظة، ولكن لي ولد عم قد بلغ من الكبر كثيرًا، وهو رجل أعمى، حيث أن عمره يناهز السبعين، فهل في الكلام معه، والسلام عليه إثم علي؟ جزاكم الله خيرًا.","title":"ما حكم سلام المرأة وكلامها مع غير المحارم؟","answer":"الجواب: ليس في الكلام معه، والسلام عليه إثم، بل هذا من صلة الرحم، ولا بأس أيضًا بالكلام مع غيره حتى لو كان أجنبيًا إذا لم يكن هناك شر، ولا فتنة، ولا خلوة، فالمسلمة تسلم على أقاربها، وإن كانوا ليسوا محارمًا، تسلم على جيرانها، وأخي زوجها، ونحوهم، من دون خلوة، ومن دون تعاطي أمور توجب التهمة.  فإذا كانت الأمور واضحة، ليس فيها تهمة، فالسلام حق على ابن عمك وعلى غيره من دون خلوة، ولكن من دون مصافحة بالكلام، كيف حالك، السلام عليكم، وعليكم السلام، كيف حالكم، كيف الأهل والأولاد، كل هذا لا بأس به، من دون مصافحة، ولا تقبيل كما يفعل بعض الجهلة، لا.  المصافحة تكون مع النساء، أو مع المحارم كالأخ والعم، أما مع الأجنبي سلام بدون مصافحة، بدون تقبيل رأس، ولا غيره، بدون خلوة، فإذا سلمت عليه بحضرة من يزيل الخلوة أمك، أو أختك، أو أخيك، أو غير ذلك، المقصود بدون خلوة يكون معكم ثالث، وبدون ريبة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15291/ما-حكم-سلام-المراة-وكلامها-مع-غير-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81606.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":16664,"question":"سماحة الشيخ هذه سائلة رمزت لاسمها بـ (ر. ب. ك. العرفجي) تقول: ما حكم ركوب امرأتين، أو أكثر مع سائق النقل بدون محرم، وذلك للضرورة، مع كونهن متحجبات، ومتسترات بالحجاب الشرعي، وذلك مثل نقل مدرسات أو طالبات، مأجورين؟","title":"حكم ركوب أكثر من امرأة مع سائق أجنبي","answer":"الجواب: إذا كان الركوب مع السائق في غير سفر، في البلد، فلا بأس، إذا كن ثنتين، أو أكثر لا حرج، المحرم الخلوة إذا كان وحدها، أما إذا كانوا ثنتين، أو ثلاثًا، أو أكثر، وليس هناك تهمة؛ فلا حرج في ذلك.  أما السفر لا، لا تسافر إلا مع محرم، والواحدة لا تركب مع السائق الأجنبي، ولو في البلد، لأن هذه خلوة، والرسول ﷺ يقول: لا يخلون رجل بامرأة فإن الشيطان ثالثهما. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/15397/حكم-ركوب-اكثر-من-امراة-مع-ساىق-اجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58321.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":16665,"question":"من أسئلتها تقول: هل يجوز للمرأة أن تجلس مع حماها إذا اضطرت إلى ذلك، وتكون هذه المرأة متغطية، وعليها الحجاب الذي يغطي الرأس، وجميع جسمها؟","title":"حكم جلوس المرأة مع عم أو أخي زوجها","answer":"الجواب: نعم، لها أن تجلس مع أخي زوجها، وعم زوجها إذا كان معهما ثالث بدون شبهة، أما أن تخلو بعم زوجها، أو بأخي زوجها لا، ما يجوز لها الخلوة، الرسول ﷺ قال: لا يخلون رجل بامرأة إلا ومعها ذو محرم لا يجوز لها الخلوة، لكن إذا جلست مع أخي زوجها، أو عم زوجها بحضرة أبيها، بحضرة أمها، بحضرة أخواتها لا بأس، المحرم الخلوة، نعم.  المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15398/حكم-جلوس-المراة-مع-عم-او-اخي-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58322.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":16739,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلينا من المستمع محمد من ليبيا، أخونا عرضنا له سؤالًا في حلقة مضت، ونعرض بقية أسئلته -إن شاء الله تعالى- في هذه الحلقة، فيسأل ويقول: ما حكم الخلوة بامرأة أجنبية في سيارة، أو مكتب، أو دار؟","title":"حكم الخلوة بالأجنبية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإن حكم الخلوة بالمرأة الأجنبية في سيارة، أو مكتب، أو غيرهما؛ حكمه التحريم، حكمها التحريم بلا شك؛ لقول النبي ﷺ: لا يخلون رجل بامرأة إلا ومعها ذو محرم متفق على صحته، وقوله ﷺ: لا تسافر امرأة إلا مع ذي محرم متفق على صحته. وقوله ﷺ: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما خرجه الإمام أحمد من حديث عمر بن الخطاب -رضي الله تعالى عنه- بإسناد صحيح. فليس للرجل أن يخلو بالمرأة، لا في مكتب، ولا في سيارة، ولا في غرفة، بل يجب عليه أن يحذر ذلك؛ لأن الشيطان قد يدعو إلى ما لا تحمد عقباه، ولهذا قال: فإن الشيطان ثالثهما هكذا قال ﷺ. ومن هذا ما قد يقع لبعض الناس يكون له سكرتيرة، يجلس معها في مكتبه، هذا منكر لا يجوز أن يكون للرجل سكرتيرة يخلو بها في مكتبه، أو بيته، أو غير ذلك، بل يكون للرجل سكرتير من الرجال، والمرأة لها سكرتيرة من النساء، فالنساء للنساء، والرجال للرجال، أما أن يتخذ سكرتيرة في مكتبه، أو في إدارته، أو في محل علاجه؛ لكونه طبيبًا، أو ما أشبه ذلك، هذا لا يجوز، وهذا منكر عظيم، ووسيلة للشر العظيم. وهكذا الخلوة في السيارة كونه يذهب بها هاهنا، وهاهنا ما معه أحد، وسيلة لشر عظيم، قد يغلبه الشيطان، ويذهب بها إلى حيث يشاء، وقد يتفق معها في السيارة على ما لا تحمد عقباه، فهذا كله لا يجوز، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15485/حكم-الخلوة-بالاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_821/nour_82101.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":16859,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، آثر فيها عدم ذكر اسمه، يسأل جمعًا من الأسئلة، فيقول: عندي، وبجواري عجائز، وهن من أقاربي، ولكنهن ليس من محارمي، وأذهب إليهن لأزورهن، وأساعدهن في بعض ما يحتجن إليه، لكني عند دخولي عليهن أصافحهن، أو أسلم على رؤوسهن، فما حكم الشرع في ذلك؟ وهل يحق لي زيارتهن، والحال ما ذكر؟ جزاكم الله خيرًا.","title":"حكم مصافحة العجائز والخلوة بهن","answer":"الجواب: أنت مأجور في الإحسان إليهن، وقضاء حوائجهن -جزاك الله خيرًا- لقول الله سبحانه: وَالْجَارِ ذِي الْقُرْبَى وَالْجَارِ الْجُنُبِ [النساء:36] فأمر بالإحسان إلى الجار القريب، وغير القريب، ولقول النبي ﷺ: من كان يؤمن بالله واليوم الآخر؛ فليكرم جاره وفي اللفظ الآخر: فليحسن إلى جاره وقال -عليه الصلاة والسلام-: ما زال جبريل يوصيني بالجار حتى ظننت أنه سيورثه.  فنوصيك بالاستمرار في هذا العمل الطيب، والإحسان إليهن، ولكن لا تصافحهن، ولا تقبل رؤوسهن، بل يكفي السلام، والكلام، والمساعدة؛ لقول النبي ﷺ: إني لا أصافح النساء وقول عائشة -رضي الله عنها-: \"والله ما مست يد رسول الله يد امرأة قط، ماكان يبايعهن إلا بالكلام\" ولو كان يصافح العجائز؛ لنقل؛ ولأن الإنسان قد يفتن بالعجوز، قد تكون جميلة، وقد تكون ذات صوت رخيم، قد تكون.. المقصود: أن كل ساقطة لها لاقطة، قد يقع فتنة، فالسنة، والواجب ألا تصافحهن، ولا تقبل رؤوسهن، ولكن بالكلام الطيب، والسلام، والإحسان إليهن بقضاء حوائجهن، والصدقة عليهن إن كن محتاجات. وهناك أمر آخر، وهو الخلوة، ليس لك الخلوة بواحدة منهن؛ لقول النبي ﷺ: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما وهذا يعم الكبيرة، والشابة، لكن إذا كن ثنتين، فأكثر؛ فلا بأس، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15612/حكم-مصافحة-العجاىز-والخلوة-بهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_764/nour_76409.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":16896,"question":"تقول أختنا: أنا لا أحب زيارة بعض الأقارب؛ لأن بناتهم يكثرن الاختلاط مع الرجال، ويكثرن الحكي معهم، ويجلسون معهم، وأنا لا أحب هذه التصرفات، ويقولون: إني معقدة، فهل أنا مذنبة لأني لا أحب الاختلاط مع أولاد الخالة، وأولاد الخال، ولا أولاد العم؟ أم أنا على صواب؛ لعدم مخالطة الرجال عامة، ولست معقدة؟ جزاكم الله خيرًا.","title":"حكم اختلاط المرأة مع أولاد عمها وخالها","answer":"الجواب: قد أصبت -بارك الله فيك- وأحسنت؛ لأن الاختلاط بالرجل الأجنبي فيه خطر عظيم، وابن العم، وابن الخال، وابن الخالة كلهم يعتبرون أجانب، غير محارم، أما الاختلاط الذي معناه رد السلام عليهم في المجلس، أو كيف حالكم، وكيف أولادكم؟ مع البعد عن أسباب الريبة، والكلام الباطل، فلا حرج في ذلك، إذا سلمت على بني عمها، أو بني خالها سلامًا ليس فيه ريبة، وليس فيه خلوة، بل سلمت عليه في مجلس، أو زاروهم، وسلموا عليها من باب صلة الرحم؛ هذا لا بأس به. المحرم الخلوة بالرجل، أو تعاطي أسباب الريبة، والفتنة مع الرجال، بالكلام، أو بالفعال، أما سلامًا نزيهًا، وكلامًا نزيهًا، بعيدًا عن الفتنة، فلا حرج أن تسلم على ابن عمها، أو ابن خالتها، أو ترد عليه السلام، أو تسأله عن أهله، وأولاده، لا بأس بذلك من دون خلوة، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15653/حكم-اختلاط-المراة-مع-اولاد-عمها-وخالها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_765/nour_76511.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":16897,"question":"آخر سؤال لأختنا تقول فيه: هل يجوز للمرأة الصلاة خارج البيت، وأمام بعض الأقارب؛ علمًا أنا في الريف، ولا يوجد لدينا بيت، مع أنه أيضًا لبسنا غير محتشم؟ وجهونا جزاكم الله خيرًا.","title":"ما حكم صلاة المرأة في غير بيتها؟","answer":"الجواب: إذا كانت الصلاة في بيت الأقارب، أو بيت الناس الذي زارتهم المرأة، وحضرت الصلاة، تصلي عندهم، ولكن إذا كان حولها رجل تصلي في محل بعيد عن رؤية الرجل؛ حتى لا يرى منها شيئًا، ولاسيما إذا كانت ثيابها غير محتشمة، يجب عليها أن تبتعد عن رؤية الرجال الأجانب، سواءً في بيتها، أو في غير بيتها، وإذا كانت محتشمة وصَلَّت في البيت، أو عند بعض من زارتهم لما حضرت الصلاة؛ فكل هذا لا بأس به، أما عند الأجنبي ولو ابن خال، أو ابن خالة، أو ابن عم؛ فلا بد أن تكون تامة الستر، ولا يوجد خلوة، بل تصلي في البيت من دون خلوة، من دون أي خلوة بها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15654/ما-حكم-صلاة-المراة-في-غير-بيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_765/nour_76512.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":17014,"question":"يسأل أخونا عبدالرحيم عبدالله من الخرطوم في السودان فيقول: ما حكم التحدث مع المرأة الأجنبية؟ وهل يجوز التحدث معها بوجود محرم لها؟ مع الدليل؟ جزاكم الله خيرًا.","title":"حكم التحدث مع المرأة الأجنبية","answer":"الجواب:  التحدث مع المرأة لا حرج فيه، إذا كان ما فيه تهمة، ولا خلوة، كان النساء يتحدثن مع النبي ﷺ ومع الصحابة، ويسألن، ويستفتين، لا حرج في ذلك، أما مع أسباب الفتنة كونها سافرة، أو في أمور تتعلق بالجماع، وأسباب الفتنة؛ هذا لا يجوز، أو مع الخلوة، ليس للأجنبي أن يتحدث معها فيما يسبب الفتنة، أو يميلها إليه للفاحشة، وليس له أن يخلو بها، ولو لتعليم القرآن، أو تعليمها، لا يخلو بها، يقول النبي ﷺ: لا يخلون رجل بامرأة فإن الشيطان ثالثهما. فالواجب على الرجال، والنساء التحرز من ذلك، فيحرم على الجميع الخلوة، لكن إذا كان معهما ثالث، وليس هناك تهمة؛ زالت الخلوة، إذا تحدث معها بحضرة أخيها، أو أمها، أو أبيها، أو امرأة أخرى، أو رجل آخر؛ زالت الخلوة، بشرط أن يكون الحديث بعيد عن الشر، والفتنة، سلام، سؤال عن علم، سؤال عن أولادها، عن مسائل تتعلق بحاجاتها؛ لا بأس، أما التحدث بشيء يسبب الفتنة، هذا لا يجوز، لا معها وحدها، ولا مع غيرها؛ لأن الواجب على المؤمن الحذر من أسباب الفتنة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15819/حكم-التحدث-مع-المراة-الاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76710.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":17033,"question":"يقول السائل من اليمن سماحة الشيخ: عندنا عادة وهي مصافحة الرجال للنساء غير المحارم، وإذا قلنا لهم: بأن هذا لا يجوز، قالوا: إن قلوبنا نظيفة، ونحن كالأهل، وجهونا في ضوء ذلك مأجورين.","title":"حرمة مصافحة المرأة الأجنبية","answer":"الجواب: لا يجوز للرجل أن يصافح المرأة التي ليست محرمًا له، سواءٌ كانت زوجة أخيه، أو زوجة عمه، أو من جيرانه، لا ليس له مصافحتها، يسلم عليها بالكلام فقط، أما المصافحة لا، لا يصافح إلا محارمه، كأمه، وأخته، وزوجته، وزوجة أبيه لا بأس، أما امرأة ليست محرمًا له، بل أجنبية كزوجة أخيه، أو زوجة عمه، أو بعض جيرانه، أو بعض بنات عمه، كل هؤلاء ليسوا محارم، لسن محارمًا له، فلا يجوز له أن يصافحهن، يقول النبي ﷺ لما مدت امرأة يدها إليه قال: إني لا أصافح النساء -عليه الصلاة والسلام- في البيعة، قال: إني لا أصافح النساء وقالت عائشة -رضي الله عنها-: «والله ما مست يد رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام » -عليه الصلاة والسلام- ولأن مسها وسيلة للفتنة، نعم. المقدم: أحسن الله إليكم يا شيخ.","link":"https://binbaz.org.sa/fatwas/15817/حرمة-مصافحة-المراة-الاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58711.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":17154,"question":"تقول السائلة أم هادي: هل يجوز لبنت في الثامنة من العمر أن تذهب مع ابن الجيران، أو مع ابن عمها لضرورة، مثلًا أن تكون مريضة، وبحاجة للطبيب تذهب معه، وإخوان هذه البنت الصغيرة ليسوا موجودين في البيت؟","title":"حكم خروج البنت مع غير المحارم","answer":"الجواب: لا حرج إن شاء الله، لا حرج إن شاء الله. نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15972/حكم-خروج-البنت-مع-غير-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58932.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":17269,"question":"من أسئلتها تقول: هل يجوز للمرأة أن تجلس مع حماها إذا اضطرت إلى ذلك، وتكون هذه المرأة متغطية، وعليها الحجاب الذي يغطي الرأس، وجميع جسمها؟","title":"حكم جلوس المرأة مع أخي زوجها","answer":"الجواب: نعم لها أن تجلس مع أخي زوجها، وعم زوجها إذا كان معهما ثالث بدون شبهة، أما وأن تخلو بعم زوجها، أو بأخي زوجها لا ما يجوز لها الخلوة؛ الرسول ﷺ قال: لا يخلون رجل بامرأة إلا ومعها ذو محرم لا يجوز لها الخلوة، لكن إذا جلست مع أخي زوجها، أو عم زوجها بحضرة أبيها، بحضرة أمها، بحضرة أخواتها، لا بأس المحرم الخلوة. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16111/حكم-جلوس-المراة-مع-اخي-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59219.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":17280,"question":"تقول: أنا لا أحب زيارة بعض الأقارب؛ لأن بناتهم يكثرن الاختلاط مع الرجال، ويكثرن الحكي معهم، ويجلسون معهم، وأنا لا أحب هذه التصرفات، ويقولون: إني معقدة، فهل أنا مذنبة والحال ما ذكرت، أو أنني معقدة، أو أنني على صواب؟ وجهوني، ووجهوا أمثال هؤلاء جزاكم الله خيرًا.","title":"حكم زيارة من تخالط الرجال وتجالسهم","answer":"الجواب: الواجب على كل امرأة أن تتقي الله، وأن تحذر ما حرم الله عليها من الاختلاط بالرجال على وجه يسبب الفتنة من كشف، أو التغنج، وخضوع بالقول، أو غير هذا من أسباب الفتنة. أما الاختلاط الذي لا يضر: مثل دخولها السوق لشراء حاجة، مثل صلاتها مع الناس خلف الجماعة، هذا ما يسمى اختلاط، ولا حرج فيه مع التستر، والبعد عن الفتنة، أما اختلاط بحيث تجلس مع الرجل، أو تكشف بعض محاسنها، ومفاتنها حتى يراها الرجال، أو تغازل الرجال، أو تخضع بالقول للرجل؛ هذا كله من المحرمات.. المقدم: أو تخضع..؟ الشيخ: بالقول؛ لأن الله قال: فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32] يعني: لا تغنج، لا تزينه تكسر في القول، فالمقصود أنها تبتعد عن كل ما يسبب الفتنة مع الرجال، سواء كان الرجال بني عم، أو أزواج أخوات، أو إخوان زوج، أو خدامًا، أو غير ذلك، يجب الحذر، وأنت مأجورة في الحذر من هذه الأشياء، والحرص على السلامة، أنت مأجورة -إن شاء الله- بذلك، نسأل الله للجميع الهداية، والتوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/16121/حكم-زيارة-من-تخالط-الرجال-وتجالسهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_768/nour_76812.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":17297,"question":"شخص حلف على المصحف الشريف بأنه لم يفعل شيئًا، وهو يكذب، وقد توفي هذا الشخص الآن، وأنا ابنته، تقول السائلة: أريد أن أبري ذمة والدي، فهل أعلم الشخص الذي حلف له؟ أم ماذا أفعل يا سماحة الشيخ؟الشيخ: أعد.المقدم: تقول السائلة: شخص حلف على المصحف الشريف بأنه لم يفعل شيئًا وهو يكذب، وقد توفي الآن هذا الشخص وأنا ابنته، وأريد أن أبري ذمة والدي، فهل أعلم الشخص الآخر الذي حلف له والدي؟ أم ماذا أفعل؟","title":"حكم تبرئة ذمة الوالد من حقوق المخلوقين","answer":"الجواب: إذا كنت تعرفين أن والدك أخطأ وكذب؛ فأدي عنه إذا قال: والله ما أخذت من مالك شيئًا، أو والله ما عندي لك دين، وهو يكذب؛ أعطيه حقه من مالك، وإلا من التركة، إذا كنت تعرفين هذا، إذا صدقك الورثة، وإن كان ما صدقوك أعطيه من مالك، وأبشري بالخير، والأجر، إذا كنت تعلمين أن الوالد كاذب، وأن الحق ثابت في ذمته؛ سواء دين، أو سرقة، أو غصب، أو غير ذلك، أدي أبرئي ذمة والدك، وأبشري بالخير. المقدم: ماذا يلزم هذه البنت تجاه والدها من الدعاء، والعمل الصالح؟ الشيخ: تدعو له، وتستغفر له، عليك أن تدعي له بالمغفرة، والرحمة، هذا من حقه عليك إذا كان مسلمًا. نعم. المقدم: الحمد لله، جزاكم الله خيرًا يا شيخ.","link":"https://binbaz.org.sa/fatwas/16138/حكم-تبرىة-ذمة-الوالد-من-حقوق-المخلوقين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59310.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":17388,"question":"تسأل أيضًا وتقول: هل يجوز للمرأة أن تجلس مع الرجال من أقربائها على أن تكون متسترة، وتتكلم معهم في أمور الدين، وأمور عامة؟","title":"حكم جلوس المرأة متسترة مع أقاربها","answer":"الجواب: نعم، لا بأس أن تجلس المرأة مع الرجال على صفة ليس فيها تبذل، ولا فتنة، بل متحجبة للنصيحة، أو للتحدث في أمر تحتاج إليه، كالجلوس مع أحمائها، إخوان زوجها، أو مع أزواج أخواتها، أو بني عمها، أو ما أشبه ذلك، للتحدث معهم فيما يحتاجه البيت، أو فيما يتعلق بالنصيحة، أو ما أشبه هذا من الأمور التي تحتاج الكلام معهم فيها، من غبر خلوة بواحد منهم، ومن دون تكشف، وعدم حجاب، بل تكون متسترة بالحجاب الشرعي، تستر وجهها، وبدنها، وتتكلم معهم بالكلام الطيب الذي ليس فيه ما يفتن أحدًا منهم، وليس فيه خضوع بالقول، بل بالكلام العادي؛ لقول الله -جل وعلا-: يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ وَقُلْنَ قَوْلًا مَعْرُوفًا [الأحزاب:32]. فالمشروع للمرأة أن تتكلم كلامًا معروفًا، ليس فيه تبذل، ولا تكسر، ولا تغنج، ولا خضوع، وليس بفاحش وغليظ وعنيف، ولكن بين ذلك. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16250/حكم-جلوس-المراة-متسترة-مع-اقاربها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83503.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":17398,"question":"تسأل أيضًا وتقول: هل يجوز للمرأة أن تجلس مع الرجال من أقربائها على أن تكون متسترة، وتتكلم معهم في أمور الدين، وأمور عامة؟","title":"حكم جلوس المرأة متسترة مع أقاربها","answer":"الجواب: نعم، لا بأس أن تجلس المرأة مع الرجال على صفة ليس فيها تبذل، ولا فتنة، بل متحجبة للنصيحة، أو للتحدث في أمر تحتاج إليه، كالجلوس مع أحمائها، إخوان زوجها، أو مع أزواج أخواتها، أو بني عمها، أو ما أشبه ذلك، للتحدث معهم فيما يحتاجه البيت، أو فيما يتعلق بالنصيحة، أو ما أشبه هذا من الأمور التي تحتاج الكلام معهم فيها، من غبر خلوة بواحد منهم، ومن دون تكشف، وعدم حجاب، بل تكون متسترة بالحجاب الشرعي، تستر وجهها، وبدنها، وتتكلم معهم بالكلام الطيب الذي ليس فيه ما يفتن أحدًا منهم، وليس فيه خضوع بالقول، بل بالكلام العادي؛ لقول الله -جل وعلا-: يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ وَقُلْنَ قَوْلًا مَعْرُوفًا [الأحزاب:32]. فالمشروع للمرأة أن تتكلم كلامًا معروفًا، ليس فيه تبذل، ولا تكسر، ولا تغنج، ولا خضوع، وليس بفاحش وغليظ وعنيف، ولكن بين ذلك. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16250/حكم-جلوس-المراة-متسترة-مع-اقاربها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83503.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":17470,"question":"يقول: أردت أن أتزوج بفتاة، لكن تلك الفتاة مشغولة موظفة بإدارة، ورغم ذلك لم تحتجب، ما حكم الشرع في الزواج بها، هل هو ممكن، أم لا؟ جزاكم الله خيرًا.","title":"حكم الزواج بامرأة تعمل مع الرجال ولا تتحجب","answer":"الجواب: إذا كانت مسلمة طيبة توحد الله، تعبد الله وحده، لا تعبد أصحاب القبور، وكانت تصلي، فإنها يجوز الزواج بها، وتعلم الحجاب، يقال لها: تحجبي؛ لأنه لا يجوز للمرأة أن تكشف للأجانب؛ لأن الله يقول سبحانه في كتابه العظيم: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ البعول: الأزواج إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ .. [النور:31] الآية من سورة النور، ويقول سبحانه في سورة الأحزاب: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]. فتعلم أنه يجب عليها الحجاب، ولا توظف مع الرجال، توظف في عمل النساء، لا توظف في عمل الرجال؛ لأن عملها مع الرجال فتنة، من أسباب الشر، ووقوع الفواحش، لكن تكون في عمل النساء ممرضة.. طبيبة للنساء، مديرة لمدرسة النساء.. عميدة لا بأس، مع النساء خاصة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16354/حكم-الزواج-بامراة-تعمل-مع-الرجال-ولا-تتحجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_725/nour_72507.mp3","categories":["النظر والخلوة والاختلاط","شروط وأركان الزواج"]},{"id":17477,"question":"في آخر أسئلة هذه السائلة تقول: هل يجوز أن تجلس المرأة وهي كاشفة لوجهها أمام كل من زوج الخالة، وخال الأم، وزوج الأخت؟","title":"حكم كشف الوجه أمام زوج الخالة وزوج الأخت","answer":"الشيخ: ليس لها أن تكشف عند زوج الأخت، ولا عند زوج الخالة، ولكن عند زوج الأم لا بأس، زوج الجدة لا بأس؛ لأنها محرم لزوج الأم، وزوج الجدة من الربائب إذا كان قد دخل بها، أما خال الأم فهو خال لها، خال أمك خال لك، إذا خال أمها، وخال جدتها، وخال أبيها؛ خال لها، محرم لها، وهكذا عم أمها، وعم أبيها عم لها، نعم.  المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16377/حكم-كشف-الوجه-امام-زوج-الخالة-وزوج-الاخت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_773/nour_77309.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":17598,"question":"رسالة وصلت إلى البرنامج من جيزان باعثها مستمع من هناك هو موسى علي نحاس له جمع من الأسئلة من بينها سؤال عن امرأة الخال، هل له أن يخلو بها وأن يذهب بها في السيارة إلى المستشفى أو لزيارة بعض الأقارب مثلًا؟","title":"ما حكم الخلوة بزوجة الخال؟","answer":"الجواب: امرأة الخال ليست محرمًا، وهكذا امرأة الأخ والعم لسن محارم، الأخ أقرب ومع هذا ليست زوجته محرماً والخال أبعد، هذا خرافة من بعض العامة لا أصل لها، فزوجة الخال وزوجة العم وزوجة الأخ كلهم أجنبيات، ليس له الخلوة بها والجلوس معها وحدها، أو الذهاب بها في السيارة وحدها، كل هذا لا يجوز، فهي ليست محرمًا، زوجة الخال وزوجة الأخ وزوجة العم إلا إذا كان بينك وبينها قرابة أو رضاعة، أما مجرد كونها زوجة الخال أو كونها زوجة الأخ أو العم هذا لا يجعلها محرمًا بل هي أجنبية ليس لك أن تخلو بها، وليس لك أن تسافر بها، وليس لك أن تذهب بها في السيارة وحدك، فالواجب التنبه لهذا الأمر والحذر من طاعة الشيطان والهوى. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16525/ما-حكم-الخلوة-بزوجة-الخال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84111.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":17611,"question":"الرسالة التالية وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: سائلة من السودان، تقول عن نفسها: أنا امرأة والحمد لله ملتزمة بالدين ولي والدة لم يطب لها التزامي بالدين وخاصة الحجاب الشرعي، وقد طلقها أبي منذ فترة وكنت في رعايتها بعد الله .وبعد أن تزوجت بأحد الإخوة الملتزمين رفضت والدتي زيارتي إليها، وما زلت بعد ذلك أزورها أنا وزوجي فإذا بها ترفض رفضًا باتًا مقابلتي عند بيتها، وكتبت لزوجي خطابات فحواها أنها ستعيش في قلق وضيق إذا زارها هو وابنتها فعليها التوقف عن زيارتها لتعيش مطمئنة حسب قولها، فهل في مثل هذه الحالة إذا انقطعت عن زيارة والدتي إرضاء لها أكون عاقة لها، علمًا بأن قلبي يتفطر ألمًا في مسلك والدتي هذا، حيث أنني لم أنقص من حقها شيئًا في الطاعة في المعروف جزاكم الله خيرًا.","title":"هل يجوز طاعة الوالدة في طلبها عدم زيارتها؟","answer":"الجواب: أنت مأجورة ومشكورة وعليك طاعة الله ورسوله، عليك أن تطيعي الله ورسوله في كل شيء ولو غضبت الوالدة أو غير الوالدة، يقول النبي ﷺ: إنما الطاعة في المعروف، ويقول ﷺ: لا طاعة لمخلوق في معصية الخالق.\nفالوالدة والوالد والأمير والسلطان والزوجة والزوج كلهم لا يطاعون في معاصي الله، لا أحد يطاع في معاصي الله أبدًا، ولكن عليك الدعاء لها بالتوفيق والهداية والصلاح والإحسان إليها إذا كانت محتاجة بالمال والرفق، وإذا كلمتها بالتلفون ورضيت بالكلام فلا بأس وإلا ليس عليك إثم، الإثم عليها هي، أما أنت ليس عليك إثم، إذا كنت فعلت ما شرع الله لك من الحجاب وغضبت من أجل الحجاب فهذا غلط منها وجهل منها فاسألي الله لها التوفيق والهداية والصلاح، وأحسني إليها بالدعاء لها أن الله يوفقها وأن الله يهديها وأن الله يفقهها في الدين، وأن الله يعيذها من الشيطان وأبشري بالخير. وليس عليك حرج إذا ما زرتيها إذا كانت ترغب ألا تزوريها، ولا تؤذيها بالزيارة، وإن سمحت بالمكالمة التلفونية أو بالمكاتبة فافعلي، وإن لم تسمح فلا تفعلي أيضًا، وأنت معذورة ومشكورة ومأجورة والإثم على أمك، فاسألي الله لها الهداية، وأن الله يسامحها ويعفو عنها وأبشري بالخير، ونسأل الله لأمك الهداية، نسأل الله لأمك الهداية وأن يوفقها للفقه في الدين وأن يرزقها البطانة الصالحة التي ترشدها إلى الخير. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16540/هل-يجوز-طاعة-الوالدة-في-طلبها-عدم-زيارتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_842/nour_84203.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":17673,"question":"هل يجوز للرجل أن يصافح زوجة عمه وخاله؟","title":"هل يجوز مصافحة زوجة الخال والعم؟","answer":"الجواب: لا، زوجة عمه وخاله ليستا محرمًا له، ليس له مصافحتهما ولا الخلوة بواحدة منهما؛ لأنهما ليستا محرمًا له، زوجة العم والخال ولا زوجة الأخ أيضًا؛ كلهن لسن محرمًا له، فلا يصافح زوجة أخيه ولا زوجة عمه ولا زوجة خاله، لكن يصافح زوجة أبيه ما يخالف، زوجة أبيه جده زوجة ابنه لا بأس ابن بنته، أما زوجة أخيه وزوجة خاله وزوجة عمه فكلهن أجنبيات. نعم.","link":"https://binbaz.org.sa/fatwas/16604/هل-يجوز-مصافحة-زوجة-الخال-والعم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59502.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":17714,"question":"تقول الأخت السائلة أم محمد من مدينة الزلفي في آخر أسئلتها: سماحة الشيخ! هل علي إثم إذا لم أكشف وجهي عن زوج ابنتي؟ جزاكم الله خيرًا.","title":"مشروعية كشف المرأة وجهها عند زوج ابنتها","answer":"الجواب: المشروع لك كشفه، التعبد بهذا ما يجوز؛ لأن هذا خلاف ما شرع الله، زوج بنتك محرم لك؛ لأن الله قال: وَأُمَّهَاتُ نِسَائِكُمْ [النساء:23]، المقصود أنه محرم، فالحاصل أن أم الزوجة محرم للزوج فلا تغطي عنه، بل اكشفي له الوجه وخذي برخص الله، الرسول ﷺ يقول: عليكم برخص الله التي رخص لكم وهذا تنطع وتكلف لا ينبغي ولا يجوز. نعم.\nالمقدم: أحسن الله إليكمـ وبارك فيكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16668/مشروعية-كشف-المراة-وجهها-عند-زوج-ابنتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59525.mp3","categories":["النظر والخلوة والاختلاط","المحرمات من النساء"]},{"id":17961,"question":"السائلة تقول: يتساهل كثير من النساء هداهن الله في دخول الصبيان من أقاربهم عليهم، وهؤلاء الصبيان قد بلغوا، فهل نصيحة لمثل من تساهلوا لمثل هؤلاء؟","title":"حكم دخول الأولاد البالغين على النساء","answer":"الجواب: نعم، الواجب على المرأة الحذر، وأن لا يدخل عليها المكلف، بل يجب أن تحذر ذلك، وأن لا تخلو برجل مكلف، وعليها أن تستتر وأن تصون نفسها وتختمر، ولا يجوز لها الخلوة بأجنبي مطلقًا، سواء أخا زوجها أو عم زوجها أو غيرهم، عليها أن تتقي الله وأن تراقب الله، وأن لا يدخل عليها من ليس محرمًا لها، إلا إذا كان معها غيرها ليس بخلوة ولا تهمة. نعم.","link":"https://binbaz.org.sa/fatwas/16975/حكم-دخول-الاولاد-البالغين-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59834.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة","نصائح وتوجيهات"]},{"id":18017,"question":"رسالة من حائل وبعثت بها إحدى الأخوات من هناك تقول المرسلة (ع. ش. ب) تسأل تقول: ما حكم جلوسي مع أخي زوجي وأطفالي في حضرتي؟","title":"حكم جلوس المرأة مع أخي زوجها بحضرة أطفالها","answer":"الجواب: ليس لك الجلوس مع أخي زوجك مع الأطفال؛ لأن هذه خلوة والرسول ﷺ يقول: لا يخلون رجل بامرأة فإن الشيطان ثالثهما . أما إذا كانوا مميزين بحيث يحترمون تزول الخلوة، ابن سبع وابن ثمان وابن عشر، أما الصغار دون السبع فليس لوجودهم فائدة ولا يمنعوا من الخلوة، فلابد أن يكون الأولاد من سبع فأكثر يحصل بهم جواز الخلوة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17049/حكم-جلوس-المراة-مع-اخي-زوجها-بحضرة-اطفالها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85003.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":18071,"question":"رسالة وصلت إلى البرنامج من الأعظمية في بغداد وباعثتها إحدى الأخوات من هناك، رسالتها مطولة في الواقع، أستأذن سماحة الشيخ في أن أقرأها كما وردت.تقول: بسم الله الرحمن الرحيم وبه نستعين، والصلاة والسلام على محمد وعلى آله وأصحابه أجمعين:رسالتي لكم رسالة أم مؤمنة مسلمة عاشت عمرها الذي تجاوز الخمسين عامًا على عبادة الله وعلى سنة نبيه الكريم ﷺ أنشأت ابنتها الكبيرة على طريقتها حتى تزوجت قبل عشر سنوات وصارت تبتعد عني رغم أني أتقرب إليها حيث لم ينجب زوجها ذرية لسبب فيه، وتركنا ذلك إلى مشيئة الله  وفي الفترة الأخيرة افتقدتها نهائيًا ولم أعلم عنها شيئًا وانقطعت أخبارها، وقد تركتني أنا الأم التي أنشأتها على طاعة الله والوالدين أفتش عنها في كل زاوية ودرب مشوشة الفكر قلقة مشدودة الأعصاب.علمًا بأني تحت العلاج الطبي والعمليات الجراحية التي أجريت لي حتى الآن لم تشف، أكرر: هل ما أمر به الله تعالى بالعطف على الوالدين ورعايتهم وعدم الإساءة لهم بالقول البسيط (أف)، كيف بهذا العمل الذي أقلقني في صلاتي وحرمني طعم الخشوع، أدعو أبناءنا إلى الطاعة فيما يرضي الله ورسوله، وليتركوا تعسفهم بالوالدين باسم الانقطاع الكلي لفكرهم وآرائهم التي ينقصها التجربة والعطف والواقع الذي يلف البشر.فالله الله بهذه الأم التي أرضعت وربت ودرست وعلمت وهذبت على شريعة المصطفى محمد ﷺ أن تعامل هكذا.أرجو منكم حفظكم الله إذاعة رسالتي أكثر من مرة فهي تستمع إلى ندوتكم المذاعة منذ سنوات كما نسمعها جميعًا، ودمتم، وآخر دعوانا أن الحمد لله رب العالمين. وتسأل أربعة أسئلة فيما يبدو على ضوء ما ذكرت فتقول:سماحة الشيخ! ما حكم الشرع في هذا العمل حيث خرجت بدون محرم معها وكذبت على والديها؟ما حكم الشرع في هذا العقوق ومعاملة الوالدين وهما من أهل الإسلام والإيمان؟ما درجة صحة حديث رسول الله ﷺ حينما أمر أحد المجاهدين بالرجوع عن الجهاد والبقاء مع أمه رأفة بها من نبي الرحمة الكريم ﷺ؟هل غاب عن بال من يصرف النظر عن والديه أن النبي الكريم أوصى بالأم ثلاث مرات وبالأب مرة دون غيرهم؟ أرجو أن تتفضلوا بالتوجيه والإرشاد حول هذه القضية.والواقع رسالة مطابقة تمامًا لهذا الموضوع لكن مرسلها أخونا عبد الله العبيدي من بغداد أيضًا، والموضوع واحد كما قلت سماحة الشيخ.","title":"وجوب بر الوالدين والعناية بهما","answer":"الجواب: لا ريب أن بر الوالدين والإحسان إليهما والرفق بهما من أهم الواجبات، ومن أفضل القربات، وقد أوجب الله سبحانه حق الوالدين وأمر بالإحسان إليهما في كتابه العظيم في آيات كثيرات؛ منها: قوله : وَقَضَى رَبُّكَ أَلاَّ تَعْبُدُوا إِلاَّ إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَاناً إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنْ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:23-24]. ومنها: قوله سبحانه في سورة لقمان: أَنْ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14]. فبرهما من أهم الفرائض، وهذا العمل الذي عملته هذه البنت عمل سيئ ومنكر ولاشك أنه عقوق، والواجب عليها أن تضع يدها في يد والدتها، وأن تطلب منها السماحة والإباحة والعفو؛ لأنها قد أساءت إلى والدتها مع ما فعلت الوالدة من الخير العظيم والتربية والإحسان والصبر على أذى الطفل.. إلى غير ذلك مما تقوم به الوالدة، فينبغي لهذه البنت أن تتوب إلى الله وأن ترجع إليه سبحانه وأن تستغفره جل وعلا من ذنبها وتقصيرها، وأن تضع يدها في يد والدتها وتستسمحها وتطلبها العفو. وإذا كان هناك شيء حصل من والدتها يضرها ففي إمكانها توسيط من ترى من أهل الخير والأقارب حتى يصلح بينها وبين والدتها إن كان هناك شيء أوجب هذه القطيعة وهذا البعد. وأما ما يتعلق بسفر المرأة بغير محرم فهذا لا يجوز، ليس لها أن تسافر إلا بمحرم كما أمر به النبي عليه الصلاة والسلام حيث قال: لا تسافر امرأة إلا مع ذي محرم وكذلك قال النبي عليه الصلاة والسلام لما قال له رجل: «يا رسول الله! من أبر؟ قال: أمك  قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أباك، ثم الأقرب فالأقرب. وفي اللفظ الآخر يقول عليه الصلاة والسلام لما سئل قيل: «يا رسول الله! أي الناس أحق بحسن الصحبة؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أبوك. فحق الوالدة أعظم وأكبر من حق الوالد ثلاث مرات، حتى الجهاد إذا كان ليس فرض عين لابد من استئذان الوالدين أو أحدهما إذا كان الموجود أحدهما وهو الجهاد الذي هو من أهم الفرائض وقد يجب على الأعيان في بعض الأحيان. فالحاصل أنه يجب على الولد أن يستأذن والديه في الجهاد إذا لم يكن فرض عين لعظم حقهما ولهذا قال عليه الصلاة والسلام لما استأذنه رجل للجهاد قال: أحي والداك؟ قال: نعم. قال: ففيهما فجاهد. فالمقصود: أن حق الوالدين عظيم، فالواجب على البنين والبنات أن يعنوا بهذا الأمر وأن يعطفوا على والديهم وأن يرحموا والديهم، وأن يحسنوا إلى الوالدين، وأن يتلطفوا بالوالدين، ويعطفوا على الوالدين، فهذا من بعض حق الوالدين، رزق الله الجميع التوفيق والهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17106/وجوب-بر-الوالدين-والعناية-بهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_902/nour_90206.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":18098,"question":"سماحة الشيخ! المعيشة أحيانًا تلزم الإنسان بأن يبقى مع إخوته في سكن واحد، هل من توجيه شرعي حيال ذلك؟","title":"حكم سكن المرأة مع إخوة زوجها للضرورة","answer":"الجواب: هذا لا شك أن فيه خطر من جهة التكشف من الرجل على زوجة أخيه، وعدم التحرز من ذلك، ولكن إذا دعت إليه الضرورة فلا بأس مع التحرز، على كل واحدة أن تتحرز من أخي زوجها بعدم الخلوة وعدم التكشف له، بل تعتني بالحجاب والستر وتسأل الله العافية، وتحذر الميل إلى ما يزينه الشيطان، فعلى كل واحدة أن تبتعد عن أسباب الفتنة من إظهار المحاسن والزينة، وأن تتحجب عن أخي زوجها وعن أخواله وأعمامه ونحو ذلك، وتصبر على المشقة في ذلك حتى تنجو من العاقبة الوخيمة ولا حول ولا قوة إلا بالله، ومع ذلك عليها أن تحسن العشرة مع أهل بيته حسب طاقتها، فإذا تيسر أن تنتقل مع زوجها إلى محل آخر فذلك أصلح وأسلم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17133/حكم-سكن-المراة-مع-اخوة-زوجها-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_903/nour_90305.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":18176,"question":"رسالة وصلت إلى البرنامج من جمهورية السودان الديمقراطية -الخرطوم- وباعثتها إحدى الأخوات من هناك تقول مستمعة البرنامج زهرة الطاهر محمد، أختنا تقول في أحد أسئلتها في هذه الرسالة: سمعت في إحدى حلقات برنامجكم بأنه لا يجوز أن تركب النساء بجانب الرجال في المركبات العامة، وحيث أنه لا يمكن تخصيص مركبات خاصة عندنا وبحكم عملي أضطر لركوب هذه المركبات يوميًا ما رأيكم؟ وبم توجهونني؟ جزاكم الله خيرًا.","title":"حكم ركوب المرأة في وسائل المواصلات العامة","answer":"الجواب: إذا كان ولابد من الركوب في الحافلات العامة فليكن مركب النساء على حدة وراء الرجال، والرجال أمامهم على حدة حتى لا تمس المرأة الرجل، وحتى لا يحصل تماس وتقارب يخشى منه الفتنة، ينبغي أن تكون مراكب النساء خلف الرجال والرجال أمامهم يخصص لهؤلاء مراكب ولهؤلاء مراكب. فإذا اضطرت إلى خلاف ذلك فلتحرص على التحجب والتستر والبعد عن مماسة الرجل فيما يسبب الفتنة حتى تصل إلى جهتها إذا كانت قريبة لا تعد سفرًا. أما إن كانت المسافة تعتبر سفرًا فلابد من المحرم؛ لقول النبي ﷺ: لا تسافر امرأة إلا مع ذي محرم وعلى كل حال الواجب على النساء والرجال أن يتقوا الله جميعًا وأن يحرصوا على البعد عن أسباب الفتنة. وإذا دعت الحاجة إلى المراكب العامة فليجتهد المسئولون عنها أن يجعلوا مراكب النساء على حدة، ومراكب الرجال على حدة، إبعادًا لأسباب الفتنة، وينبغي للركاب المعروفين أن يفعلوا ذلك وأن يطلبوا من المسئولين عن الحافلات أن يفعلوا هذا حتى تكون الفتنة أقل وحتى يكون الشر أقل إن شاء الله. نعم. المقدم: هل تنصحون المرأة بعدم جلوسها في نفس الكرسي الذي يجلس عليه الرجل؟ الشيخ: نعم أنصحها بألا تجلس معه إذا كان فيه مماسة وتقارب يخشى منه الفتنة فلتبتعد ولتجلس في مركب بعيد عن ذلك ليس فيه مماساة، وإذا تيسر أن تكون مراكب النساء على حدة، ومراكب الرجال على حدة انتهى الموضوع وزالت المشكلة. نعم. المقدم: نعم نعم، إذًا النصيحة أيضًا توجه للرجال؟ الشيخ: نعم للرجال والنساء جميعًا، كلهم عليهم أن يحذروا الفتنة، وأن يجتهدوا في أن تكون مراكب الرجال على حدة في الجهة الأمامية، والنساء وراءهم في الجهة الخلفية حتى يحصل المقصود من دون ارتكاب للفتنة مع التحجب من النساء والحرص على الستر والبعد عن أسباب الفتنة، وعدم إظهار ما يفتن الرجال من التبرج، وإظهار زينة المرأة في وجهها وغيرها، بل تكون مستورة الوجه مستورة الشعر ومستورة البدن، بعيدة عن أسباب الفتنة، والله المستعان. نعم. المقدم: الله المستعان.","link":"https://binbaz.org.sa/fatwas/17216/حكم-ركوب-المراة-في-وساىل-المواصلات-العامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_854/nour_85403.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":18183,"question":"من المستمع: (ح. ب. أبو سعيد )، رسالة ضمنها جمعًا من الأسئلة، في أحدها يقول: هل يحق للأب أن يأخذ مال ابنه، وممتلكاته بحجة أن الرسول ﷺ قال: أنت ومالك لأبيك؟","title":"حكم أخذ الأب جميع مال ابنه","answer":"الجواب: نعم، له أن يأخذ من مال ابنه، من مال ابنه ما شاء، إذا لم يضر ابنه، أنت ومالك لأبيك، ويقول عليه الصلاة والسلام: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم؛ لكن ليس له أن يضره، بل يجب أن يترك له ما يكفيه، وإن كان له ذرية، وزوجة كذلك، لابد أن يترك له ما يكفيه وزوجته وأولاده؛ لقوله ﷺ: لا ضرر، ولا ضرار، لا ضرر، ولا ضرار، فليس له أن يضر ولده. أما إذا كان ولده ما عنده أحد، وأخذ ماله وصار ينفق عليه؛ فلا بأس، لكن الأفضل للوالد أن يتعاطى الأمور التي لا تجعل الأولاد يبغضونه، ويكرهونه، ويتمنون زواله، ينبغي له أن يلاحظ خواطرهم، وأن لا يطمع في أموالهم، لكن يأخذ ما يحتاج إليه، يأخذ من أموالهم ما لا يضرهم، فيما يحتاج إليه. أما يتعمد ضررهم، فلا يجوز له ذلك، بل لابد أن يدع لهم ما يحتاجون إليه، ولاسيما إذا كان لهم أولاد، لهم زوجة، لابد يترك لهم ما هو كاف، ولا يتسبب في تعطيل أمرهم، وضررهم، لقوله ﷺ: لا ضرر، ولا ضرار. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17221/حكم-اخذ-الاب-جميع-مال-ابنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73112.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":18184,"question":"من المستمع: (ح. ب. أبو سعيد )، رسالة ضمنها جمعًا من الأسئلة، في أحدها يقول: هل يحق للأب أن يأخذ مال ابنه، وممتلكاته بحجة أن الرسول ﷺ قال: أنت ومالك لأبيك؟","title":"حكم أخذ الأب جميع مال ابنه","answer":"الجواب: نعم، له أن يأخذ من مال ابنه، من مال ابنه ما شاء، إذا لم يضر ابنه، أنت ومالك لأبيك، ويقول عليه الصلاة والسلام: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم؛ لكن ليس له أن يضره، بل يجب أن يترك له ما يكفيه، وإن كان له ذرية، وزوجة كذلك، لابد أن يترك له ما يكفيه وزوجته وأولاده؛ لقوله ﷺ: لا ضرر، ولا ضرار، لا ضرر، ولا ضرار، فليس له أن يضر ولده. أما إذا كان ولده ما عنده أحد، وأخذ ماله وصار ينفق عليه؛ فلا بأس، لكن الأفضل للوالد أن يتعاطى الأمور التي لا تجعل الأولاد يبغضونه، ويكرهونه، ويتمنون زواله، ينبغي له أن يلاحظ خواطرهم، وأن لا يطمع في أموالهم، لكن يأخذ ما يحتاج إليه، يأخذ من أموالهم ما لا يضرهم، فيما يحتاج إليه. أما يتعمد ضررهم، فلا يجوز له ذلك، بل لابد أن يدع لهم ما يحتاجون إليه، ولاسيما إذا كان لهم أولاد، لهم زوجة، لابد يترك لهم ما هو كاف، ولا يتسبب في تعطيل أمرهم، وضررهم، لقوله ﷺ: لا ضرر، ولا ضرار. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17221/حكم-اخذ-الاب-جميع-مال-ابنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73112.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":18224,"question":"ما حكم عمل المرأة كمدرسة للبنات في مدرسة بها رجال مدرسين وهي متنقبة، والسائلة من السودان؟","title":"حكم تدريس المرأة للبنات في مدرسة بها مدرسون","answer":"الجواب: إذا كانت تدرس النساء من غير اختلاط بالرجال هؤلاء على حدة وهؤلاء على حدة لا بأس، أما مع اختلاطها بالرجال لا يجوز؛ لأن هذا فتنة يسبب شرًا كثيرًا، لكن إذا كانت تدرس النساء وحدهن في مدرسة وحدها في مكان وحده لا بأس، أما مختلطة مع الرجال فلا يجوز. نعم. المقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/17272/حكم-تدريس-المراة-للبنات-في-مدرسة-بها-مدرسون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78213.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":18383,"question":"تقول عن نفسها: أنا امرأة مسلمة، وأعمل، فما هي مواصفات الملابس الإسلامية التي يجب أن أرتديها؟ هل لبس الملابس الملونة الزاهية الألوان حرام؟ أم لا؟وهل لبس الملابس الحريرية اللامعة حلال؟ أم لا؟ وهل لبس الملابس المزركشة حلال؟ أم حرام؟ وجهوني حول هذا الموضوع، جزاكم الله خيرًا.","title":"اللباس الشرعي للمرأة المسلمة وحكم عملها بين الرجال","answer":"الجواب: إذا كنت بين النساء تلبسين ما يسر الله لك، والأولى أن يكون لباسًا معتدلًا، ليس فيه تكلف، ولا شهرة؛ لأن هذا قد يشوش على العاملين معكِ؛ قد يدعوهم إلى أن يتكلفوا مثلك، فالبسي لباسًا معتدلًا، مقاربًا لزميلاتك؛ حتى لا يحصل التشويش عليهن، أو إلجاؤهن إلى أن يتشبهن بك فيتكلفن، البسي اللباس المعتاد، المناسب، الذي ليس فيه تكلف. أما بين الرجال فلا تعملي بينهم، إن كان العمل بين الرجال؛ فلا تعملي بين الرجال، بالكلية، التمسي عملًا آخر ليس بين الرجال؛ فإن وجودك بين الرجال سكرتيرة، أو طبيبة بين الأطباء، أو ممرضة بين ممرضين رجال، هذا فيه خطر عظيم، وفتنة، فأنصحك بالحذر من هذا الشيء. أما بين النساء فالحمد لله، الأمر واسع، ولكن ننصح بأن تكون الملابس مقاربة، ليست فيها شهرة، ولا تكلف، بل مقاربة للباس الزميلات. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17445/اللباس-الشرعي-للمراة-المسلمة-وحكم-عملها-بين-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73215.mp3","categories":["قضايا المرأة","النظر والخلوة والاختلاط","اللباس والزينة"]},{"id":18392,"question":"على ضوء هذا الموضوع في صدري بعض الأسئلة شيخ عبد العزيز أطرحها أو لا؟الشيخ: نعم، لا بأس.المقدم: المرأة في زماننا في حاجة إلى الطب ولا شك، والبنات في حاجة إلى تعلم الطب حتى يخدمن المرأة، المرأة اصطدمت باختلاطها مع الدكتور ومع المعلم أيضًا ومع المرضى، لابد أن سماحتكم قد أهب وجهز موازنة لهذين الأمرين:الأمر الأول: حاجة المرأة إلى التطبب.والأمر الثاني: أن الفتاة المتعلمة للطب لابد أن تختلط؛ لأنه لا يوجد حتى الآن كلية للطب منفصلة، ولا يوجد حتى الآن مستشفيات تخلو من الرجال، كيف يكون الجواب لو تكرمتم؟","title":"حاجة الناس إلى الطبيبات مع وجود الاختلاط","answer":"الجواب: دين المرأة ألزم عليها من علاج الناس ومن نفع الناس، دينها وسمعتها وعفتها ورضا الله عنها مقدم على نفعها للناس، فإذا لم يتيسر تعلم تتوصل به هي إلى نفع أخواتها وشعبها ومجتمعها إلا بما يضرها في دينها ويسبب الخطر عليها وتعريضها للفتنة؛ فإن حفظ دينها وحفظ سمعتها وعفتها مقدم على أن تنفع الناس، هذا هو الذي أعتقده، وهذا هو الذي نراه واجبًا في حق البنين والبنات، أن يكون كل واحد حريصًا على حفظ دينه وسلامة إيمانه مما يخدشه ويضره. ولا يجب أن يتعلل بأن عدم التعلم يضر شعبي أو مجتمعي، فإن عليه أن يحفظ دينه أولاً وعليه أن يسعى لحفظ دينه وسلامته، ثم يسعى في نفع الناس بعد ذلك، فلا يقدم نفع الناس على هلاكه، كالسراج يضيء للناس ويحرق نفسه، كالفتيلة، كما ذكر جمع من أهل العلم في تمثيل العالم الذي يهلك نفسه ويعلم الناس ولكنه لا يعمل بل يخالف علمه عمله، فهو كالفتيلة التي تحرق نفسها للإضاءة لغيرها، لا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/17488/حاجة-الناس-الى-الطبيبات-مع-وجود-الاختلاط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_863/nour_86305.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":18394,"question":"تسأل سؤال أخير سماحة الشيخ وتقول: أختي لديها طفلة معاقة وتبلغ هذه الطفلة من العمر ست سنوات وهي متعبة جدًا بالنسبة لوالدتها، وتحتاج إلى كثير من الرعاية علمًا بأن والدتها غير مؤهلة صحيًا لذلك، وذلك لأنها مريضة ولها أطفال وحامل أيضًا، ولا تضع إلا بالعملية القيصرية، وينصحها الأطباء بعدم حمل الثقيل وعدم شد الأشياء الثقيلة، فهل يجوز لها جلب خادمة مسلمة تتولى العناية بهذه الطفلة علمًا بأن هذه الخادمة ستكون بدون محرم وستعيش معهم في البيت، فهل هذا جائز أم لا؟ أفيدوني وجزاكم الله خيرًا.","title":"حكم استقدام خادمة مسلمة بغير محرم","answer":"الجواب: إذا كان في البيت نساء غيرك فلا حرج في ذلك، وعلى والد الأطفال أن يقدم للمحرم ما يلزم من جهة تذكرة السفر ذهابًا وإيابًا مع المرأة، وإذا تيسر من دون محرم خادمة في البلد من دون حاجة إلى استجلابها من خارج وتيسر خادمة طيبة فلا بأس إذا كان هناك من يكون معها في البيت غيرك حتى لا يحصل خلوة بها من والد الأطفال. فالمقصود إذا كان المقام ليس فيه خطر ولا خشية من وقوع الفاحشة بل في البيت من تشترك معه الخادمة وتكون معه الخادمة ويكون سببًا للسلامة من الخلوة بزوجك فلا بأس إن شاء الله ولا حرج، وعليك وعلى زوجك أن تقوما بقيمة تذكرة المحرم إذا كانت تستقدم من خارج، وإن تيسر من الداخل فذلك طيب. نعم.","link":"https://binbaz.org.sa/fatwas/17495/حكم-استقدام-خادمة-مسلمة-بغير-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_863/nour_86307.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":18412,"question":"ابن أخت زوجي منذ كان عمره سنة والآن عمره ثلاث عشرة سنة وهو معنا في منزل واحد، هل يجوز لنا الكشف عليه إذا بلغ؟ هذا الشطر الأول من السؤال.","title":"أخو الزوج وأبناؤه وأبناء أخواته ليسوا محارم","answer":"الجواب: لا يجوز، ليس لك الكشف عليه؛ لأنه أجنبي ابن أخت الزوج وابن أخي الزوج وأخو الزوج نفسه كلهم ليسوا محارم، كلهم أجناب، فالواجب عدم الكشف لهم وعدم الخلوة بواحد منهم؛ لأنهم ليسوا محارم. نعم. المقدم: جزاكم الله خيرًا. بنات أختي هل يجوز لهن الكشف على زوجي إذا بلغن؟ الشيخ: بنات أختك أجنبيات لزوجك، وهكذا أخواتك أنفسهن أجنبيات ليس لهن الكشف لزوجك. نعم. ولا الخلوة به، ليس لواحدة أن تخلو به. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17486/اخو-الزوج-وابناوه-وابناء-اخواته-ليسوا-محارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73304.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":18428,"question":"تسأل أختنا وتقول: هل لي أن أسمع نداء أبي أو أمي إذا كان الفيديو أو ما شابه الفيديو مفتوحًا وبه فلم أو أمراني بالجلوس معهما؟ وهل يحق لهما منعي من قراءة الكتب النافعة التي تزيد بصيرتي في الدين؟","title":"حكم إجابة الوالدين وفي حضرتهما منكر","answer":"الجواب: ليس للوالدين ولا غيرهما أن يمنعا البنت أو الولد الذكر من قراءة الكتب النافعة، وليس لهما أيضًا أن يلزما الذكر أو البنت بحضور أفلام خليعة لا خير فيها، كل هذا ليس لهم ذلك، وليس للولد أن يطيعهما في المعصية، وله أن يخالفهما لكن بالأسلوب الحسن والكلام الطيب؛ لقول النبي ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق . ولا شك أن منع الوالدين للولد ذكرًا كان أو أنثى، لا شك أن منعهما له من قراءة الكتب المفيدة، أمر لا يجوز ومنكر، وكل إنسان في حاجة إلى الكتب المفيدة، من ذكر وأنثى. وهكذا دعوتهما الولد، ذكر وأنثى إلى أن يحضر الأفلام الخليعة، والأشياء المنكرة في تلفاز أو فلم أو غيره، لا شك أن دعوة الوالد لهما للبنت أو الابن دعوة منكرة، لا يلزمهما طاعته في ذلك، بل لا يجوز لهما طاعته في ذلك، إذا كان ذلك مما حرم الله ؛ لأن الله نهى عن حضور المنكر، وأمر بالبعد عن ذلك، وأمر أيضًا باجتناب ما حرم الله، وعدم التعاون على الإثم والعدوان، ونهى عن طاعة المخلوق في معصية الخالق، فليس للولد ذكرًا كان أو أنثى أن يستجيب لدعوة أبيه أو أمه فيما حرم الله. نعم. المقدم: جزاكم الله خيرًا. إذًا هناك حد معين لطاعة الوالدين؟ الشيخ: نعم، في المعروف، هذا الحد. المقدم: الطاعة في المعروف. الشيخ: المعروف هو المشروع والمباح، أما المعصية فلا، لكن عليهما أن يعني: على الولد ذكرًا كان أو أنثى عليه أن يعتني بالأسلوب الحسن والكلام الطيب، والدعاء لوالديه بالتوفيق والهداية، يا والدي رحمك الله، يا أبي رضي الله عنك، يا أمي رحمك الله، يا والدتي! غفر الله لك، هذا شيء لا يجوز، هذا شيء لا أتمكن من الاستجابة إليه، يعني: بعبارات طيبة، بعبارات لبقة لطيفة ليس فيها عنف؛ لأن الله قال في حق الوالدين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] ولو كانا كافرين، فكيف بالمسلمين. وقال الله سبحانه: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ [لقمان:14] وقال: وَبِالْوَالِدَيْنِ إِحْسَانًا [البقرة:83]. نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17507/حكم-اجابة-الوالدين-وفي-حضرتهما-منكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_914/nour_91403.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":18509,"question":"إذا كان الرجل عنده خادمة، وهو لم يأت بها إلا لحاجة ضرورية، وهي تأكل وتنام مع العائلة، ولا تتحجب عن صاحب البيت، فما رأيكم؟","title":"وجوب تحجب الخادمة من الأجانب","answer":"الجواب: الواجب على الخادمة وعلى غير الخادمة هو التحجب والحذر من الخلوة من الأجنبي سواء كان مخدومًا لها أو ابن عمها أو ابن خالها أو أحد جيرانها أو أخا زوجها أو ابن عم زوجها أو عم زوجها أو ما أشبه ذلك. الواجب على المرأة الاحتجاب عن كل من ليس محرمًا لها من الرجال؛ لأنها عورة وفتنة والله سبحانه يقول: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]. فقد أوضح سبحانه وجوب الحجاب، ولم يستثن وجهًا ولا غيره، وبين سبحانه أن هذا أطهر للجميع أطهر لقلوب هؤلاء وهؤلاء للرجال والنساء، فدل ذلك على أن عدم الحجاب فيه خبث وفيه خطر وهكذا قوله : وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية، هذه آية صريحة في منع إبداء الزينة لغير المحارم وأعظم الزينة الوجه؛ لأنه عنوان جمال المرأة أو دمامتها. فكما لا يجوز إظهار الشعر والساق والساعد والصدر ونحو ذلك فهكذا الوجه من باب أولى واليد والقدم وسائر بدنها كلها عورة إلا العجوز-القواعد- فقد قال الله تعالى: وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ [النور:60] فالعجوز التي لا ترجو النكاح ولا تتزين لا بكحل ولا بغيره من أنواع الزينة يجوز لها طرح الحجاب عن وجهها وترك ذلك والتعفف والتستر أولى وأفضل لها؛ لأن كل ساقطة لها لاقطة، خطر، فالتعفف والاستعفاف والتستر أولى ولو كانت عجوزًا لا تشتهى ولو كانت كبيرة لا تتزين، فالاستعفاف خير لها ولهذا قال سبحانه: وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ [النور:60] فإذا كانت العجوز التي لا ترجو النكاح ومع هذا لا تتزين لا بكحل ولا بمكياج ولا غير ذلك ولا بملابس ولا غير هذا تعففها وتسترها أولى فالشابة والمتزينة من باب أولى في وجوب التحجب والحذر من أسباب الفتنة.\nوفي الصحيحين عن عائشة رضي الله عنها أنها قالت: لما تخلفت في غزوة الإفك ورآها صفوان المعطل واسترجع قالت: \"فلما سمعت صوته خمرت وجهي وكان قد رآني قبل الحجاب\" فدل ذلك على أنهم بعد الحجاب لا يكشفون الوجوه، وإنما كانوا يكشفونها قبل الحجاب عند الرجال، فلما جاء الحجاب وأنزل الله الحجاب تسترن. أما حديث أسماء بنت أبي بكر الذي روته عائشة عن النبي ﷺ وهو ما رواه أبو داود في السنن عن عائشة رضي الله عنها قالت: دخلت أسماء بنت أبي بكر رضي الله عنهما وعليها ثياب رقاق فلما رآها النبي ﷺ أعرض عنها وقال: يا أسماء إن المرأة إذا بلغت المحيض لم يصلح أن يرى منها إلا هذا وهذا، وأشار إلى وجهه وكفيه، هذا الحديث ضعيف من وجوه لا يصح أن يحتج به، وقد تعلق به بعض الناس جهلًا وغلطًا، والصواب أنه حديث ضعيف من وجوه كثيرة لا يجوز التعلق به ولا أن تعارض به الأدلة من كتاب الله وسنة رسوله عليه الصلاة والسلام. وإليك أيها المستمع بيان ذلك؛ بيان أسباب ضعفه: أولًا: أنه من رواية خالد بن دريك عن عائشة وهو لم يسمع منها فهو منقطع والمنقطع عند أهل العلم ضعيف لا يحتج به عند جميع أئمة الحديث. العلة الثانية: أنه من رواية قتادة عن خالد بالعنعنة، وقتادة مدلس ولا يحتج به إذا عنعن في غير الصحيحين. العلة الثالثة: أن في سنده سعيد بن بشير وهو ضعيف عند أهل الحديث لا يحتج به. العلة الرابعة: أنه يحتمل أن يكون قبل الحجاب، أنه كان قديمًا، والحديث إذا احتمل أن يكون قبل الحجاب أو بعد الحجاب لا يحتج به؛ لأنه محتمل أن هذا لو صح أن يكون قبل الحجاب، قبل أن يحرم على المرأة حجب وجهها وكفيها، وكانت النساء قبل الحجاب يبدين وجوههن وأيديهن فلما نزل الحجاب منعن من ذلك. العلة الخامسة: أن هذا لا يليق بمثل أسماء ولا يظن بها ذلك؛ لأنها امرأة صالحة وهي أسن من عائشة وهي زوجة الزبير بن العوام أحد العشرة المشهود لهم بالجنة وحواري الرسول ﷺ، فكيف يظن بها أن تدخل على النبي ﷺ في ثياب رقيقة ترى منها العورة؟ كيف يظن ظان أن هذا يقع من هذه المرأة الصالحة العظيمة الشأن؟ فهذا شاذ ومتن منكر لا يليق من أسماء أن تفعله رضي الله عنها. ولو فرضنا صحته ولو فرضنا وقوعه منها لكان محتملًا أن يكون قبل الحجاب مع أنك عرفت أنه ضعيف لا يصح من وجه من الوجوه، فهو ضعيف من هذه الوجوه كلها، والله ولي التوفيق. نعم. المقدم: جزاكم الله خيرًا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17604/وجوب-تحجب-الخادمة-من-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_868/nour_86802.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":18651,"question":"ظهرت في الآونة الأخيرة -والأسئلة لا زالت لأخينا من السودان- يقول: ظهرت في الآونة الأخيرة في مجتمعنا الإسلامي ظاهرة الإدارات النسائية في بعض المؤسسات والمصالح، وحتى الوزارات، والتي يعمل تحت إمرتها كثير من الرجال الذين عليهم بالطاعة، وإراقة ماء الوجه لتنفيذ الأوامر على مضض من أجل الوظيفة لضمان لقمة العيش، فكيف يتفق كل هذا والشريعة السمحة تقول بأن الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ [النساء:34]؟","title":"حكم اختلاط النساء بالرجال في الأماكن العامة","answer":"الجواب: هذا قد سبق فيه غير مرة التنبيه في الإذاعة والتلفاز، وأن الواجب على النساء أن يكن في عمل النساء، وأن يكون الرجال في عمل الرجال، وألا يبرز الرجال في محل النساء؛ كطبيب النساء وممرض النساء، أو أشباه ذلك، بل يكون الطبيب للرجال والطبيبة للنساء، والممرض للرجال، والممرضة للنساء هذا هو الواجب، وكما تكون المعلمة للبنات، والمعلم للرجال، كل له ما يناسبه درءًا للفتنة، وحماية للمجتمع من أسباب الفساد. فليس للرجال أن يتولوا تدريس النساء، وليس للنساء أن يتولين تدريس الأولاد، بل يجب أن تكون المدرسة للبنات، وأن يكون المدرس للذكور؛ حسمًا لمادة الفتن، وهكذا في الدوائر، يجب أن تكون الدوائر للرجال، إذا كانت الدائرة للرجال، وأيضًا أن تكون الدائرة للنساء كمدارس النساء، وأشباه ذلك مما يكون فيه عمل النساء. ومستشفيات النساء يكون فيها النساء، كل طائفة يكون فيها ما يناسبها، طائفة الرجال يكون فيها الموظفون من الرجال بقدر الحاجة، وطائفة النساء يكون لهن موظفات من النساء، هذا هو الواجب سدًا لباب الشر، وحسمًا لأسباب الفساد. ولا مانع من استثناء بعض الحالات التي يضطر إليها، كأن يتولى الطبيب المختص علاج امرأة لم يوجد طبيبة تعالجها، أو طبيبة مختصة تعالج رجلًا بمرض لم يوجد في البلد أو في المستشفى من يعالجه، هذه ضرورات؛ مع الحشمة، ومع البعد عن أسباب الفتنة، ومع البعد عن الخلوة، هذا يجب عند الحاجة التقيد بهذه القيود، والحذر من أسباب الشر، فتكون الطبيبة التي اضطر إليها في علاج الرجل غير متعاطية لأسباب الفتنة، وغير خالية بالمريض، وهكذا الرجل إذا أراد أن يطب المرأة يكون هكذا عند الضرورة، ومن غير خلوة، وهي كذلك لا تتعاطى أسباب الفتنة، وإلا فالأصل هو ما تقدم: الأصل أن يكون الرجال للرجال والنساء للنساء؛ في التعليم، وفي الدوائر، وفي كل شيء؛ حسمًا لأسباب الفتن، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/17786/حكم-اختلاط-النساء-بالرجال-في-الاماكن-العامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_872/nour_87206.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":18725,"question":"إذا كان للمرأة ابن عم وعمره خمس عشرة سنة، هل يجب عليها أن تحتجب عنه أو لا؟","title":"حكم احتجاب المرأة عن ابن عمها","answer":"الجواب: نعم، إذا بلغ الطفل خمسة عشر سنة؛ وجب الاحتجاب على المرأة الأجنبية التي هي ليست محرمًا له، ووجب عليه الاستئذان، كما قال الله  في سورة النور: وَإِذَا بَلَغَ الأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا كَمَا اسْتَأْذَنَ الَّذِينَ مِنْ قَبْلِهِمْ [النور:59]. فهذا يدل على أنهم قبل ذلك لا يجب عليهم الاستئذان إلا في العورات الثلاث، كما في الآيات الأخرى.  فالحاصل: أنه إذا بلغ خمسة عشر سنة، أو احتلم، ولو قبل ذلك بأن رأى في نومه أنه جامع المرأة، وأنزل المني، أو أنزل من دون جماع بأن تحركت شهوته فأنزل، ولو في غير نوم؛ فإنه يكون بهذا قد بلغ الحلم، ولو كان أقل من خمسة عشر سنة، وهكذا إذا أنبت الشعر الخشن حول الفرج؛ فإنه يبلغ بذلك. فينبغي للمرأة أن تحتاط وتستتر وتحتجب عن المراهق؛ لأن المراهق قد يكون بلغ بالسن أو بالاحتلام وإنزال المني أو بإنبات الشعر، فإذا علمت أنه كمل خمسة عشر سنة، فإن هذا رجل يتعين الاحتجاب عنه من كل امرأة ليست محرمًا له، ولو كانت ابنة عمه أو ابنة خاله أو ابنة عمته أو نحو ذلك؛ لقول الله -عز وجل- في الآية الأخرى: إِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] ولقوله سبحانه: يا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] والجلباب: ما يوضع فوق الرأس وفوق البدن، فيستر وجه المرأة وأطرافها. ولقوله  أيضًا في سورة النور: لا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31].. الآية، والبعولة هم الأزواج؛ ولما ثبت في الصحيحين عن عائشة -رضي الله عنها- أنها ذكرت لما سمعت صوت صفوان بن المعطل يسترجع حين تخلفت في بعض الغزوات قالت: \"إنه عرفني؛ فاسترجع، وذلك أنه كان قد رآني قبل الحجاب؛ فلما سمعت صوته خمرت وجهي\".  فدل ذلك على أنهم بعد الحجاب بعد نزول آية الحجاب أمروا بتخمير الوجوه، يعني: أمر النساء بتخمير الوجوه، وهذا كان في غزوة الإفك التي تخلفت فيها عائشة عن الغزو لما ذهبت تقضي حاجتها، فجاء الذين يرحلون فرحلوا هودجها يظنون أنها في الهودج لخفتها، فلما جاءت ولم تجدهم اضطجعت في محلها، وعلمت أنهم سيرجعون إليها. فلما رآها صفوان المعطل استرجع لما رآها، وأركبها فوق راحلته، وجعل يقود بها حتى أوصلها الجيش، وقالت عند ذلك أنها لما سمعت صوته خمرت وجهها، وكان قد رآها قبل الحجاب؛ فعرفها، فدل ذلك على أن النساء أمرن بعد الحجاب بتخمير الوجوه.  وأما حديث أسماء بنت أبي بكر الذي روته عائشة -رضي الله عنها- أختها فيما رواه أبو داود في سننه من طريق عائشة -رضي الله عنها- أن أسماء بنت أبي بكر دخلت على النبي ﷺ في بيت عائشة وعليها ثياب رقاق، فلما رآها النبي ﷺ أعرض عنها وقال: يا أسماء إن المرأة إذا بلغت المحيض لم يصلح أن يرى منها إلا هذا وهذا، وأشار إلى وجهه وكفيه فهذا الحديث قد تعلق به بعض الناس في التسهيل في كشف الوجه للنساء، وهو خطأ عظيم وغلط واضح؛ لأن هذا الحديث ضعيف جدًا من وجوه كثيرة، ولأن كشف المرأة وجهها من أسباب الفتنة والخطر؛ لأن زينتها في وجهها وعنوانها في وجهها دمامة وجمالًا. وهذا الحديث كما سبق ضعيف من وجوه: منها: أنه منقطع بين عائشة، والراوي عنها، فإن الراوي عنها هو خالد بن دريك ، وهو لم يسمع منها كما قال أبو داود وغيره، والحديث المنقطع يعتبر ضعيفًا لا حجة فيه. الوجه الثاني: أنه من رواية قتادة عن خالد بالعنعنة، وقتادة مدلس، وروايته بالعنعنة ضعيفة كسائر المدلسين المعروفين بالتدليس إذا لم يصرحوا بالسماع: كـابن إسحاق وغيره من المدلسين، فإن روايتهم تعتبر ضعيفة حتى يصرحوا بالسماع، ما عدا ما في الصحيحين، فإن ما رواه الشيخان محتمل؛ لأنهم فتشوا عن أحاديث المدلسين ورووا منها ما صح عندهم وثبت عندهم فيه السماع.\nوهناك وجه ثالث يضعف به الحديث أيضًا: وهو أنه من رواية سعيد بن بشير ، وهو ضعيف الرواية لا يحتج به. وهناك وجه رابع: وهو أنه لو صح لكان يحتمل أنه قبل نزول آية الحجاب، وما كان محتملًا، فلا يحتج به؛ لأن آية الحجاب دلت على وجوب التستر والحجاب، فلو صح لكان محمولًا على أن هذا كان قبل الحجاب، فإن النساء كن قبل الحجاب يكشفن وجوههن وأيديهن، فلما نزل الحجاب منعن من ذلك. وهناك وجه خامس: وهو أنه يبعد أن يقع هذا من أسماء، فالمتن منكر، المتن في نفسه منكر؛ لأنه يبعد أن يقع مثل هذا من أسماء مع فضلها وعلمها وجلالة قدرها، وكونها زوجة الزبير بن العوام حواري الرسول ﷺ ، يبعد أن يخفى عليها هذا الأمر، ويبعد أن تدخل على النبي ﷺ بالرقاق، فإن هذا لا يليق بأمثالها، ولا يظن بأمثالها، فهو منكر من هذه الحيثية.  فاجتمع في تضعيفه خمسة وجوه، كلها تدل على ضعفه، وأنه لا يجوز التعلق به في إباحة السفور للنساء، والله المستعان.","link":"https://binbaz.org.sa/fatwas/17850/حكم-احتجاب-المراة-عن-ابن-عمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_874/nour_87404.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":18727,"question":"من ضمن أسئلة هذا السائل من سوريا يقول: طفل صغير توفيت والدته، وقامت امرأة بتربيته في بيتها مع أولادها بدون رضاع، هل تصبح هذه المرأة وبناتها محرمات عليه؟","title":"محرمية المرأة لرجل ربته صغيرًا","answer":"الجواب: التربية لا يجعلها مرضعة، إذا ربت المرأة صبيًا صغيرًا ولم ترضعه، فإنه لا يكون ولدًا لها، ولا يكون أخًا لأولادها، بل هو أجنبي لا تخلو به، ولا بناتها، إلا بالرضاع، إذا أرضعته خمس رضعات في الحولين كانت أمًا له، أما مجرد التربية كونها أحسنت فيه، وربته؛ فهذا لا تكون به أمًا له، ولا يكن بناتها أخوات له، بل هو أجنبي منهم جميعًا، نعم.","link":"https://binbaz.org.sa/fatwas/17857/محرمية-المراة-لرجل-ربته-صغيرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_789/nour_78910.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":18909,"question":"هل يجوز الجلوس مع زوج الأخت مع وجود المحرم، علمًا بأنه لا يظهر أمامه شيء لأنا ملتزمات بالحجاب؟","title":"حكم جلوس المرأة متحجبة مع زوج أختها مع وجود محرم","answer":"الجواب: لا مانع من جلوس المرأة مع أخي زوجها، ومع زوج أختها، إذا كان معهم من تزول به الخلوة، ولم يكن هناك تهمة، ولا ريبة، فلا بأس بذلك مع التستر والحجاب، إذا جلسوا يتحدثون: المرأة وزوج أختها، وأخو زوجها، ونحو ذلك ومعهم من تزول به الخلوة كأمهم وأخواتهم، ونحو ذلك، مع التستر والحجاب، وعدم الريبة، فالحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18044/حكم-جلوس-المراة-متحجبة-مع-زوج-اختها-مع-وجود-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_923/nour_92309.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":18912,"question":"مستمع بعث برسالة يقول فيها: المرسل (م. د) أخونا رسالته مطولة في الواقع ملخصها: أنه احتاج إلى السكن مع أحد أقاربه، لكنه يعاني من مشكلة الاختلاط، ويرجو من سماحتكم التوجيه.","title":"حكم السكن مع الأقارب مع وجود الاختلاط","answer":"الجواب: عليه أن يتقي الله مهما أمكن، إذا كان يخشى الاختلاط لا يسكن معهم، يبتعد إلى محل سليم؛ فإن الاختلاط خطره عظيم؛ فإن استطاع أن يكون في غرفة خاصة بعيدًا عن الاختلاط، يأتيها وقت حاجته، وإذا خرج غض بصره، فليتق الله، وإذا لم يستطع ذلك فليبتعد، وليلتمس مكانًا لا خطر فيه، فالمؤمن يحاسب نفسه، ويتقي الله في ذلك ولا يخاطر، فالله -جل وعلا- حرم على العبد أن يتعاطى ما حرم الله عليه، وحرم عليه أن يخاطر بدينه، فأنت يا أخي، اتق الله، واحذر أن تجلس أو تقيم في محل فيه خطر على دينك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18051/حكم-السكن-مع-الاقارب-مع-وجود-الاختلاط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_923/nour_92312.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":18933,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من جمهورية السودان، وباعثها أحد الإخوة يقول: ابنكم عمر ملوان -فيما يبدو- أخونا رسالته مطولة، وكتبها بلهجته العامية السودانية، فهمت منها سماحة الشيخ: أن أمه غير مسلمة، ويسأل عن البر بها بعد وفاتها، كيف تنصحونه سماحة الشيخ؟","title":"حكم بر الوالدة الكافرة بعد وفاتها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: ما دامت توفيت فليس هناك شيء يلحقها بعد الوفاة؛ لأن الكافر لا يلحقه شيء بعد الوفاة، ما دامت ماتت على دين النصرانية أو الوثنية، فلا تدع عليها، ولا تدع لها، ولا يلحقها منك شيء، لا صدقة، ولا استغفار، ولا غير ذلك، إنما هذا في حق الميت المسلم: إذا مات انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له أما إذا كنت تعلم أنها ماتت على النصرانية أو اليهودية أو الوثنية وعبادة القبور، فهذه لا يلحقها شيء منك، لا تدع لها، ولا تتصدق عنها، وإنا لله وإنا إليه راجعون، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18066/حكم-بر-الوالدة-الكافرة-بعد-وفاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_924/nour_92401.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":19014,"question":"يقول: لي صديق مؤمن بالله الحق، ويعيش مع عائلة يكسب رب أسرتها المال الحرام، أي: من القمار والاختلاس من الناس، علمًا أن هذه العائلة كما يقال: متطورة، أي: في إظهار المفاتن والتزين خارج المنزل، وقد وجه هذا الشخص النصائح الكثيرة الكثيرة إلى والده وإخوته، ولكن دون جدوى، وهو طالب في مدرسة مختلطة من الشبان والبنات، في الصف والمقعد، والبنات يظهرن المفاتن والمغريات أمام الشباب كلهم، ماذا يفعل أيترك البيت وليس له مورد؟ أفيدونا جزاكم الله خيرًا.","title":"حكم الدراسة المختلطة والأكل من كسب الوالد الحرام","answer":"الجواب: الواجب على الناصح وهذا الشاب أن يتقي الله، وأن يغادر البيت ويبتعد عن أسباب الفتنة، وسوف يجعل الله له فرجًا ومخرجًا، إما بالسكن مع الطلبة إذا كان هناك سكن، أو بأسباب أخرى، يقول الله سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3] ، ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. فعليه أن يتقي الله وأن يبتعد عن أسباب الفتنة، وكذلك المدرسة التي يدرس فيها لا يدرس فيها إذا كان مختلطة يلتمس عملًا يقوم بحاله ولا يدرس في هذه المدرسة، بل يدرس على العلماء في المساجد أو في مدارس أهلية، ليس فيها اختلاط، وليس طلب العلم عذرًا له في أن يجلس مع النساء والبنات ويختلط بهن، هذا مرض لقلبه ومرض لدينه، ومن أسباب هلاكه، فلا يجوز أن يجلس معهن في مقاعد الدراسة، ولا يبقى مع أهله ما داموا على الفساد والشر. أما النصيحة فيبذلها ويجتهد في النصيحة ويتابع النصيحة لعله يستجاب له، ولكن لا يجلس معهم ما دام أكلهم حرام وأعمالهم خبيثة فلا يجلس معهم؛ لأن الأكل ليس بسليم والأسرة غير سليمة، والاختلاط بهم فيه ما فيه من الشر. فالواجب أن يغادر المحل هذا، ويحذر، ولا مانع من الزيارة التي يريد بها النصيحة لوالديه وإخوته وأقاربه، أما الأكل والسكن فلينتقل إلى محل آخر يسلم فيه على دينه، وسوف يعينه الله ويسهل أمره كما قال تعالى: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، رزق الله الجميع التوفيق والهداية. نعم. المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18180/حكم-الدراسة-المختلطة-والاكل-من-كسب-الوالد-الحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_926/nour_92607.mp3","categories":["النظر والخلوة والاختلاط","نصائح وتوجيهات"]},{"id":19035,"question":"هذه السائلة أم رشيدة من اليمن الخضراء تقول سماحة الشيخ: أحيانًا أكون في مجلس ومعي بعض من النساء، فيدخل علينا الرجل الكبير في العمر فيسلم ويمد يده للمصافحة، وأنا لم أمد يدي لكن النساء الذي معي يغضبن علي، هل هذا العمل صحيح أم لا ؟","title":"حكم مصافحة المرأة للرجل الأجنبي المسن","answer":"الجواب: المرأة لا تصافح الرجال من غير محارمها، ولكن يرد عليه السلام يقال: وعليكم السلام أما أنه يصافح لا، لا تجوز مصافحة المرأة للرجل الأجنبي، إنما تصافح محرمها كأخيها وأبيها، أما الأجانب لا، يقول النبي ﷺ: إني لا أصافح النساء، وتقول عائشة رضي الله عنها: \"والله ما مست يد رسول الله يد امرأة قط ما كان يبايعهن إلا بالكلام\"، عليه الصلاة والسلام. فعليك أن تنكري عليهم إذا صافحوا أنكري عليهم وعلميهم وأرشديهم بارك الله فيك. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18198/حكم-مصافحة-المراة-للرجل-الاجنبي-المسن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88303.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":19069,"question":"هذه أخت سائلة تقول: بأنها فتاة ملتزمة بفضل الله، ومن الله عليها بالتقوى وحلاوة الإيمان وغض البصر، علمًا تقول: بأنها في جامعة مختلطة، وأسرتها غير ملتزمة، وتلبس الحجاب بدون غطاء الوجه، فهل عليها وزر؛ لأنها تكشف الوجه؟","title":"حكم دراسة المرأة في الجامعات المختلطة","answer":"الجواب: لا يجوز لها الدراسة مع الطلبة مختلطة بالشباب، ولا يجوز لها كشف الوجه، بل يجب عليها الحجاب، والبعد عن الاختلاط، ولو تركت الدراسة حتى يتيسر لها دراسة غير مختلطة؛ لأن الدراسة المختلطة وسيلة إلى شر كبير إذا كانت مع الأولاد في الصفوف صفوف الدراسة، وليس لها كشف الوجه بل عليها [تغطيته] الله يقول: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، ويقول سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31]، الآية. والوجه من أعظم الزينة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18261/حكم-دراسة-المراة-في-الجامعات-المختلطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88326.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":19072,"question":"من جمهورية مصر العربية المستمع (ع. س. س. ع) له قضية يقول فيها: إنني رجل متزوج، والحمد لله أعمل في الخارج، ووجود زوجتي معي ضروري شرعًا، لكن أترك والدتي وحيدة علمًا بأنني العائل الوحيد لها، وتكون تحت رعاية أختي المتزوجة، ولكن لا أسافر إلا بموافقتها، وهي تتمنى أن أجلس معها، وألغي سفري؛ لأن سفري يؤلمها مع العلم بأن وجود زوجتي معها يخفف من آلامها، فهل أمكث معها، وألغي سفري نهائيًا؟ أم أبقي معها زوجتي، وليس علي حرج في تأثر والدتي؟ جزاكم الله خيرًا.","title":"حكم سفر الابن لطلب الرزق تاركًا أمه وحيدة","answer":"الجواب: هذا فيه تفصيل: إذا أمكنك العمل في المحل الذي فيه والدتك، وأن تجبر خاطرها، وترضيها؛ فهذا أولى؛ لأن مراعاة خاطرها من أهم المهمات، ومن أفضل القربات. أما إذا كنت مضطرًا للسفر لطلب الرزق، وليس في بلدك سبب يعينك على حاجتك، ويسبب غناك عن السفر؛ فأنت معذور في هذا، الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]. وإذا كان لا يضرك بقاء الزوجة عند أمك فأبقها عند أمك جبرًا لها، وإيناسًا لها، أما إذا كان عليك خطر وتخشى على نفسك فإنك تسافر بزوجتك تطلب من الوالدة السماح، ومتى سمحت فالحمد لله، فإن لم تسمح فهذا محل نظر؛ لأن الرسول ﷺ يقول: إنما الطاعة في المعروف. وأنت قد يكون عليك ضرر كبير في بقائك بدون زوجة في بلاد الغربة، فالأقرب والله أعلم أنه يجوز لك السفر بها، وإن لم ترض الوالدة من أجل الضرورة، وشدة الحاجة إليها معك؛ حرصًا على عفتك، وسلامتك، وسلامتها أيضًا. ولكن مهما أمكن أن تستسمح الوالدة، وتجتهد في رضاها عنك؛ فهو أولى وأكمل، يسر الله أمرك، وقضى حاجتك. المقدم: آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18267/حكم-سفر-الابن-لطلب-الرزق-تاركا-امه-وحيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_797/nour_79704.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":19085,"question":"هذا سائل للبرنامج أرسل بمجموعة من الأسئلة أخوكم ( ح. ش. ن. ) يقول يا سماحة الشيخ: بأنه شاب يعيش مع أخيه المتزوج في بيت واحد والبيت لأبيه وزوجة الأخ تقوم بجميع الأعمال المنزلية، وأيضًا يسكن معهم الأم، هل يجوز له أن يعيش معهم في هذا البيت أم لا؟","title":"حكم السكن مع الأخ وزوجته","answer":"الجواب: نعم يعيش معهم، ولكن لا يخلو بزوجة أخيه لا يخلو بها، ولكن يعيش معهم، ولكن يبتعد عن الخلوة بزوجة أخيه؛ لأنها ليست محرمًا له. نعم.","link":"https://binbaz.org.sa/fatwas/18239/حكم-السكن-مع-الاخ-وزوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88317.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":19103,"question":"يسأل أيضًا ويقول: ما حكم الشرع فيمن يذهبن مع سائق أجنبي؟ علمًا بأن المدرسة تبعد عن مكان المعلمات هؤلاء عشرة كيلو مترات، ولا يوجد معهن محرم، وأيضًا فهن يحافظن على الحجاب ومحتشمات؟ جزاكم الله خيرًا.","title":"حكم ركوب المدرسات مع سائق أجنبي إلى المدرسة","answer":"الجواب: لا حرج في ذلك؛ لأن هذا ليس بسفر، الممنوع السفر لا تسافر امرأة إلا مع ذي محرم، أما كونه ينقلهن من بيوتهن إلى المدرسة، أو إلى السوق؛ هذا لا يحتاج إلى محرم، لكن لا يخلو بواحدة يكون معه جماعة، وإذا بقي اثنتان تنزلان جميعًا، وهكذا في الركوب أول يركبان جميعًا، حتى لا يخلو بواحدة؛ لأن الرسول ﷺ نهى عن الخلوة فقال: لا يخلون رجل بامرأة إلا ومعها ذو محرم وقال عليه الصلاة والسلام: لا يخلون رجل بامرأة فإن الشيطان ثالثهما، فالسائق الأجنبي يكون معه أمه أو زوجته لا بأس، حتى لا يخلو بأحد، فإذا لم يكن معه لا زوجة، ولا أم، ولا أحد؛ فلا بد أن يكون معه ثنتان فأكثر، بعيدات عن الفتنة، وعن التهمة، حتى لا يحصل خلوة. ولا مانع من نقلهن إلى المدرسة، أو إلى زيارة بيت صديقاتهن .. أو نحو ذلك، المقصود أن النقل في البلد وأطراف البلد لا بأس به ليس بسفر، لكن لا بد أن يكون ليس فيه خلوة. نعم.\nيعني إذا كان لواحدة لا بد أن يكون معها ثالث. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18294/حكم-ركوب-المدرسات-مع-ساىق-اجنبي-الى-المدرسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_797/nour_79709.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":19114,"question":"رسالة وصلت إلى البرنامج من المستمع: محمد يوسف من جدة، أخونا له جمع من القضايا في إحداها يقول: سماحة الشيخ! ما الحكم فيمن صافح امرأة أجنبية أو تحدث معها في نهار رمضان وهو صائم وأيضًا هي صائمة؟ هل هذا يفسد الصوم أو يجرحه؟ نرجو توجيهنا جزاكم الله خيرًا، وهل من كفارة؟","title":"حكم مصافحة ومحادثة الأجنبية في نهار رمضان وغيره","answer":"الجواب: أولاً: المصافحة للمرأة الأجنبية لا تجوز؛ لأن الرسول عليه السلام قال: إني لا أصافح النساء وقالت عائشة رضي الله عنها: «ما مست يد رسول الله ﷺ يد امرأة قط ما كان يبايعهن إلا بالكلام» يعني: النساء الأجنبيات غير المحارم، أما المحرم كأخته وعمته فلا بأس أن يصافحها. وأما المكالمة للأجنبية فلا بأس بها إذا كانت مكالمة مباحة ليس فيها تهمة ولا ريبة، كي يسألها عن أولادها يسألها عن أبيها يسألها عن حاجة من حوائج الجيران أو الأقارب لا بأس بذلك. أما إن كانت المكالمة للتحدث فيما يتعلق بالفساد والزنا ومواعيد الزنا أو عن شهوة أو عن كشف منها له، بأن يرى محاسنها يرى وجهها يرى محاسنها كل هذا لا يجوز. أما إذا كانت المحادثة مع التستر ومع الحجاب ومع البعد عن الريبة، وليس عن شهوة فإنه لا حرج عليه في ذلك، وقد تحدث النبي ﷺ إلى النساء وتحدث النساء إليه ولا حرج في ذلك والصوم صحيح، لا يضره المصافحة ولا تضره المحادثة إلا إذا كانت عن شهوة وخرج المني، فإنه يبطل الصوم بخروج المني عن شهوة، وعليه أن يعيد الصوم على من خرج منه ذلك أن يعيد الصوم. أما مجرد التحدث ولم يخرج شيء فإنه لا يضر الصوم، وهكذا لو خرج مذي المذي لا يبطل الصوم على الصحيح، وإنما يبطله خروج المني عن شهوة في نهار الصوم. والواجب على المؤمن أن يحذر ما حرم الله عليه، وأن لا يصافح امرأة لا تحل له، وأن لا يتحدث إليها عن شهوة أو ينظر إلى محاسنها، والله يقول جل وعلا: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ [النور:30] فالتحفظ من أسباب الشر واجب على المؤمن أينما كان، نسأل الله لنا وللمسلمين جميعًا السلامة. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18284/حكم-مصافحة-ومحادثة-الاجنبية-في-نهار-رمضان-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_931/nour_93104.mp3","categories":["قضايا المرأة","ما لا يفسد الصيام","النظر والخلوة والاختلاط"]},{"id":19140,"question":"أخونا يسأل ويقول: ما حكم الاختلاط العائلي، مثل ابن العم وابن الخال، وأخو الزوج وما أشبه ذلك؟وهل يجوز للمرأة أن تصافح الرجل، مثل ابن العم وابن الخال، وأخي الزوج وغير ذلك، ومن هم الذين تجوز مصافحتهم، وما صحة الحديث الذي يقول ما معناه: \"خير لأحدكم أن يطعن في رأسه بمخيط من حديد ولا يمس امرأة لا تحل له\"؟","title":"حكم الاختلاط العائلي ومصافحة أقارب الزوج","answer":"الجواب: الاختلاط العائلي فيه تفصيل: أما بين المرأة وأبي زوجها وجد زوجها، وأولاد زوجها، فلا بأس؛ لأنهم محارم، أما اختلاطها مع إخوته أو بني عمه، يرونها ولا تحتجب عنهم، أو تصافحهم فهذا لا يجوز، ليس لها الكشف لهم، وليس لها مصافحتهم، وإنما تصافح المحارم فقط، كأخيها وعمها وخالها، وأبي زوجها، وابن زوجها، أما أن تصافح أخا زوجها، أو عم زوجها، أو خال زوجها فلا، وهكذا ابن عمها وابن خالها وابن خالتها، لا، لا تصافحه، ولا تكشف له أيضًا، بل تحتجب، تحجب وجهها وبدنها، ولا تصافحه ولكن تكلمه، ترد عليه السلام، تسلم عليه، تسأله عن حاله وحال أولاده، لا بأس، لكن لا تصافحه ولا تكشف له، بل تحتجب عنه، تحجب وجهها وبدنها كله عن هذا الذي هو ابن عمها أو ابن خالها، أو أخو زوجها، أو زوج أختها أو ما أشبه ذلك، وهذا كثير من الناس يفرط فيه، كثير من العوائل يتساهلون في هذا، وهذا غلط كبير، يجب الحذر، وعدم التساهل. وأما ما يروى عنه ﷺ أنه: لأن يطعن بحديدة في رأسه خير من أن يصافح امرأة، حديث معروف، لكن لا أذكر الآن حال سنده، وهو معروف، وهو يدل على شدة الإنكار في هذا، وشدة الإثم في هذا، كونه ينبغي للمؤمن أن يحذر أن يصافح امرأة لا تحل له؛ لأنه وسيلة إلى التساهل وإلى وقوع ما حرم الله، وقد قال عليه الصلاة والسلام لما بايع النساء قال: إني لا أصافح النساء، وقالت عائشة رضي الله عنها كما جاء في الصحيحين: \"ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام\"، رضي الله عنهن، فالحاصل أنه ﷺ كان يبايع النساء بالكلام لا بالمصافحة. فالواجب الحذر مما حذر منه ﷺ والتأسي به، ولأن المصافحة قد تكون وسيلة إلى ما حرم الله . نعم. المقدم: بارك الله فيكم، وجزاكم خيرًا.","link":"https://binbaz.org.sa/fatwas/18346/حكم-الاختلاط-العاىلي-ومصافحة-اقارب-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_886/nour_88609.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":19161,"question":"رسالة من مجموعة من الأخوات المستمعات يسألن فيقلن: أخواتكم في الإسلام (غ. س. ج) يسألن جمعًا من الأسئلة في أحدها يقلن: أخي تزوج من امرأة، وكانت قد أنجبت من رجل آخر ولدًا، وقد تربى هذا الولد في حجر أخي وهو يبلغ من العمر سنتان، الآن قد بلغ من العمر خمسًا وعشرين سنة، فهل لي أن أحتجب عنه مع العلم أن أخي قد رباه وصرف عليه وهو يتيم؟","title":"حكم تحجب المرأة من ربيب أخيها","answer":"الجواب: لا ينبغي، ليس ولد أخيك إلا إذا كان زوجة أخيك قد أرضعته من لبن أخيك، إذا كان هذا الولد رضع من زوجة أخيكِ أو زوجة أبيك حتى يكون أخًا لك، أما إذا كان ما فيه رضاع مجرد كونه ولد زوجة أخيك ما يكون محرمًا لك، إلا إذا كان هناك رضاع يجعله محرمًا، كأن تكون أرضعته أختك أو زوجة أبيك أو أمك، وإلا فكونه رباه أخوك ما يكون محرمًا لك، وكونه ولد زوجة أخيك ما يكون محرمًا لك. نعم. المقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/18350/حكم-تحجب-المراة-من-ربيب-اخيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_737/nour_73714.mp3","categories":["النظر والخلوة والاختلاط"]},{"id":19225,"question":"شيخ عبد العزيز ! اجتمع لي في هذه الحلقة ثلاث رسائل، ومرسلوها من أخواتنا المسلمات المستمعات، وقضيتهن واحدة تقريبًا، لعل إحدى هذه الرسائل تعبر عن تلكم القضية، فهذه إحداهن تقول: أنا أختكم في الإسلام، وأنا أعاني من مشاكل في حياتي، وهي أنني أعيش في وسط بعيد كل الناس فيه عن الدين، فأنا أدرس في معهد، وهذا المعهد مختلط بين الجنسين، ويمنع فيه لبس أي نوع من الحجاب، وكل الذين موجودين فيه بعيدين عن الدين، وأنا أجد نفسي أتأثر بتصرفاتهم، ويزداد بعدي عن الله وعن إقامة فرائضه وهي الصلاة، حيث أقول لنفسي: ما نفع صلاتي، وأنا أضطر كل يوم إلى ارتكاب المحرمات والمعاصي بقصد وبدون قصد، وأريد منكم أن ترشدوني إلى الطريق الذي فيه سلامتي من غضب الله وراحة للنفس، مع أنني لا أستطيع أن أترك الدراسة وأحافظ على العزلة؛ لأن الشهادة في هذا الزمن ضرورية جدًا وبخاصة لي، أفيدوني جزاكم الله خيرًا.ورسالة أخرى وصلت من العراق في نفس المعنى، وثالثة من جمهورية مصر العربية، نرجو من سماحة الشيخ أن يتفضل بتوجيه الأخوات إلى الطريق الأمثل وهن في ذلكم الوسط الذي وصفنه في رسائلهم.","title":"نصيحة لمن تدرس في بيئة مختلطة","answer":"الجواب: مقتضى الأدلة الشرعية أن الدراسة إذا كانت تشتمل على ما يضر الدارسة أو الدارس أنه لا حاجة إليها؛ لأن الواجب أن يتعلم المسلم ما لا يسعه جهله، وهذا في إمكانه أن يتعلمه من المعلمين في المساجد مع الحجاب والبعد عن الفتنة، في المدارس الأهلية السليمة، في بيت بواسطة أبيه أو أمه أو امرأة صالحة أو ما أشبه ذلك. أما هذه الدراسة المختلطة، هذه خطرها عظيم وفسادها كبير ولا سيما أيضًا مع السفور وعدم الحجاب، فيجتمع الشر كله، فالذي أنصح به هؤلاء الأخوات أن يدعن هذه الدراسة وأن يبتعدن عن هذه الدراسة حفاظًا على دينهن وعلى أخلاقهن، وسوف يجعل الله لهن فرجًا ومخرجًا من طريق دراسة سليمة يحصل بها معرفة الدين من دون وقوع فيما حرم الله. وليست الوظائف ضرورية وليست الشهادات ضرورية، فقد مر السلف الأول وليسوا ممن يتعاطى هذا الأمر، ويمكن العمل في أشياء أخرى بدون هذه الشهادة. وليس من الضروري أيضًا العمل؛ لأن الرجال قوامون على النساء، وفي إمكانها أن تتزوج ويقوم عليها الزوج، أو يقوم عليها والدها أو إخوتها فيما تحتاج إليه، فالرجال قوامون على النساء. وبكل حال هذه الدراسة منكر وشر عظيم وعواقبها وخيمة، وسوف يجعل الله لمن تركها فرجًا ومخرجًا، وسوف يسهل الله له طلبه السليم إذا صدق في ذلك، وكان قصده وجه الله والدار الآخرة، كما قال الله سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]، فعلى الطالب والطالبة في هذه الأقسام عليه الحذر وعليها الحذر، عليهما الحذر جميعًا، فالبقاء في هذه الدراسة تعريض للنفس والعرض والدين لما لا تحمد عقباه، والمسلم مأمور بأن يصون نفسه عما حرم الله، وأن يبتعد عن أسباب الخطر، وقد وعد الله عباده بتفريج الكروب وتيسير الأمور، فعند الضيق يجيء الفرج، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. فهذه نصيحتي لهؤلاء الأخوات ولأشباههن من الطالبات في المدارس والمعاهد والكليات المختلطة، نصيحتي للجميع ترك هذه الدراسة والمطالبة لولاة الأمور بدراسة غير مختلطة للنساء على حدة وللرجال على حدة، ومتى صدق الشعب في هذه الأمور وطلب من ولاة الأمور إفراد النساء وإفراد الرجال كل على حدة، كل في دراسة تخصه، فإن ولاة الأمور لا بد أن يستجيبوا؛ لأن هذا أمر معقول ومصلحته ظاهرة، وإذا جد فيه الشعب الطيب، وبين لولاة الأمور الأضرار العظيمة والعواقب الوخيمة فإن ولاة الأمور إن شاء الله يستجيبون لهذا الأمر إذا رأوا من الشعب الصدق في ذلك والهمة العالية في ذلك. ولا يجوز للإنسان أن يقول: هذا مستحيل أو هذا أمر غير ممكن، لا، كل هذه دعوى لا تليق، بل ينبغي أن نحسن الظن بالله وأن لا نيئس من الإصلاح، وولاة الأمور في بلاد المسلمين يرجى لهم الهداية إذا صدقوا وإذا أرادوا الخير، والله المسئول أن يهديهم ويوفقهم للخير، وأن يصلح لهم القلوب والأعمال والبطانة، وأن يشرح صدورهم للتمسك بشريعة الله وللحكم بشريعة الله، فعلى الشعب أن يعينهم على هذا، وأن لا يطاوع فيما حرم الله، بل يكون عنده النشاط والهمة العالية في فعل ما أمر الله وترك ما نهى الله، رزق الله الجميع التوفيق والهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18416/نصيحة-لمن-تدرس-في-بيىة-مختلطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_890/nour_89005.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":19702,"question":"إنني رجلٌ قد تزوجتُ وأبقيتُ زوجتي حسب رغبة الوالد عنده، ومُصرٌّ والدي ألا أغترب بهذه الزوجة، علمًا بأن الزوجة لا تريد أن تُفارقني، فهل أنا مذنبٌ إن تركتُ المرأة عند والدي، أم أنا مذنبٌ إن أخذتُها منه وهو غاضبٌ وأكون عاقًّا لوالدي؟","title":"حكم طاعة الوالدين في ترك الزوجة عندهم والسفر وهو محتاج لها","answer":"الجواب: إذا أمكن الجمع بين المصالح بأن تذهب وترجع بين وقتٍ آخر وتتركها عند والدك لحاجة والديك إليها، وأنت لا تتأخر كثيرًا، بين شهرٍ وشهرٍ ترجع إليها، وتقوم بحاجتها وملاحظة ما تُريد، وتُرضي والديك، هذا طيبٌ. أما إذا كنتَ تحتاج إليها ولا تتمكن من المجيء إليهم، فحاجاتك مقدَّمة؛ تذهب بها معك، وتستسمح والدك، وليس له طاعةٌ في هذا؛ لأنك محتاجٌ لها: تعفّك وتُعينك على محاربة الشيطان، فتذهب بها، ولا طاعةَ لمخلوقٍ في معصية الخالق؛ لأنَّ ذهابك وحدك يُعرضك لأمورٍ خطيرةٍ، وهي أيضًا كذلك قد تتعرض لأمورٍ خطيرةٍ في جلوسها.\nفالواجب أن تأخذها معك، وأن تعفّ بها فرجك، وتغضّ بها بصرك، وتستسمح الوالد بالكلام الطيب، وتُشير عليه بأن يسمح، وتستعين على ذلك بخواصّ الأقارب: كأعمامك أو أخوالك حتى يرضى عنك، أما تركها عندهم وأنت لا تستطيع الرجوع إليها بين وقتٍ قريبٍ لقضاء حاجتك وعفَّة فرجك فهذا لا يصلح، وهذا غلطٌ من أبيك.","link":"https://binbaz.org.sa/fatwas/20657/حكم-طاعة-الوالدين-في-ترك-الزوجة-عندهم-والسفر-وهو-محتاج-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0575%D8%AD%D9%83%D9%85%20%D8%B7%D8%A7%D8%B9%D8%A9%20%D8%A7%D9%84%D9%88%D8%A7%D9%84%D8%AF%D9%8A%D9%86%20%D9%81%D9%8A%20%D8%AA%D8%B1%D9%83%20%D8%A7%D9%84%D8%B2%D9%88%D8%AC%D8%A9%20%D8%B9%D9%86%D8%AF%D9%87%D9%85%20%D9%88%D8%A7%D9%84%D8%B3%D9%81%D8%B1%20%D9%88%D9%87%D9%88%20%D9%85%D8%AD%D8%AA%D8%A7%D8%AC%20%D9%84%D9%87%D8%A7%D8%9F%20%D8%A7%D8%A8%D9%86%20%D8%A8%D8%A7%D8%B2%20%D9%81%D8%AA%D8%A7%D9%88%D9%89%20%D8%A7%D9%84%D9%85%D8%AD%D8%A7%D8%B6%D8%B1%D8%A7%D8%AA.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]}]
